window.MT_DATA['he'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Israël, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Tel Aviv","phrases":[{"fr":"Bienvenue à Tel Aviv !","tgt":"ברוך הבא לתל אביב!","ro":"Barukh ha-ba le-Tel Aviv!","lit":"béni · [le]-venant · à-Tel Aviv !"},{"fr":"Je suis étudiant à Tel Aviv.","tgt":"אני סטודנט בתל אביב.","ro":"Ani student be-Tel Aviv.","lit":"moi · étudiant · à-Tel Aviv"},{"fr":"Moi, je suis français.","tgt":"אני צרפתי.","ro":"Ani tsarfati.","lit":"moi · français"},{"fr":"David est touriste.","tgt":"דוד תייר.","ro":"David tayar.","lit":"David · touriste"},{"fr":"L'hôtel est près de la mer.","tgt":"המלון ליד הים.","ro":"Ha-malon leyad ha-yam.","lit":"[le]-hôtel · près-de · [la]-mer"},{"fr":"Le passeport est dans le sac.","tgt":"הדרכון בתיק.","ro":"Ha-darkon ba-tik.","lit":"[le]-passeport · dans-[le]-sac"},{"fr":"Tu es fatigué après le vol ?","tgt":"אתה עייף אחרי הטיסה?","ro":"Ata ayef akharei ha-tisa?","lit":"toi · fatigué · après · [le]-vol ?"},{"fr":"Oui, je suis très fatigué.","tgt":"כן, אני מאוד עייף.","ro":"Ken, ani me'od ayef.","lit":"oui · moi · très · fatigué"},{"fr":"Le taxi est ici.","tgt":"המונית פה.","ro":"Ha-monit po.","lit":"[le]-taxi · ici"},{"fr":"Tel Aviv est très belle !","tgt":"תל אביב יפה מאוד!","ro":"Tel Aviv yafa me'od!","lit":"Tel Aviv · belle · très !"}],"tip":{"title":"Pas de verbe être au présent : ani student","example":"Je suis étudiant à Tel Aviv. — <b>אני</b> <b>סטודנט</b> בתל אביב.","body":"En hébreu, le verbe être disparaît complètement au présent. Pour dire « je suis étudiant », on dit simplement « ani student », mot à mot « moi étudiant ». On dirait un style télégraphique, et pourtant c'est parfaitement correct et naturel. De la même façon, « ata ayef ? » veut dire « tu es fatigué ? », littéralement « toi fatigué ? ». Et « ha-monit po », c'est « le taxi ici », donc « le taxi est ici ». Le français glisse un petit verbe entre les deux, l'hébreu pose les mots directement côte à côte. Pour retenir, imaginez que vous montrez du doigt : moi, étudiant ; le taxi, ici. C'est un vrai cadeau pour parler dès le premier jour.","exampleRo":"Ani student be-Tel Aviv.","lit":"moi · étudiant · à-Tel Aviv"}},{"title":"Un café sur le boulevard Rothschild","phrases":[{"fr":"Bonjour, Yoni !","tgt":"בוקר טוב, יוני!","ro":"Boker tov, Yoni!","lit":"matin · bon · Yoni !"},{"fr":"Un café pour moi, s'il vous plaît.","tgt":"קפה אחד בשבילי, בבקשה.","ro":"Kafe ekhad bishvili, bevakasha.","lit":"café · un · pour-moi · s'il-te-plaît"},{"fr":"Avec du lait ?","tgt":"עם חלב?","ro":"Im khalav?","lit":"avec · lait ?"},{"fr":"Oui, avec un peu de lait.","tgt":"כן, עם קצת חלב.","ro":"Ken, im ktsat khalav.","lit":"oui · avec · un-peu · lait"},{"fr":"Le café est bien chaud.","tgt":"הקפה חם.","ro":"Ha-kafe kham.","lit":"[le]-café · chaud"},{"fr":"Le boulevard est très joli.","tgt":"השדרה יפה מאוד.","ro":"Ha-sdera yafa me'od.","lit":"[le]-boulevard · joli · très"},{"fr":"Les arbres sont grands.","tgt":"העצים גדולים.","ro":"Ha-etsim gdolim.","lit":"[les]-arbres · grands"},{"fr":"Le gâteau est délicieux.","tgt":"העוגה טעימה.","ro":"Ha-uga te'ima.","lit":"[le]-gâteau · délicieux"},{"fr":"Merci, c'est parfait.","tgt":"תודה, זה מושלם.","ro":"Toda, ze mushlam.","lit":"merci · ça · parfait"},{"fr":"Bonne journée, Dana !","tgt":"יום טוב, דנה!","ro":"Yom tov, Dana!","lit":"jour · bon · Dana !"}],"tip":{"title":"L'accent tonique : souvent sur la dernière syllabe","example":"Merci, c'est parfait. — <b>תודה</b>, זה <b>מושלם</b>.","body":"En hébreu, la plupart des mots portent l'accent sur la dernière syllabe, un peu comme en français, mais de façon plus marquée. Dans « toda », merci, on appuie sur « da » : to, puis da, bien fort. Dans « mushlam », parfait, la voix monte sur « lam ». Même chose pour « kafe », café, et pour « khalav », le lait, où c'est la fin du mot qui sonne. Attention, il existe des exceptions très courantes : « boker », le matin, et « erev », le soir, s'appuient sur la première syllabe. Ne laissez pas mourir la fin des mots comme on le fait parfois en français, terminez au contraire avec énergie. Une bonne astuce consiste à répéter « to-da, to-da » en tapant dans les mains sur la deuxième syllabe. Votre hébreu sonnera tout de suite plus naturel.","exampleRo":"Toda, ze mushlam.","lit":"merci · ça · parfait"}},{"title":"Une journée à la plage","phrases":[{"fr":"La mer est bleue.","tgt":"הים כחול.","ro":"Ha-yam kakhol.","lit":"[la]-mer · bleue"},{"fr":"Le soleil est fort aujourd'hui.","tgt":"השמש חזקה היום.","ro":"Ha-shemesh khazaka ha-yom.","lit":"[le]-soleil · fort · [le]-jour"},{"fr":"Quelle chaleur aujourd'hui !","tgt":"איזה חום היום!","ro":"Eize khom ha-yom!","lit":"quelle · chaleur · [le]-jour !"},{"fr":"Le sable est brûlant.","tgt":"החול לוהט.","ro":"Ha-khol lohet.","lit":"[le]-sable · brûlant"},{"fr":"L'eau est froide ?","tgt":"המים קרים?","ro":"Ha-mayim karim?","lit":"[les]-eaux · froides ?"},{"fr":"Non, l'eau est agréable.","tgt":"לא, המים נעימים.","ro":"Lo, ha-mayim ne'imim.","lit":"non · [les]-eaux · agréables"},{"fr":"La serviette est sur le sable.","tgt":"המגבת על החול.","ro":"Ha-magevet al ha-khol.","lit":"[la]-serviette · sur · [le]-sable"},{"fr":"Le parasol est grand.","tgt":"השמשייה גדולה.","ro":"Ha-shimshiya gdola.","lit":"[le]-parasol · grand"},{"fr":"Le ciel est clair.","tgt":"השמיים בהירים.","ro":"Ha-shamayim behirim.","lit":"[les]-cieux · clairs"},{"fr":"La plage est pleine de monde.","tgt":"החוף מלא אנשים.","ro":"Ha-khof male anashim.","lit":"[la]-plage · pleine · gens"}],"tip":{"title":"« Ha- » : l'article défini collé au mot","example":"La mer est bleue. — <b>הים</b> כחול.","body":"En hébreu, l'article défini le, la, les se dit « ha », et il se colle directement devant le mot. « Yam », c'est mer, et « ha-yam », c'est la mer. Il n'y a qu'une seule forme : aucune différence entre le, la et les, ni entre masculin et féminin, ni entre singulier et pluriel. On dit ainsi « ha-khol », le sable, « ha-shemesh », le soleil, et « ha-mayim », l'eau. En revanche, il n'existe pas d'article indéfini : pour dire « une serviette », on dit simplement « magevet », sans rien devant. Dans « ha-yam kakhol », mot à mot « la-mer bleue », il n'y a ni verbe être ni autre petit mot : deux mots suffisent. Pour retenir, pensez à un petit souffle, « ha », qui annonce une chose précise, que tout le monde connaît.","exampleRo":"Ha-yam kakhol.","lit":"[la]-mer · bleue"}},{"title":"Le marché du Carmel","phrases":[{"fr":"Le marché est immense.","tgt":"השוק ענק.","ro":"Ha-shuk anak.","lit":"[le]-marché · immense"},{"fr":"La boutique est petite.","tgt":"החנות קטנה.","ro":"Ha-khanut ktana.","lit":"[la]-boutique · petite"},{"fr":"La tomate est rouge.","tgt":"העגבנייה אדומה.","ro":"Ha-agvaniya aduma.","lit":"[la]-tomate · rouge"},{"fr":"Le poivron est rouge.","tgt":"הפלפל אדום.","ro":"Ha-pilpel adom.","lit":"[le]-poivron · rouge"},{"fr":"La pastèque est bien sucrée.","tgt":"האבטיח מתוק.","ro":"Ha-avati'akh matok.","lit":"[la]-pastèque · sucrée"},{"fr":"La figue est sucrée.","tgt":"התאנה מתוקה.","ro":"Ha-te'ena metuka.","lit":"[la]-figue · sucrée"},{"fr":"Le vendeur est sympathique.","tgt":"המוכר נחמד.","ro":"Ha-mokher nekhmad.","lit":"[le]-vendeur · sympathique"},{"fr":"La vendeuse est très sympathique.","tgt":"המוכרת נחמדה מאוד.","ro":"Ha-mokheret nekhmada me'od.","lit":"[la]-vendeuse · sympathique · très"},{"fr":"Les épices sont fraîches.","tgt":"התבלינים טריים.","ro":"Ha-tavlinim triyim.","lit":"[les]-épices · fraîches"},{"fr":"Les olives sont délicieuses.","tgt":"הזיתים טעימים.","ro":"Ha-zeitim te'imim.","lit":"[les]-olives · délicieuses"}],"tip":{"title":"Masculin et féminin : tout s'accorde","example":"La figue est sucrée. — התאנה <b>מתוקה</b>.","body":"En hébreu, chaque nom est masculin ou féminin, et tout ce qui l'accompagne s'accorde : l'adjectif, mais aussi le verbe. Bonne nouvelle, l'oreille repère vite le féminin, qui se termine très souvent par « a » ou par « et ». Ainsi « matok », sucré au masculin, devient « metuka » au féminin. Dans « ha-te'ena metuka », mot à mot « la-figue sucrée », la figue est féminine, donc l'adjectif prend la terminaison « a ». Comparez « ha-pilpel adom », le poivron est rouge, et « ha-agvaniya aduma », la tomate est rouge. Au pluriel, on entend « im » pour le masculin, comme dans « ha-zeitim te'imim », les olives sont délicieuses, et « ot » pour le féminin. Attention, le genre ne suit pas toujours le français : la pastèque, « avati'akh », est masculine. L'astuce : écoutez la fin du nom et faites-lui écho dans l'adjectif.","exampleRo":"Ha-te'ena metuka.","lit":"[la]-figue · sucrée"}},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Je suis le nouveau voisin.","tgt":"אני השכן החדש.","ro":"Ani ha-shakhen he-khadash.","lit":"moi · [le]-voisin · [le]-nouveau"},{"fr":"Tu es d'ici, toi ?","tgt":"אתה מפה?","ro":"Ata mi-po?","lit":"toi · de-ici ?"},{"fr":"Et toi, Noa, tu es d'ici ?","tgt":"ואת, נועה, את מפה?","ro":"Ve-at, Noa, at mi-po?","lit":"[et]-toi · Noa · toi · de-ici ?"},{"fr":"Il est musicien.","tgt":"הוא מוזיקאי.","ro":"Hu muzika'i.","lit":"lui · musicien"},{"fr":"Elle est médecin.","tgt":"היא רופאה.","ro":"Hi rofa.","lit":"elle · médecin"},{"fr":"Elle est au troisième étage.","tgt":"היא בקומה השלישית.","ro":"Hi ba-koma ha-shlishit.","lit":"elle · dans-[l']-étage · [le]-troisième"},{"fr":"Tu es étudiante, Maya ?","tgt":"את סטודנטית, מאיה?","ro":"At studentit, Maya?","lit":"toi · étudiante · Maya ?"},{"fr":"Non, je suis prof de yoga.","tgt":"לא, אני מורה ליוגה.","ro":"Lo, ani mora le-yoga.","lit":"non · moi · professeure · de-yoga"},{"fr":"Il est de Haïfa.","tgt":"הוא מחיפה.","ro":"Hu mi-Kheifa.","lit":"lui · de-Haïfa"},{"fr":"Elle est de Paris.","tgt":"היא מפריז.","ro":"Hi mi-Pariz.","lit":"elle · de-Paris"}],"tip":{"title":"Les pronoms : ani, ata, at, hu, hi","example":"Tu es étudiante, Maya ? — <b>את</b> סטודנטית, מאיה?","body":"Les pronoms de base sont courts et faciles à dire : « ani », je ou moi, « ata », tu pour un homme, « at », tu pour une femme, « hu », il, et « hi », elle. La grande différence avec le français, c'est qu'on distingue le tu masculin et le tu féminin. À un homme, on dit « ata », à une femme, « at ». Dans « at studentit, Maya ? », mot à mot « toi étudiante, Maya ? », on entend « at » parce qu'on parle à une femme, et « studentit » est aussi au féminin. Attention au piège : « hu » veut dire il et « hi » veut dire elle, presque l'inverse de ce qu'imagine l'oreille française. Écoutez encore « hu muzika'i », il est musicien, et « hi rofa », elle est médecin. Pour retenir, répétez « hu ve-hi », lui et elle, comme un petit refrain.","exampleRo":"At studentit, Maya?","lit":"toi · étudiante · Maya ?"}},{"title":"Au stand de falafel","phrases":[{"fr":"Tu as faim ?","tgt":"אתה רעב?","ro":"Ata ra'ev?","lit":"toi · affamé ?"},{"fr":"Oui, j'ai très faim.","tgt":"כן, אני רעב מאוד.","ro":"Ken, ani ra'ev me'od.","lit":"oui · moi · affamé · très"},{"fr":"Le falafel est chaud ?","tgt":"הפלאפל חם?","ro":"Ha-falafel kham?","lit":"[le]-falafel · chaud ?"},{"fr":"Est-ce que la pita est fraîche ?","tgt":"האם הפיתה טרייה?","ro":"Ha'im ha-pita triya?","lit":"[question] · [la]-pita · fraîche ?"},{"fr":"Est-ce que c'est piquant ?","tgt":"האם זה חריף?","ro":"Ha'im ze kharif?","lit":"[question] · ça · piquant ?"},{"fr":"Oui, c'est un peu piquant.","tgt":"כן, זה קצת חריף.","ro":"Ken, ze ktsat kharif.","lit":"oui · ça · un-peu · piquant"},{"fr":"Avec de la tahina ?","tgt":"עם טחינה?","ro":"Im tkhina?","lit":"avec · tahina ?"},{"fr":"Avec des frites ?","tgt":"עם צ'יפס?","ro":"Im chips?","lit":"avec · frites ?"},{"fr":"C'est tout ?","tgt":"זה הכול?","ro":"Ze ha-kol?","lit":"ça · [le]-tout ?"},{"fr":"Est-ce que le stand est ouvert ce soir ?","tgt":"האם הדוכן פתוח הערב?","ro":"Ha'im ha-dukhan patuakh ha-erev?","lit":"[question] · [le]-stand · ouvert · [le]-soir ?"}],"tip":{"title":"Poser une question : avec la voix, ou avec « ha'im »","example":"Est-ce que la pita est fraîche ? — <b>האם</b> הפיתה טרייה?","body":"En hébreu parlé, la façon la plus simple de poser une question est de garder la phrase affirmative et de faire monter la voix à la fin, exactement comme en français familier. « Ata ra'ev », tu as faim, devient une question dès que la voix monte : « ata ra'ev ? ». Pour une question plus soignée, on peut placer « ha'im » au début, un peu comme notre « est-ce que ». « Ha'im ha-pita triya ? », mot à mot « est-ce que la-pita fraîche ? », veut dire « est-ce que la pita est fraîche ? ». Remarquez que l'ordre des mots ne change pas : on ajoute seulement « ha'im » devant. Dans la rue, vous entendrez surtout la version avec la voix, car « ha'im » sonne un peu plus formel. Astuce : si vous hésitez, dites simplement la phrase et levez la voix à la fin, on vous comprendra toujours.","exampleRo":"Ha'im ha-pita triya?","lit":"[question] · [la]-pita · fraîche ?"}},{"title":"En bus et à vélo","phrases":[{"fr":"Le bus n'est pas là.","tgt":"האוטובוס לא פה.","ro":"Ha-otobus lo po.","lit":"[le]-bus · pas · ici"},{"fr":"Le bus n'est pas cher.","tgt":"האוטובוס לא יקר.","ro":"Ha-otobus lo yakar.","lit":"[le]-bus · pas · cher"},{"fr":"Je ne suis pas pressé.","tgt":"אני לא ממהר.","ro":"Ani lo memaher.","lit":"moi · pas · pressé"},{"fr":"Le vélo n'est pas lourd.","tgt":"האופניים לא כבדים.","ro":"Ha-ofanayim lo kvedim.","lit":"[le]-vélo · pas · lourd"},{"fr":"La piste cyclable est large.","tgt":"שביל האופניים רחב.","ro":"Shvil ha-ofanayim rakhav.","lit":"chemin · [le]-vélo · large"},{"fr":"La station n'est pas loin.","tgt":"התחנה לא רחוקה.","ro":"Ha-takhana lo rekhoka.","lit":"[la]-station · pas · loin"},{"fr":"Désolé, je ne suis pas d'ici.","tgt":"סליחה, אני לא מפה.","ro":"Slikha, ani lo mi-po.","lit":"pardon · moi · pas · de-ici"},{"fr":"Le chauffeur n'est pas content.","tgt":"הנהג לא מרוצה.","ro":"Ha-nahag lo merutse.","lit":"[le]-chauffeur · pas · content"},{"fr":"Il ne fait pas froid aujourd'hui.","tgt":"לא קר היום.","ro":"Lo kar ha-yom.","lit":"pas · froid · [le]-jour"},{"fr":"Le vélo électrique est rapide.","tgt":"האופניים החשמליים מהירים.","ro":"Ha-ofanayim ha-khashmaliyim mehirim.","lit":"[le]-vélo · [l']-électrique · rapide"}],"tip":{"title":"« Lo » : la négation","example":"Je ne suis pas pressé. — אני <b>לא</b> ממהר.","body":"Pour dire non, et pour mettre une phrase à la forme négative, l'hébreu utilise un seul petit mot : « lo ». Il se place juste devant ce qu'on veut nier, sans deuxième élément comme notre « ne pas ». « Ani memaher », je suis pressé, devient « ani lo memaher », je ne suis pas pressé, mot à mot « moi pas pressé ». De même, « ha-otobus lo yakar », le bus n'est pas cher, et « lo kar ha-yom », il ne fait pas froid aujourd'hui. Tout seul, « lo » répond tout simplement non à une question. Le français a besoin de deux morceaux, l'hébreu d'un seul, ce qui rend la négation très facile à placer en parlant. Pour retenir, voyez « lo » comme un petit panneau stop posé juste avant le mot.","exampleRo":"Ani lo memaher.","lit":"moi · pas · pressé"}},{"title":"Mon appartement à Tel Aviv","phrases":[{"fr":"C'est mon appartement.","tgt":"זאת הדירה שלי.","ro":"Zot ha-dira sheli.","lit":"ceci · [l']-appartement · [de]-moi"},{"fr":"La cuisine est petite.","tgt":"המטבח קטן.","ro":"Ha-mitbakh katan.","lit":"[la]-cuisine · petite"},{"fr":"Le balcon de Dana est grand.","tgt":"המרפסת של דנה גדולה.","ro":"Ha-mirpeset shel Dana gdola.","lit":"[le]-balcon · [de] · Dana · grand"},{"fr":"Ta chambre est jolie.","tgt":"החדר שלך יפה.","ro":"Ha-kheder shelkha yafe.","lit":"[la]-chambre · [de]-toi · jolie"},{"fr":"Où est ma clé ?","tgt":"איפה המפתח שלי?","ro":"Eifo ha-mafte'akh sheli?","lit":"où · [la]-clé · [de]-moi ?"},{"fr":"La clé est sur la table.","tgt":"המפתח על השולחן.","ro":"Ha-mafte'akh al ha-shulkhan.","lit":"[la]-clé · sur · [la]-table"},{"fr":"Le propriétaire est sympathique.","tgt":"בעל הדירה נחמד.","ro":"Ba'al ha-dira nekhmad.","lit":"maître · [l']-appartement · sympathique"},{"fr":"Son appartement est près de la plage.","tgt":"הדירה שלו ליד הים.","ro":"Ha-dira shelo leyad ha-yam.","lit":"[l']-appartement · [de]-lui · près-de · [la]-mer"},{"fr":"Le canapé de Yoni est confortable.","tgt":"הספה של יוני נוחה.","ro":"Ha-sapa shel Yoni nokha.","lit":"[le]-canapé · [de] · Yoni · confortable"},{"fr":"Le loyer est cher.","tgt":"שכר הדירה יקר.","ro":"Skhar ha-dira yakar.","lit":"salaire · [l']-appartement · cher"}],"tip":{"title":"« Shel » : de, le possessif","example":"Le balcon de Dana est grand. — המרפסת <b>של</b> דנה גדולה.","body":"Le petit mot « shel » veut dire « de », au sens de l'appartenance. « Ha-mirpeset shel Dana », c'est le balcon de Dana, mot à mot « le-balcon de Dana ». Pour dire mon, ton, son, on colle une terminaison à « shel » : « sheli », à moi, « shelkha », à toi pour un homme, « shelo », à lui, et « shela », à elle. Attention à l'ordre : le possessif vient après le nom, et le nom garde son article. On dit donc « ha-dira sheli », mot à mot « l'appartement de-moi », pour mon appartement. Autres exemples : « ha-mafte'akh sheli », ma clé, et « ha-kheder shelkha », ta chambre. C'est un peu comme dire en français familier « l'appartement à moi », ce qui aide beaucoup à retenir la construction.","exampleRo":"Ha-mirpeset shel Dana gdola.","lit":"[le]-balcon · [de] · Dana · grand"}},{"title":"Un houmous au coin de la rue","phrases":[{"fr":"C'est du houmous frais.","tgt":"זה חומוס טרי.","ro":"Ze khumus tari.","lit":"ceci · houmous · frais"},{"fr":"Et ça, qu'est-ce que c'est ?","tgt":"וזה, מה זה?","ro":"Ve-ze, ma ze?","lit":"[et]-ceci · quoi · ceci ?"},{"fr":"C'est de la tahina.","tgt":"זאת טחינה.","ro":"Zot tkhina.","lit":"ceci · tahina"},{"fr":"Cette assiette est énorme !","tgt":"הצלחת הזאת ענקית!","ro":"Ha-tsalakhat ha-zot anakit!","lit":"[l']-assiette · [la]-ceci · énorme !"},{"fr":"Ce restaurant est célèbre.","tgt":"המסעדה הזאת מפורסמת.","ro":"Ha-mis'ada ha-zot mefursemet.","lit":"[le]-restaurant · [la]-ceci · célèbre"},{"fr":"Ce houmous est délicieux.","tgt":"החומוס הזה טעים.","ro":"Ha-khumus ha-ze ta'im.","lit":"[le]-houmous · [le]-ceci · délicieux"},{"fr":"C'est pour toi.","tgt":"זה בשבילך.","ro":"Ze bishvilkha.","lit":"ceci · pour-toi"},{"fr":"C'est un oignon.","tgt":"זה בצל.","ro":"Ze batsal.","lit":"ceci · oignon"},{"fr":"Cette table est libre ?","tgt":"השולחן הזה פנוי?","ro":"Ha-shulkhan ha-ze panui?","lit":"[la]-table · [la]-ceci · libre ?"},{"fr":"Cette sauce est piquante.","tgt":"הרוטב הזה חריף.","ro":"Ha-rotev ha-ze kharif.","lit":"[la]-sauce · [la]-ceci · piquante"}],"tip":{"title":"« Ze » et « zot » : ceci, cela","example":"Cette assiette est énorme ! — הצלחת <b>הזאת</b> ענקית!","body":"« Ze » veut dire ceci, cela, ou c'est, et sa forme féminine est « zot ». Pour présenter une chose, on dit simplement « ze khumus », c'est du houmous, sans verbe être. Si la chose est féminine, on dit plutôt « zot », comme dans « zot tkhina », c'est de la tahina. Pour dire « ce » ou « cette » devant un nom, la construction change : le mot se place après le nom, avec l'article « ha » devant lui aussi. « Ha-tsalakhat ha-zot », mot à mot « l'assiette la-ceci », signifie cette assiette. De même, « ha-khumus ha-ze », ce houmous, et « ha-shulkhan ha-ze », cette table. Dans la conversation, beaucoup de gens disent « ze » presque partout, donc pas de panique si vous hésitez. Astuce : « zot », avec son t final, est le féminin, comme le t de « cette ».","exampleRo":"Ha-tsalakhat ha-zot anakit!","lit":"[l']-assiette · [la]-ceci · énorme !"}},{"title":"La routine du matin","phrases":[{"fr":"Je bois un café le matin.","tgt":"אני שותה קפה בבוקר.","ro":"Ani shote kafe ba-boker.","lit":"moi · buvant · café · dans-[le]-matin"},{"fr":"Dana boit du thé.","tgt":"דנה שותה תה.","ro":"Dana shota te.","lit":"Dana · buvant · thé"},{"fr":"Nous mangeons à la maison.","tgt":"אנחנו אוכלים בבית.","ro":"Anakhnu okhlim ba-bayit.","lit":"nous · mangeant · dans-[la]-maison"},{"fr":"Les filles courent sur la plage.","tgt":"הבנות רצות בחוף.","ro":"Ha-banot ratsot ba-khof.","lit":"[les]-filles · courant · sur-[la]-plage"},{"fr":"Je cours sur la promenade.","tgt":"אני רץ בטיילת.","ro":"Ani rats ba-tayelet.","lit":"moi · courant · sur-[la]-promenade"},{"fr":"Elle court avec le chien.","tgt":"היא רצה עם הכלב.","ro":"Hi ratsa im ha-kelev.","lit":"elle · courant · avec · [le]-chien"},{"fr":"Je travaille de chez moi.","tgt":"אני עובד מהבית.","ro":"Ani oved me-ha-bayit.","lit":"moi · travaillant · de-[la]-maison"},{"fr":"Maya travaille à Jaffa.","tgt":"מאיה עובדת ביפו.","ro":"Maya ovedet be-Yafo.","lit":"Maya · travaillant · à-Jaffa"},{"fr":"Les enfants dorment encore.","tgt":"הילדים עדיין ישנים.","ro":"Ha-yeladim adayin yeshenim.","lit":"[les]-enfants · encore · dormant"},{"fr":"Les voisines écoutent de la musique.","tgt":"השכנות שומעות מוזיקה.","ro":"Ha-shkhenot shom'ot muzika.","lit":"[les]-voisines · écoutant · musique"}],"tip":{"title":"Les verbes au présent : quatre formes","example":"Maya travaille à Jaffa. — מאיה <b>עובדת</b> ביפו.","body":"Au présent, un verbe hébreu ne change pas selon je, tu ou il : il n'a que quatre formes, masculin singulier, féminin singulier, masculin pluriel et féminin pluriel. Prenons travailler : « oved » pour un homme, « ovedet » pour une femme, « ovdim » pour plusieurs hommes ou un groupe mixte, et « ovdot » pour plusieurs femmes. C'est donc le pronom qui indique la personne, et la forme du verbe qui indique le genre et le nombre. Un homme dit « ani oved », une femme dit « ani ovedet ». Dans « Maya ovedet be-Yafo », mot à mot « Maya travaillant à-Jaffa », on entend bien la terminaison « et » du féminin. Même logique avec boire : « shote », « shota », « shotim », « shotot ». Retenez la petite musique des fins de mots, rien, puis « et » ou « a », puis « im », puis « ot », et vous savez déjà utiliser presque tous les verbes au présent.","exampleRo":"Maya ovedet be-Yafo.","lit":"Maya · travaillant · à-Jaffa"}},{"title":"Compter au marché","phrases":[{"fr":"On compte : un, deux, trois !","tgt":"סופרים: אחת, שתיים, שלוש!","ro":"Sofrim: akhat, shtayim, shalosh!","lit":"comptant : · un · deux · trois !"},{"fr":"Une pita, s'il vous plaît.","tgt":"פיתה אחת, בבקשה.","ro":"Pita akhat, bevakasha.","lit":"pita · une · s'il-te-plaît"},{"fr":"Trois tomates, s'il vous plaît.","tgt":"שלוש עגבניות, בבקשה.","ro":"Shalosh agvaniyot, bevakasha.","lit":"trois · tomates · s'il-te-plaît"},{"fr":"Ça coûte cinq shekels.","tgt":"זה עולה חמישה שקלים.","ro":"Ze ole khamisha shkalim.","lit":"ça · coûtant · cinq · shekels"},{"fr":"Deux citrons, c'est tout.","tgt":"שני לימונים, זה הכול.","ro":"Shnei limonim, ze ha-kol.","lit":"deux · citrons · ça · [le]-tout"},{"fr":"Quatre pitas pour dix shekels.","tgt":"ארבע פיתות בעשרה שקלים.","ro":"Arba pitot be-asara shkalim.","lit":"quatre · pitas · à-dix · shekels"},{"fr":"La pastèque coûte huit shekels.","tgt":"האבטיח עולה שמונה שקלים.","ro":"Ha-avati'akh ole shmona shkalim.","lit":"[la]-pastèque · coûtant · huit · shekels"},{"fr":"Six œufs, s'il vous plaît.","tgt":"שש ביצים, בבקשה.","ro":"Shesh beitsim, bevakasha.","lit":"six · œufs · s'il-te-plaît"},{"fr":"Neuf shekels en tout.","tgt":"תשעה שקלים בסך הכול.","ro":"Tish'a shkalim be-sakh ha-kol.","lit":"neuf · shekels · dans-total · [le]-tout"},{"fr":"Voilà dix shekels.","tgt":"הנה עשרה שקלים.","ro":"Hine asara shkalim.","lit":"voici · dix · shekels"}],"tip":{"title":"Compter : ekhad, shtayim, shalosh","example":"Ça coûte cinq shekels. — זה עולה <b>חמישה</b> שקלים.","body":"Les nombres hébreux existent en deux séries, une masculine et une féminine, ce qui surprend au début. Pour compter dans le vide, on utilise la série féminine : « akhat, shtayim, shalosh, arba, khamesh ». Devant un nom féminin, comme « agvaniya », la tomate, on garde cette série : « shalosh agvaniyot », trois tomates. Devant un nom masculin, comme « shekel », on passe à l'autre série : « khamisha shkalim », cinq shekels, et « asara shkalim », dix shekels. Le nombre un est spécial, car il se place après le nom : « pita akhat », une pita, mais « kafe ekhad », un café. Dans « ze ole khamisha shkalim », mot à mot « ça coûtant cinq shekels », le nombre se place avant le nom, comme en français. Astuce de marché : apprenez d'abord les prix avec les shekels, vous les entendrez partout au Carmel.","exampleRo":"Ze ole khamisha shkalim.","lit":"ça · coûtant · cinq · shekels"}},{"title":"Dans le quartier","phrases":[{"fr":"Il y a un café près de l'appartement.","tgt":"יש בית קפה ליד הדירה.","ro":"Yesh beit kafe leyad ha-dira.","lit":"il-y-a · maison · café · près-de · [l']-appartement"},{"fr":"Il y a une épicerie ici ?","tgt":"יש פה מכולת?","ro":"Yesh po makolet?","lit":"il-y-a · ici · épicerie ?"},{"fr":"Il n'y a pas de parking dans la rue.","tgt":"אין חניה ברחוב.","ro":"Ein khanaya ba-rekhov.","lit":"il-n'y-a-pas · parking · dans-[la]-rue"},{"fr":"Il y a beaucoup de vélos.","tgt":"יש הרבה אופניים.","ro":"Yesh harbe ofanayim.","lit":"il-y-a · beaucoup · vélos"},{"fr":"Il n'y a pas de bruit le soir.","tgt":"אין רעש בערב.","ro":"Ein ra'ash ba-erev.","lit":"il-n'y-a-pas · bruit · dans-[le]-soir"},{"fr":"Il y a un jardin public tout près.","tgt":"יש גינה קרובה.","ro":"Yesh gina krova.","lit":"il-y-a · jardin · proche"},{"fr":"Il n'y a pas d'ascenseur dans l'immeuble.","tgt":"אין מעלית בבניין.","ro":"Ein ma'alit ba-binyan.","lit":"il-n'y-a-pas · ascenseur · dans-[l']-immeuble"},{"fr":"Il y a du vent aujourd'hui.","tgt":"יש רוח היום.","ro":"Yesh ru'akh ha-yom.","lit":"il-y-a · vent · [le]-jour"},{"fr":"Il n'y a pas de nuages ce matin.","tgt":"אין עננים הבוקר.","ro":"Ein ananim ha-boker.","lit":"il-n'y-a-pas · nuages · [le]-matin"},{"fr":"Il y a une boulangerie dans le quartier ?","tgt":"יש מאפייה בשכונה?","ro":"Yesh ma'afiya ba-shkhuna?","lit":"il-y-a · boulangerie · dans-[le]-quartier ?"}],"tip":{"title":"« Yesh » et « ein » : il y a, il n'y a pas","example":"Il y a beaucoup de vélos. — <b>יש</b> הרבה אופניים.","body":"Pour dire il y a, l'hébreu utilise « yesh », et pour dire il n'y a pas, « ein ». Ces deux mots ne changent jamais, ni selon le genre ni selon le nombre. « Yesh harbe ofanayim », mot à mot « il-y-a beaucoup vélos », veut dire il y a beaucoup de vélos. « Ein ma'alit ba-binyan » veut dire il n'y a pas d'ascenseur dans l'immeuble. Pas besoin de « de » ni d'article : on met le nom juste après. Pour poser la question, on garde la phrase et on fait monter la voix : « yesh po makolet ? », il y a une épicerie ici ? La réponse courte est tout simplement « yesh », il y en a, ou « ein », il n'y en a pas. Astuce : « yesh » sonne comme un oui joyeux, « ein » comme une petite moue déçue.","exampleRo":"Yesh harbe ofanayim.","lit":"il-y-a · beaucoup · vélos"}},{"title":"Le téléphone","phrases":[{"fr":"J'ai un nouveau téléphone.","tgt":"יש לי טלפון חדש.","ro":"Yesh li telefon khadash.","lit":"il-y-a · [à moi] · téléphone · nouveau"},{"fr":"Tu as un chargeur pour moi ?","tgt":"יש לך מטען בשבילי?","ro":"Yesh lekha mit'an bishvili?","lit":"il-y-a · [à toi] · chargeur · pour-moi ?"},{"fr":"Je n'ai plus de batterie.","tgt":"אין לי בטרייה.","ro":"Ein li batarya.","lit":"il-n'y-a-pas · [à moi] · batterie"},{"fr":"Tu as le numéro de Dana ?","tgt":"יש לך את המספר של דנה?","ro":"Yesh lekha et ha-mispar shel Dana?","lit":"il-y-a · [à toi] · [objet] · [le]-numéro · [de] · Dana ?"},{"fr":"Oui, j'ai son numéro.","tgt":"כן, יש לי את המספר שלה.","ro":"Ken, yesh li et ha-mispar shela.","lit":"oui · il-y-a · [à moi] · [objet] · [le]-numéro · [de]-elle"},{"fr":"Je n'ai pas de réseau ici.","tgt":"אין לי קליטה פה.","ro":"Ein li klita po.","lit":"il-n'y-a-pas · [à moi] · réseau · ici"},{"fr":"Elle a un message pour toi.","tgt":"יש לה הודעה בשבילך.","ro":"Yesh la hoda'a bishvilkha.","lit":"il-y-a · à-elle · message · pour-toi"},{"fr":"Tu as du temps ce soir ?","tgt":"יש לך זמן הערב?","ro":"Yesh lekha zman ha-erev?","lit":"il-y-a · [à toi] · temps · [le]-soir ?"},{"fr":"Non, ce soir je n'ai pas le temps.","tgt":"לא, הערב אין לי זמן.","ro":"Lo, ha-erev ein li zman.","lit":"non · [le]-soir · il-n'y-a-pas · [à moi] · temps"},{"fr":"Il a une application pour le bus.","tgt":"יש לו אפליקציה לאוטובוס.","ro":"Yesh lo aplikatsya la-otobus.","lit":"il-y-a · à-lui · application · pour-[le]-bus"}],"tip":{"title":"« Yesh li » : avoir, littéralement il y a à moi","example":"J'ai un nouveau téléphone. — <b>יש</b> <b>לי</b> טלפון חדש.","body":"L'hébreu n'a pas de verbe avoir au présent. Pour dire j'ai, on dit « yesh li », mot à mot « il y a à moi ». « Yesh li telefon khadash », c'est donc « il-y-a à-moi téléphone nouveau », autrement dit j'ai un nouveau téléphone. On change seulement le petit mot après « yesh » : « li », à moi, « lekha », à toi pour un homme, « lakh », à toi pour une femme, « lo », à lui, et « la », à elle. Pour la négation, on remplace « yesh » par « ein » : « ein li zman », je n'ai pas le temps. Pour la question, il suffit de faire monter la voix : « yesh lekha zman ? », tu as du temps ? Une petite astuce : pensez à la tournure française « c'est à moi », la chose existe et elle m'appartient.","exampleRo":"Yesh li telefon khadash.","lit":"il-y-a · [à moi] · téléphone · nouveau"}},{"title":"Sur la promenade du bord de mer","phrases":[{"fr":"Je vais sur la promenade.","tgt":"אני הולך לטיילת.","ro":"Ani holekh la-tayelet.","lit":"moi · allant · vers-[la]-promenade"},{"fr":"De Tel Aviv à Jaffa, à pied.","tgt":"מתל אביב ליפו ברגל.","ro":"Mi-Tel Aviv le-Yafo ba-regel.","lit":"de-Tel Aviv · à-Jaffa · à-[le]-pied"},{"fr":"Je suis de Marseille.","tgt":"אני ממרסיי.","ro":"Ani mi-Marsei.","lit":"moi · de-Marseille"},{"fr":"Le kiosque est sur la plage.","tgt":"הקיוסק בחוף.","ro":"Ha-kiosk ba-khof.","lit":"[le]-kiosque · sur-[la]-plage"},{"fr":"Je vais à Jaffa à vélo.","tgt":"אני נוסע ליפו באופניים.","ro":"Ani nose'a le-Yafo ba-ofanayim.","lit":"moi · allant · à-Jaffa · en-[le]-vélo"},{"fr":"Elle rentre du travail.","tgt":"היא חוזרת מהעבודה.","ro":"Hi khozeret me-ha-avoda.","lit":"elle · rentrant · de-[le]-travail"},{"fr":"Il y a un banc à l'ombre.","tgt":"יש ספסל בצל.","ro":"Yesh safsal ba-tsel.","lit":"il-y-a · banc · dans-[l']-ombre"},{"fr":"Les enfants vont à la mer.","tgt":"הילדים הולכים לים.","ro":"Ha-yeladim holkhim la-yam.","lit":"[les]-enfants · allant · vers-[la]-mer"},{"fr":"Le vent vient de la mer.","tgt":"הרוח באה מהים.","ro":"Ha-ru'akh ba'a me-ha-yam.","lit":"[le]-vent · venant · de-[la]-mer"},{"fr":"Nous buvons un jus au kiosque.","tgt":"אנחנו שותים מיץ בקיוסק.","ro":"Anakhnu shotim mits ba-kiosk.","lit":"nous · buvant · jus · à-[le]-kiosque"}],"tip":{"title":"Les petits mots collés : be-, le-, mi-","example":"De Tel Aviv à Jaffa, à pied. — <b>מתל</b> אביב <b>ליפו</b> <b>ברגל</b>.","body":"En hébreu, plusieurs petites prépositions ne sont pas des mots séparés : elles se collent au début du mot suivant. « Be » veut dire dans ou à, « le » veut dire vers ou à, et « mi », parfois « me », veut dire de, au sens de la provenance. « Mi-Tel Aviv le-Yafo ba-regel », mot à mot « de-Tel Aviv à-Jaffa à-pied », veut dire de Tel Aviv à Jaffa, à pied : trois petits mots collés font toute la phrase. Quand « be » ou « le » rencontrent l'article « ha », ils fusionnent avec lui : on ne dit pas « be-ha-khof » mais « ba-khof », sur la plage, et « la-yam », vers la mer. Avec « mi », en revanche, l'article reste bien audible : « me-ha-yam », de la mer. Astuce : écoutez le début des mots, un « ba » ou un « la » cache souvent un petit « le » ou « la » français.","exampleRo":"Mi-Tel Aviv le-Yafo ba-regel.","lit":"de-Tel Aviv · à-Jaffa · à-[le]-pied"}},{"title":"Les vêtements d'été","phrases":[{"fr":"Je cherche une chemise blanche.","tgt":"אני מחפש חולצה לבנה.","ro":"Ani mekhapes khultsa levana.","lit":"moi · cherchant · chemise · blanche"},{"fr":"Ce pantalon noir est cher.","tgt":"המכנסיים השחורים יקרים.","ro":"Ha-mikhnasayim ha-shkhorim yekarim.","lit":"[le]-pantalon · [le]-noir · cher"},{"fr":"J'aime cette robe rouge.","tgt":"אני אוהב את השמלה האדומה.","ro":"Ani ohev et ha-simla ha-aduma.","lit":"moi · aimant · [objet] · [la]-robe · [la]-rouge"},{"fr":"Un grand chapeau pour la plage.","tgt":"כובע גדול לחוף.","ro":"Kova gadol la-khof.","lit":"chapeau · grand · pour-[la]-plage"},{"fr":"Des sandales confortables, s'il vous plaît.","tgt":"סנדלים נוחים, בבקשה.","ro":"Sandalim nokhim, bevakasha.","lit":"sandales · confortables · s'il-te-plaît"},{"fr":"C'est un tee-shirt léger.","tgt":"זאת חולצה קלה.","ro":"Zot khultsa kala.","lit":"ceci · tee-shirt · léger"},{"fr":"Le maillot de bain vert est trop petit.","tgt":"בגד הים הירוק קטן מדי.","ro":"Beged ha-yam ha-yarok katan midai.","lit":"habit · [la]-mer · [le]-vert · petit · trop"},{"fr":"Vous avez une taille moyenne ?","tgt":"יש לך מידה בינונית?","ro":"Yesh lekha mida beinonit?","lit":"il-y-a · [à toi] · taille · moyenne ?"},{"fr":"Les chaussures neuves sont belles.","tgt":"הנעליים החדשות יפות.","ro":"Ha-na'alayim ha-khadashot yafot.","lit":"[les]-chaussures · [les]-neuves · belles"},{"fr":"Un pull chaud ? Pas à Tel Aviv !","tgt":"סוודר חם? לא בתל אביב!","ro":"Sveder kham? Lo be-Tel Aviv!","lit":"pull · chaud ? · pas · à-Tel Aviv !"}],"tip":{"title":"L'adjectif après le nom : bayit gadol","example":"Je cherche une chemise blanche. — אני מחפש חולצה <b>לבנה</b>.","body":"En hébreu, l'adjectif se place toujours après le nom : « bayit gadol », mot à mot « maison grande », veut dire une grande maison. Là où le français hésite entre « une grande maison » et « une maison blanche », l'hébreu ne se pose jamais la question : le nom d'abord, l'adjectif ensuite. L'adjectif s'accorde en genre et en nombre : dans « khultsa levana », une chemise blanche, il est au féminin. Quand le nom porte l'article « ha », l'adjectif le prend aussi : « ha-simla ha-aduma », mot à mot « la-robe la-rouge », veut dire la robe rouge. De même, « ha-na'alayim ha-khadashot », les chaussures neuves. Cette répétition de « ha » est obligatoire et donne une petite musique à la phrase. Astuce : quand vous dites « ha » devant le nom, préparez-vous à le redire devant l'adjectif.","exampleRo":"Ani mekhapes khultsa levana.","lit":"moi · cherchant · chemise · blanche"}},{"title":"Demander son chemin","phrases":[{"fr":"Où est le marché du Carmel ?","tgt":"איפה שוק הכרמל?","ro":"Eifo shuk ha-Karmel?","lit":"où · marché · [le]-Carmel ?"},{"fr":"Combien de minutes à pied ?","tgt":"כמה דקות ברגל?","ro":"Kama dakot ba-regel?","lit":"combien · minutes · à-[le]-pied ?"},{"fr":"Environ dix minutes.","tgt":"בערך עשר דקות.","ro":"Be-erekh eser dakot.","lit":"environ · dix · minutes"},{"fr":"Quand part le bus ?","tgt":"מתי האוטובוס יוצא?","ro":"Matai ha-otobus yotse?","lit":"quand · [le]-bus · sortant ?"},{"fr":"Qui est ce monsieur ?","tgt":"מי האיש הזה?","ro":"Mi ha-ish ha-ze?","lit":"qui · [l']-homme · [le]-ceci ?"},{"fr":"Qu'est-ce que tu cherches ?","tgt":"מה אתה מחפש?","ro":"Ma ata mekhapes?","lit":"quoi · toi · cherchant ?"},{"fr":"Je cherche le boulevard Rothschild.","tgt":"אני מחפש את שדרות רוטשילד.","ro":"Ani mekhapes et sderot Rotshild.","lit":"moi · cherchant · [objet] · boulevard · Rothschild"},{"fr":"C'est où, la station de vélos ?","tgt":"איפה תחנת האופניים?","ro":"Eifo takhanat ha-ofanayim?","lit":"où · station · [le]-vélo ?"},{"fr":"Le ticket de bus coûte combien ?","tgt":"כמה עולה כרטיס לאוטובוס?","ro":"Kama ole kartis la-otobus?","lit":"combien · coûtant · ticket · pour-[le]-bus ?"},{"fr":"Quand est-ce qu'on arrive ?","tgt":"מתי אנחנו מגיעים?","ro":"Matai anakhnu magi'im?","lit":"quand · nous · arrivant ?"}],"tip":{"title":"Les mots interrogatifs : ma, mi, eifo, matai, kama","example":"Quand part le bus ? — <b>מתי</b> האוטובוס יוצא?","body":"Les mots interrogatifs sont courts et se placent en tête de phrase. « Ma » veut dire quoi, « mi » veut dire qui, « eifo » veut dire où, « matai » veut dire quand, et « kama » veut dire combien. Ensuite, on garde simplement l'ordre normal des mots, sans inversion ni « est-ce que ». « Matai ha-otobus yotse ? », mot à mot « quand le-bus sortant ? », veut dire quand part le bus. « Eifo shuk ha-Karmel ? », où est le marché du Carmel, n'a même pas besoin de verbe. Et « kama dakot ba-regel ? » demande combien de minutes à pied. Attention à ne pas confondre « mi », qui, avec le petit « mi » collé qui veut dire de. Astuce : « eifo » et « matai » sont les deux mots qui vous sauvent quand vous cherchez votre chemin ou votre bus, répétez-les jusqu'à ce qu'ils sortent tout seuls.","exampleRo":"Matai ha-otobus yotse?","lit":"quand · [le]-bus · sortant ?"}},{"title":"Une shakshuka au petit-déjeuner","phrases":[{"fr":"Je prends une shakshuka.","tgt":"אני לוקח שקשוקה.","ro":"Ani lokeakh shakshuka.","lit":"moi · prenant · shakshuka"},{"fr":"Moi aussi, une shakshuka !","tgt":"גם אני, שקשוקה!","ro":"Gam ani, shakshuka!","lit":"aussi · moi · shakshuka !"},{"fr":"Du pain aussi, s'il vous plaît.","tgt":"גם לחם, בבקשה.","ro":"Gam lekhem, bevakasha.","lit":"aussi · pain · s'il-te-plaît"},{"fr":"La salade aussi est fraîche.","tgt":"גם הסלט טרי.","ro":"Gam ha-salat tari.","lit":"aussi · [la]-salade · fraîche"},{"fr":"La shakshuka est piquante.","tgt":"השקשוקה חריפה.","ro":"Ha-shakshuka kharifa.","lit":"[la]-shakshuka · piquante"},{"fr":"Le café est fort, lui aussi.","tgt":"גם הקפה חזק.","ro":"Gam ha-kafe khazak.","lit":"aussi · [le]-café · fort"},{"fr":"Dana aussi adore la shakshuka.","tgt":"גם דנה אוהבת שקשוקה.","ro":"Gam Dana ohevet shakshuka.","lit":"aussi · Dana · aimant · shakshuka"},{"fr":"Il y a aussi du fromage blanc.","tgt":"יש גם גבינה לבנה.","ro":"Yesh gam gvina levana.","lit":"il-y-a · aussi · fromage · blanc"},{"fr":"Le petit-déjeuner israélien est énorme.","tgt":"ארוחת הבוקר הישראלית ענקית.","ro":"Arukhat ha-boker ha-yisre'elit anakit.","lit":"repas · [le]-matin · [l']-israélien · énorme"},{"fr":"C'est bon et pas cher en plus.","tgt":"זה טעים וגם לא יקר.","ro":"Ze ta'im ve-gam lo yakar.","lit":"ça · bon · [et]-aussi · pas · cher"}],"tip":{"title":"« Gam » : aussi","example":"La salade aussi est fraîche. — <b>גם</b> הסלט טרי.","body":"« Gam » veut dire aussi, et il a une place bien précise : juste avant le mot qu'il concerne. « Gam ani », c'est moi aussi, mot à mot « aussi moi ». « Gam ha-salat tari », mot à mot « aussi la-salade fraîche », veut dire la salade aussi est fraîche, et pas seulement la shakshuka. Dans « yesh gam gvina levana », il y a aussi du fromage blanc, « gam » porte sur le fromage qui le suit. Le français met souvent aussi à la fin, l'hébreu le place devant, comme un petit projecteur braqué sur le mot suivant. On l'associe volontiers à « ve », et : « ve-gam », et aussi, en plus. Astuce : au café, quand votre voisin commande, il vous suffit de dire « gam ani ! » pour avoir la même chose.","exampleRo":"Gam ha-salat tari.","lit":"aussi · [la]-salade · fraîche"}},{"title":"Un soir à Tel Aviv","phrases":[{"fr":"Je veux aller à la plage.","tgt":"אני רוצה ללכת לים.","ro":"Ani rotse lalekhet la-yam.","lit":"moi · voulant · aller · vers-[la]-mer"},{"fr":"Tu veux un verre de vin ?","tgt":"אתה רוצה כוס יין?","ro":"Ata rotse kos yayin?","lit":"toi · voulant · verre · vin ?"},{"fr":"Noa veut danser.","tgt":"נועה רוצה לרקוד.","ro":"Noa rotsa lirkod.","lit":"Noa · voulant · danser"},{"fr":"Que veux-tu manger ce soir ?","tgt":"מה אתה רוצה לאכול הערב?","ro":"Ma ata rotse le'ekhol ha-erev?","lit":"quoi · toi · voulant · manger · [le]-soir ?"},{"fr":"Je veux un falafel.","tgt":"אני רוצה פלאפל.","ro":"Ani rotse falafel.","lit":"moi · voulant · falafel"},{"fr":"Dana, tu veux venir avec nous ?","tgt":"דנה, את רוצה לבוא איתנו?","ro":"Dana, at rotsa lavo itanu?","lit":"Dana · toi · voulant · venir · avec-nous ?"},{"fr":"Oui, je veux venir !","tgt":"כן, אני רוצה לבוא!","ro":"Ken, ani rotsa lavo!","lit":"oui · moi · voulant · venir !"},{"fr":"Ils veulent voir le coucher de soleil.","tgt":"הם רוצים לראות את השקיעה.","ro":"Hem rotsim lir'ot et ha-shki'a.","lit":"eux · voulant · voir · [objet] · [le]-coucher-de-soleil"},{"fr":"On veut une table dehors.","tgt":"אנחנו רוצים שולחן בחוץ.","ro":"Anakhnu rotsim shulkhan ba-khuts.","lit":"nous · voulant · table · dans-[le]-dehors"},{"fr":"Je ne veux pas rentrer tôt.","tgt":"אני לא רוצה לחזור מוקדם.","ro":"Ani lo rotse lakhzor mukdam.","lit":"moi · pas · voulant · rentrer · tôt"}],"tip":{"title":"« Rotse » et « rotsa » : vouloir","example":"Noa veut danser. — נועה <b>רוצה</b> לרקוד.","body":"Vouloir se dit « rotse » pour un homme et « rotsa » pour une femme, et au pluriel « rotsim » et « rotsot ». Comme les autres verbes au présent, il ne change pas selon la personne, seulement selon le genre et le nombre. « Noa rotsa lirkod », mot à mot « Noa voulant danser », veut dire Noa veut danser. Après « rotse », on met un nom, comme dans « ani rotse falafel », je veux un falafel, ou bien un verbe à l'infinitif, qui commence presque toujours par le son « l » : « lirkod », danser, « lalekhet », aller, « lavo », venir. Pour refuser, on ajoute « lo » devant : « ani lo rotse », je ne veux pas. En Israël, on utilise « rotse » très directement, même avec un serveur, et ce n'est pas du tout impoli. Astuce : retenez la paire « rotse, rotsa » comme un homme et une femme qui ont envie de la même chose.","exampleRo":"Noa rotsa lirkod.","lit":"Noa · voulant · danser"}},{"title":"Quelle heure est-il ?","phrases":[{"fr":"Excuse-moi, quelle heure est-il ?","tgt":"סליחה, מה השעה?","ro":"Slikha, ma ha-sha'a?","lit":"pardon · quoi · [l']-heure ?"},{"fr":"Il est huit heures pile.","tgt":"השעה שמונה בדיוק.","ro":"Ha-sha'a shmone bediyuk.","lit":"[l']-heure · huit · exactement"},{"fr":"Il est neuf heures et demie.","tgt":"השעה תשע וחצי.","ro":"Ha-sha'a tesha va-khetsi.","lit":"[l']-heure · neuf · [et]-demie"},{"fr":"Le bus arrive à dix heures.","tgt":"האוטובוס מגיע בעשר.","ro":"Ha-otobus magi'a be-eser.","lit":"[le]-bus · arrivant · à-dix"},{"fr":"Le marché ouvre à sept heures.","tgt":"השוק נפתח בשבע.","ro":"Ha-shuk niftakh be-sheva.","lit":"[le]-marché · s'ouvrant · à-sept"},{"fr":"On se retrouve à six heures ?","tgt":"נפגשים בשש?","ro":"Nifgashim be-shesh?","lit":"se-retrouvant · à-six ?"},{"fr":"À quelle heure tu finis le travail ?","tgt":"באיזו שעה אתה מסיים לעבוד?","ro":"Be-eizo sha'a ata mesayem la'avod?","lit":"à-quelle · heure · toi · finissant · travailler ?"},{"fr":"À cinq heures et quart.","tgt":"בחמש ורבע.","ro":"Be-khamesh va-reva.","lit":"à-cinq · [et]-quart"},{"fr":"Il est déjà midi !","tgt":"כבר צהריים!","ro":"Kvar tsohorayim!","lit":"déjà · midi !"},{"fr":"Oh non, je suis en retard !","tgt":"אוי, אני מאחר!","ro":"Oy, ani me'akher!","lit":"oh · moi · en-retard !"}],"tip":{"title":"L'heure : ha-sha'a","example":"Il est neuf heures et demie. — <b>השעה</b> תשע וחצי.","body":"Pour demander l'heure, on dit « ma ha-sha'a ? », mot à mot « quoi l'heure ? ». La réponse commence par « ha-sha'a », suivi du nombre, toujours dans la série féminine : « ha-sha'a shmone », il est huit heures, littéralement « l'heure huit ». On ne répète pas le mot heures après le nombre, et il n'y a pas de verbe être. Pour les demies et les quarts, on ajoute « va-khetsi », et demie, ou « va-reva », et quart : « ha-sha'a tesha va-khetsi », il est neuf heures et demie. Pour dire à quelle heure, on colle « be » devant le nombre : « be-eser », à dix heures, « be-shesh », à six heures. Dans la conversation, on compte souvent sur douze heures, et le contexte suffit, avec « ba-boker », le matin, ou « ba-erev », le soir. Astuce : retenez d'abord « ma ha-sha'a ? », c'est la question la plus utile de la journée.","exampleRo":"Ha-sha'a tesha va-khetsi.","lit":"[l']-heure · neuf · [et]-demie"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Shalom à tous !","tgt":"שלום לכולם!","ro":"Shalom le-khulam!","lit":"paix · à-tous !"},{"fr":"Merci pour tout !","tgt":"תודה על הכול!","ro":"Toda al ha-kol!","lit":"merci · sur · [le]-tout !"},{"fr":"Pardon, encore une fois, s'il te plaît.","tgt":"סליחה, עוד פעם, בבקשה.","ro":"Slikha, od pa'am, bevakasha.","lit":"pardon · encore · fois · s'il-te-plaît"},{"fr":"La vie à Tel Aviv est facile maintenant.","tgt":"החיים בתל אביב קלים עכשיו.","ro":"Ha-khayim be-Tel Aviv kalim akhshav.","lit":"[la]-vie · à-Tel Aviv · faciles · maintenant"},{"fr":"L'hébreu est une belle langue.","tgt":"עברית היא שפה יפה.","ro":"Ivrit hi safa yafa.","lit":"hébreu · elle · langue · belle"},{"fr":"Je parle un peu hébreu.","tgt":"אני מדבר קצת עברית.","ro":"Ani medaber ktsat ivrit.","lit":"moi · parlant · un-peu · hébreu"},{"fr":"Maintenant, place aux voyages !","tgt":"עכשיו, טיולים!","ro":"Akhshav, tiyulim!","lit":"maintenant · voyages !"},{"fr":"Bravo et merci beaucoup !","tgt":"כל הכבוד ותודה רבה!","ro":"Kol ha-kavod ve-toda raba!","lit":"tout · [l']-honneur · [et]-merci · beaucoup !"},{"fr":"De rien, avec plaisir.","tgt":"בבקשה, בכיף.","ro":"Bevakasha, be-kef.","lit":"je-t'en-prie · avec-plaisir"},{"fr":"À très bientôt, shalom !","tgt":"נתראה בקרוב, שלום!","ro":"Nitra'e be-karov, shalom!","lit":"on-se-reverra · bientôt · paix !"}],"tip":{"title":"Les formules magiques : shalom, toda, bevakasha, slikha","example":"Pardon, encore une fois, s'il te plaît. — <b>סליחה</b>, עוד פעם, <b>בבקשה</b>.","body":"Quatre mots suffisent pour être poli partout en Israël. « Shalom » veut dire paix, et il sert à la fois à dire bonjour et au revoir. « Toda » veut dire merci, et « toda raba », merci beaucoup. « Bevakasha » veut dire s'il te plaît, mais aussi je t'en prie, ou encore voilà quand on tend quelque chose. Enfin « slikha » veut dire pardon ou excusez-moi, pour attirer l'attention comme pour s'excuser. Dans « slikha, od pa'am, bevakasha », mot à mot « pardon, encore fois, s'il-te-plaît », on demande poliment de répéter, une phrase précieuse pour un débutant. Le ton israélien est direct et chaleureux, donc ces petits mots suffisent largement à créer le contact. Astuce : glissez « toda » et « bevakasha » dans chaque échange, et vous verrez les sourires arriver.","exampleRo":"Slikha, od pa'am, bevakasha.","lit":"pardon · encore · fois · s'il-te-plaît"}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Israël.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport Ben Gourion","phrases":[{"fr":"Bonjour, bienvenue en Israël !","tgt":"שלום, ברוכים הבאים לישראל!","ro":"Shalom, brukhim ha-ba'im le-Yisra'el!","lit":"paix · bénis · [les]-arrivants · à-Israël !"},{"fr":"Où sont les valises ?","tgt":"איפה המזוודות?","ro":"Eifo ha-mizvadot?","lit":"où · [les]-valises ?"},{"fr":"Mon passeport, le voici.","tgt":"הנה הדרכון שלי.","ro":"Hine ha-darkon sheli.","lit":"voici · [le]-passeport · [de]-moi"},{"fr":"Je suis un touriste de France.","tgt":"אני תייר מצרפת.","ro":"Ani tayar mi-Tsarfat.","lit":"moi · touriste · de-France"},{"fr":"La sortie, c'est par ici.","tgt":"היציאה פה.","ro":"Ha-yetsi'a po.","lit":"[la]-sortie · ici"},{"fr":"Il y a un taxi dehors ?","tgt":"יש מונית בחוץ?","ro":"Yesh monit ba-khuts?","lit":"il-y-a · taxi · dans-[le]-dehors ?"},{"fr":"Combien de valises as-tu ?","tgt":"כמה מזוודות יש לך?","ro":"Kama mizvadot yesh lekha?","lit":"combien · valises · il-y-a · [à toi] ?"},{"fr":"J'ai juste une valise.","tgt":"יש לי רק מזוודה אחת.","ro":"Yesh li rak mizvada akhat.","lit":"il-y-a · [à moi] · seulement · valise · une"},{"fr":"Je suis fatigué après le vol.","tgt":"אני עייף אחרי הטיסה.","ro":"Ani ayef akharei ha-tisa.","lit":"moi · fatigué · après · [le]-vol"},{"fr":"Le train est en bas, à droite.","tgt":"הרכבת למטה, מימין.","ro":"Ha-rakevet lemata, mi-yamin.","lit":"[le]-train · en-bas · de-droite"}]},{"title":"Touristes et excursions","phrases":[{"fr":"Je suis touriste à Jérusalem.","tgt":"אני תייר בירושלים.","ro":"Ani tayar bi-Yerushalayim.","lit":"moi · touriste · à-Jérusalem"},{"fr":"C'est ma première excursion.","tgt":"זה הטיול הראשון שלי.","ro":"Ze ha-tiyul ha-rishon sheli.","lit":"ce · [l']-excursion · [la]-première · [de]-moi"},{"fr":"Je me promène dans la vieille ville.","tgt":"אני מטייל בעיר העתיקה.","ro":"Ani metayel ba-ir ha-atika.","lit":"moi · me-promène · dans-[la]-ville · [l']-ancienne"},{"fr":"Le trajet est court.","tgt":"הנסיעה קצרה.","ro":"Ha-nesi'a ktsara.","lit":"[le]-trajet · courte"},{"fr":"Les voyageurs sont dans le train.","tgt":"הנוסעים ברכבת.","ro":"Ha-nos'im ba-rakevet.","lit":"[les]-voyageurs · dans-[le]-train"},{"fr":"Le guide parle français.","tgt":"המדריך מדבר צרפתית.","ro":"Ha-madrikh medaber tsarfatit.","lit":"[le]-guide · parle · français"},{"fr":"C'est le bon chemin ?","tgt":"זאת הדרך הנכונה?","ro":"Zot ha-derekh ha-nekhona?","lit":"celle-ci · [le]-chemin · [le]-correct ?"},{"fr":"Tu voyages en train ?","tgt":"אתה נוסע ברכבת?","ro":"Ata nose'a ba-rakevet?","lit":"toi · voyages · dans-[le]-train ?"},{"fr":"Le guide montre le chemin.","tgt":"המדריך מראה את הדרך.","ro":"Ha-madrikh mar'e et ha-derekh.","lit":"[le]-guide · montre · [objet] · [le]-chemin"},{"fr":"Les touristes se promènent beaucoup.","tgt":"התיירים מטיילים הרבה.","ro":"Ha-tayarim metaylim harbe.","lit":"[les]-touristes · se-promènent · beaucoup"}],"tip":{"title":"Les familles de mots : une même racine, plusieurs mots","example":"Le guide montre le chemin. — <b>המדריך</b> מראה את <b>הדרך</b>.","body":"En hébreu, beaucoup de mots se construisent autour d'une racine de trois consonnes, un peu comme une famille. Avec les sons T, Y, L, on obtient « tiyul », l'excursion, « metayel », je me promène, et « tayar », le touriste. Avec N, S, A, on a « nose'a », je voyage, « nesi'a », le trajet, et « nos'im », les voyageurs. Prenons notre phrase : « Ha-madrikh mar'e et ha-derekh », mot à mot le guide, montre, le chemin. « Derekh », le chemin, et « madrikh », celui qui montre le chemin, partagent les mêmes consonnes D, R, KH. En français aussi, on a voyage, voyageur et voyager, mais en hébreu ce jeu est partout. Quand tu entends un mot nouveau, cherche ses trois consonnes : souvent, tu devineras le sens tout seul. Astuce : imagine la racine comme un squelette, et les voyelles comme des vêtements qui changent selon le rôle du mot.","exampleRo":"Ha-madrikh mar'e et ha-derekh.","lit":"[le]-guide · montre · [objet] · [le]-chemin"}},{"title":"Le train vers Jérusalem","phrases":[{"fr":"Je veux un billet pour Jérusalem.","tgt":"אני רוצה כרטיס לירושלים.","ro":"Ani rotse kartis li-Yerushalayim.","lit":"moi · veux · billet · pour-Jérusalem"},{"fr":"Un aller simple ou un aller-retour ?","tgt":"כיוון אחד או הלוך ושוב?","ro":"Kivun ekhad o halokh va-shov?","lit":"direction · une · ou · aller · et-retour ?"},{"fr":"Aller-retour, pour aujourd'hui.","tgt":"הלוך ושוב, להיום.","ro":"Halokh va-shov, le-hayom.","lit":"aller · et-retour · pour-aujourd'hui"},{"fr":"Le train part à quelle heure ?","tgt":"באיזו שעה הרכבת יוצאת?","ro":"Be-eizo sha'a ha-rakevet yotset?","lit":"à-quelle · heure · [le]-train · sort ?"},{"fr":"Dans dix minutes.","tgt":"בעוד עשר דקות.","ro":"Be-od eser dakot.","lit":"dans-encore · dix · minutes"},{"fr":"Le quai est en bas.","tgt":"הרציף למטה.","ro":"Ha-ratsif lemata.","lit":"[le]-quai · en-bas"},{"fr":"Cette place est libre ?","tgt":"המקום הזה פנוי?","ro":"Ha-makom ha-ze panui?","lit":"[la]-place · [la]-celle-ci · libre ?"},{"fr":"Oui, assieds-toi.","tgt":"כן, שב.","ro":"Ken, shev.","lit":"oui · assieds-toi"},{"fr":"Le train est rapide et propre.","tgt":"הרכבת מהירה ונקייה.","ro":"Ha-rakevet mehira u-nkiya.","lit":"[le]-train · rapide · et-propre"},{"fr":"Jérusalem est en haut, sur la montagne.","tgt":"ירושלים למעלה, על ההר.","ro":"Yerushalayim lemala, al ha-har.","lit":"Jérusalem · en-haut · sur · [la]-montagne"}]},{"title":"Au guichet de la gare","phrases":[{"fr":"Un billet, s'il te plaît.","tgt":"כרטיס אחד, בבקשה.","ro":"Kartis ekhad, bevakasha.","lit":"billet · un · s'il-te-plaît"},{"fr":"Voici ton billet.","tgt":"בבקשה, הכרטיס שלך.","ro":"Bevakasha, ha-kartis shelkha.","lit":"voici · [le]-billet · [de]-toi"},{"fr":"Ah, merci beaucoup !","tgt":"אה, תודה רבה!","ro":"A, toda raba!","lit":"ah · merci · nombreuse !"},{"fr":"De rien, c'est avec plaisir.","tgt":"בבקשה, בכיף.","ro":"Bevakasha, be-kef.","lit":"de-rien · avec-plaisir"},{"fr":"Un plan de la ville, s'il te plaît.","tgt":"מפה של העיר, בבקשה.","ro":"Mapa shel ha-ir, bevakasha.","lit":"plan · [de] · [la]-ville · s'il-te-plaît"},{"fr":"Voilà, un plan gratuit.","tgt":"בבקשה, מפה בחינם.","ro":"Bevakasha, mapa be-khinam.","lit":"voici · plan · gratuitement"},{"fr":"Où est la sortie, s'il te plaît ?","tgt":"איפה היציאה, בבקשה?","ro":"Eifo ha-yetsi'a, bevakasha?","lit":"où · [la]-sortie · s'il-te-plaît ?"},{"fr":"C'est tout droit, puis à gauche.","tgt":"ישר ואז שמאלה.","ro":"Yashar ve-az smola.","lit":"tout-droit · et-alors · à-gauche"},{"fr":"Pardon, le bus pour la vieille ville ?","tgt":"סליחה, האוטובוס לעיר העתיקה?","ro":"Slikha, ha-otobus la-ir ha-atika?","lit":"pardon · [le]-bus · vers-[la]-ville · [l']-ancienne ?"},{"fr":"Merci, et passe une bonne journée !","tgt":"תודה, ויום טוב!","ro":"Toda, ve-yom tov!","lit":"merci · et-jour · bon !"}],"tip":{"title":"« Bevakasha » : s'il te plaît, de rien, voici","example":"De rien, c'est avec plaisir. — <b>בבקשה</b>, בכיף.","body":"« Bevakasha » est sans doute le mot le plus pratique de ton voyage. Il veut dire s'il te plaît : « Kartis ekhad, bevakasha », un billet, s'il te plaît. Mais on le dit aussi pour répondre à un merci, comme notre de rien. Et quand on tend quelque chose à quelqu'un, on dit encore « bevakasha », comme voici ou tiens. Dans notre exemple, « Bevakasha, be-kef », mot à mot de rien, avec plaisir, c'est une réponse chaleureuse et très courante. On accentue la dernière syllabe : be, va, ka, SHA. Le mot marche avec tout le monde, homme ou femme, ami ou inconnu. Astuce : dès que tu donnes, demandes ou remercies, « bevakasha » est presque toujours la bonne réponse.","exampleRo":"Bevakasha, be-kef.","lit":"de-rien · avec-plaisir"}},{"title":"Dans la vieille ville de Jérusalem","phrases":[{"fr":"Voici la porte de Jaffa.","tgt":"הנה שער יפו.","ro":"Hine sha'ar Yafo.","lit":"voici · porte-de · Jaffa"},{"fr":"Les remparts sont très anciens.","tgt":"החומות עתיקות מאוד.","ro":"Ha-khomot atikot me'od.","lit":"[les]-remparts · anciens · très"},{"fr":"Il y a une promenade sur les remparts.","tgt":"יש טיול על החומות.","ro":"Yesh tiyul al ha-khomot.","lit":"il-y-a · promenade · sur · [les]-remparts"},{"fr":"La vue est magnifique d'ici.","tgt":"הנוף מדהים מכאן.","ro":"Ha-nof madhim mi-kan.","lit":"[la]-vue · magnifique · d'-ici"},{"fr":"Les ruelles sont étroites.","tgt":"הסמטאות צרות.","ro":"Ha-simta'ot tsarot.","lit":"[les]-ruelles · étroites"},{"fr":"Il y a beaucoup de touristes aujourd'hui.","tgt":"יש הרבה תיירים היום.","ro":"Yesh harbe tayarim hayom.","lit":"il-y-a · beaucoup · touristes · aujourd'hui"},{"fr":"Où est le musée ?","tgt":"איפה המוזיאון?","ro":"Eifo ha-muze'on?","lit":"où · [le]-musée ?"},{"fr":"Le musée est à côté de la porte.","tgt":"המוזיאון ליד השער.","ro":"Ha-muze'on leyad ha-sha'ar.","lit":"[le]-musée · à-côté-de · [la]-porte"},{"fr":"Il fait très chaud ici.","tgt":"חם מאוד פה.","ro":"Kham me'od po.","lit":"chaud · très · ici"},{"fr":"J'ai de l'eau dans le sac.","tgt":"יש לי מים בתיק.","ro":"Yesh li mayim ba-tik.","lit":"il-y-a · [à moi] · eau · dans-[le]-sac"}]},{"title":"Au marché Mahane Yehuda","phrases":[{"fr":"Combien coûte ce fromage-là ?","tgt":"כמה עולה הגבינה הזאת?","ro":"Kama ola ha-gvina ha-zot?","lit":"combien · monte · [le]-fromage · [le]-celui-ci ?"},{"fr":"Dix shekels le kilo.","tgt":"עשרה שקלים לקילו.","ro":"Asara shkalim la-kilo.","lit":"dix · shekels · pour-[le]-kilo"},{"fr":"Et ça, combien ça coûte ?","tgt":"וזה, כמה זה עולה?","ro":"Ve-ze, kama ze ole?","lit":"et-ça · combien · ça · monte ?"},{"fr":"Seulement cinq shekels.","tgt":"רק חמישה שקלים.","ro":"Rak khamisha shkalim.","lit":"seulement · cinq · shekels"},{"fr":"C'est cher !","tgt":"זה יקר!","ro":"Ze yakar!","lit":"ça · cher !"},{"fr":"Non, c'est bon marché.","tgt":"לא, זה זול.","ro":"Lo, ze zol.","lit":"non · ça · bon-marché"},{"fr":"Combien coûtent les dattes ?","tgt":"כמה עולים התמרים?","ro":"Kama olim ha-tmarim?","lit":"combien · montent · [les]-dattes ?"},{"fr":"Vingt shekels la boîte.","tgt":"עשרים שקל לקופסה.","ro":"Esrim shekel la-kufsa.","lit":"vingt · shekel · pour-[la]-boîte"},{"fr":"Je prends deux boîtes.","tgt":"אני לוקח שתי קופסאות.","ro":"Ani loke'akh shtei kufsa'ot.","lit":"moi · prends · deux · boîtes"},{"fr":"Combien ça fait, tout ensemble ?","tgt":"כמה זה ביחד?","ro":"Kama ze beyakhad?","lit":"combien · ça · ensemble ?"}],"tip":{"title":"« Kama ze ole ? » : demander un prix, les shekels","example":"Et ça, combien ça coûte ? — וזה, <b>כמה</b> זה <b>עולה</b>?","body":"Pour demander un prix, la formule magique est « Kama ze ole ? », mot à mot combien, ça, monte ? En hébreu, un prix ne coûte pas, il monte : le verbe « ole » veut dire monter. Ce verbe s'accorde avec ce qu'on achète : « Kama ola ha-gvina ? » pour le fromage, qui est féminin en hébreu, et « Kama olim ha-tmarim ? » pour les dattes, au pluriel. Pour la réponse, on donne le nombre puis la monnaie : « asara shkalim », dix shekels. Dans la rue, on entend aussi souvent le singulier après un nombre : « esrim shekel », vingt shekels. Pour l'addition, demande simplement « Kama ze beyakhad ? », combien ça fait ensemble. Astuce : pense à un prix qui monte au marché, et tu n'oublieras plus « ole ».","exampleRo":"Ve-ze, kama ze ole?","lit":"et-ça · combien · ça · monte ?"}},{"title":"Une journée à la mer Morte","phrases":[{"fr":"La mer Morte est très salée.","tgt":"ים המלח מלוח מאוד.","ro":"Yam ha-Melakh malu'akh me'od.","lit":"mer-de · [le]-sel · salée · très"},{"fr":"C'est l'endroit le plus bas du monde.","tgt":"זה המקום הכי נמוך בעולם.","ro":"Ze ha-makom hakhi namukh ba-olam.","lit":"ce · [le]-endroit · le-plus · bas · dans-[le]-monde"},{"fr":"On flotte sur l'eau !","tgt":"צפים על המים!","ro":"Tsafim al ha-mayim!","lit":"flottons · sur · [les]-eaux !"},{"fr":"L'eau est chaude.","tgt":"המים חמים.","ro":"Ha-mayim khamim.","lit":"[les]-eaux · chaudes"},{"fr":"Attention aux yeux !","tgt":"זהירות עם העיניים!","ro":"Zehirut im ha-einayim!","lit":"prudence · avec · [les]-yeux !"},{"fr":"La boue est noire.","tgt":"הבוץ שחור.","ro":"Ha-buts shakhor.","lit":"[la]-boue · noire"},{"fr":"Il y a de l'ombre là-bas ?","tgt":"יש צל שם?","ro":"Yesh tsel sham?","lit":"il-y-a · ombre · là-bas ?"},{"fr":"N'oublie pas ta crème solaire.","tgt":"אל תשכח קרם הגנה.","ro":"Al tishkakh krem hagana.","lit":"ne-pas · oublie · crème · protection"},{"fr":"Le soleil est très fort.","tgt":"השמש חזקה מאוד.","ro":"Ha-shemesh khazaka me'od.","lit":"[le]-soleil · forte · très"},{"fr":"Je veux une douche.","tgt":"אני רוצה מקלחת.","ro":"Ani rotse miklakhat.","lit":"moi · veux · douche"}]},{"title":"Horaires et distances","phrases":[{"fr":"Le musée est ouvert de neuf heures à cinq heures.","tgt":"המוזיאון פתוח מתשע עד חמש.","ro":"Ha-muze'on patu'akh mi-tesha ad khamesh.","lit":"[le]-musée · ouvert · de-neuf · jusqu'à · cinq"},{"fr":"Le petit-déjeuner, de sept à dix heures.","tgt":"ארוחת בוקר משבע עד עשר.","ro":"Arukhat boker mi-sheva ad eser.","lit":"repas-de · matin · de-sept · jusqu'à · dix"},{"fr":"La piscine est ouverte jusqu'à quand ?","tgt":"הבריכה פתוחה עד מתי?","ro":"Ha-brekha ptukha ad matay?","lit":"[la]-piscine · ouverte · jusqu'à · quand ?"},{"fr":"Jusqu'à huit heures du soir.","tgt":"עד שמונה בערב.","ro":"Ad shmone ba-erev.","lit":"jusqu'à · huit · dans-[le]-soir"},{"fr":"De Tel Aviv à Jérusalem, c'est une heure.","tgt":"מתל אביב עד ירושלים זה שעה.","ro":"Mi-Tel Aviv ad Yerushalayim ze sha'a.","lit":"de-Tel Aviv · jusqu'à · Jérusalem · ça · heure"},{"fr":"Il y a un bus d'ici jusqu'à l'hôtel ?","tgt":"יש אוטובוס מכאן עד המלון?","ro":"Yesh otobus mi-kan ad ha-malon?","lit":"il-y-a · bus · d'-ici · jusqu'à · [l']-hôtel ?"},{"fr":"Je suis ici de lundi à jeudi.","tgt":"אני פה מיום שני עד יום חמישי.","ro":"Ani po mi-yom sheni ad yom khamishi.","lit":"moi · ici · de-jour · deuxième · jusqu'à · jour · cinquième"},{"fr":"La chambre est libre jusqu'à midi.","tgt":"החדר פנוי עד הצהריים.","ro":"Ha-kheder panui ad ha-tsohorayim.","lit":"[la]-chambre · libre · jusqu'à · [le]-midi"},{"fr":"Du matin au soir, on marche.","tgt":"מהבוקר עד הערב אנחנו הולכים.","ro":"Me-ha-boker ad ha-erev anakhnu holkhim.","lit":"de-[le]-matin · jusqu'à · [le]-soir · nous · marchons"},{"fr":"D'ici à la plage, cinq minutes.","tgt":"מכאן עד החוף, חמש דקות.","ro":"Mi-kan ad ha-khof, khamesh dakot.","lit":"d'-ici · jusqu'à · [la]-plage · cinq · minutes"}],"tip":{"title":"« Mi... ad... » : de... à...","example":"Le musée est ouvert de neuf heures à cinq heures. — המוזיאון פתוח <b>מתשע</b> <b>עד</b> חמש.","body":"Pour dire de... à..., l'hébreu utilise « mi » et « ad ». « Mi », qui devient « me » devant certains sons, se colle directement au mot suivant : « mi-tesha », de neuf heures, « mi-kan », d'ici. « Ad » veut dire jusqu'à, et reste un petit mot séparé. Notre exemple, « Ha-muze'on patu'akh mi-tesha ad khamesh », se lit mot à mot : le musée, ouvert, de-neuf, jusqu'à, cinq. Remarque qu'il n'y a pas de verbe être : on dit simplement le musée ouvert. Cela marche pour les heures, les jours et les lieux : « mi-Tel Aviv ad Yerushalayim », de Tel Aviv à Jérusalem. Et tout seul, « ad matay ? » veut dire jusqu'à quand ? Astuce : « mi » est le point de départ, « ad » la ligne d'arrivée.","exampleRo":"Ha-muze'on patu'akh mi-tesha ad khamesh.","lit":"[le]-musée · ouvert · de-neuf · jusqu'à · cinq"}},{"title":"À la réception de l'hôtel","phrases":[{"fr":"J'ai une réservation.","tgt":"יש לי הזמנה.","ro":"Yesh li hazmana.","lit":"il-y-a · [à moi] · réservation"},{"fr":"À quel nom ?","tgt":"על איזה שם?","ro":"Al eize shem?","lit":"sur · quel · nom ?"},{"fr":"Au nom de Martin.","tgt":"על שם מרטין.","ro":"Al shem Martin.","lit":"sur · nom · Martin"},{"fr":"Voici la clé de ta chambre.","tgt":"הנה המפתח לחדר שלך.","ro":"Hine ha-mafte'akh la-kheder shelkha.","lit":"voici · [la]-clé · pour-[la]-chambre · [de]-toi"},{"fr":"La chambre est au troisième étage.","tgt":"החדר בקומה השלישית.","ro":"Ha-kheder ba-koma ha-shlishit.","lit":"[la]-chambre · à-[l']-étage · [le]-troisième"},{"fr":"Où est l'ascenseur ?","tgt":"איפה המעלית?","ro":"Eifo ha-ma'alit?","lit":"où · [l']-ascenseur ?"},{"fr":"Il y a Internet dans la chambre ?","tgt":"יש אינטרנט בחדר?","ro":"Yesh internet ba-kheder?","lit":"il-y-a · Internet · dans-[la]-chambre ?"},{"fr":"Le mot de passe est sur la carte.","tgt":"הסיסמה על הכרטיס.","ro":"Ha-sisma al ha-kartis.","lit":"[le]-mot-de-passe · sur · [la]-carte"},{"fr":"Le climatiseur ne marche pas.","tgt":"המזגן לא עובד.","ro":"Ha-mazgan lo oved.","lit":"[le]-climatiseur · ne-pas · travaille"},{"fr":"Pas de problème, on arrive tout de suite.","tgt":"אין בעיה, אנחנו באים מיד.","ro":"Ein be'aya, anakhnu ba'im miyad.","lit":"il-n'y-a-pas · problème · nous · venons · tout-de-suite"}]},{"title":"Qu'as-tu fait hier ?","phrases":[{"fr":"Hier, je suis allé à la vieille ville.","tgt":"אתמול הלכתי לעיר העתיקה.","ro":"Etmol halakhti la-ir ha-atika.","lit":"hier · suis-allé · à-[la]-ville · [l']-ancienne"},{"fr":"Tu es allé au marché ?","tgt":"הלכת לשוק?","ro":"Halakhta la-shuk?","lit":"es-allé · au-[le]-marché ?"},{"fr":"Oui, je suis allé au marché le matin.","tgt":"כן, הלכתי לשוק בבוקר.","ro":"Ken, halakhti la-shuk ba-boker.","lit":"oui · suis-allé · au-[le]-marché · dans-[le]-matin"},{"fr":"J'ai marché sur les remparts.","tgt":"הלכתי על החומות.","ro":"Halakhti al ha-khomot.","lit":"ai-marché · sur · [les]-remparts"},{"fr":"Tu as marché longtemps ?","tgt":"הלכת הרבה זמן?","ro":"Halakhta harbe zman?","lit":"as-marché · beaucoup · temps ?"},{"fr":"Trois heures, c'était super.","tgt":"שלוש שעות, היה מעולה.","ro":"Shalosh sha'ot, haya me'ule.","lit":"trois · heures · était · excellent"},{"fr":"Nous sommes allés à la plage.","tgt":"הלכנו לחוף.","ro":"Halakhnu la-khof.","lit":"sommes-allés · à-[la]-plage"},{"fr":"Et toi, Dana, où es-tu allée ?","tgt":"ואת, דנה, לאן הלכת?","ro":"Ve-at, Dana, le-an halakht?","lit":"et-toi · Dana · vers-où · es-allée ?"},{"fr":"J'ai mangé au marché.","tgt":"אכלתי בשוק.","ro":"Akhalti ba-shuk.","lit":"ai-mangé · dans-[le]-marché"},{"fr":"Je suis allé dormir tôt.","tgt":"הלכתי לישון מוקדם.","ro":"Halakhti lishon mukdam.","lit":"suis-allé · dormir · tôt"}],"tip":{"title":"Le passé : halakhti, halakhta","example":"Tu es allé au marché ? — <b>הלכת</b> לשוק?","body":"Pour parler au passé, l'hébreu ajoute une petite terminaison à la fin du verbe. Le verbe aller, ou marcher, se dit au passé « halakh », il est allé. Pour moi, on ajoute « ti » : « halakhti », je suis allé. Pour toi, on ajoute « ta » : « halakhta », tu es allé, et pour une femme on dit « halakht ». Pour nous, c'est « nu » : « halakhnu », nous sommes allés. Notre exemple, « Halakhta la-shuk ? », se lit mot à mot : es-allé, au-marché ? Pas besoin de dire « ata », toi : la terminaison suffit. La même recette marche avec d'autres verbes : « akhalti », j'ai mangé. Astuce : la fin en « ti » signe ce que j'ai fait moi-même, la fin en « ta » ce que tu as fait.","exampleRo":"Halakhta la-shuk?","lit":"es-allé · au-[le]-marché ?"}},{"title":"Massada au lever du soleil","phrases":[{"fr":"Massada est un site historique.","tgt":"מצדה היא אתר היסטורי.","ro":"Metsada hi atar histori.","lit":"Massada · elle · site · historique"},{"fr":"On monte à pied ou en téléphérique ?","tgt":"עולים ברגל או ברכבל?","ro":"Olim ba-regel o ba-rakhbal?","lit":"montons · à-[le]-pied · ou · en-[le]-téléphérique ?"},{"fr":"Le sentier commence ici.","tgt":"השביל מתחיל כאן.","ro":"Ha-shvil matkhil kan.","lit":"[le]-sentier · commence · ici"},{"fr":"Il est quatre heures du matin !","tgt":"עכשיו ארבע בבוקר!","ro":"Akhshav arba ba-boker!","lit":"maintenant · quatre · dans-[le]-matin !"},{"fr":"Il fait encore nuit.","tgt":"עדיין חושך.","ro":"Adayin khoshekh.","lit":"encore · obscurité"},{"fr":"Prends une lampe de poche.","tgt":"קח פנס.","ro":"Kakh panas.","lit":"prends · lampe"},{"fr":"Le lever du soleil est magnifique.","tgt":"הזריחה מדהימה.","ro":"Ha-zrikha madhima.","lit":"[le]-lever-du-soleil · magnifique"},{"fr":"En bas, on voit la mer Morte.","tgt":"למטה רואים את ים המלח.","ro":"Lemata ro'im et Yam ha-Melakh.","lit":"en-bas · voyons · [objet] · mer-de · [le]-sel"},{"fr":"Les ruines sont très impressionnantes.","tgt":"השרידים מרשימים מאוד.","ro":"Ha-sridim marshimim me'od.","lit":"[les]-vestiges · impressionnants · très"},{"fr":"On redescend en téléphérique.","tgt":"יורדים ברכבל.","ro":"Yordim ba-rakhbal.","lit":"descendons · en-[le]-téléphérique"}]},{"title":"Comment aller à Ein Gedi ?","phrases":[{"fr":"Comment on va à Ein Gedi ?","tgt":"איך מגיעים לעין גדי?","ro":"Ekh magi'im le-Ein Gedi?","lit":"comment · arrive-t-on · à-Ein Gedi ?"},{"fr":"En bus, depuis Jérusalem.","tgt":"באוטובוס, מירושלים.","ro":"Ba-otobus, mi-Yerushalayim.","lit":"en-[le]-bus · de-Jérusalem"},{"fr":"Comment ça se dit en hébreu ?","tgt":"איך אומרים את זה בעברית?","ro":"Ekh omrim et ze be-ivrit?","lit":"comment · dit-on · [objet] · ça · en-hébreu ?"},{"fr":"Comment va-t-on à la cascade ?","tgt":"איך מגיעים למפל?","ro":"Ekh magi'im la-mapal?","lit":"comment · arrive-t-on · à-[la]-cascade ?"},{"fr":"C'était comment, l'excursion ?","tgt":"איך היה הטיול?","ro":"Ekh haya ha-tiyul?","lit":"comment · était · [l']-excursion ?"},{"fr":"Super, il y a de l'eau partout.","tgt":"מעולה, יש מים בכל מקום.","ro":"Me'ule, yesh mayim be-khol makom.","lit":"excellent · il-y-a · eau · dans-tout · endroit"},{"fr":"Comment s'appelle ce sentier ?","tgt":"איך קוראים לשביל הזה?","ro":"Ekh kor'im la-shvil ha-ze?","lit":"comment · appelle-t-on · à-[le]-sentier · [le]-celui-ci ?"},{"fr":"C'est le ruisseau de David.","tgt":"זה נחל דוד.","ro":"Ze Nakhal David.","lit":"ce · ruisseau · David"},{"fr":"Comment tu te sens ?","tgt":"איך אתה מרגיש?","ro":"Ekh ata margish?","lit":"comment · toi · sens ?"},{"fr":"Fatigué, mais très content.","tgt":"עייף, אבל שמח מאוד.","ro":"Ayef, aval same'akh me'od.","lit":"fatigué · mais · content · très"}],"tip":{"title":"« Ekh » : comment, et comment aller","example":"Comment on va à Ein Gedi ? — <b>איך</b> <b>מגיעים</b> לעין גדי?","body":"« Ekh » veut dire comment, et il se place en tête de phrase. Pour demander son chemin, la formule la plus utile est « Ekh magi'im ? », mot à mot comment, arrive-t-on ? Notre exemple, « Ekh magi'im le-Ein Gedi ? », veut donc dire comment on va à Ein Gedi. On ne dit pas comment je vais, mais comment on arrive : c'est plus simple et ça marche pour tout le monde. On retrouve « ekh » partout : « Ekh haya ha-tiyul ? », comment était l'excursion, ou « Ekh ata margish ? », comment tu te sens. Et pour connaître un nom, on dit « Ekh kor'im la-shvil ha-ze ? », comment appelle-t-on ce sentier. Astuce : « ekh » ressemble à un petit cri d'étonnement, celui de quelqu'un qui cherche sa route.","exampleRo":"Ekh magi'im le-Ein Gedi?","lit":"comment · arrive-t-on · à-Ein Gedi ?"}},{"title":"La nature à Ein Gedi","phrases":[{"fr":"Regarde, un bouquetin !","tgt":"תראה, יעל!","ro":"Tir'e, ya'el!","lit":"regarde · bouquetin !"},{"fr":"Il y a beaucoup de bouquetins ici.","tgt":"יש פה הרבה יעלים.","ro":"Yesh po harbe ye'elim.","lit":"il-y-a · ici · beaucoup · bouquetins"},{"fr":"Ne donne pas à manger aux animaux.","tgt":"אל תאכיל את החיות.","ro":"Al ta'akhil et ha-khayot.","lit":"ne-pas · nourris · [objet] · [les]-animaux"},{"fr":"L'eau de la cascade est froide.","tgt":"המים במפל קרים.","ro":"Ha-mayim ba-mapal karim.","lit":"[les]-eaux · dans-[la]-cascade · froides"},{"fr":"Il y a des palmiers partout.","tgt":"יש דקלים בכל מקום.","ro":"Yesh dkalim be-khol makom.","lit":"il-y-a · palmiers · dans-tout · endroit"},{"fr":"C'est une vraie oasis.","tgt":"זה נווה מדבר אמיתי.","ro":"Ze neve midbar amiti.","lit":"ce · oasis-de · désert · vraie"},{"fr":"Le désert est tout autour.","tgt":"המדבר מסביב.","ro":"Ha-midbar misaviv.","lit":"[le]-désert · tout-autour"},{"fr":"J'ai soif.","tgt":"אני צמא.","ro":"Ani tsame.","lit":"moi · assoiffé"},{"fr":"Il y a un robinet près de l'entrée.","tgt":"יש ברז ליד הכניסה.","ro":"Yesh berez leyad ha-knisa.","lit":"il-y-a · robinet · à-côté-de · [l']-entrée"},{"fr":"Quelle belle nature !","tgt":"איזה טבע יפה!","ro":"Eize teva yafe!","lit":"quelle · nature · belle !"}]},{"title":"Une petite demande","phrases":[{"fr":"Je peux laisser mon sac ici ?","tgt":"אני יכול להשאיר את התיק פה?","ro":"Ani yakhol lehash'ir et ha-tik po?","lit":"moi · peux · laisser · [objet] · [le]-sac · ici ?"},{"fr":"Oui, tu peux.","tgt":"כן, אתה יכול.","ro":"Ken, ata yakhol.","lit":"oui · toi · peux"},{"fr":"Tu peux m'aider ?","tgt":"אתה יכול לעזור לי?","ro":"Ata yakhol la'azor li?","lit":"toi · peux · aider · [à moi] ?"},{"fr":"Bien sûr, avec grand plaisir.","tgt":"בטח, בכיף.","ro":"Betakh, be-kef.","lit":"bien-sûr · avec-plaisir"},{"fr":"Tu peux répéter, s'il te plaît ?","tgt":"אתה יכול לחזור על זה, בבקשה?","ro":"Ata yakhol lakhzor al ze, bevakasha?","lit":"toi · peux · revenir · sur · ça · s'il-te-plaît ?"},{"fr":"Je ne peux pas marcher vite.","tgt":"אני לא יכול ללכת מהר.","ro":"Ani lo yakhol lalekhet maher.","lit":"moi · ne-pas · peux · marcher · vite"},{"fr":"Dana, tu peux prendre une photo ?","tgt":"דנה, את יכולה לצלם?","ro":"Dana, at yekhola letsalem?","lit":"Dana · toi · peux · photographier ?"},{"fr":"On peut entrer gratuitement ?","tgt":"אפשר להיכנס בחינם?","ro":"Efshar lehikanes be-khinam?","lit":"possible · entrer · gratuitement ?"},{"fr":"Nous pouvons venir demain.","tgt":"אנחנו יכולים לבוא מחר.","ro":"Anakhnu yekholim lavo makhar.","lit":"nous · pouvons · venir · demain"},{"fr":"Pardon, je ne peux pas aujourd'hui.","tgt":"סליחה, אני לא יכול היום.","ro":"Slikha, ani lo yakhol hayom.","lit":"pardon · moi · ne-pas · peux · aujourd'hui"}],"tip":{"title":"« Yakhol » : pouvoir","example":"Tu peux m'aider ? — אתה <b>יכול</b> לעזור לי?","body":"« Yakhol » veut dire peut, et c'est la clé de toutes les demandes polies. Il change selon la personne : « yakhol » pour un homme, « yekhola » pour une femme, « yekholim » pour plusieurs. Notre exemple, « Ata yakhol la'azor li ? », se lit mot à mot : toi, peux, aider, à-moi ? Après « yakhol », on met un verbe à l'infinitif, comme en français : pouvoir aider, pouvoir venir. Pour dire non, on ajoute simplement « lo » devant : « Ani lo yakhol », je ne peux pas. Et pour une question générale, sans personne précise, on dit « efshar », c'est possible : « Efshar lehikanes ? », on peut entrer ? Astuce : avec « ata yakhol » ou « efshar », tu peux demander presque n'importe quoi en voyage.","exampleRo":"Ata yakhol la'azor li?","lit":"toi · peux · aider · [à moi] ?"}},{"title":"À la pharmacie","phrases":[{"fr":"J'ai vraiment mal à la tête.","tgt":"ממש כואב לי הראש.","ro":"Mamash ko'ev li ha-rosh.","lit":"vraiment · fait-mal · [à moi] · [la]-tête"},{"fr":"J'ai un coup de soleil.","tgt":"יש לי כוויה מהשמש.","ro":"Yesh li kviya me-ha-shemesh.","lit":"il-y-a · [à moi] · brûlure · de-[le]-soleil"},{"fr":"Tu as une crème pour ça ?","tgt":"יש לך קרם לזה?","ro":"Yesh lekha krem la-ze?","lit":"il-y-a · [à toi] · crème · pour-ça ?"},{"fr":"Oui, cette crème est très bonne.","tgt":"כן, הקרם הזה טוב מאוד.","ro":"Ken, ha-krem ha-ze tov me'od.","lit":"oui · [la]-crème · [la]-celle-ci · bonne · très"},{"fr":"Et j'ai aussi mal au ventre.","tgt":"וגם כואבת לי הבטן.","ro":"Ve-gam ko'evet li ha-beten.","lit":"et-aussi · fait-mal · [à moi] · [le]-ventre"},{"fr":"Tu as de la fièvre ?","tgt":"יש לך חום?","ro":"Yesh lekha khom?","lit":"il-y-a · [à toi] · fièvre ?"},{"fr":"Non, juste un peu.","tgt":"לא, רק קצת.","ro":"Lo, rak ktsat.","lit":"non · seulement · un-peu"},{"fr":"Un comprimé, trois fois par jour.","tgt":"כדור אחד, שלוש פעמים ביום.","ro":"Kadur ekhad, shalosh pe'amim ba-yom.","lit":"comprimé · un · trois · fois · dans-[le]-jour"},{"fr":"Avec de l'eau, après le repas.","tgt":"עם מים, אחרי האוכל.","ro":"Im mayim, akharei ha-okhel.","lit":"avec · eau · après · [la]-nourriture"},{"fr":"Prompt rétablissement !","tgt":"רפואה שלמה!","ro":"Refu'a shlema!","lit":"guérison · complète !"}]},{"title":"Des envies de vacances","phrases":[{"fr":"Je veux visiter Massada.","tgt":"אני רוצה לבקר במצדה.","ro":"Ani rotse levaker be-Metsada.","lit":"moi · veux · visiter · à-Massada"},{"fr":"Tu veux manger quelque chose ?","tgt":"אתה רוצה לאכול משהו?","ro":"Ata rotse le'ekhol mashehu?","lit":"toi · veux · manger · quelque-chose ?"},{"fr":"Oui, j'aime manger au marché.","tgt":"כן, אני אוהב לאכול בשוק.","ro":"Ken, ani ohev le'ekhol ba-shuk.","lit":"oui · moi · aime · manger · dans-[le]-marché"},{"fr":"Elle veut nager dans la mer.","tgt":"היא רוצה לשחות בים.","ro":"Hi rotsa liskhot ba-yam.","lit":"elle · veut · nager · dans-[la]-mer"},{"fr":"Nous voulons dormir un peu.","tgt":"אנחנו רוצים לישון קצת.","ro":"Anakhnu rotsim lishon ktsat.","lit":"nous · voulons · dormir · un-peu"},{"fr":"J'aime marcher dans la vieille ville.","tgt":"אני אוהב ללכת בעיר העתיקה.","ro":"Ani ohev lalekhet ba-ir ha-atika.","lit":"moi · aime · marcher · dans-[la]-ville · [l']-ancienne"},{"fr":"Il est interdit de fumer ici.","tgt":"אסור לעשן כאן.","ro":"Asur le'ashen kan.","lit":"interdit · fumer · ici"},{"fr":"On a le droit de prendre des photos ?","tgt":"מותר לצלם?","ro":"Mutar letsalem?","lit":"permis · photographier ?"},{"fr":"C'est difficile de trouver l'hôtel.","tgt":"קשה למצוא את המלון.","ro":"Kashe limtso et ha-malon.","lit":"difficile · trouver · [objet] · [l']-hôtel"},{"fr":"Parler hébreu, c'est amusant !","tgt":"כיף לדבר עברית!","ro":"Kef ledaber ivrit!","lit":"plaisir · parler · hébreu !"}],"tip":{"title":"« Le » + verbe : l'infinitif","example":"Tu veux manger quelque chose ? — אתה רוצה <b>לאכול</b> משהו?","body":"En français, l'infinitif se reconnaît à sa fin : manger, aller, dormir. En hébreu, il se reconnaît à son début : un petit « le », « li » ou « la » collé devant le verbe. On dit « le'ekhol », manger, « lishon », dormir, « lalekhet », marcher ou aller. Notre exemple, « Ata rotse le'ekhol mashehu ? », se lit mot à mot : toi, veux, manger, quelque-chose ? On l'utilise après « rotse », je veux, « ohev », j'aime, ou après des petits mots comme « asur », interdit, et « mutar », permis. « Asur le'ashen », il est interdit de fumer : deux mots seulement ! Et « Mutar letsalem ? » suffit pour demander si on peut prendre des photos. Astuce : le « le » de l'infinitif est comme une petite porte d'entrée, toujours placée devant le verbe.","exampleRo":"Ata rotse le'ekhol mashehu?","lit":"toi · veux · manger · quelque-chose ?"}},{"title":"Une valise perdue","phrases":[{"fr":"Ma valise n'est toujours pas arrivée.","tgt":"המזוודה שלי עדיין לא הגיעה.","ro":"Ha-mizvada sheli adayin lo hegi'a.","lit":"[la]-valise · [de]-moi · encore · ne-pas · est-arrivée"},{"fr":"Ta valise est de quelle couleur ?","tgt":"באיזה צבע המזוודה שלך?","ro":"Be-eize tseva ha-mizvada shelkha?","lit":"en-quelle · couleur · [la]-valise · [de]-toi ?"},{"fr":"Elle est grande et rouge.","tgt":"היא גדולה ואדומה.","ro":"Hi gdola ve-aduma.","lit":"elle · grande · et-rouge"},{"fr":"Voici mon numéro de vol.","tgt":"הנה מספר הטיסה שלי.","ro":"Hine mispar ha-tisa sheli.","lit":"voici · numéro-de · [le]-vol · [de]-moi"},{"fr":"On la cherche maintenant.","tgt":"אנחנו מחפשים אותה עכשיו.","ro":"Anakhnu mekhapsim ota akhshav.","lit":"nous · cherchons · elle · maintenant"},{"fr":"Tu as un numéro de téléphone ?","tgt":"יש לך מספר טלפון?","ro":"Yesh lekha mispar telefon?","lit":"il-y-a · [à toi] · numéro-de · téléphone ?"},{"fr":"Oui, voici mon numéro.","tgt":"כן, הנה המספר שלי.","ro":"Ken, hine ha-mispar sheli.","lit":"oui · voici · [le]-numéro · [de]-moi"},{"fr":"Je n'ai pas de vêtements !","tgt":"אין לי בגדים!","ro":"Ein li bgadim!","lit":"il-n'y-a-pas · [à moi] · vêtements !"},{"fr":"La valise arrive demain à l'hôtel.","tgt":"המזוודה מגיעה מחר למלון.","ro":"Ha-mizvada magi'a makhar la-malon.","lit":"[la]-valise · arrive · demain · à-[l']-hôtel"},{"fr":"Quel soulagement !","tgt":"איזו הקלה!","ro":"Eizo hakala!","lit":"quel · soulagement !"}]},{"title":"Petits imprévus","phrases":[{"fr":"J'ai besoin d'un taxi.","tgt":"אני צריך מונית.","ro":"Ani tsarikh monit.","lit":"moi · ai-besoin · taxi"},{"fr":"Tu as besoin d'aide ?","tgt":"אתה צריך עזרה?","ro":"Ata tsarikh ezra?","lit":"toi · as-besoin · aide ?"},{"fr":"Oui, j'ai besoin d'un chargeur.","tgt":"כן, אני צריך מטען.","ro":"Ken, ani tsarikh mit'an.","lit":"oui · moi · ai-besoin · chargeur"},{"fr":"Il faut changer de train.","tgt":"צריך להחליף רכבת.","ro":"Tsarikh lehakhlif rakevet.","lit":"il-faut · changer · train"},{"fr":"Il faut acheter un nouveau billet ?","tgt":"צריך לקנות כרטיס חדש?","ro":"Tsarikh liknot kartis khadash?","lit":"il-faut · acheter · billet · nouveau ?"},{"fr":"Dana a besoin d'un médecin.","tgt":"דנה צריכה רופא.","ro":"Dana tsrikha rofe.","lit":"Dana · a-besoin · médecin"},{"fr":"Il faut appeler l'hôtel.","tgt":"צריך להתקשר למלון.","ro":"Tsarikh lehitkasher la-malon.","lit":"il-faut · téléphoner · à-[l']-hôtel"},{"fr":"Nous avons besoin d'une chambre.","tgt":"אנחנו צריכים חדר.","ro":"Anakhnu tsrikhim kheder.","lit":"nous · avons-besoin · chambre"},{"fr":"Le bus est en retard.","tgt":"האוטובוס מאחר.","ro":"Ha-otobus me'akher.","lit":"[le]-bus · est-en-retard"},{"fr":"Il faut attendre un peu.","tgt":"צריך לחכות קצת.","ro":"Tsarikh lekhakot ktsat.","lit":"il-faut · attendre · un-peu"}],"tip":{"title":"« Tsarikh » : avoir besoin de, il faut","example":"Il faut changer de train. — <b>צריך</b> להחליף רכבת.","body":"« Tsarikh » a deux emplois très utiles en voyage. Avec un nom, il veut dire avoir besoin de : « Ani tsarikh monit », j'ai besoin d'un taxi. Il s'accorde : « tsrikha » pour une femme, « tsrikhim » pour plusieurs. Avec un verbe à l'infinitif, et sans personne devant, il veut dire il faut. Notre exemple, « Tsarikh lehakhlif rakevet », se lit mot à mot : il-faut, changer, train. Remarque qu'il n'y a ni « de » ni article : on change train, tout simplement. En question, c'est aussi facile : « Tsarikh liknot kartis ? », il faut acheter un billet ? Astuce : « tsarikh » tout seul en début de phrase, c'est le il faut des panneaux et des imprévus.","exampleRo":"Tsarikh lehakhlif rakevet.","lit":"il-faut · changer · train"}},{"title":"Le dernier jour du voyage","phrases":[{"fr":"C'est le dernier jour du voyage.","tgt":"זה היום האחרון של הטיול.","ro":"Ze ha-yom ha-akharon shel ha-tiyul.","lit":"ce · [le]-jour · [le]-dernier · [de] · [le]-voyage"},{"fr":"Je fais ma valise.","tgt":"אני אורז את המזוודה.","ro":"Ani orez et ha-mizvada.","lit":"moi · emballe · [objet] · [la]-valise"},{"fr":"Le vol part à midi.","tgt":"הטיסה יוצאת בצהריים.","ro":"Ha-tisa yotset ba-tsohorayim.","lit":"[le]-vol · sort · à-[le]-midi"},{"fr":"On rend la clé à la réception.","tgt":"מחזירים את המפתח בקבלה.","ro":"Makhzirim et ha-mafte'akh ba-kabala.","lit":"rendons · [objet] · [la]-clé · à-[la]-réception"},{"fr":"Le taxi attend dehors.","tgt":"המונית מחכה בחוץ.","ro":"Ha-monit mekhaka ba-khuts.","lit":"[le]-taxi · attend · dans-[le]-dehors"},{"fr":"J'ai des cadeaux pour la famille.","tgt":"יש לי מתנות למשפחה.","ro":"Yesh li matanot la-mishpakha.","lit":"il-y-a · [à moi] · cadeaux · pour-[la]-famille"},{"fr":"Des épices du marché Mahane Yehuda.","tgt":"תבלינים משוק מחנה יהודה.","ro":"Tavlinim mi-shuk Makhane Yehuda.","lit":"épices · de-marché-de · Mahane Yehuda"},{"fr":"Et du sel de la mer Morte.","tgt":"ומלח מים המלח.","ro":"U-melakh mi-Yam ha-Melakh.","lit":"et-sel · de-mer-de · [le]-sel"},{"fr":"Israël me manque déjà.","tgt":"אני כבר מתגעגע לישראל.","ro":"Ani kvar mitga'ge'a le-Yisra'el.","lit":"moi · déjà · m'ennuie · à-Israël"},{"fr":"Au revoir, Jérusalem !","tgt":"להתראות, ירושלים!","ro":"Lehitra'ot, Yerushalayim!","lit":"au-revoir · Jérusalem !"}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Demain, j'irai à l'aéroport.","tgt":"מחר אני אלך לשדה התעופה.","ro":"Makhar ani elekh li-sde ha-te'ufa.","lit":"demain · moi · irai · au-champ-de · [l']-aviation"},{"fr":"Ce soir, nous irons au marché.","tgt":"הערב נלך לשוק.","ro":"Ha-erev nelekh la-shuk.","lit":"[le]-soir · irons · au-[le]-marché"},{"fr":"Tu iras à la plage ?","tgt":"אתה תלך לחוף?","ro":"Ata telekh la-khof?","lit":"toi · iras · à-[la]-plage ?"},{"fr":"Dans ce module, on a beaucoup voyagé.","tgt":"במודול הזה טיילנו הרבה.","ro":"Ba-modul ha-ze tiyalnu harbe.","lit":"dans-[le]-module · [le]-celui-ci · avons-voyagé · beaucoup"},{"fr":"Tu parles déjà un peu hébreu.","tgt":"אתה כבר מדבר קצת עברית.","ro":"Ata kvar medaber ktsat ivrit.","lit":"toi · déjà · parles · un-peu · hébreu"},{"fr":"Maintenant, tu sais demander un prix.","tgt":"עכשיו אתה יודע לשאול מחיר.","ro":"Akhshav ata yode'a lish'ol mekhir.","lit":"maintenant · toi · sais · demander · prix"},{"fr":"Et tu sais demander ton chemin.","tgt":"ואתה יודע לשאול על הדרך.","ro":"Ve-ata yode'a lish'ol al ha-derekh.","lit":"et-toi · sais · demander · sur · [le]-chemin"},{"fr":"Au prochain module, on parlera avec les gens.","tgt":"במודול הבא נדבר עם אנשים.","ro":"Ba-modul ha-ba nedaber im anashim.","lit":"dans-[le]-module · [le]-suivant · parlerons · avec · gens"},{"fr":"Bravo, et merci !","tgt":"כל הכבוד, ותודה!","ro":"Kol ha-kavod, ve-toda!","lit":"tout · [l']-honneur · et-merci !"},{"fr":"Nous irons loin ensemble !","tgt":"נלך רחוק ביחד!","ro":"Nelekh rakhok beyakhad!","lit":"irons · loin · ensemble !"}],"tip":{"title":"Le futur : elekh, nelekh","example":"Ce soir, nous irons au marché. — הערב <b>נלך</b> לשוק.","body":"Au futur, l'hébreu change le début du verbe, et non la fin comme au passé. Le verbe aller donne « elekh », j'irai, avec un « e » au début. Pour nous, le début devient « n » : « nelekh », nous irons. Pour toi, c'est « t » : « telekh », tu iras. Notre exemple, « Ha-erev nelekh la-shuk », se lit mot à mot : le-soir, irons, au-marché. À l'oral, on garde souvent le pronom devant : « ani elekh », « ata telekh ». Et « Nelekh ? » tout seul sert aussi à proposer : on y va ? Astuce : retiens le trio « e » pour moi, « t » pour toi, « n » pour nous, et tu sauras déjà parler de tes prochains voyages.","exampleRo":"Ha-erev nelekh la-shuk.","lit":"[le]-soir · irons · au-[le]-marché"}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une rencontre au port de Haïfa","phrases":[{"fr":"Bonjour, tu habites à Haïfa ?","tgt":"שלום, אתה גר בחיפה?","ro":"Shalom, ata gar be-Kheifa?","lit":"paix · toi · habitant · à-Haïfa ?"},{"fr":"Oui, j'habite près du port.","tgt":"כן, אני גר ליד הנמל.","ro":"Ken, ani gar leyad ha-namal.","lit":"oui · moi · habitant · à-côté-de · [le]-port"},{"fr":"Le port est très beau ce soir.","tgt":"הנמל יפה מאוד הערב.","ro":"Ha-namal yafe me'od ha-erev.","lit":"[le]-port · beau · très · [le]-soir"},{"fr":"Tu es nouveau ici ?","tgt":"אתה חדש פה?","ro":"Ata khadash po?","lit":"toi · nouveau · ici ?"},{"fr":"Oui, je suis français.","tgt":"כן, אני צרפתי.","ro":"Ken, ani tsarfati.","lit":"oui · moi · français"},{"fr":"Je suis à Haïfa pour le travail.","tgt":"אני בחיפה בשביל העבודה.","ro":"Ani be-Kheifa bishvil ha-avoda.","lit":"moi · à-Haïfa · pour · [le]-travail"},{"fr":"Bienvenue chez nous, à Haïfa !","tgt":"ברוך הבא לחיפה!","ro":"Barukh ha-ba le-Kheifa!","lit":"béni · [le]-venant · à-Haïfa !"},{"fr":"Merci, la ville est très agréable.","tgt":"תודה, העיר מאוד נעימה.","ro":"Toda, ha-ir me'od ne'ima.","lit":"merci · [le]-ville · très · agréable"},{"fr":"Tu bois un café avec moi ?","tgt":"אתה שותה איתי קפה?","ro":"Ata shote iti kafe?","lit":"toi · buvant · avec-moi · café ?"},{"fr":"Oui, avec joie !","tgt":"כן, בשמחה!","ro":"Ken, be-simkha!","lit":"oui · avec-joie !"}]},{"title":"Se présenter","phrases":[{"fr":"Comment tu t'appelles, toi ?","tgt":"איך קוראים לך?","ro":"Eikh kor'im lekha?","lit":"comment · on-appelle · à-toi ?"},{"fr":"Je m'appelle Daniel.","tgt":"קוראים לי דניאל.","ro":"Kor'im li Daniel.","lit":"on-appelle · à-moi · Daniel"},{"fr":"Et elle, comment elle s'appelle ?","tgt":"ואיך קוראים לה?","ro":"Ve-eikh kor'im la?","lit":"[et]-comment · on-appelle · à-elle ?"},{"fr":"Elle s'appelle Noa, c'est ma collègue.","tgt":"קוראים לה נועה, היא קולגה שלי.","ro":"Kor'im la No'a, hi kolega sheli.","lit":"on-appelle · à-elle · Noa · elle · collègue · [de]-moi"},{"fr":"Enchanté, Noa.","tgt":"נעים מאוד, נועה.","ro":"Na'im me'od, No'a.","lit":"agréable · très · Noa"},{"fr":"Et moi, je m'appelle Tamar.","tgt":"ולי קוראים תמר.","ro":"Ve-li kor'im Tamar.","lit":"[et]-à-moi · on-appelle · Tamar"},{"fr":"Comment s'appelle ton chef ?","tgt":"איך קוראים למנהל שלך?","ro":"Eikh kor'im la-menahel shelkha?","lit":"comment · on-appelle · à-[le]-directeur · [de]-toi ?"},{"fr":"Il s'appelle Yossi.","tgt":"קוראים לו יוסי.","ro":"Kor'im lo Yossi.","lit":"on-appelle · à-lui · Yossi"},{"fr":"Moi, c'est Daniel, de Paris.","tgt":"אני דניאל, מפריז.","ro":"Ani Daniel, mi-Pariz.","lit":"moi · Daniel · de-Paris"},{"fr":"Ravi de faire ta connaissance.","tgt":"נעים להכיר.","ro":"Na'im lehakir.","lit":"agréable · connaître"}],"tip":{"title":"Se présenter : kor'im li","example":"Je m'appelle Daniel. — <b>קוראים</b> <b>לי</b> דניאל.","body":"Pour dire son prénom, on dit « kor'im li », suivi du prénom. Mot à mot, cela signifie « on appelle à moi » : il n'y a pas de verbe « s'appeler » comme en français, on dit simplement que les gens m'appellent ainsi. Par exemple, « kor'im li Daniel » veut dire je m'appelle Daniel. Pour poser la question, on ajoute « eikh », comment, au début : « eikh kor'im lekha ? » à un homme, et « eikh kor'im lakh ? » à une femme. Seul le petit mot de la fin change : « li » pour moi, « lekha » pour toi, « lo » pour lui, « la » pour elle. Ainsi, « kor'im la No'a » signifie elle s'appelle Noa. Pour répondre poliment, on ajoute « na'im me'od », très agréable, qui correspond à notre enchanté. Astuce : imaginez des amis qui courent vers vous en criant votre prénom, « kor'im li », on m'appelle !","exampleRo":"Kor'im li Daniel.","lit":"on-appelle · à-moi · Daniel"}},{"title":"D'où viens-tu ?","phrases":[{"fr":"Tu es d'où, toi ?","tgt":"מאיפה אתה?","ro":"Me'eifo ata?","lit":"d'où · toi ?"},{"fr":"Je viens de Lyon.","tgt":"אני מליון.","ro":"Ani mi-Lyon.","lit":"moi · de-Lyon"},{"fr":"Et toi, tu es de Haïfa ?","tgt":"ואתה מחיפה?","ro":"Ve-ata mi-Kheifa?","lit":"[et]-toi · de-Haïfa ?"},{"fr":"Oui, ma famille est d'ici.","tgt":"כן, המשפחה שלי מפה.","ro":"Ken, ha-mishpakha sheli mi-po.","lit":"oui · [le]-famille · [de]-moi · d'ici"},{"fr":"Tu habites dans quel quartier ?","tgt":"באיזו שכונה אתה גר?","ro":"Be-eizo shkhuna ata gar?","lit":"dans-quel · quartier · toi · habitant ?"},{"fr":"J'habite sur le mont Carmel.","tgt":"אני גר בכרמל.","ro":"Ani gar ba-Karmel.","lit":"moi · habitant · dans-[le]-Carmel"},{"fr":"C'est un quartier calme et vert.","tgt":"זאת שכונה שקטה וירוקה.","ro":"Zot shkhuna shketa ve-yeruka.","lit":"ceci · quartier · calme · [et]-verte"},{"fr":"Mon amie habite à Bat Galim.","tgt":"החברה שלי גרה בבת גלים.","ro":"Ha-khavera sheli gara be-Bat Galim.","lit":"[le]-amie · [de]-moi · habitante · à-Bat-Galim"},{"fr":"C'est près de la mer ?","tgt":"זה קרוב לים?","ro":"Ze karov la-yam?","lit":"ceci · proche · à-[le]-mer ?"},{"fr":"Oui, à cinq minutes à pied.","tgt":"כן, חמש דקות ברגל.","ro":"Ken, khamesh dakot ba-regel.","lit":"oui · cinq · minutes · à-[le]-pied"}]},{"title":"Ce que j'aime","phrases":[{"fr":"J'aime le café.","tgt":"אני אוהב קפה.","ro":"Ani ohev kafe.","lit":"moi · aimant · café"},{"fr":"Noa aime le thé à la menthe.","tgt":"נועה אוהבת תה עם נענע.","ro":"No'a ohevet te im nana.","lit":"Noa · aimante · thé · avec · menthe"},{"fr":"Tu aimes le houmous ?","tgt":"אתה אוהב חומוס?","ro":"Ata ohev khumus?","lit":"toi · aimant · houmous ?"},{"fr":"Oui, j'en suis fou !","tgt":"כן, אני מת על זה!","ro":"Ken, ani met al ze!","lit":"oui · moi · mort · sur · ceci !"},{"fr":"Et toi, Tamar, tu aimes la mer ?","tgt":"ואת, תמר, אוהבת את הים?","ro":"Ve-at, Tamar, ohevet et ha-yam?","lit":"[et]-toi · Tamar · aimante · [objet] · [le]-mer ?"},{"fr":"Oui, j'aime beaucoup la mer.","tgt":"כן, אני מאוד אוהבת את הים.","ro":"Ken, ani me'od ohevet et ha-yam.","lit":"oui · moi · très · aimante · [objet] · [le]-mer"},{"fr":"Mon collègue n'aime pas le café.","tgt":"הקולגה שלי לא אוהב קפה.","ro":"Ha-kolega sheli lo ohev kafe.","lit":"[le]-collègue · [de]-moi · ne-pas · aimant · café"},{"fr":"Elle aime les fleurs.","tgt":"היא אוהבת פרחים.","ro":"Hi ohevet prakhim.","lit":"elle · aimante · fleurs"},{"fr":"Nous aimons le Carmel.","tgt":"אנחנו אוהבים את הכרמל.","ro":"Anakhnu ohavim et ha-Karmel.","lit":"nous · aimants · [objet] · [le]-Carmel"},{"fr":"Il aime Haïfa le soir.","tgt":"הוא אוהב את חיפה בערב.","ro":"Hu ohev et Kheifa ba-erev.","lit":"lui · aimant · [objet] · Haïfa · dans-[le]-soir"}],"tip":{"title":"« Ohev » et « ohevet » : aimer","example":"Noa aime le thé à la menthe. — נועה <b>אוהבת</b> תה עם נענע.","body":"Le verbe aimer se dit « ohev » quand c'est un homme qui parle, et « ohevet » quand c'est une femme. Au présent, le verbe ne change pas selon je, tu ou il, mais selon qu'on parle d'un homme ou d'une femme. Un homme dit « ani ohev kafe », mot à mot moi aimant café, et une femme dit « ani ohevet kafe ». De la même façon, on dit « hu ohev » pour lui et « hi ohevet » pour elle. Au pluriel, on dit « ohavim », comme dans « anakhnu ohavim et ha-Karmel », nous aimons le Carmel. Pour poser une question, il suffit de faire monter la voix à la fin : « ata ohev khumus ? », tu aimes le houmous ? Pour dire qu'on n'aime pas, on place « lo » devant : « lo ohev ». Astuce : la finale « -et » est une marque féminine très fréquente, retenez-la comme une signature au féminin.","exampleRo":"No'a ohevet te im nana.","lit":"Noa · aimante · thé · avec · menthe"}},{"title":"Au café sur le Carmel","phrases":[{"fr":"Est-ce que cette table est libre ?","tgt":"השולחן הזה פנוי?","ro":"Ha-shulkhan ha-ze panui?","lit":"[le]-table · [le]-ceci · libre ?"},{"fr":"Oui, vas-y, assieds-toi.","tgt":"כן, שב.","ro":"Ken, shev.","lit":"oui · assieds-toi"},{"fr":"Qu'est-ce que tu bois, toi ?","tgt":"מה אתה שותה?","ro":"Ma ata shote?","lit":"quoi · toi · buvant ?"},{"fr":"Un café noir, s'il te plaît.","tgt":"קפה שחור, בבקשה.","ro":"Kafe shakhor, bevakasha.","lit":"café · noir · s'il-te-plaît"},{"fr":"Et pour moi, une limonade.","tgt":"ובשבילי לימונדה.","ro":"U-vishvili limonada.","lit":"[et]-pour-moi · limonade"},{"fr":"La vue d'ici est étonnante.","tgt":"הנוף מפה מדהים.","ro":"Ha-nof mi-po madhim.","lit":"[le]-vue · d'ici · étonnant"},{"fr":"On voit tout le port.","tgt":"רואים את כל הנמל.","ro":"Ro'im et kol ha-namal.","lit":"voyant · [objet] · tout · [le]-port"},{"fr":"Le café ici est très bon.","tgt":"הקפה פה טוב מאוד.","ro":"Ha-kafe po tov me'od.","lit":"[le]-café · ici · bon · très"},{"fr":"Tu veux aussi un gâteau ?","tgt":"אתה רוצה גם עוגה?","ro":"Ata rotse gam uga?","lit":"toi · voulant · aussi · gâteau ?"},{"fr":"Non merci, ça me suffit.","tgt":"לא תודה, זה מספיק.","ro":"Lo toda, ze maspik.","lit":"non · merci · ceci · suffisant"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Tu as des frères et sœurs, toi ?","tgt":"יש לך אחים?","ro":"Yesh lekha akhim?","lit":"il-y-a · à-toi · frères ?"},{"fr":"Oui, j'ai un frère et aussi une sœur.","tgt":"כן, יש לי אח וגם אחות.","ro":"Ken, yesh li akh ve-gam akhot.","lit":"oui · il-y-a · à-moi · frère · [et]-aussi · sœur"},{"fr":"Mon frère habite à Tel Aviv.","tgt":"האח שלי גר בתל אביב.","ro":"Ha-akh sheli gar be-Tel Aviv.","lit":"[le]-frère · [de]-moi · habitant · à-Tel-Aviv"},{"fr":"Ma sœur est étudiante à Haïfa.","tgt":"האחות שלי סטודנטית בחיפה.","ro":"Ha-akhot sheli studentit be-Kheifa.","lit":"[le]-sœur · [de]-moi · étudiante · à-Haïfa"},{"fr":"Mon père est médecin.","tgt":"אבא שלי רופא.","ro":"Aba sheli rofe.","lit":"papa · [de]-moi · médecin"},{"fr":"Et ta mère, qu'est-ce qu'elle fait ?","tgt":"ומה אמא שלך עושה?","ro":"U-ma ima shelkha osa?","lit":"[et]-quoi · maman · [de]-toi · faisant ?"},{"fr":"Ma mère est professeure.","tgt":"אמא שלי מורה.","ro":"Ima sheli mora.","lit":"maman · [de]-moi · professeure"},{"fr":"Mes parents habitent près du port.","tgt":"ההורים שלי גרים ליד הנמל.","ro":"Ha-horim sheli garim leyad ha-namal.","lit":"[le]-parents · [de]-moi · habitants · à-côté-de · [le]-port"},{"fr":"Ta famille est grande ?","tgt":"המשפחה שלך גדולה?","ro":"Ha-mishpakha shelkha gdola?","lit":"[le]-famille · [de]-toi · grande ?"},{"fr":"Non, nous sommes quatre.","tgt":"לא, אנחנו ארבעה.","ro":"Lo, anakhnu arba'a.","lit":"non · nous · quatre"}],"tip":{"title":"La famille : aba, ima, akh, akhot","example":"Mon père est médecin. — <b>אבא</b> שלי רופא.","body":"Bonne nouvelle, les mots de la famille sont courts et faciles à dire. Papa se dit « aba » et maman « ima », exactement comme le diraient de petits enfants. Le frère se dit « akh » et la sœur « akhot », avec ce son « kh » qui se prononce au fond de la gorge, comme un « r » français bien frotté. Pour dire mon père, on dit simplement « aba sheli », papa de moi, sans article devant. Pour le frère et la sœur, en revanche, on ajoute « ha », le : « ha-akh sheli », mon frère, et « ha-akhot sheli », ma sœur. Les parents, ce sont « ha-horim », et la famille tout entière, « ha-mishpakha ». Par exemple, « ima sheli mora » veut dire ma mère est professeure, mot à mot maman de moi professeure, sans verbe être. Astuce : « akhot » ressemble à « akh » avec juste « -ot » en plus, comme une petite sœur qui suit son frère partout.","exampleRo":"Aba sheli rofe.","lit":"papa · [de]-moi · médecin"}},{"title":"Les collègues au travail","phrases":[{"fr":"Voici Avi, mon collègue.","tgt":"זה אבי, הקולגה שלי.","ro":"Ze Avi, ha-kolega sheli.","lit":"ceci · Avi · [le]-collègue · [de]-moi"},{"fr":"Il travaille avec moi au bureau.","tgt":"הוא עובד איתי במשרד.","ro":"Hu oved iti ba-misrad.","lit":"lui · travaillant · avec-moi · dans-[le]-bureau"},{"fr":"Le bureau est à côté du port.","tgt":"המשרד ליד הנמל.","ro":"Ha-misrad leyad ha-namal.","lit":"[le]-bureau · à-côté-de · [le]-port"},{"fr":"Tu travailles ici depuis longtemps ?","tgt":"אתה עובד פה הרבה זמן?","ro":"Ata oved po harbe zman?","lit":"toi · travaillant · ici · beaucoup · temps ?"},{"fr":"Non, je suis nouveau dans l'équipe.","tgt":"לא, אני חדש בצוות.","ro":"Lo, ani khadash ba-tsevet.","lit":"non · moi · nouveau · dans-[le]-équipe"},{"fr":"L'équipe est très sympa.","tgt":"הצוות נחמד מאוד.","ro":"Ha-tsevet nekhmad me'od.","lit":"[le]-équipe · sympathique · très"},{"fr":"On mange ensemble à midi ?","tgt":"אוכלים ביחד בצהריים?","ro":"Okhlim be-yakhad ba-tsohorayim?","lit":"mangeant · ensemble · dans-[le]-midi ?"},{"fr":"Oui, il y a un bon restaurant en bas.","tgt":"כן, יש מסעדה טובה למטה.","ro":"Ken, yesh mis'ada tova le-mata.","lit":"oui · il-y-a · restaurant · bon · en-bas"},{"fr":"Avi est toujours de bonne humeur.","tgt":"אבי תמיד במצב רוח טוב.","ro":"Avi tamid be-matsav ru'akh tov.","lit":"Avi · toujours · dans-état · esprit · bon"},{"fr":"Mon travail est intéressant.","tgt":"העבודה שלי מעניינת.","ro":"Ha-avoda sheli me'anyenet.","lit":"[le]-travail · [de]-moi · intéressant"}]},{"title":"Mon nom, ma maison","phrases":[{"fr":"Je m'appelle Yonatan.","tgt":"שמי יונתן.","ro":"Shmi Yonatan.","lit":"nom-de-moi · Yonatan"},{"fr":"Et ton nom, c'est quoi ?","tgt":"מה שמך?","ro":"Ma shimkha?","lit":"quoi · nom-de-toi ?"},{"fr":"Comment vas-tu, Avi ?","tgt":"מה שלומך, אבי?","ro":"Ma shlomkha, Avi?","lit":"quoi · paix-de-toi · Avi ?"},{"fr":"Et toi, Noa, comment vas-tu ?","tgt":"ומה שלומך, נועה?","ro":"U-ma shlomekh, No'a?","lit":"[et]-quoi · paix-de-toi · Noa ?"},{"fr":"Ma femme s'appelle Michal.","tgt":"לאשתי קוראים מיכל.","ro":"Le-ishti kor'im Mikhal.","lit":"à-femme-de-moi · on-appelle · Michal"},{"fr":"Mon mari travaille au port.","tgt":"בעלי עובד בנמל.","ro":"Ba'ali oved ba-namal.","lit":"mari-de-moi · travaillant · dans-[le]-port"},{"fr":"Ma maison est ta maison.","tgt":"ביתי הוא ביתך.","ro":"Beiti hu beitkha.","lit":"maison-de-moi · lui · maison-de-toi"},{"fr":"Viens avec moi au café.","tgt":"בוא איתי לבית הקפה.","ro":"Bo iti le-veit ha-kafe.","lit":"viens · avec-moi · à-maison-de · [le]-café"},{"fr":"Mon ami habite sur le Carmel.","tgt":"חברי גר בכרמל.","ro":"Khaveri gar ba-Karmel.","lit":"ami-de-moi · habitant · dans-[le]-Carmel"},{"fr":"Ma famille vit à Haïfa.","tgt":"משפחתי גרה בחיפה.","ro":"Mishpakhti gara be-Kheifa.","lit":"famille-de-moi · habitante · à-Haïfa"}],"tip":{"title":"Les possessifs collés : shmi, beiti","example":"Je m'appelle Yonatan. — <b>שמי</b> יונתן.","body":"En hébreu, on peut coller le possessif directement à la fin du mot. « Shem » veut dire nom, et « shmi » veut dire mon nom ; « bayit » veut dire maison, et « beiti » ma maison. La terminaison « -i » signifie à moi, et « -kha » signifie à toi quand on parle à un homme, comme dans « shimkha », ton nom. Dans la conversation de tous les jours, on dit plus souvent « ha-bayit sheli », la maison de moi, mais les formes collées restent très vivantes dans les formules toutes faites. La plus célèbre est « ma shlomkha ? », comment vas-tu, mot à mot quoi paix de toi ; à une femme, on dit « ma shlomekh ? ». Pour se présenter de façon un peu soignée, « shmi Yonatan » est parfait. On entend aussi « ishti », ma femme, et « ba'ali », mon mari. Astuce : le petit « i » final, c'est vous, comme un doigt pointé vers soi.","exampleRo":"Shmi Yonatan.","lit":"nom-de-moi · Yonatan"}},{"title":"Les jardins en terrasses","phrases":[{"fr":"Tu connais les jardins en terrasses ?","tgt":"אתה מכיר את הגנים המדורגים?","ro":"Ata makir et ha-ganim ha-medoragim?","lit":"toi · connaissant · [objet] · [le]-jardins · [le]-en-terrasses ?"},{"fr":"Oui, ils sont magnifiques.","tgt":"כן, הם מדהימים.","ro":"Ken, hem madhimim.","lit":"oui · eux · étonnants"},{"fr":"On y va ensemble demain ?","tgt":"הולכים מחר ביחד?","ro":"Holkhim makhar be-yakhad?","lit":"allant · demain · ensemble ?"},{"fr":"Bonne idée, le matin c'est mieux.","tgt":"רעיון טוב, בבוקר יותר טוב.","ro":"Ra'ayon tov, ba-boker yoter tov.","lit":"idée · bonne · dans-[le]-matin · plus · bon"},{"fr":"Le matin, il fait moins chaud.","tgt":"בבוקר פחות חם.","ro":"Ba-boker pakhot kham.","lit":"dans-[le]-matin · moins · chaud"},{"fr":"D'en haut, on voit toute la ville.","tgt":"מלמעלה רואים את כל העיר.","ro":"Mi-lemala ro'im et kol ha-ir.","lit":"d'en-haut · voyant · [objet] · toute · [le]-ville"},{"fr":"Il y a énormément de fleurs.","tgt":"יש הרבה פרחים.","ro":"Yesh harbe prakhim.","lit":"il-y-a · beaucoup · fleurs"},{"fr":"L'entrée des jardins est gratuite.","tgt":"הכניסה לגנים בחינם.","ro":"Ha-knisa la-ganim be-khinam.","lit":"[le]-entrée · à-[le]-jardins · gratuitement"},{"fr":"Il y a beaucoup de marches !","tgt":"יש הרבה מדרגות!","ro":"Yesh harbe madregot!","lit":"il-y-a · beaucoup · marches !"},{"fr":"Pas grave, on descend doucement.","tgt":"לא נורא, יורדים לאט.","ro":"Lo nora, yordim le'at.","lit":"pas · terrible · descendant · lentement"}]},{"title":"Comparer","phrases":[{"fr":"Haïfa est plus calme que Tel Aviv.","tgt":"חיפה יותר שקטה מתל אביב.","ro":"Kheifa yoter shketa mi-Tel Aviv.","lit":"Haïfa · plus · calme · que-Tel-Aviv"},{"fr":"Le Carmel est plus vert que le centre.","tgt":"הכרמל יותר ירוק מהמרכז.","ro":"Ha-Karmel yoter yarok me-ha-merkaz.","lit":"[le]-Carmel · plus · vert · que-[le]-centre"},{"fr":"Mon frère est plus grand que moi.","tgt":"אחי יותר גבוה ממני.","ro":"Akhi yoter gavoha mimeni.","lit":"frère-de-moi · plus · grand · que-moi"},{"fr":"Tu préfères le thé ou le café ?","tgt":"אתה מעדיף תה או קפה?","ro":"Ata ma'adif te o kafe?","lit":"toi · préférant · thé · ou · café ?"},{"fr":"Pour moi, le café est meilleur que le thé.","tgt":"בשבילי קפה יותר טוב מתה.","ro":"Bishvili kafe yoter tov mi-te.","lit":"pour-moi · café · plus · bon · que-thé"},{"fr":"Ce café-là est moins cher.","tgt":"בית הקפה הזה יותר זול.","ro":"Beit ha-kafe ha-ze yoter zol.","lit":"maison-de · [le]-café · [le]-ceci · plus · bon-marché"},{"fr":"Ma sœur est plus jeune que mon frère.","tgt":"אחותי יותר צעירה מאחי.","ro":"Akhoti yoter tse'ira me-akhi.","lit":"sœur-de-moi · plus · jeune · que-frère-de-moi"},{"fr":"La Carmelit est plus rapide que le bus.","tgt":"הכרמלית יותר מהירה מהאוטובוס.","ro":"Ha-Karmelit yoter mehira me-ha-otobus.","lit":"[le]-Carmelit · plus · rapide · que-[le]-bus"},{"fr":"C'est le plus beau quartier de la ville.","tgt":"זאת השכונה הכי יפה בעיר.","ro":"Zot ha-shkhuna hakhi yafa ba-ir.","lit":"ceci · [le]-quartier · le-plus · beau · dans-[le]-ville"},{"fr":"Sur la montagne, il fait plus frais.","tgt":"על ההר יותר קריר.","ro":"Al ha-har yoter karir.","lit":"sur · [le]-montagne · plus · frais"}],"tip":{"title":"Comparer : yoter... mi-","example":"Haïfa est plus calme que Tel Aviv. — חיפה <b>יותר</b> שקטה <b>מתל</b> אביב.","body":"Pour comparer, on place « yoter », plus, devant l'adjectif, puis « mi- », que, collé au mot suivant. Ainsi, « Kheifa yoter shketa mi-Tel Aviv » veut dire Haïfa est plus calme que Tel Aviv, mot à mot Haïfa plus calme que-Tel-Aviv, toujours sans verbe être. Devant un mot qui commence par l'article, on entend « me-ha », comme dans « me-ha-merkaz », que le centre. Pour dire que moi, on dit « mimeni », et pour que toi, « mimkha ». Le contraire de « yoter » est « pakhot », moins : « pakhot kham », moins chaud. Et pour dire le plus, on utilise « hakhi » : « ha-shkhuna hakhi yafa », le plus beau quartier. L'adjectif garde son accord habituel, au masculin ou au féminin. Astuce : retenez le trio « yoter », « pakhot », « hakhi », plus, moins, le plus, et vous pourrez comparer tout ce que vous voyez à Haïfa.","exampleRo":"Kheifa yoter shketa mi-Tel Aviv.","lit":"Haïfa · plus · calme · que-Tel-Aviv"}},{"title":"Parler de son métier","phrases":[{"fr":"Tu fais quoi dans la vie, toi ?","tgt":"מה אתה עושה בחיים?","ro":"Ma ata ose ba-khayim?","lit":"quoi · toi · faisant · dans-[le]-vie ?"},{"fr":"Je suis ingénieur.","tgt":"אני מהנדס.","ro":"Ani mehandes.","lit":"moi · ingénieur"},{"fr":"Je travaille dans la high-tech.","tgt":"אני עובד בהייטק.","ro":"Ani oved be-haitek.","lit":"moi · travaillant · dans-high-tech"},{"fr":"Et toi, Michal, tu travailles où ?","tgt":"ואת, מיכל, איפה את עובדת?","ro":"Ve-at, Mikhal, eifo at ovedet?","lit":"[et]-toi · Michal · où · toi · travaillante ?"},{"fr":"Je suis infirmière à l'hôpital.","tgt":"אני אחות בבית החולים.","ro":"Ani akhot be-veit ha-kholim.","lit":"moi · infirmière · dans-maison-de · [le]-malades"},{"fr":"C'est un travail difficile ?","tgt":"זאת עבודה קשה?","ro":"Zot avoda kasha?","lit":"ceci · travail · difficile ?"},{"fr":"Oui, mais j'aime beaucoup ça.","tgt":"כן, אבל אני מאוד אוהבת את זה.","ro":"Ken, aval ani me'od ohevet et ze.","lit":"oui · mais · moi · très · aimante · [objet] · ceci"},{"fr":"Tu travailles le vendredi ?","tgt":"אתה עובד בימי שישי?","ro":"Ata oved be-yemei shishi?","lit":"toi · travaillant · dans-jours-de · sixième ?"},{"fr":"Non, le vendredi je suis libre.","tgt":"לא, ביום שישי אני חופשי.","ro":"Lo, be-yom shishi ani khofshi.","lit":"non · dans-jour · sixième · moi · libre"},{"fr":"Mon bureau est au centre-ville.","tgt":"המשרד שלי במרכז העיר.","ro":"Ha-misrad sheli be-merkaz ha-ir.","lit":"[le]-bureau · [de]-moi · dans-centre-de · [le]-ville"}]},{"title":"Expliquer pourquoi","phrases":[{"fr":"Pourquoi tu es fatigué ?","tgt":"למה אתה עייף?","ro":"Lama ata ayef?","lit":"pourquoi · toi · fatigué ?"},{"fr":"Parce que je travaille beaucoup.","tgt":"כי אני עובד הרבה.","ro":"Ki ani oved harbe.","lit":"parce-que · moi · travaillant · beaucoup"},{"fr":"Je suis en retard à cause du bus.","tgt":"אני מאחר בגלל האוטובוס.","ro":"Ani me'akher biglal ha-otobus.","lit":"moi · en-retard · à-cause-de · [le]-bus"},{"fr":"J'aime Haïfa parce qu'il y a la mer.","tgt":"אני אוהב את חיפה כי יש ים.","ro":"Ani ohev et Kheifa ki yesh yam.","lit":"moi · aimant · [objet] · Haïfa · parce-que · il-y-a · mer"},{"fr":"Et aussi à cause de la montagne.","tgt":"וגם בגלל ההר.","ro":"Ve-gam biglal ha-har.","lit":"[et]-aussi · à-cause-de · [le]-montagne"},{"fr":"Elle ne vient pas, parce qu'elle est malade.","tgt":"היא לא באה, כי היא חולה.","ro":"Hi lo ba'a, ki hi khola.","lit":"elle · ne-pas · venante · parce-que · elle · malade"},{"fr":"On reste à la maison à cause de la pluie.","tgt":"נשארים בבית בגלל הגשם.","ro":"Nish'arim ba-bayit biglal ha-geshem.","lit":"restant · dans-[le]-maison · à-cause-de · [le]-pluie"},{"fr":"Je prends du thé, parce que c'est déjà le soir.","tgt":"אני שותה תה, כי כבר ערב.","ro":"Ani shote te, ki kvar erev.","lit":"moi · buvant · thé · parce-que · déjà · soir"},{"fr":"Pourquoi tu aimes ce café ?","tgt":"למה אתה אוהב את בית הקפה הזה?","ro":"Lama ata ohev et beit ha-kafe ha-ze?","lit":"pourquoi · toi · aimant · [objet] · maison-de · [le]-café · [le]-ceci ?"},{"fr":"À cause de la vue sur le port.","tgt":"בגלל הנוף לנמל.","ro":"Biglal ha-nof la-namal.","lit":"à-cause-de · [le]-vue · vers-[le]-port"}],"tip":{"title":"« Ki » et « biglal » : parce que","example":"Parce que je travaille beaucoup. — <b>כי</b> אני עובד הרבה.","body":"Pour donner une raison, l'hébreu a deux petits mots très utiles. « Ki » veut dire parce que, et il est suivi d'une phrase complète : « ki ani oved harbe », parce que je travaille beaucoup, mot à mot parce-que moi travaillant beaucoup. « Biglal » veut dire à cause de, et il est suivi d'un simple nom : « biglal ha-geshem », à cause de la pluie. La règle est donc simple : après « ki », une phrase avec quelqu'un qui fait quelque chose, après « biglal », une chose. Pour poser la question, on dit « lama ? », pourquoi ? On peut répondre très court, juste « biglal ha-nof », à cause de la vue. « Ki » se prononce exactement comme notre mot « qui ». Astuce : « ki » est court comme une phrase qui démarre vite, et « biglal » est plus long, comme un nom bien posé derrière lui.","exampleRo":"Ki ani oved harbe.","lit":"parce-que · moi · travaillant · beaucoup"}},{"title":"Une invitation au dîner du vendredi","phrases":[{"fr":"Vendredi soir, tu es libre ?","tgt":"אתה פנוי ביום שישי בערב?","ro":"Ata panui be-yom shishi ba-erev?","lit":"toi · libre · dans-jour · sixième · dans-[le]-soir ?"},{"fr":"Oui, pourquoi ?","tgt":"כן, למה?","ro":"Ken, lama?","lit":"oui · pourquoi ?"},{"fr":"Viens dîner chez nous.","tgt":"בוא לארוחת ערב אצלנו.","ro":"Bo le-arukhat erev etslenu.","lit":"viens · à-repas-de · soir · chez-nous"},{"fr":"Toute la famille vient.","tgt":"כל המשפחה באה.","ro":"Kol ha-mishpakha ba'a.","lit":"toute · [le]-famille · venante"},{"fr":"C'est vraiment gentil, merci !","tgt":"זה מאוד נחמד, תודה!","ro":"Ze me'od nekhmad, toda!","lit":"ceci · très · gentil · merci !"},{"fr":"Et c'est à quelle heure ?","tgt":"באיזו שעה?","ro":"Be-eizo sha'a?","lit":"dans-quelle · heure ?"},{"fr":"Vers sept heures.","tgt":"בסביבות שבע.","ro":"Bi-svivot sheva.","lit":"dans-environs · sept"},{"fr":"Vous habitez où exactement ?","tgt":"איפה אתם גרים?","ro":"Eifo atem garim?","lit":"où · vous · habitants ?"},{"fr":"À Hadar, près du marché.","tgt":"בהדר, ליד השוק.","ro":"Be-Hadar, leyad ha-shuk.","lit":"à-Hadar · à-côté-de · [le]-marché"},{"fr":"Parfait, alors à vendredi !","tgt":"מעולה, אז ביום שישי!","ro":"Me'ule, az be-yom shishi!","lit":"excellent · alors · dans-jour · sixième !"}]},{"title":"Ce qu'on apporte","phrases":[{"fr":"Tu connais ma sœur ?","tgt":"אתה מכיר את אחותי?","ro":"Ata makir et akhoti?","lit":"toi · connaissant · [objet] · sœur-de-moi ?"},{"fr":"Je ne connais pas encore ta famille.","tgt":"אני עוד לא מכיר את המשפחה שלך.","ro":"Ani od lo makir et ha-mishpakha shelkha.","lit":"moi · encore · ne-pas · connaissant · [objet] · [le]-famille · [de]-toi"},{"fr":"J'apporte le vin.","tgt":"אני מביא את היין.","ro":"Ani mevi et ha-yayin.","lit":"moi · apportant · [objet] · [le]-vin"},{"fr":"Noa apporte des fleurs.","tgt":"נועה מביאה פרחים.","ro":"No'a mevi'a prakhim.","lit":"Noa · apportante · fleurs"},{"fr":"Ma mère prépare le dîner.","tgt":"אמא שלי מכינה את ארוחת הערב.","ro":"Ima sheli mekhina et arukhat ha-erev.","lit":"maman · [de]-moi · préparante · [objet] · repas-de · [le]-soir"},{"fr":"Tu vois la maison bleue ?","tgt":"אתה רואה את הבית הכחול?","ro":"Ata ro'e et ha-bayit ha-kakhol?","lit":"toi · voyant · [objet] · [le]-maison · [le]-bleue ?"},{"fr":"Je cherche l'arrêt de bus.","tgt":"אני מחפש את התחנה.","ro":"Ani mekhapes et ha-takhana.","lit":"moi · cherchant · [objet] · [le]-arrêt"},{"fr":"Tu aimes la cuisine de ma mère ?","tgt":"אתה אוהב את האוכל של אמא שלי?","ro":"Ata ohev et ha-okhel shel ima sheli?","lit":"toi · aimant · [objet] · [le]-nourriture · [de] · maman · [de]-moi ?"},{"fr":"Tu me passes le pain, s'il te plaît ?","tgt":"תעביר לי את הלחם, בבקשה?","ro":"Ta'avir li et ha-lekhem, bevakasha?","lit":"tu-passeras · à-moi · [objet] · [le]-pain · s'il-te-plaît ?"},{"fr":"Je ne vois pas Daniel.","tgt":"אני לא רואה את דניאל.","ro":"Ani lo ro'e et Daniel.","lit":"moi · ne-pas · voyant · [objet] · Daniel"}],"tip":{"title":"« Et » : la petite marque de l'objet défini","example":"J'apporte le vin. — אני מביא <b>את</b> היין.","body":"Voici une particularité qui n'existe pas en français : le petit mot « et », qui se place devant l'objet quand cet objet est précis. Il ne se traduit pas, il signale simplement : attention, voici la chose précise dont on parle. On dit « ani mevi et ha-yayin », j'apporte le vin, mot à mot moi apportant objet le-vin. Mais si l'on parle de vin en général, sans article, « et » disparaît : « ani mevi yayin », j'apporte du vin. On le met aussi devant un prénom, comme dans « ani lo ro'e et Daniel », je ne vois pas Daniel, et devant un mot avec mon ou ton, comme « et akhoti », ma sœur. Il se prononce « ète », sans aucun rapport avec notre « et » français. Astuce : pensez à « et » comme à une petite flèche qui pointe vers la chose précise que vous avez en tête.","exampleRo":"Ani mevi et ha-yayin.","lit":"moi · apportant · [objet] · [le]-vin"}},{"title":"Offrir un cadeau","phrases":[{"fr":"On apporte quoi comme cadeau ?","tgt":"מה מביאים במתנה?","ro":"Ma mevi'im be-matana?","lit":"quoi · apportant · en-cadeau ?"},{"fr":"Une bouteille de vin, c'est bien.","tgt":"בקבוק יין זה טוב.","ro":"Bakbuk yayin ze tov.","lit":"bouteille · vin · ceci · bon"},{"fr":"Ou peut-être des fleurs ?","tgt":"או אולי פרחים?","ro":"O ulai prakhim?","lit":"ou · peut-être · fleurs ?"},{"fr":"Les fleurs, c'est pour la maman.","tgt":"הפרחים בשביל אמא.","ro":"Ha-prakhim bishvil ima.","lit":"[le]-fleurs · pour · maman"},{"fr":"Ce cadeau est pour toi.","tgt":"המתנה הזאת בשבילך.","ro":"Ha-matana ha-zot bishvilkha.","lit":"[le]-cadeau · [le]-ceci · pour-toi"},{"fr":"Merci beaucoup, il ne fallait pas !","tgt":"תודה רבה, אין צורך!","ro":"Toda raba, ein tsorekh!","lit":"merci · nombreuse · il-n'y-a-pas · besoin !"},{"fr":"C'est un petit souvenir de France.","tgt":"זאת מזכרת קטנה מצרפת.","ro":"Zot mazkeret ktana mi-Tsarfat.","lit":"ceci · souvenir · petit · de-France"},{"fr":"Quel joli cadeau !","tgt":"איזו מתנה יפה!","ro":"Eizo matana yafa!","lit":"quel · cadeau · joli !"},{"fr":"Les gâteaux sont pour le dessert.","tgt":"העוגות בשביל הקינוח.","ro":"Ha-ugot bishvil ha-kinu'akh.","lit":"[le]-gâteaux · pour · [le]-dessert"},{"fr":"Ma mère fait les meilleurs gâteaux.","tgt":"אמא שלי עושה את העוגות הכי טובות.","ro":"Ima sheli osa et ha-ugot hakhi tovot.","lit":"maman · [de]-moi · faisante · [objet] · [le]-gâteaux · le-plus · bons"}]},{"title":"Un, deux, beaucoup","phrases":[{"fr":"J'ai deux frères.","tgt":"יש לי שני אחים.","ro":"Yesh li shnei akhim.","lit":"il-y-a · à-moi · deux · frères"},{"fr":"Et trois sœurs.","tgt":"ושלוש אחיות.","ro":"Ve-shalosh akhayot.","lit":"[et]-trois · sœurs"},{"fr":"Mes amis sont très gentils.","tgt":"החברים שלי מאוד נחמדים.","ro":"Ha-khaverim sheli me'od nekhmadim.","lit":"[le]-amis · [de]-moi · très · gentils"},{"fr":"Mes amies sont étudiantes.","tgt":"החברות שלי סטודנטיות.","ro":"Ha-khaverot sheli studentiyot.","lit":"[le]-amies · [de]-moi · étudiantes"},{"fr":"Il y a beaucoup de restaurants au port.","tgt":"יש הרבה מסעדות בנמל.","ro":"Yesh harbe mis'adot ba-namal.","lit":"il-y-a · beaucoup · restaurants · dans-[le]-port"},{"fr":"Les jardins sont très beaux.","tgt":"הגנים מאוד יפים.","ro":"Ha-ganim me'od yafim.","lit":"[le]-jardins · très · beaux"},{"fr":"Le soir, les rues sont calmes.","tgt":"הרחובות שקטים בערב.","ro":"Ha-rekhovot shketim ba-erev.","lit":"[le]-rues · calmes · dans-[le]-soir"},{"fr":"Les enfants jouent dans le parc.","tgt":"הילדים משחקים בפארק.","ro":"Ha-yeladim mesakhakim ba-park.","lit":"[le]-enfants · jouant · dans-[le]-parc"},{"fr":"Les filles aiment la plage.","tgt":"הבנות אוהבות את החוף.","ro":"Ha-banot ohavot et ha-khof.","lit":"[le]-filles · aimantes · [objet] · [le]-plage"},{"fr":"Il y a de nouveaux cafés sur le Carmel.","tgt":"יש בתי קפה חדשים בכרמל.","ro":"Yesh batei kafe khadashim ba-Karmel.","lit":"il-y-a · maisons-de · café · nouveaux · dans-[le]-Carmel"}],"tip":{"title":"Le pluriel : -im et -ot","example":"Mes amies sont étudiantes. — <b>החברות</b> שלי <b>סטודנטיות</b>.","body":"Le pluriel en hébreu est très régulier et s'entend bien. Les mots masculins prennent en général « -im » : « khaver », ami, devient « khaverim », et « gan », jardin, devient « ganim ». Les mots féminins, souvent terminés par « -a », prennent « -ot » : « khavera » devient « khaverot », et « mis'ada », restaurant, devient « mis'adot ». L'adjectif suit le nom et s'accorde lui aussi, par exemple « ha-ganim yafim », les jardins sont beaux, mot à mot les-jardins beaux. Quelques mots trichent, comme « rekhov », rue, qui fait « rekhovot » au pluriel tout en restant masculin : on dit donc « ha-rekhovot shketim », avec un adjectif en « -im ». La famille a aussi ses surprises : « akh » devient « akhim », et « akhot » devient « akhayot ». Astuce : « -im » pour les garçons, « -ot » pour les filles, et écoutez toujours l'adjectif, c'est lui qui dit la vérité.","exampleRo":"Ha-khaverot sheli studentiyot.","lit":"[le]-amies · [de]-moi · étudiantes"}},{"title":"Le dîner en famille","phrases":[{"fr":"Bon appétit à tous !","tgt":"בתיאבון לכולם!","ro":"Be-te'avon le-khulam!","lit":"avec-appétit · à-tous !"},{"fr":"Tout a l'air délicieux.","tgt":"הכול נראה טעים.","ro":"Ha-kol nir'e ta'im.","lit":"[le]-tout · semblant · délicieux"},{"fr":"Tu veux encore du riz ?","tgt":"אתה רוצה עוד אורז?","ro":"Ata rotse od orez?","lit":"toi · voulant · encore · riz ?"},{"fr":"Oui, avec plaisir, c'est très bon.","tgt":"כן, בשמחה, זה טעים מאוד.","ro":"Ken, be-simkha, ze ta'im me'od.","lit":"oui · avec-joie · ceci · délicieux · très"},{"fr":"C'est la recette de ta grand-mère ?","tgt":"זה המתכון של סבתא שלך?","ro":"Ze ha-matkon shel savta shelkha?","lit":"ceci · [le]-recette · [de] · mamie · [de]-toi ?"},{"fr":"Oui, ma grand-mère cuisine très bien.","tgt":"כן, סבתא שלי מבשלת מעולה.","ro":"Ken, savta sheli mevashelet me'ule.","lit":"oui · mamie · [de]-moi · cuisinante · excellent"},{"fr":"Le vendredi, toute la famille mange ensemble.","tgt":"בימי שישי כל המשפחה אוכלת ביחד.","ro":"Be-yemei shishi kol ha-mishpakha okhelet be-yakhad.","lit":"dans-jours-de · sixième · toute · [le]-famille · mangeante · ensemble"},{"fr":"C'est une belle habitude.","tgt":"זה מנהג יפה.","ro":"Ze minhag yafe.","lit":"ceci · coutume · belle"},{"fr":"Ton grand-père parle français ?","tgt":"סבא שלך מדבר צרפתית?","ro":"Saba shelkha medaber tsarfatit?","lit":"papi · [de]-toi · parlant · français ?"},{"fr":"Un peu, il adore Paris.","tgt":"קצת, הוא מאוד אוהב את פריז.","ro":"Ktsat, hu me'od ohev et Pariz.","lit":"un-peu · lui · très · aimant · [objet] · Paris"}]},{"title":"Ce que j'aime faire","phrases":[{"fr":"J'aime marcher au bord de la mer.","tgt":"אני אוהב ללכת ליד הים.","ro":"Ani ohev lalekhet leyad ha-yam.","lit":"moi · aimant · marcher · à-côté-de · [le]-mer"},{"fr":"Tu aimes cuisiner ?","tgt":"אתה אוהב לבשל?","ro":"Ata ohev levashel?","lit":"toi · aimant · cuisiner ?"},{"fr":"Oui, j'aime cuisiner pour mes amis.","tgt":"כן, אני אוהב לבשל לחברים שלי.","ro":"Ken, ani ohev levashel la-khaverim sheli.","lit":"oui · moi · aimant · cuisiner · pour-[le]-amis · [de]-moi"},{"fr":"Michal aime lire au café.","tgt":"מיכל אוהבת לקרוא בבית קפה.","ro":"Mikhal ohevet likro be-veit kafe.","lit":"Michal · aimante · lire · dans-maison-de · café"},{"fr":"Nous aimons nager le matin.","tgt":"אנחנו אוהבים לשחות בבוקר.","ro":"Anakhnu ohavim liskhot ba-boker.","lit":"nous · aimants · nager · dans-[le]-matin"},{"fr":"Je n'aime pas me lever tôt.","tgt":"אני לא אוהב לקום מוקדם.","ro":"Ani lo ohev lakum mukdam.","lit":"moi · ne-pas · aimant · se-lever · tôt"},{"fr":"Et toi, Noa, qu'est-ce que tu aimes faire ?","tgt":"ומה את אוהבת לעשות, נועה?","ro":"U-ma at ohevet la'asot, No'a?","lit":"[et]-quoi · toi · aimante · faire · Noa ?"},{"fr":"J'aime danser et chanter.","tgt":"אני אוהבת לרקוד ולשיר.","ro":"Ani ohevet lirkod ve-lashir.","lit":"moi · aimante · danser · [et]-chanter"},{"fr":"Mon père aime jardiner.","tgt":"אבא שלי אוהב לעבוד בגינה.","ro":"Aba sheli ohev la'avod ba-gina.","lit":"papa · [de]-moi · aimant · travailler · dans-[le]-jardin"},{"fr":"Nous aimons nous balader sur le Carmel.","tgt":"אנחנו אוהבים לטייל בכרמל.","ro":"Anakhnu ohavim letayel ba-Karmel.","lit":"nous · aimants · se-promener · dans-[le]-Carmel"}],"tip":{"title":"Aimer faire quelque chose : ani ohev li-","example":"Tu aimes cuisiner ? — אתה <b>אוהב</b> <b>לבשל</b>?","body":"Pour dire qu'on aime faire quelque chose, on garde « ani ohev » ou « ani ohevet », et on ajoute simplement un verbe à l'infinitif. En hébreu, l'infinitif commence presque toujours par « le- », « li- » ou « la- » : « levashel », cuisiner, « liskhot », nager, « lirkod », danser. On dit donc « ani ohev levashel », mot à mot moi aimant cuisiner, exactement dans le même ordre qu'en français. Une femme dira « ani ohevet lirkod », j'aime danser. Pour poser la question, on dit « ma ata ohev la'asot ? », qu'est-ce que tu aimes faire ? Pour la négation, on glisse « lo » devant : « ani lo ohev lakum mukdam », je n'aime pas me lever tôt. Astuce : quand vous entendez « le » ou « li » juste après « ohev », c'est le signal qu'une action arrive.","exampleRo":"Ata ohev levashel?","lit":"toi · aimant · cuisiner ?"}},{"title":"Se dire au revoir après le dîner","phrases":[{"fr":"Il est déjà tard.","tgt":"כבר מאוחר.","ro":"Kvar me'ukhar.","lit":"déjà · tard"},{"fr":"Merci pour cette belle soirée.","tgt":"תודה על הערב היפה.","ro":"Toda al ha-erev ha-yafe.","lit":"merci · sur · [le]-soir · [le]-beau"},{"fr":"Ta mère cuisine merveilleusement.","tgt":"אמא שלך מבשלת נהדר.","ro":"Ima shelkha mevashelet nehedar.","lit":"maman · [de]-toi · cuisinante · merveilleux"},{"fr":"Reviens quand tu veux.","tgt":"תחזור מתי שאתה רוצה.","ro":"Takhzor matai she-ata rotse.","lit":"tu-reviendras · quand · que-toi · voulant"},{"fr":"Avec plaisir, et la prochaine fois, c'est chez moi.","tgt":"בשמחה, בפעם הבאה אצלי.","ro":"Be-simkha, ba-pa'am ha-ba'a etsli.","lit":"avec-joie · dans-[le]-fois · [le]-prochaine · chez-moi"},{"fr":"Et toi, tu rentres comment ?","tgt":"ואיך אתה חוזר הביתה?","ro":"Ve-eikh ata khozer ha-bayta?","lit":"[et]-comment · toi · revenant · à-la-maison ?"},{"fr":"Je prends un taxi.","tgt":"אני לוקח מונית.","ro":"Ani lokeakh monit.","lit":"moi · prenant · taxi"},{"fr":"Bonne nuit à tous !","tgt":"לילה טוב לכולם!","ro":"Laila tov le-khulam!","lit":"nuit · bonne · à-tous !"},{"fr":"Rentre prudemment.","tgt":"סע בזהירות.","ro":"Sa bi-zehirut.","lit":"roule · avec-prudence"},{"fr":"On se revoit la semaine prochaine !","tgt":"להתראות בשבוע הבא!","ro":"Lehitra'ot ba-shavua ha-ba!","lit":"se-revoir · dans-[le]-semaine · [le]-prochaine !"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Allez, on y va !","tgt":"יאללה, הולכים!","ro":"Yalla, holkhim!","lit":"allez · allant !"},{"fr":"Demain à huit heures, ça te va ?","tgt":"מחר בשמונה, בסדר?","ro":"Makhar bi-shmone, beseder?","lit":"demain · à-huit · en-ordre ?"},{"fr":"Oui, c'est d'accord pour moi.","tgt":"כן, בסדר לי.","ro":"Ken, beseder li.","lit":"oui · en-ordre · à-moi"},{"fr":"Cool, c'est parfait !","tgt":"סבבה, מעולה!","ro":"Sababa, me'ule!","lit":"cool · excellent !"},{"fr":"Maintenant, je peux me présenter en hébreu.","tgt":"עכשיו אני יכול להציג את עצמי בעברית.","ro":"Akhshav ani yakhol lehatsig et atsmi be-ivrit.","lit":"maintenant · moi · pouvant · présenter · [objet] · moi-même · en-hébreu"},{"fr":"Je parle de ma famille et de mon travail.","tgt":"אני מדבר על המשפחה ועל העבודה שלי.","ro":"Ani medaber al ha-mishpakha ve-al ha-avoda sheli.","lit":"moi · parlant · sur · [le]-famille · [et]-sur · [le]-travail · [de]-moi"},{"fr":"Je sais dire ce que j'aime.","tgt":"אני יודע להגיד מה אני אוהב.","ro":"Ani yode'a lehagid ma ani ohev.","lit":"moi · sachant · dire · quoi · moi · aimant"},{"fr":"L'hébreu devient de plus en plus facile.","tgt":"עברית זה יותר ויותר קל.","ro":"Ivrit ze yoter ve-yoter kal.","lit":"hébreu · ceci · plus · [et]-plus · facile"},{"fr":"Tout est cool !","tgt":"הכול סבבה!","ro":"Ha-kol sababa!","lit":"[le]-tout · cool !"},{"fr":"Allez, à la prochaine leçon !","tgt":"יאללה, לשיעור הבא!","ro":"Yalla, la-shi'ur ha-ba!","lit":"allez · à-[le]-leçon · [le]-prochaine !"}],"tip":{"title":"« Yalla », « sababa », « beseder » : les mots de la conversation","example":"Allez, on y va ! — <b>יאללה</b>, הולכים!","body":"Trois petits mots vous feront sonner comme un vrai habitant de Haïfa. « Yalla » veut dire allez, on y va, ou dépêche-toi : on l'entend partout, pour partir, pour commencer ou pour encourager. « Sababa » veut dire cool, super, pas de souci ; à la question « ma nishma ? », quoi de neuf, on répond très souvent « sababa ». « Beseder » veut dire d'accord ou ça va, mot à mot en ordre, et « ha-kol beseder » signifie tout va bien. Par exemple, « yalla, holkhim », mot à mot allez allant, veut dire allez, on y va. On les combine volontiers : « yalla, beseder », allez, d'accord. « Sababa » est familier, gardez-le pour les amis et les collègues proches, alors que « beseder » passe partout. Astuce : « beseder » rassure, « sababa » détend, et « yalla » fait avancer.","exampleRo":"Yalla, holkhim!","lit":"allez · allant !"}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un appartement à Tel Aviv","phrases":[{"fr":"Nous avons enfin trouvé un appartement à Tel Aviv.","tgt":"סוף סוף מצאנו דירה בתל אביב.","ro":"Sof sof matsanu dira be-Tel Aviv."},{"fr":"Il est au troisième étage, sans ascenseur.","tgt":"היא בקומה השלישית, בלי מעלית.","ro":"Hi ba-koma ha-shlishit, bli ma'alit."},{"fr":"Le propriétaire nous a montré toutes les pièces.","tgt":"בעל הבית הראה לנו את כל החדרים.","ro":"Ba'al ha-bayit her'a lanu et kol ha-khadarim."},{"fr":"Le loyer est de cinq mille shekels par mois.","tgt":"שכר הדירה הוא חמשת אלפים שקל לחודש.","ro":"Skhar ha-dira hu khameshet alafim shekel la-khodesh."},{"fr":"Le bail est d'un an, avec une option de prolongation.","tgt":"החוזה לשנה, עם אופציה להארכה.","ro":"Ha-khoze le-shana, im optsiya le-ha'arakha."},{"fr":"Il faut aussi deux garants.","tgt":"צריך גם שני ערבים.","ro":"Tsarikh gam shnei arevim."},{"fr":"La cuisine est petite mais très lumineuse.","tgt":"המטבח קטן אבל מאוד מואר.","ro":"Ha-mitbakh katan aval me'od mu'ar."},{"fr":"Le balcon donne sur la mer ?","tgt":"המרפסת פונה לים?","ro":"Ha-mirpeset pona la-yam?"},{"fr":"Non, mais on voit un peu la mer depuis le toit.","tgt":"לא, אבל רואים קצת ים מהגג.","ro":"Lo, aval ro'im ktsat yam me-ha-gag."},{"fr":"On signe demain matin chez l'agent immobilier.","tgt":"אנחנו חותמים מחר בבוקר אצל המתווך.","ro":"Anakhnu khotmim makhar ba-boker etsel ha-metavekh."}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Je voudrais ouvrir un compte à la banque.","tgt":"אני רוצה לפתוח חשבון בבנק.","ro":"Ani rotse liftoakh kheshbon ba-bank."},{"fr":"À quelle heure ouvre l'agence ?","tgt":"באיזו שעה הסניף נפתח?","ro":"Be-eizo sha'a ha-snif niftakh?"},{"fr":"Elle ouvre à huit heures et demie et ferme à une heure.","tgt":"הוא נפתח בשמונה וחצי ונסגר באחת.","ro":"Hu niftakh be-shmone va-khetsi ve-nisgar be-akhat."},{"fr":"L'employée m'a ouvert un compte en dix minutes.","tgt":"הפקידה פתחה לי חשבון בעשר דקות.","ro":"Ha-pkida patkha li kheshbon be-eser dakot."},{"fr":"Elle a calculé les frais avec moi.","tgt":"היא חישבה איתי את העמלות.","ro":"Hi khishva iti et ha-amlot."},{"fr":"Je pense que c'est un peu cher.","tgt":"אני חושב שזה קצת יקר.","ro":"Ani khoshev she-ze ktsat yakar."},{"fr":"Je paie le loyer par virement chaque mois.","tgt":"אני משלם את שכר הדירה בהעברה בנקאית כל חודש.","ro":"Ani meshalem et skhar ha-dira be-ha'avara bankait kol khodesh."},{"fr":"L'application ne s'ouvre pas sur mon téléphone.","tgt":"האפליקציה לא נפתחת לי בטלפון.","ro":"Ha-aplikatsya lo niftakhat li ba-telefon."},{"fr":"J'ai fermé l'application et maintenant elle marche.","tgt":"סגרתי את האפליקציה ועכשיו היא עובדת.","ro":"Sagarti et ha-aplikatsya ve-akhshav hi ovedet."},{"fr":"Le conseiller m'apprend à utiliser le site.","tgt":"היועץ מלמד אותי להשתמש באתר.","ro":"Ha-yo'ets melamed oti lehishtamesh ba-atar."}],"tip":{"title":"Les groupes de verbes : une racine, plusieurs sens","example":"À quelle heure ouvre l'agence ? — באיזו שעה הסניף <b>נפתח</b>?","body":"En hébreu, presque tous les verbes reposent sur une racine de trois consonnes, et cette racine change de sens selon le moule dans lequel on la coule. Avec la racine p, t, kh, « patakh » veut dire il a ouvert, quelqu'un ouvre quelque chose, alors que « niftakh » veut dire il s'est ouvert, exactement comme notre verbe pronominal. Dans « ha-snif niftakh », mot à mot l'agence s'ouvre, personne n'ouvre rien : le petit son « ni » du début fait le travail de notre « se ». De la même façon, « sagar » c'est il a fermé, et « nisgar » c'est il s'est fermé. Une autre racine, kh, sh, v, donne « khoshev », je pense, « mekhashev », je calcule, et même « kheshbon », le compte en banque. Astuce : quand vous entendez « ni » devant une racine que vous connaissez, pensez tout de suite à un verbe en « se ».","exampleRo":"Be-eizo sha'a ha-snif niftakh?","lit":"dans-quelle · heure · [le]-agence · s'ouvre ?"}},{"title":"La caisse maladie et la clinique","phrases":[{"fr":"Je dois m'inscrire à une caisse maladie.","tgt":"אני צריך להירשם לקופת חולים.","ro":"Ani tsarikh leherashem le-kupat kholim."},{"fr":"La clinique du quartier est juste à côté.","tgt":"המרפאה של השכונה ממש ליד.","ro":"Ha-mirpa'a shel ha-shkhuna mamash leyad."},{"fr":"J'ai pris rendez-vous chez le médecin de famille.","tgt":"קבעתי תור לרופא המשפחה.","ro":"Kavati tor le-rofe ha-mishpakha."},{"fr":"La secrétaire m'a demandé ma carte d'identité.","tgt":"המזכירה ביקשה ממני תעודת זהות.","ro":"Ha-mazkira bikesha mimeni te'udat zehut."},{"fr":"La doctoresse ne reçoit que le matin.","tgt":"הרופאה מקבלת רק בבוקר.","ro":"Ha-rof'a mekabelet rak ba-boker."},{"fr":"Depuis quand as-tu de la fièvre ?","tgt":"ממתי יש לך חום?","ro":"Me-matai yesh lekha khom?"},{"fr":"Depuis hier soir, et j'ai mal à la tête.","tgt":"מאתמול בערב, וכואב לי הראש.","ro":"Me-etmol ba-erev, ve-ko'ev li ha-rosh."},{"fr":"Elle m'a donné une ordonnance pour des antibiotiques.","tgt":"היא נתנה לי מרשם לאנטיביוטיקה.","ro":"Hi natna li mirsham le-antibiyotika."},{"fr":"Je dois aussi faire une prise de sang.","tgt":"אני צריך לעשות גם בדיקת דם.","ro":"Ani tsarikh la'asot gam bdikat dam."},{"fr":"Les résultats arriveront dans l'application.","tgt":"התוצאות יגיעו באפליקציה.","ro":"Ha-totsa'ot yagi'u ba-aplikatsya."}]},{"title":"À la pharmacie","phrases":[{"fr":"Bonjour, j'ai une ordonnance de la clinique.","tgt":"שלום, יש לי מרשם מהמרפאה.","ro":"Shalom, yesh li mirsham me-ha-mirpa'a."},{"fr":"Vous êtes membre de quelle caisse maladie ?","tgt":"באיזו קופת חולים אתה חבר?","ro":"Be-eizo kupat kholim ata khaver?"},{"fr":"Le médicament coûte vingt shekels avec la réduction.","tgt":"התרופה עולה עשרים שקל עם ההנחה.","ro":"Ha-trufa ola esrim shekel im ha-hanakha."},{"fr":"Combien de fois par jour faut-il le prendre ?","tgt":"כמה פעמים ביום צריך לקחת אותה?","ro":"Kama pe'amim ba-yom tsarikh lakakhat ota?"},{"fr":"Trois fois par jour, après le repas.","tgt":"שלוש פעמים ביום, אחרי האוכל.","ro":"Shalosh pe'amim ba-yom, akharei ha-okhel."},{"fr":"Avez-vous quelque chose contre la toux ?","tgt":"יש לך משהו נגד שיעול?","ro":"Yesh lekha mashehu neged shi'ul?"},{"fr":"Ce sirop est très efficace pour les enfants.","tgt":"הסירופ הזה מאוד יעיל לילדים.","ro":"Ha-sirop ha-ze me'od ya'il li-yeladim."},{"fr":"Je cherche aussi de la crème solaire.","tgt":"אני מחפש גם קרם הגנה.","ro":"Ani mekhapes gam krem hagana."},{"fr":"Elle est sur l'étagère près de la caisse.","tgt":"הוא על המדף ליד הקופה.","ro":"Hu al ha-madaf leyad ha-kupa."},{"fr":"Je vous souhaite un prompt rétablissement.","tgt":"רפואה שלמה!","ro":"Refu'a shlema!"}]},{"title":"Hier au bureau","phrases":[{"fr":"Hier, j'ai travaillé jusqu'à huit heures du soir.","tgt":"אתמול עבדתי עד שמונה בערב.","ro":"Etmol avadti ad shmone ba-erev."},{"fr":"Tu as fini le rapport pour le client ?","tgt":"סיימת את הדוח בשביל הלקוח?","ro":"Siyamta et ha-dokh bishvil ha-lako'akh?"},{"fr":"Oui, je l'ai envoyé avant la réunion.","tgt":"כן, שלחתי אותו לפני הישיבה.","ro":"Ken, shalakhti oto lifnei ha-yeshiva."},{"fr":"Dana a préparé la présentation toute seule.","tgt":"דנה הכינה את המצגת לבד.","ro":"Dana hekhina et ha-matseget levad."},{"fr":"Nous avons mangé ensemble à la cafétéria.","tgt":"אכלנו יחד בקפיטריה.","ro":"Akhalnu yakhad ba-kafeterya."},{"fr":"Les collègues ont beaucoup ri pendant le déjeuner.","tgt":"הקולגות צחקו הרבה בארוחת הצהריים.","ro":"Ha-kolegot tsakhaku harbe be-arukhat ha-tsohorayim."},{"fr":"Et toi, Noa, qu'as-tu fait hier ?","tgt":"ואת, נועה, מה עשית אתמול?","ro":"Ve-at, No'a, ma asit etmol?"},{"fr":"J'ai travaillé de la maison toute la journée.","tgt":"עבדתי מהבית כל היום.","ro":"Avadti me-ha-bayit kol ha-yom."},{"fr":"Vous avez parlé avec le directeur ?","tgt":"דיברתם עם המנהל?","ro":"Dibartem im ha-menahel?"},{"fr":"Oui, et il a accepté notre idée.","tgt":"כן, והוא הסכים לרעיון שלנו.","ro":"Ken, ve-hu hiskim la-ra'ayon shelanu."}],"tip":{"title":"Le passé à toutes les personnes","example":"Nous avons mangé ensemble à la cafétéria. — <b>אכלנו</b> יחד בקפיטריה.","body":"Pour parler du passé en hébreu, on garde la racine du verbe et on ajoute à la fin une petite terminaison qui dit qui a fait l'action. Avec « avad », il a travaillé, on dit « avadti », j'ai travaillé, « avadta » à un homme, « avadt » à une femme, « avda » pour elle, « avadnu » pour nous, « avadtem » pour vous et « avdu » pour eux. Dans « akhalnu yakhad », mot à mot nous-avons-mangé ensemble, la finale « nu » suffit : inutile d'ajouter « anakhnu », nous. On laisse donc souvent tomber le pronom à la première et à la deuxième personne. À la troisième personne, en revanche, on garde en général « hu » ou « hi », comme dans « hu hiskim », il a accepté. Astuce : « ti » sonne comme moi, et « nu » comme nous.","exampleRo":"Akhalnu yakhad ba-kafeterya.","lit":"nous-avons-mangé · ensemble · dans-[la]-cafétéria"}},{"title":"Les projets du week-end","phrases":[{"fr":"Ce week-end, j'irai à la plage de Jaffa.","tgt":"בסוף השבוע אלך לחוף ביפו.","ro":"Be-sof ha-shavu'a elekh la-khof be-Yafo."},{"fr":"Tu viendras avec nous vendredi matin ?","tgt":"תבוא איתנו ביום שישי בבוקר?","ro":"Tavo itanu be-yom shishi ba-boker?"},{"fr":"Peut-être, je te dirai ça demain soir.","tgt":"אולי, אגיד לך מחר בערב.","ro":"Ulai, agid lekha makhar ba-erev."},{"fr":"Yossi apportera des fruits et de l'eau fraîche.","tgt":"יוסי יביא פירות ומים קרים.","ro":"Yosi yavi perot u-mayim karim."},{"fr":"Maya préparera des sandwichs pour tout le monde.","tgt":"מאיה תכין כריכים לכולם.","ro":"Maya takhin krikhim le-khulam."},{"fr":"Nous resterons là-bas jusqu'au coucher du soleil.","tgt":"נישאר שם עד השקיעה.","ro":"Nisha'er sham ad ha-shki'a."},{"fr":"Vous mangerez avec nous le soir ?","tgt":"תאכלו איתנו בערב?","ro":"Tokhlu itanu ba-erev?"},{"fr":"Les enfants joueront au ballon sur le sable.","tgt":"הילדים ישחקו בכדור על החול.","ro":"Ha-yeladim yesakhaku be-kadur al ha-khol."},{"fr":"Samedi, je dormirai jusqu'à midi.","tgt":"בשבת אישן עד הצהריים.","ro":"Be-shabat ishan ad ha-tsohorayim."},{"fr":"Ensuite, nous irons boire un café au port.","tgt":"אחר כך נלך לשתות קפה בנמל.","ro":"Akhar kakh nelekh lishtot kafe ba-namal."}],"tip":{"title":"Le futur à toutes les personnes","example":"Ce week-end, j'irai à la plage de Jaffa. — בסוף השבוע <b>אלך</b> לחוף ביפו.","body":"Le futur fonctionne à l'inverse du passé : cette fois, ce sont de petits sons placés devant la racine qui indiquent la personne. Avec « le'ekhol », manger, on dit « okhal », je mangerai, « tokhal », tu mangeras ou elle mangera, « yokhal », il mangera, « nokhal », nous mangerons, « tokhlu », vous mangerez, et « yokhlu », ils mangeront. Dans « elekh la-khof », mot à mot j'irai à-la-plage, le « e » du début veut dire je. Le même son « t » sert pour tu et pour elle, et c'est le contexte qui fait la différence. À une femme, on ajoute un « i » à la fin : « tokhli », tu mangeras. Astuce : « ni » ou « ne » devant le verbe, c'est nous, comme dans « nelekh », on ira.","exampleRo":"Be-sof ha-shavu'a elekh la-khof be-Yafo.","lit":"dans-fin-de · [la]-semaine · j'irai · à-[la]-plage · à-Jaffa"}},{"title":"Au supermarché","phrases":[{"fr":"Le supermarché est plein le jeudi soir.","tgt":"הסופר מלא ביום חמישי בערב.","ro":"Ha-super male be-yom khamishi ba-erev."},{"fr":"Il nous faut du lait, des œufs et du pain.","tgt":"אנחנו צריכים חלב, ביצים ולחם.","ro":"Anakhnu tsrikhim khalav, beitsim ve-lekhem."},{"fr":"Où se trouve le rayon des fromages ?","tgt":"איפה המחלקה של הגבינות?","ro":"Eifo ha-makhlaka shel ha-gvinot?"},{"fr":"Au fond, à côté des yaourts.","tgt":"בסוף, ליד היוגורטים.","ro":"Ba-sof, leyad ha-yogurtim."},{"fr":"Ces tomates viennent de Galilée.","tgt":"העגבניות האלה מהגליל.","ro":"Ha-agvaniyot ha-ele me-ha-Galil."},{"fr":"J'ai oublié de prendre un sac.","tgt":"שכחתי לקחת שקית.","ro":"Shakhakhti lakakhat sakit."},{"fr":"Il coûte combien, un sac, ici ?","tgt":"כמה עולה שקית פה?","ro":"Kama ola sakit po?"},{"fr":"Vous avez une carte de fidélité ?","tgt":"יש לך כרטיס מועדון?","ro":"Yesh lekha kartis mo'adon?"},{"fr":"Non, mais j'en voudrais bien une.","tgt":"לא, אבל הייתי רוצה אחד.","ro":"Lo, aval hayiti rotse ekhad."},{"fr":"Je paie par carte, s'il vous plaît.","tgt":"אני משלם בכרטיס, בבקשה.","ro":"Ani meshalem be-kartis, bevakasha."}]},{"title":"Les voisins","phrases":[{"fr":"Ruth est notre nouvelle voisine.","tgt":"רות היא השכנה החדשה שלנו.","ro":"Rut hi ha-shkhena ha-khadasha shelanu."},{"fr":"Elle habite l'appartement d'en face, au deuxième étage.","tgt":"היא גרה בדירה ממול, בקומה השנייה.","ro":"Hi gara ba-dira mi-mul, ba-koma ha-shniya."},{"fr":"Elle nous a apporté un gâteau pour nous souhaiter la bienvenue.","tgt":"היא הביאה לנו עוגה כדי להגיד ברוכים הבאים.","ro":"Hi hevi'a lanu uga kedei lehagid brukhim ha-ba'im."},{"fr":"Si tu as besoin de quelque chose, ne sois pas gêné.","tgt":"אם אתה צריך משהו, אל תתבייש.","ro":"Im ata tsarikh mashehu, al titbayesh."},{"fr":"Le voisin du dessus fait des travaux depuis une semaine.","tgt":"השכן מלמעלה עושה שיפוצים כבר שבוע.","ro":"Ha-shakhen mi-lemala ose shiputsim kvar shavu'a."},{"fr":"Le bruit commence à sept heures du matin.","tgt":"הרעש מתחיל בשבע בבוקר.","ro":"Ha-ra'ash matkhil be-sheva ba-boker."},{"fr":"Je suis monté lui parler poliment.","tgt":"עליתי לדבר איתו בנימוס.","ro":"Aliti ledaber ito be-nimus."},{"fr":"Il s'est excusé et a promis de commencer plus tard.","tgt":"הוא התנצל והבטיח להתחיל יותר מאוחר.","ro":"Hu hitnatsel ve-hivti'akh lehatkhil yoter me'ukhar."},{"fr":"Le comité de l'immeuble se réunit mardi soir.","tgt":"ועד הבית נפגש ביום שלישי בערב.","ro":"Va'ad ha-bayit nifgash be-yom shlishi ba-erev."},{"fr":"La cotisation est de quatre-vingts shekels par mois.","tgt":"דמי הוועד הם שמונים שקל לחודש.","ro":"Dmei ha-va'ad hem shmonim shekel la-khodesh."}]},{"title":"À la mairie","phrases":[{"fr":"Je dois aller à la mairie pour la taxe d'habitation.","tgt":"אני צריך ללכת לעירייה בגלל הארנונה.","ro":"Ani tsarikh lalekhet la-iriya biglal ha-arnona."},{"fr":"On peut prendre un numéro à l'accueil.","tgt":"אפשר לקחת מספר בקבלה.","ro":"Efshar lakakhat mispar ba-kabala."},{"fr":"Il y a encore trente personnes avant moi.","tgt":"יש עוד שלושים אנשים לפניי.","ro":"Yesh od shloshim anashim lefanai."},{"fr":"J'ai emménagé dans l'appartement il y a seulement une semaine.","tgt":"עברתי לדירה רק לפני שבוע.","ro":"Avarti la-dira rak lifnei shavu'a."},{"fr":"Avez-vous le contrat de location sur vous ?","tgt":"יש לך את חוזה השכירות?","ro":"Yesh lekha et khoze ha-skhirut?"},{"fr":"Oui, et aussi une facture d'électricité.","tgt":"כן, וגם חשבון חשמל.","ro":"Ken, ve-gam kheshbon khashmal."},{"fr":"Pour les nouveaux habitants, il y a une réduction.","tgt":"לתושבים חדשים יש הנחה.","ro":"Le-toshavim khadashim yesh hanakha."},{"fr":"La réduction est valable six mois.","tgt":"ההנחה בתוקף לשישה חודשים.","ro":"Ha-hanakha be-tokef le-shisha khodashim."},{"fr":"Vous pouvez aussi tout faire sur le site de la ville.","tgt":"אפשר גם לעשות הכול באתר של העירייה.","ro":"Efshar gam la'asot ha-kol ba-atar shel ha-iriya."},{"fr":"Si j'avais su, je serais resté chez moi !","tgt":"אם הייתי יודע, הייתי נשאר בבית!","ro":"Im hayiti yode'a, hayiti nish'ar ba-bayit!"}]},{"title":"La climatisation en panne","phrases":[{"fr":"Le climatiseur ne marche plus depuis ce matin.","tgt":"המזגן לא עובד מהבוקר.","ro":"Ha-mazgan lo oved me-ha-boker."},{"fr":"Il fait trente-cinq degrés dans le salon.","tgt":"בסלון יש שלושים וחמש מעלות.","ro":"Ba-salon yesh shloshim ve-khamesh ma'alot."},{"fr":"J'ai appelé le technicien de la société.","tgt":"התקשרתי לטכנאי של החברה.","ro":"Hitkasharti la-tekhna'i shel ha-khevra."},{"fr":"Il ne peut venir que demain après-midi.","tgt":"הוא יכול לבוא רק מחר אחרי הצהריים.","ro":"Hu yakhol lavo rak makhar akharei ha-tsohorayim."},{"fr":"En attendant, on a ouvert toutes les fenêtres.","tgt":"בינתיים פתחנו את כל החלונות.","ro":"Beintayim patakhnu et kol ha-khalonot."},{"fr":"Le ventilateur ne fait que brasser l'air chaud.","tgt":"המאוורר רק מזיז את האוויר החם.","ro":"Ha-me'avrer rak meziz et ha-avir ha-kham."},{"fr":"Le technicien a dit qu'il fallait changer une pièce.","tgt":"הטכנאי אמר שצריך להחליף חלק.","ro":"Ha-tekhna'i amar she-tsarikh lehakhlif khelek."},{"fr":"La réparation coûtera trois cents shekels.","tgt":"התיקון יעלה שלוש מאות שקל.","ro":"Ha-tikun ya'ale shlosh me'ot shekel."},{"fr":"C'est au propriétaire de payer, non ?","tgt":"בעל הבית צריך לשלם, לא?","ro":"Ba'al ha-bayit tsarikh leshalem, lo?"},{"fr":"Enfin de l'air frais ! On peut respirer !","tgt":"סוף סוף אוויר קר! אפשר לנשום!","ro":"Sof sof avir kar! Efshar linshom!"}]},{"title":"Le marché aux puces de Jaffa","phrases":[{"fr":"Le vendredi matin, nous allons au marché aux puces de Jaffa.","tgt":"ביום שישי בבוקר אנחנו הולכים לשוק הפשפשים ביפו.","ro":"Be-yom shishi ba-boker anakhnu holkhim le-shuk ha-pishpeshim be-Yafo."},{"fr":"On y trouve de vieux meubles et des lampes.","tgt":"יש שם רהיטים ישנים ומנורות.","ro":"Yesh sham rehitim yeshanim u-menorot."},{"fr":"Cette chaise en bois me plaît beaucoup.","tgt":"הכיסא הזה מעץ מוצא חן בעיניי.","ro":"Ha-kise ha-ze me-ets motse khen be-einai."},{"fr":"Vous en voulez combien ?","tgt":"כמה אתה רוצה עליו?","ro":"Kama ata rotse alav?"},{"fr":"Deux cents shekels, c'est un prix spécial.","tgt":"מאתיים שקל, זה מחיר מיוחד.","ro":"Matayim shekel, ze mekhir meyukhad."},{"fr":"C'est trop cher, je vous en donne cent.","tgt":"זה יקר מדי, אני נותן לך מאה.","ro":"Ze yakar midai, ani noten lekha me'a."},{"fr":"Allez, cent cinquante et elle est à vous.","tgt":"יאללה, מאה וחמישים והוא שלך.","ro":"Yalla, me'a ve-khamishim ve-hu shelkha."},{"fr":"D'accord, marché conclu !","tgt":"בסדר, סגרנו!","ro":"Beseder, sagarnu!"},{"fr":"Après, on boit un jus d'orange pressé près de la tour de l'horloge.","tgt":"אחר כך אנחנו שותים מיץ תפוזים טבעי ליד מגדל השעון.","ro":"Akhar kakh anakhnu shotim mits tapuzim tiv'i leyad migdal ha-sha'on."},{"fr":"Ce quartier est plein de vie du matin jusqu'à la nuit.","tgt":"יש חיים בשכונה הזאת מהבוקר עד הלילה.","ro":"Yesh khayim ba-shkhuna ha-zot me-ha-boker ad ha-layla."}]},{"title":"Guider le livreur","phrases":[{"fr":"Allô, je suis en bas de l'immeuble avec votre colis.","tgt":"הלו, אני למטה ליד הבניין עם החבילה שלך.","ro":"Halo, ani lemata leyad ha-binyan im ha-khavila shelkha."},{"fr":"Entrez par la petite porte à gauche.","tgt":"תיכנס בדלת הקטנה משמאל.","ro":"Tikanes ba-delet ha-ktana mi-smol."},{"fr":"Montez au quatrième étage.","tgt":"תעלה לקומה הרביעית.","ro":"Ta'ale la-koma ha-revi'it."},{"fr":"Attends, l'ascenseur ne marche pas aujourd'hui.","tgt":"חכה, המעלית לא עובדת היום.","ro":"Khake, ha-ma'alit lo ovedet ha-yom."},{"fr":"Laisse le colis devant la porte, s'il te plaît.","tgt":"תשאיר את החבילה ליד הדלת, בבקשה.","ro":"Tash'ir et ha-khavila leyad ha-delet, bevakasha."},{"fr":"Ne sonne pas, le bébé dort.","tgt":"אל תצלצל, התינוק ישן.","ro":"Al tetsaltsel, ha-tinok yashen."},{"fr":"Envoie-moi une photo du colis.","tgt":"שלח לי תמונה של החבילה.","ro":"Shlakh li tmuna shel ha-khavila."},{"fr":"Noa, viens m'aider avec les sacs !","tgt":"נועה, בואי תעזרי לי עם השקיות!","ro":"No'a, bo'i ta'azri li im ha-sakiyot!"},{"fr":"Ouvre la fenêtre et allume le ventilateur.","tgt":"תפתח את החלון ותדליק את המאוורר.","ro":"Tiftakh et ha-khalon ve-tadlik et ha-me'avrer."},{"fr":"Dis merci au livreur de ma part.","tgt":"תגיד תודה לשליח בשמי.","ro":"Tagid toda la-shali'akh bi-shmi."}],"tip":{"title":"L'impératif","example":"Montez au quatrième étage. — <b>תעלה</b> לקומה הרביעית.","body":"Pour donner un ordre ou une consigne, les Israéliens utilisent surtout le futur. « Ta'ale la-koma ha-revi'it », mot à mot tu-monteras à-l'étage le-quatrième, veut simplement dire montez au quatrième étage, sur un ton neutre et poli. Il existe aussi des formes courtes, très fréquentes à l'oral : « bo », viens, « khake », attends, « shev », assieds-toi, et pour une femme « bo'i », « khaki », « shvi ». Pour défendre quelque chose, on dit toujours « al » suivi du futur : « al tetsaltsel », ne sonne pas, ou « al tid'ag », ne t'inquiète pas. Ne confondez pas : « lo » nie un fait, alors que « al » arrête une action. Astuce : ajoutez « bevakasha » à la fin, et n'importe quel ordre devient une demande aimable.","exampleRo":"Ta'ale la-koma ha-revi'it.","lit":"tu-monteras · à-[le]-étage · [le]-quatrième"}},{"title":"Le week-end dernier","phrases":[{"fr":"Qu'avez-vous fait le week-end dernier, toi et Maya ?","tgt":"מה עשיתם בסוף השבוע שעבר, אתה ומאיה?","ro":"Ma asitem be-sof ha-shavu'a she-avar, ata u-Maya?"},{"fr":"Nous avons loué des vélos et longé la mer.","tgt":"שכרנו אופניים ורכבנו לאורך הים.","ro":"Sakharnu ofanayim ve-rakhavnu le-orekh ha-yam."},{"fr":"Nous sommes arrivés jusqu'au port de Jaffa.","tgt":"הגענו עד הנמל של יפו.","ro":"Higanu ad ha-namal shel Yafo."},{"fr":"Maya a acheté des boucles d'oreilles au marché.","tgt":"מאיה קנתה עגילים בשוק.","ro":"Maya kanta agilim ba-shuk."},{"fr":"Le soir, nous avons dîné chez ses parents.","tgt":"בערב אכלנו ארוחת ערב אצל ההורים שלה.","ro":"Ba-erev akhalnu arukhat erev etsel ha-horim shela."},{"fr":"Sa mère a préparé un repas incroyable.","tgt":"אמא שלה בישלה אוכל מדהים.","ro":"Ima shela bishla okhel madhim."},{"fr":"Et vous, vous êtes sortis ?","tgt":"ואתם, יצאתם?","ro":"Ve-atem, yetsatem?"},{"fr":"Non, les enfants étaient malades, on est restés à la maison.","tgt":"לא, הילדים היו חולים, נשארנו בבית.","ro":"Lo, ha-yeladim hayu kholim, nisharnu ba-bayit."},{"fr":"Nous avons regardé deux films sur le canapé.","tgt":"ראינו שני סרטים על הספה.","ro":"Ra'inu shnei sratim al ha-sapa."},{"fr":"Finalement, ce n'était pas mal non plus.","tgt":"גם זה לא היה רע, בסוף.","ro":"Gam ze lo haya ra, ba-sof."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais à Haïfa.","tgt":"כשהייתי קטן, גרתי בחיפה.","ro":"Kshe-hayiti katan, garti be-Kheifa."},{"fr":"Notre maison était près de la mer.","tgt":"הבית שלנו היה קרוב לים.","ro":"Ha-bayit shelanu haya karov la-yam."},{"fr":"Mon grand-père m'emmenait pêcher le samedi.","tgt":"סבא שלי היה לוקח אותי לדוג בשבת.","ro":"Saba sheli haya loke'akh oti ladug be-shabat."},{"fr":"Je détestais l'école, mais j'adorais la récréation.","tgt":"שנאתי את בית הספר, אבל אהבתי את ההפסקה.","ro":"Saneti et beit ha-sefer, aval ahavti et ha-hafsaka."},{"fr":"Ma sœur et moi, on se disputait tout le temps.","tgt":"אני ואחותי רבנו כל הזמן.","ro":"Ani ve-akhoti ravnu kol ha-zman."},{"fr":"L'été, on jouait dans la rue jusqu'à la nuit.","tgt":"בקיץ שיחקנו ברחוב עד הלילה.","ro":"Ba-kayits sikhaknu ba-rekhov ad ha-layla."},{"fr":"À l'époque, il n'y avait pas de téléphones portables.","tgt":"לא היו אז טלפונים ניידים.","ro":"Lo hayu az telefonim nayadim."},{"fr":"Et toi, Shira, tu as grandi où ?","tgt":"ואת, שירה, איפה גדלת?","ro":"Ve-at, Shira, eifo gadalt?"},{"fr":"J'ai grandi dans un kibboutz du sud.","tgt":"גדלתי בקיבוץ בדרום.","ro":"Gadalti be-kibuts ba-darom."},{"fr":"Là-bas, tout le monde se connaissait.","tgt":"כולם הכירו את כולם שם.","ro":"Kulam hikiru et kulam sham."}]},{"title":"La canicule","phrases":[{"fr":"Quelle chaleur aujourd'hui, c'est un vrai sharav !","tgt":"איזה חום היום! יש שרב.","ro":"Eize khom ha-yom! Yesh sharav."},{"fr":"La météo annonce quarante degrés à Tel Aviv.","tgt":"התחזית אומרת ארבעים מעלות בתל אביב.","ro":"Ha-takhazit omeret arba'im ma'alot be-Tel Aviv."},{"fr":"L'air est sec et plein de poussière.","tgt":"האוויר יבש ומלא אבק.","ro":"Ha-avir yavesh u-male avak."},{"fr":"Il faut boire beaucoup d'eau toute la journée.","tgt":"צריך לשתות הרבה מים כל היום.","ro":"Tsarikh lishtot harbe mayim kol ha-yom."},{"fr":"Je ne sors pas entre midi et quatre heures.","tgt":"אני לא יוצא בין שתים עשרה לארבע.","ro":"Ani lo yotse bein shteim esre le-arba."},{"fr":"Les personnes âgées doivent rester à l'intérieur.","tgt":"אנשים מבוגרים צריכים להישאר בפנים.","ro":"Anashim mevugarim tsrikhim lehisha'er bifnim."},{"fr":"Même la mer est chaude comme une baignoire.","tgt":"אפילו הים חם כמו אמבטיה.","ro":"Afilu ha-yam kham kmo ambatya."},{"fr":"Le soir, toute la ville descend sur la promenade.","tgt":"בערב כל העיר יורדת לטיילת.","ro":"Ba-erev kol ha-ir yoredet la-tayelet."},{"fr":"D'habitude, ça ne dure que deux ou trois jours.","tgt":"בדרך כלל זה נמשך רק יומיים או שלושה.","ro":"Be-derekh klal ze nimshakh rak yomayim o shlosha."},{"fr":"Quand est-ce que l'automne arrivera enfin ?","tgt":"מתי כבר יגיע הסתיו?","ro":"Matai kvar yagi'a ha-stav?"}]},{"title":"Une fuite sous l'évier","phrases":[{"fr":"Il y a une fuite d'eau sous l'évier.","tgt":"יש נזילה מתחת לכיור.","ro":"Yesh nezila mitakhat la-kiyor."},{"fr":"Le sol de la cuisine est tout mouillé.","tgt":"הרצפה במטבח כולה רטובה.","ro":"Ha-ritspa ba-mitbakh kula retuva."},{"fr":"J'ai fermé le robinet principal.","tgt":"סגרתי את הברז הראשי.","ro":"Sagarti et ha-berez ha-rashi."},{"fr":"Le propriétaire m'a donné le numéro d'un plombier.","tgt":"בעל הבית נתן לי מספר של אינסטלטור.","ro":"Ba'al ha-bayit natan li mispar shel instalator."},{"fr":"Le plombier est arrivé une heure plus tard.","tgt":"האינסטלטור הגיע אחרי שעה.","ro":"Ha-instalator higi'a akharei sha'a."},{"fr":"Il a dit que le tuyau était très vieux.","tgt":"הוא אמר שהצינור ישן מאוד.","ro":"Hu amar she-ha-tsinor yashan me'od."},{"fr":"Il l'a changé en vingt minutes.","tgt":"הוא החליף אותו בעשרים דקות.","ro":"Hu hekhlif oto be-esrim dakot."},{"fr":"Est-ce que je peux avoir un reçu ?","tgt":"אפשר לקבל קבלה?","ro":"Efshar lekabel kabala?"},{"fr":"Je l'enverrai au propriétaire.","tgt":"אני אשלח אותה לבעל הבית.","ro":"Ani eshlakh ota le-va'al ha-bayit."},{"fr":"Heureusement, ce n'était rien de grave.","tgt":"טוב שזה לא היה משהו רציני.","ro":"Tov she-ze lo haya mashehu retsini."}]},{"title":"Un nouveau collègue","phrases":[{"fr":"Je te présente Avi, notre nouveau développeur.","tgt":"תכיר, זה אבי, המפתח החדש שלנו.","ro":"Takir, ze Avi, ha-mefate'akh ha-khadash shelanu."},{"fr":"Enchanté, je commence aujourd'hui.","tgt":"נעים מאוד, אני מתחיל היום.","ro":"Na'im me'od, ani matkhil ha-yom."},{"fr":"On boit un café ensemble à la pause ?","tgt":"נשתה קפה ביחד בהפסקה?","ro":"Nishte kafe be-yakhad ba-hafsaka?"},{"fr":"La cafetière se trouve au bout du couloir.","tgt":"מכונת הקפה בסוף המסדרון.","ro":"Mekhonat ha-kafe be-sof ha-misderon."},{"fr":"Ici, tout le monde appelle le patron par son prénom.","tgt":"פה כולם קוראים למנהל בשם הפרטי.","ro":"Po kulam kor'im la-menahel ba-shem ha-prati."},{"fr":"Les réunions commencent souvent en retard.","tgt":"הישיבות מתחילות הרבה פעמים באיחור.","ro":"Ha-yeshivot matkhilot harbe pe'amim be-ikhur."},{"fr":"Ici, le dimanche est un jour de travail normal.","tgt":"יום ראשון הוא יום עבודה רגיל פה.","ro":"Yom rishon hu yom avoda ragil po."},{"fr":"Tu travailles combien de jours de la maison ?","tgt":"כמה ימים אתה עובד מהבית?","ro":"Kama yamim ata oved me-ha-bayit?"},{"fr":"Deux jours par semaine, le mardi et le jeudi.","tgt":"יומיים בשבוע, בשלישי ובחמישי.","ro":"Yomayim ba-shavu'a, bi-shlishi u-va-khamishi."},{"fr":"Si tu as une question, ma porte est toujours ouverte.","tgt":"אם יש לך שאלה, הדלת שלי תמיד פתוחה.","ro":"Im yesh lekha she'ela, ha-delet sheli tamid ptukha."}]},{"title":"Se déplacer en ville","phrases":[{"fr":"Je vais au travail avec la ligne quatre.","tgt":"אני נוסע לעבודה בקו ארבע.","ro":"Ani nose'a la-avoda be-kav arba."},{"fr":"Il faut recharger la carte de transport avant de monter.","tgt":"צריך להטעין את כרטיס הנסיעה לפני שעולים.","ro":"Tsarikh lehat'in et kartis ha-nesi'a lifnei she-olim."},{"fr":"Ce matin, le bus avait vingt minutes de retard.","tgt":"האוטובוס איחר בעשרים דקות הבוקר.","ro":"Ha-otobus ikher be-esrim dakot ha-boker."},{"fr":"Le tramway est beaucoup plus rapide.","tgt":"הרכבת הקלה הרבה יותר מהירה.","ro":"Ha-rakevet ha-kala harbe yoter mehira."},{"fr":"Il y a une station juste en bas de chez moi.","tgt":"יש תחנה ממש מתחת לבית שלי.","ro":"Yesh takhana mamash mitakhat la-bayit sheli."},{"fr":"Le week-end, je préfère circuler à vélo.","tgt":"בסוף השבוע אני מעדיף לנסוע באופניים.","ro":"Be-sof ha-shavu'a ani ma'adif linso'a be-ofanayim."},{"fr":"Il y a des pistes cyclables presque partout.","tgt":"יש שבילי אופניים כמעט בכל מקום.","ro":"Yesh shvilei ofanayim kim'at be-khol makom."},{"fr":"Attention aux trottinettes sur le trottoir !","tgt":"זהירות מהקורקינטים על המדרכה!","ro":"Zehirut me-ha-korkinetim al ha-midrakha!"},{"fr":"Je cherche une place pour me garer depuis une demi-heure.","tgt":"אני מחפש חניה כבר חצי שעה.","ro":"Ani mekhapes khanaya kvar khatsi sha'a."},{"fr":"Dans cette ville, mieux vaut ne pas avoir de voiture.","tgt":"בעיר הזאת עדיף לא להחזיק רכב.","ro":"Ba-ir ha-zot adif lo lehakhzik rekhev."}]},{"title":"Le règlement de l'immeuble","phrases":[{"fr":"Est-ce qu'on a le droit d'avoir un chien dans l'appartement ?","tgt":"מותר להחזיק כלב בדירה?","ro":"Mutar lehakhzik kelev ba-dira?"},{"fr":"Oui, c'est permis, mais pas dans le jardin commun.","tgt":"כן, מותר, אבל לא בגינה המשותפת.","ro":"Ken, mutar, aval lo ba-gina ha-meshutefet."},{"fr":"Il est interdit de fumer dans la cage d'escalier.","tgt":"אסור לעשן בחדר המדרגות.","ro":"Asur le'ashen be-khadar ha-madregot."},{"fr":"Il est interdit de laisser les vélos dans l'entrée.","tgt":"אסור להשאיר אופניים בכניסה.","ro":"Asur lehash'ir ofanayim ba-knisa."},{"fr":"Peut-on étendre le linge sur le toit ?","tgt":"מותר לתלות כביסה על הגג?","ro":"Mutar litlot kvisa al ha-gag?"},{"fr":"Oui, chacun a le droit d'y monter.","tgt":"כן, מותר לכל אחד לעלות לשם.","ro":"Ken, mutar le-khol ekhad la'alot le-sham."},{"fr":"Après vingt-trois heures, il est interdit de faire du bruit.","tgt":"אחרי אחת עשרה בלילה אסור לעשות רעש.","ro":"Akharei akhat esre ba-layla asur la'asot ra'ash."},{"fr":"Les enfants n'ont pas le droit de jouer au ballon dans le hall.","tgt":"לילדים אסור לשחק בכדור בלובי.","ro":"La-yeladim asur lesakhek be-kadur ba-lobi."},{"fr":"A-t-on le droit de faire un barbecue sur le balcon ?","tgt":"מותר לעשות מנגל במרפסת?","ro":"Mutar la'asot mangal ba-mirpeset?"},{"fr":"Non, c'est strictement interdit, à cause de la fumée.","tgt":"לא, זה אסור בהחלט, בגלל העשן.","ro":"Lo, ze asur behekhlet, biglal ha-ashan."}],"tip":{"title":"« Asur » et « mutar » : interdit et permis","example":"Il est interdit de fumer dans la cage d'escalier. — <b>אסור</b> לעשן בחדר המדרגות.","body":"« Asur » veut dire interdit et « mutar » veut dire permis, et ces deux mots ne changent jamais : ni masculin, ni féminin, ni pluriel. On les place simplement devant un verbe à l'infinitif, sans rien pour traduire notre « il est » : « asur le'ashen », mot à mot interdit fumer, signifie il est interdit de fumer. Pour poser la question, il suffit de monter la voix à la fin : « mutar lehikanes ? », on peut entrer ? Pour dire à qui c'est interdit, on ajoute « le » : « asur li », je n'ai pas le droit, ou « la-yeladim asur », les enfants n'ont pas le droit. Astuce : « asur » est le mot que vous entendrez partout, à la plage comme à la piscine, alors retenez-le en premier.","exampleRo":"Asur le'ashen be-khadar ha-madregot.","lit":"interdit · fumer · dans-chambre-de · [les]-escaliers"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"On a appris à se débrouiller à la banque et à la mairie.","tgt":"למדנו להסתדר בבנק ובעירייה.","ro":"Lamadnu lehistader ba-bank u-va-iriya."},{"fr":"Maintenant, on sait raconter ce qu'on a fait hier.","tgt":"עכשיו אנחנו יודעים לספר מה עשינו אתמול.","ro":"Akhshav anakhnu yod'im lesaper ma asinu etmol."},{"fr":"Et aussi ce qu'on fera demain.","tgt":"וגם מה נעשה מחר.","ro":"Ve-gam ma na'ase makhar."},{"fr":"Le passé et le futur font déjà moins peur.","tgt":"העבר והעתיד כבר פחות מפחידים.","ro":"Ha-avar ve-ha-atid kvar pakhot mafkhidim."},{"fr":"Je comprends mieux mes voisins quand ils parlent vite.","tgt":"אני מבין יותר טוב את השכנים כשהם מדברים מהר.","ro":"Ani mevin yoter tov et ha-shkhenim kshe-hem medabrim maher."},{"fr":"À la clinique, je n'ai plus besoin de traducteur.","tgt":"במרפאה אני כבר לא צריך מתרגם.","ro":"Ba-mirpa'a ani kvar lo tsarikh metargem."},{"fr":"L'hébreu devient un peu plus facile chaque semaine.","tgt":"העברית נעשית קצת יותר קלה כל שבוע.","ro":"Ha-ivrit na'aset ktsat yoter kala kol shavu'a."},{"fr":"Dans le prochain module, nous voyagerons à travers le pays.","tgt":"במודול הבא ניסע ברחבי הארץ.","ro":"Ba-modul ha-ba nisa be-rakhavei ha-arets."},{"fr":"Bravo pour tous ces efforts !","tgt":"כל הכבוד על כל המאמץ!","ro":"Kol ha-kavod al kol ha-ma'amats!"},{"fr":"On se retrouve bientôt pour la suite.","tgt":"נתראה בקרוב בהמשך.","ro":"Nitra'e be-karov ba-hemshekh."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Louer une voiture en Galilée","phrases":[{"fr":"J'ai réservé une voiture pour une semaine.","tgt":"הזמנתי רכב לשבוע.","ro":"Hizmanti rekhev le-shavua."},{"fr":"Est-ce que l'assurance est comprise dans le prix ?","tgt":"הביטוח כלול במחיר?","ro":"Ha-bituakh kalul ba-mekhir?"},{"fr":"Vous pouvez me montrer les rayures sur la portière ?","tgt":"אפשר להראות לי את השריטות על הדלת?","ro":"Efshar leharot li et ha-sritot al ha-delet?"},{"fr":"Il faut rendre la voiture avec le réservoir plein.","tgt":"צריך להחזיר את הרכב עם מיכל מלא.","ro":"Tsarikh lehakhzir et ha-rekhev im meikhal male."},{"fr":"Combien coûte un siège enfant en plus ?","tgt":"כמה עולה כיסא לילד בנוסף?","ro":"Kama ole kise le-yeled be-nosaf?"},{"fr":"Y a-t-il une limite de kilomètres ?","tgt":"יש הגבלה של קילומטרים?","ro":"Yesh hagbala shel kilometrim?"},{"fr":"Je préfère une voiture automatique.","tgt":"אני מעדיף רכב אוטומטי.","ro":"Ani ma'adif rekhev otomati."},{"fr":"Voici mon permis de conduire et le passeport.","tgt":"הנה רישיון הנהיגה שלי והדרכון.","ro":"Hine rishyon ha-nehiga sheli ve-ha-darkon."},{"fr":"Où est le parking pour rendre les voitures ?","tgt":"איפה החניה להחזרת רכבים?","ro":"Eifo ha-khanaya lehakhzarat rekhavim?"},{"fr":"On part vers le nord demain matin.","tgt":"אנחנו יוצאים צפונה מחר בבוקר.","ro":"Anakhnu yots'im tsafona makhar ba-boker."}]},{"title":"Sur les routes du nord","phrases":[{"fr":"La route monte entre des collines vertes.","tgt":"הכביש עולה בין גבעות ירוקות.","ro":"Ha-kvish ole bein giva'ot yerukot."},{"fr":"Monte un peu la musique.","tgt":"תגביר קצת את המוזיקה.","ro":"Tagbir ktsat et ha-muzika."},{"fr":"On s'est arrêtés boire un café à la station-service.","tgt":"עצרנו לשתות קפה בתחנת הדלק.","ro":"Atsarnu lishtot kafe be-takhanat ha-delek."},{"fr":"Le prochain virage est très serré.","tgt":"הסיבוב הבא חד מאוד.","ro":"Ha-sivuv ha-ba khad me'od."},{"fr":"Tu as vu le panneau pour Tibériade ?","tgt":"ראית את השלט לטבריה?","ro":"Ra'ita et ha-shelet li-Tveriya?"},{"fr":"Il y a des bouchons à l'entrée de la ville.","tgt":"יש פקקים בכניסה לעיר.","ro":"Yesh pkakim ba-knisa la-ir."},{"fr":"J'ai conduit trois heures sans pause.","tgt":"נהגתי שלוש שעות בלי הפסקה.","ro":"Nahagti shalosh sha'ot bli hafsaka."},{"fr":"Tu veux conduire à ma place un moment ?","tgt":"אתה רוצה לנהוג במקומי קצת?","ro":"Ata rotse linhog bimkomi ktsat?"},{"fr":"Le paysage ici ne ressemble pas du tout à Tel Aviv.","tgt":"הנוף כאן בכלל לא דומה לתל אביב.","ro":"Ha-nof kan bikhlal lo dome le-Tel Aviv."},{"fr":"On arrivera au village avant le coucher du soleil.","tgt":"נגיע לכפר לפני השקיעה.","ro":"Nagi'a la-kfar lifnei ha-shki'a."}]},{"title":"Une randonnée en Galilée","phrases":[{"fr":"Si on part tôt, on évitera la chaleur.","tgt":"אם נצא מוקדם, נימנע מהחום.","ro":"Im netse mukdam, nimana me-ha-khom."},{"fr":"Prends beaucoup d'eau, la montée est longue.","tgt":"קח הרבה מים, העלייה ארוכה.","ro":"Kakh harbe mayim, ha-aliya aruka."},{"fr":"Si tu es fatigué, on peut s'arrêter.","tgt":"אם אתה עייף, אפשר לעצור.","ro":"Im ata ayef, efshar la'atsor."},{"fr":"Le sentier est balisé en rouge.","tgt":"השביל מסומן באדום.","ro":"Ha-shvil mesuman be-adom."},{"fr":"S'il pleut, le sentier sera glissant.","tgt":"אם ירד גשם, השביל יהיה חלקלק.","ro":"Im yered geshem, ha-shvil yihye khalaklak."},{"fr":"D'en haut, on voit tout le lac.","tgt":"מלמעלה רואים את כל הכנרת.","ro":"Mi-lemala ro'im et kol ha-Kineret."},{"fr":"Si tu veux, je porte le sac un moment.","tgt":"אם אתה רוצה, אני אסחב את התיק קצת.","ro":"Im ata rotse, ani eskhav et ha-tik ktsat."},{"fr":"Si on se perd, on appellera le garde du parc.","tgt":"אם נלך לאיבוד, נתקשר לפקח של הפארק.","ro":"Im nelekh le-ibud, nitkasher la-pakakh shel ha-park."},{"fr":"Attention aux pierres dans la descente.","tgt":"זהירות מהאבנים בירידה.","ro":"Zehirut me-ha-avanim ba-yerida."},{"fr":"Si le temps le permet, on dormira sous les étoiles.","tgt":"אם מזג האוויר יאפשר, נישן מתחת לכוכבים.","ro":"Im mezeg ha-avir ye'afsher, nishan mitakhat la-kokhavim."}],"tip":{"title":"« Im » : si, la condition","example":"S'il pleut, le sentier sera glissant. — <b>אם</b> ירד גשם, השביל יהיה חלקלק.","body":"Pour poser une condition, on dit « im », qui veut dire si. Grande différence avec le français : quand on parle de l'avenir, l'hébreu met le futur dans les deux parties de la phrase. Prenons « im yered geshem, ha-shvil yihye khalaklak » : mot à mot, si descendra pluie, le sentier sera glissant. Sans verbe, c'est encore plus simple : « im ata ayef, efshar la'atsor », si tu es fatigué, on peut s'arrêter, et « im netse mukdam », si on part tôt. Pour retenir, pensez que la pluie n'est pas encore tombée : l'hébreu, très logique, parle donc au futur.","exampleRo":"Im yered geshem, ha-shvil yihye khalaklak.","lit":"si · descendra · pluie · [le] sentier · sera · glissant"}},{"title":"Au bord du lac de Tibériade","phrases":[{"fr":"L'eau du lac est plus chaude que je pensais.","tgt":"המים בכנרת חמים יותר ממה שחשבתי.","ro":"Ha-mayim ba-Kineret khamim yoter mi-ma she-khashavti."},{"fr":"On a loué deux kayaks pour une heure.","tgt":"שכרנו שני קיאקים לשעה.","ro":"Sakharnu shnei kayakim le-sha'a."},{"fr":"La promenade au bord de l'eau est pleine de monde le soir.","tgt":"הטיילת לאורך המים מלאה באנשים בערב.","ro":"Ha-tayelet le-orekh ha-mayim mele'a ba-anashim ba-erev."},{"fr":"Ici, on mange des poissons du lac.","tgt":"כאן אוכלים דגים מהכנרת.","ro":"Kan okhlim dagim me-ha-Kineret."},{"fr":"N'oublie pas de mettre de la crème solaire.","tgt":"אל תשכח לשים קרם הגנה.","ro":"Al tishkakh lasim krem hagana."},{"fr":"Il y a une petite plage tranquille un peu plus au nord.","tgt":"יש חוף קטן ושקט קצת יותר צפונה.","ro":"Yesh khof katan ve-shaket ktsat yoter tsafona."},{"fr":"Les enfants se baignent depuis ce matin.","tgt":"הילדים שוחים מהבוקר.","ro":"Ha-yeladim sokhim me-ha-boker."},{"fr":"On a vu un coucher de soleil magnifique sur l'eau.","tgt":"ראינו שקיעה מדהימה מעל המים.","ro":"Ra'inu shki'a madhima me'al ha-mayim."},{"fr":"Le niveau du lac a monté cette année.","tgt":"מפלס הכנרת עלה השנה.","ro":"Mifles ha-Kineret ala ha-shana."},{"fr":"Demain, on fera le tour du lac à vélo.","tgt":"מחר נעשה סיבוב סביב הכנרת באופניים.","ro":"Makhar na'ase sivuv saviv ha-Kineret be-ofanayim."}]},{"title":"Une nuit au kibboutz","phrases":[{"fr":"Tu as déjà réservé la chambre au kibboutz ?","tgt":"כבר הזמנת את החדר בקיבוץ?","ro":"Kvar hizmanta et ha-kheder ba-kibuts?"},{"fr":"Oui, j'ai déjà payé sur internet.","tgt":"כן, כבר שילמתי באינטרנט.","ro":"Ken, kvar shilamti ba-internet."},{"fr":"La réception n'est pas encore ouverte.","tgt":"הקבלה עוד לא פתוחה.","ro":"Ha-kabala od lo ptukha."},{"fr":"Le dîner est servi dans la grande salle à manger.","tgt":"ארוחת הערב מוגשת בחדר האוכל הגדול.","ro":"Arukhat ha-erev mugeshet be-khadar ha-okhel ha-gadol."},{"fr":"Je ne suis pas encore allé à la piscine.","tgt":"עוד לא הלכתי לבריכה.","ro":"Od lo halakhti la-brekha."},{"fr":"Les enfants dorment déjà dans la chambre.","tgt":"הילדים כבר ישנים בחדר.","ro":"Ha-yeladim kvar yeshenim ba-kheder."},{"fr":"Un membre du kibboutz nous a fait visiter les vergers.","tgt":"חבר קיבוץ עשה לנו סיור במטעים.","ro":"Khaver kibuts asa lanu siyur ba-mata'im."},{"fr":"Tu as déjà goûté les avocats du kibboutz ?","tgt":"כבר טעמת את האבוקדו של הקיבוץ?","ro":"Kvar ta'amta et ha-avokado shel ha-kibuts?"},{"fr":"Il est déjà dix heures, il faut libérer la chambre.","tgt":"כבר עשר, צריך לפנות את החדר.","ro":"Kvar eser, tsarikh lefanot et ha-kheder."},{"fr":"Je n'ai pas encore envie de partir.","tgt":"עוד לא בא לי לעזוב.","ro":"Od lo ba li la'azov."}],"tip":{"title":"« Kvar » et « od lo » : déjà et pas encore","example":"La réception n'est pas encore ouverte. — הקבלה <b>עוד לא</b> פתוחה.","body":"« Kvar » veut dire déjà, et il se place en général juste avant le verbe : « kvar shilamti », j'ai déjà payé. Son contraire, pas encore, se dit « od lo », mot à mot encore pas. Dans « ha-kabala od lo ptukha », on a littéralement la réception, encore pas, ouverte, sans verbe être. Ça marche aussi avec le passé : « od lo halakhti la-brekha », je ne suis pas encore allé à la piscine. Pour poser la question, il suffit de monter la voix : « kvar akhalta ? », tu as déjà mangé ? Astuce : « kvar » et « od lo » vont ensemble comme oui et non, et la réponse naturelle à une question avec « kvar » commence souvent par « od lo ».","exampleRo":"Ha-kabala od lo ptukha.","lit":"[la] réception · encore · pas · ouverte"}},{"title":"La vieille ville de Saint-Jean-d'Acre","phrases":[{"fr":"Les murailles d'Acre donnent sur la mer.","tgt":"החומות של עכו משקיפות על הים.","ro":"Ha-khomot shel Ako mashkifot al ha-yam."},{"fr":"On s'est perdus dans les ruelles étroites.","tgt":"הלכנו לאיבוד בסמטאות הצרות.","ro":"Halakhnu le-ibud ba-simta'ot ha-tsarot."},{"fr":"Les salles des Chevaliers se trouvent sous terre.","tgt":"אולמות האבירים נמצאים מתחת לאדמה.","ro":"Ulamot ha-abirim nimtsa'im mitakhat la-adama."},{"fr":"Le billet comprend l'entrée de plusieurs sites.","tgt":"הכרטיס כולל כניסה לכמה אתרים.","ro":"Ha-kartis kolel knisa le-khama atarim."},{"fr":"On a traversé un ancien tunnel jusqu'au port.","tgt":"עברנו במנהרה עתיקה עד הנמל.","ro":"Avarnu be-minhara atika ad ha-namal."},{"fr":"Le guide a raconté l'histoire de la ville pendant deux heures.","tgt":"המדריך סיפר את ההיסטוריה של העיר במשך שעתיים.","ro":"Ha-madrikh siper et ha-historya shel ha-ir be-meshekh sha'atayim."},{"fr":"Il fait frais à l'intérieur, entre les vieilles pierres.","tgt":"קריר בפנים, בין האבנים העתיקות.","ro":"Karir bifnim, bein ha-avanim ha-atikot."},{"fr":"On a pris des photos d'en haut, depuis la muraille.","tgt":"צילמנו מלמעלה, מהחומה.","ro":"Tsilamnu mi-lemala, me-ha-khoma."},{"fr":"Ça sent les épices dans le marché de la vieille ville.","tgt":"בשוק של העיר העתיקה מריח מתבלינים.","ro":"Ba-shuk shel ha-ir ha-atika meri'akh mi-tavlinim."},{"fr":"Acre est l'une des villes les plus anciennes du pays.","tgt":"עכו היא אחת הערים העתיקות בארץ.","ro":"Ako hi akhat ha-arim ha-atikot ba-arets."}]},{"title":"Au port d'Acre","phrases":[{"fr":"Les bateaux de pêche rentrent le matin.","tgt":"סירות הדייגים חוזרות בבוקר.","ro":"Sirot ha-dayagim khozrot ba-boker."},{"fr":"On a mangé du poisson frais face à la mer.","tgt":"אכלנו דג טרי מול הים.","ro":"Akhalnu dag tari mul ha-yam."},{"fr":"Des jeunes sautent dans l'eau depuis le mur du port.","tgt":"צעירים קופצים למים מהחומה של הנמל.","ro":"Tse'irim koftsim la-mayim me-ha-khoma shel ha-namal."},{"fr":"Il y a une balade en bateau toutes les heures.","tgt":"יש שיט בסירה כל שעה.","ro":"Yesh shayit be-sira kol sha'a."},{"fr":"Le vent est trop fort pour sortir en mer aujourd'hui.","tgt":"הרוח חזקה מדי כדי לצאת לים היום.","ro":"Ha-ruakh khazaka midai kdei latset la-yam ha-yom."},{"fr":"Le restaurant au bout du quai est très connu.","tgt":"המסעדה בסוף המזח מאוד מפורסמת.","ro":"Ha-mis'ada be-sof ha-mezakh me'od mefursemet."},{"fr":"Je voudrais une table près de la fenêtre.","tgt":"הייתי רוצה שולחן ליד החלון.","ro":"Hayiti rotse shulkhan leyad ha-khalon."},{"fr":"On peut avoir l'addition, s'il vous plaît ?","tgt":"אפשר חשבון, בבקשה?","ro":"Efshar kheshbon, bevakasha?"},{"fr":"Les mouettes tournent au-dessus des filets.","tgt":"השחפים חגים מעל הרשתות.","ro":"Ha-shkhafim khagim me'al ha-reshatot."},{"fr":"Le phare s'allume quand le soir tombe.","tgt":"המגדלור נדלק כשיורד הערב.","ro":"Ha-migdalor nidlak kshe-yored ha-erev."}]},{"title":"Une crevaison sur la route","phrases":[{"fr":"On a crevé au milieu de nulle part.","tgt":"היה לנו פנצ'ר באמצע שום מקום.","ro":"Haya lanu pancher be-emtsa shum makom."},{"fr":"J'aurais dû vérifier la roue de secours avant.","tgt":"הייתי צריך לבדוק את הגלגל הרזרבי קודם.","ro":"Hayiti tsarikh livdok et ha-galgal ha-rezervi kodem."},{"fr":"Il fallait appeler l'agence de location tout de suite.","tgt":"היינו צריכים להתקשר לחברת ההשכרה מיד.","ro":"Hayinu tsrikhim lehitkasher le-khevrat ha-haskara miyad."},{"fr":"La dépanneuse arrivera dans une heure.","tgt":"הגרר יגיע בעוד שעה.","ro":"Ha-grar yagi'a be-od sha'a."},{"fr":"J'ai dû attendre au bord de la route en plein soleil.","tgt":"הייתי צריך לחכות בצד הדרך בשמש.","ro":"Hayiti tsarikh lekhakot be-tsad ha-derekh ba-shemesh."},{"fr":"Tu sais changer une roue ?","tgt":"אתה יודע להחליף גלגל?","ro":"Ata yode'a lehakhlif galgal?"},{"fr":"Un chauffeur de camion s'est arrêté pour nous aider.","tgt":"נהג משאית עצר לעזור לנו.","ro":"Nahag masa'it atsar la'azor lanu."},{"fr":"Ma femme a dû annuler notre réservation du soir.","tgt":"אשתי הייתה צריכה לבטל את ההזמנה של הערב.","ro":"Ishti hayta tsrikha levatel et ha-hazmana shel ha-erev."},{"fr":"Le garage le plus proche est à vingt kilomètres.","tgt":"המוסך הכי קרוב נמצא במרחק עשרים קילומטר.","ro":"Ha-musakh hakhi karov nimtsa be-merkhak esrim kilometer."},{"fr":"La prochaine fois, il faudra prendre l'assurance complète.","tgt":"בפעם הבאה נצטרך לקחת ביטוח מלא.","ro":"Ba-pa'am ha-ba'a nitstarekh lakakhat bituakh male."}],"tip":{"title":"« Hayiti tsarikh » : il fallait","example":"J'ai dû attendre au bord de la route en plein soleil. — <b>הייתי צריך</b> לחכות בצד הדרך בשמש.","body":"Pour dire j'ai dû ou il fallait, l'hébreu combine deux mots simples : « hayiti », j'étais, et « tsarikh », obligé ou ayant besoin, suivis d'un verbe à l'infinitif. Ainsi « hayiti tsarikh lekhakot » veut dire mot à mot j'étais obligé attendre, donc j'ai dû attendre. Les deux mots s'accordent : une femme dit « hayiti tsrikha », et ensemble on dit « hayinu tsrikhim », nous avons dû. Selon le ton, la même phrase veut aussi dire j'aurais dû, comme dans « hayiti tsarikh livdok », j'aurais dû vérifier. Astuce : retenez d'abord « tsarikh » au présent, puis ajoutez simplement « hayiti » devant pour passer au passé.","exampleRo":"Hayiti tsarikh lekhakot be-tsad ha-derekh ba-shemesh.","lit":"j'étais · obligé · attendre · [à] côté · [de la] route · [dans le] soleil"}},{"title":"Les grottes de Rosh Hanikra","phrases":[{"fr":"Le téléphérique descend jusqu'aux grottes.","tgt":"הרכבל יורד עד הנקרות.","ro":"Ha-rakhbal yored ad ha-nikrot."},{"fr":"La descente en téléphérique dure à peine une minute.","tgt":"הירידה ברכבל לוקחת בקושי דקה.","ro":"Ha-yerida ba-rakhbal lokakhat be-koshi daka."},{"fr":"Les vagues entrent dans les grottes avec un bruit énorme.","tgt":"הגלים נכנסים למערות ברעש עצום.","ro":"Ha-galim nikhnasim la-me'arot be-ra'ash atsum."},{"fr":"L'eau ici est d'un bleu incroyable.","tgt":"המים כאן בצבע כחול מדהים.","ro":"Ha-mayim kan be-tseva kakhol madhim."},{"fr":"Les falaises de craie blanche sont splendides.","tgt":"צוקי הגיר הלבנים מרהיבים.","ro":"Tsukei ha-gir ha-levanim marhivim."},{"fr":"Le sol est mouillé, fais attention.","tgt":"הרצפה רטובה, תיזהר.","ro":"Ha-ritspa retuva, tizaher."},{"fr":"On a regardé un petit film sur l'histoire du lieu.","tgt":"ראינו סרט קצר על ההיסטוריה של המקום.","ro":"Ra'inu seret katsar al ha-historya shel ha-makom."},{"fr":"Il y a ici une vieille voie ferrée le long de la côte.","tgt":"יש פה מסילת רכבת ישנה לאורך החוף.","ro":"Yesh po mesilat rakevet yeshana le-orekh ha-khof."},{"fr":"C'est le point le plus au nord de la côte d'Israël.","tgt":"זו הנקודה הצפונית ביותר בחוף של ישראל.","ro":"Zo ha-nekuda ha-tsfonit beyoter ba-khof shel Yisrael."},{"fr":"Le billet adulte coûte environ soixante-dix shekels.","tgt":"כרטיס למבוגר עולה בערך שבעים שקל.","ro":"Kartis le-mevugar ole be-erekh shiv'im shekel."}]},{"title":"Le marché de Nazareth","phrases":[{"fr":"Le marché ouvre tôt le matin.","tgt":"השוק נפתח מוקדם בבוקר.","ro":"Ha-shuk niftakh mukdam ba-boker."},{"fr":"Combien coûtent ces épices ?","tgt":"כמה עולים התבלינים האלה?","ro":"Kama olim ha-tavlinim ha-ele?"},{"fr":"C'est trop cher, vous pouvez baisser le prix ?","tgt":"זה יקר מדי, אפשר להוריד במחיר?","ro":"Ze yakar midai, efshar lehorid ba-mekhir?"},{"fr":"Je vous en donne quarante shekels.","tgt":"אני נותן לך ארבעים שקל.","ro":"Ani noten lekha arba'im shekel."},{"fr":"Ces biscuits ont été cuits ce matin.","tgt":"את העוגיות האלה אפו הבוקר.","ro":"Et ha-ugiyot ha-ele afu ha-boker."},{"fr":"Je cherche un cadeau pour ma mère.","tgt":"אני מחפש מתנה לאמא שלי.","ro":"Ani mekhapes matana le-ima sheli."},{"fr":"Le vendeur nous a offert un café.","tgt":"המוכר הזמין אותנו לקפה.","ro":"Ha-mokher hizmin otanu le-kafe."},{"fr":"Les ruelles sont pleines de couleurs et d'odeurs.","tgt":"הסמטאות מלאות צבעים וריחות.","ro":"Ha-simta'ot mele'ot tsva'im ve-reikhot."},{"fr":"Donnez-moi deux cents grammes de zaatar.","tgt":"תן לי מאתיים גרם זעתר.","ro":"Ten li matayim gram za'atar."},{"fr":"On a passé toute la matinée au marché.","tgt":"העברנו את כל הבוקר בשוק.","ro":"He'evarnu et kol ha-boker ba-shuk."}]},{"title":"Une nuit en auberge de jeunesse","phrases":[{"fr":"J'ai réservé un lit dans un dortoir.","tgt":"הזמנתי מיטה בחדר משותף.","ro":"Hizmanti mita be-kheder meshutaf."},{"fr":"Le petit-déjeuner est servi de sept à dix heures.","tgt":"ארוחת הבוקר מוגשת משבע עד עשר.","ro":"Arukhat ha-boker mugeshet mi-sheva ad eser."},{"fr":"Où est-ce qu'on peut laisser nos valises ?","tgt":"איפה אפשר להשאיר את המזוודות?","ro":"Eifo efshar lehash'ir et ha-mizvadot?"},{"fr":"Mon voisin de chambre ronfle toute la nuit.","tgt":"השכן שלי בחדר נוחר כל הלילה.","ro":"Ha-shakhen sheli ba-kheder nokher kol ha-laila."},{"fr":"Il y a une cuisine commune au rez-de-chaussée.","tgt":"יש מטבח משותף בקומת הקרקע.","ro":"Yesh mitbakh meshutaf be-komat ha-karka."},{"fr":"Internet ne marche pas dans les chambres.","tgt":"האינטרנט לא עובד בחדרים.","ro":"Ha-internet lo oved ba-khadarim."},{"fr":"J'ai rencontré des voyageurs très sympas sur la terrasse.","tgt":"פגשתי מטיילים נחמדים מאוד במרפסת.","ro":"Pagashti metaylim nekhmadim me'od ba-mirpeset."},{"fr":"Ce soir, on fait un barbecue tous ensemble.","tgt":"הערב עושים על האש כולם ביחד.","ro":"Ha-erev osim al ha-esh kulam beyakhad."},{"fr":"Il faut rendre la clé avant onze heures.","tgt":"צריך להחזיר את המפתח לפני אחת עשרה.","ro":"Tsarikh lehakhzir et ha-mafte'akh lifnei akhat esre."},{"fr":"Les douches sont au fond du couloir.","tgt":"המקלחות בסוף המסדרון.","ro":"Ha-miklakhot be-sof ha-misderon."}]},{"title":"Une visite guidée à Nazareth","phrases":[{"fr":"Le guide qu'on a rencontré parle très bien français.","tgt":"המדריך שפגשנו מדבר צרפתית טוב מאוד.","ro":"Ha-madrikh she-pagashnu medaber tsarfatit tov me'od."},{"fr":"La maison qu'on visite a plus de deux cents ans.","tgt":"הבית שאנחנו מבקרים בו בן יותר ממאתיים שנה.","ro":"Ha-bayit she-anakhnu mevakrim bo ben yoter mi-matayim shana."},{"fr":"Il dit que le marché existe depuis des siècles.","tgt":"הוא אומר שהשוק קיים כבר מאות שנים.","ro":"Hu omer she-ha-shuk kayam kvar me'ot shanim."},{"fr":"C'est la ruelle qui mène à la place principale.","tgt":"זו הסמטה שמובילה לכיכר המרכזית.","ro":"Zo ha-simta she-movila la-kikar ha-merkazit."},{"fr":"Je pense qu'on a le temps de boire un café.","tgt":"אני חושב שיש לנו זמן לשתות קפה.","ro":"Ani khoshev she-yesh lanu zman lishtot kafe."},{"fr":"Le petit café qui est au coin sert du café à la cardamome.","tgt":"בית הקפה שנמצא בפינה מגיש קפה עם הל.","ro":"Beit ha-kafe she-nimtsa ba-pina magish kafe im hel."},{"fr":"Montre-moi la photo que tu as prise.","tgt":"תראה לי את התמונה שצילמת.","ro":"Tare li et ha-tmuna she-tsilamta."},{"fr":"Il y a beaucoup de choses qu'on n'a pas vues.","tgt":"יש הרבה דברים שלא ראינו.","ro":"Yesh harbe dvarim she-lo ra'inu."},{"fr":"Le guide dit qu'il faut revenir le soir.","tgt":"המדריך אומר שצריך לחזור בערב.","ro":"Ha-madrikh omer she-tsarikh lakhzor ba-erev."},{"fr":"On a dîné dans un restaurant que le guide nous a conseillé.","tgt":"אכלנו ארוחת ערב במסעדה שהמדריך המליץ עליה.","ro":"Akhalnu arukhat erev be-mis'ada she-ha-madrikh himlits aleha."}],"tip":{"title":"« She- » : que, qui","example":"Le guide qu'on a rencontré parle très bien français. — המדריך <b>שפגשנו</b> מדבר צרפתית טוב מאוד.","body":"Le petit mot « she- » remplace à la fois que et qui, et il se colle directement au mot suivant, sans pause. Dans « ha-madrikh she-pagashnu », mot à mot le guide que-nous-avons-rencontré, il relie le nom à la suite de la phrase. Il sert aussi après les verbes de parole ou de pensée : « ani khoshev she-yesh lanu zman », je pense qu'on a le temps. Pour qui, c'est pareil : « ha-simta she-movila la-kikar », la ruelle qui mène à la place. Bonne nouvelle, « she- » ne change jamais, ni au féminin ni au pluriel. Astuce : chaque fois que vous voulez dire que ou qui, collez simplement « she » devant le mot suivant.","exampleRo":"Ha-madrikh she-pagashnu medaber tsarfatit tov me'od.","lit":"[le] guide · que-nous-avons-rencontré · parle · français · bien · très"}},{"title":"Une croisière sur le lac","phrases":[{"fr":"Le bateau part de Tibériade à dix heures.","tgt":"הסירה יוצאת מטבריה בעשר.","ro":"Ha-sira yotset mi-Tveriya be-eser."},{"fr":"On peut acheter les billets à bord ?","tgt":"אפשר לקנות כרטיסים על הסירה?","ro":"Efshar liknot kartisim al ha-sira?"},{"fr":"Le capitaine a mis de la musique pour danser.","tgt":"הקפטן שם מוזיקה לריקודים.","ro":"Ha-kapitan sam muzika le-rikudim."},{"fr":"Assieds-toi à l'ombre, le soleil tape fort.","tgt":"שב בצל, השמש חזקה.","ro":"Shev ba-tsel, ha-shemesh khazaka."},{"fr":"De là, on aperçoit les montagnes au loin.","tgt":"משם רואים את ההרים מרחוק.","ro":"Mi-sham ro'im et ha-harim me-rakhok."},{"fr":"Le lac est très calme ce matin.","tgt":"האגם שקט מאוד הבוקר.","ro":"Ha-agam shaket me'od ha-boker."},{"fr":"La traversée dure environ quarante minutes.","tgt":"השיט לוקח בערך ארבעים דקות.","ro":"Ha-shayit lokeakh be-erekh arba'im dakot."},{"fr":"J'ai un peu le mal de mer.","tgt":"יש לי קצת מחלת ים.","ro":"Yesh li ktsat makhalat yam."},{"fr":"Des pêcheurs lancent leurs filets près du rivage.","tgt":"דייגים זורקים רשתות ליד החוף.","ro":"Dayagim zorkim reshatot leyad ha-khof."},{"fr":"On est rentrés au port sous un ciel orange.","tgt":"חזרנו לנמל מתחת לשמיים כתומים.","ro":"Khazarnu la-namal mitakhat la-shamayim ktumim."}]},{"title":"Une baignade aux sources de Gan HaShlosha","phrases":[{"fr":"L'eau des sources reste à vingt-huit degrés toute l'année.","tgt":"המים במעיינות נשארים עשרים ושמונה מעלות כל השנה.","ro":"Ha-mayim ba-ma'ayanot nish'arim esrim ve-shmone ma'alot kol ha-shana."},{"fr":"On a étendu une couverture sur l'herbe.","tgt":"פרשנו שמיכה על הדשא.","ro":"Parasnu smikha al ha-deshe."},{"fr":"Il y a de petites cascades entre les bassins.","tgt":"יש מפלים קטנים בין הבריכות.","ro":"Yesh mapalim ktanim bein ha-brekhot."},{"fr":"Les poissons viennent nous chatouiller les pieds.","tgt":"הדגים באים לדגדג לנו ברגליים.","ro":"Ha-dagim ba'im ledagdeg lanu ba-raglayim."},{"fr":"Le parking est plein dès neuf heures.","tgt":"החניה מלאה כבר מתשע.","ro":"Ha-khanaya mele'a kvar me-tesha."},{"fr":"On a apporté des sandwichs et des fruits.","tgt":"הבאנו כריכים ופירות.","ro":"Heveinu kerikhim ve-perot."},{"fr":"Saute, l'eau est super !","tgt":"תקפוץ, המים מעולים!","ro":"Tikfots, ha-mayim me'ulim!"},{"fr":"Les maîtres-nageurs surveillent tous les bassins.","tgt":"המצילים שומרים על כל הבריכות.","ro":"Ha-matsilim shomrim al kol ha-brekhot."},{"fr":"J'ai oublié ma serviette dans la voiture.","tgt":"שכחתי את המגבת באוטו.","ro":"Shakhakhti et ha-magevet ba-oto."},{"fr":"C'est l'un des plus beaux endroits du nord.","tgt":"זה אחד המקומות הכי יפים בצפון.","ro":"Ze ekhad ha-mekomot hakhi yafim ba-tsafon."}]},{"title":"Un bus manqué","phrases":[{"fr":"Le dernier bus est déjà parti ?","tgt":"האוטובוס האחרון כבר יצא?","ro":"Ha-otobus ha-akharon kvar yatsa?"},{"fr":"Le prochain passe dans quarante minutes.","tgt":"הבא מגיע בעוד ארבעים דקות.","ro":"Ha-ba magi'a be-od arba'im dakot."},{"fr":"Il faut payer avec une carte de transport.","tgt":"צריך לשלם עם כרטיס תחבורה.","ro":"Tsarikh leshalem im kartis takhbura."},{"fr":"Est-ce que ce bus s'arrête à la gare de Haïfa ?","tgt":"האוטובוס הזה עוצר בתחנת הרכבת של חיפה?","ro":"Ha-otobus ha-ze otser be-takhanat ha-rakevet shel Kheifa?"},{"fr":"Dis-moi quand on arrive, s'il te plaît.","tgt":"תגיד לי כשמגיעים, בבקשה.","ro":"Tagid li kshe-magi'im, bevakasha."},{"fr":"Le chauffeur a oublié de s'arrêter à mon arrêt.","tgt":"הנהג שכח לעצור בתחנה שלי.","ro":"Ha-nahag shakhakh la'atsor ba-takhana sheli."},{"fr":"Je suis descendu deux arrêts trop tard.","tgt":"ירדתי שתי תחנות מאוחר מדי.","ro":"Yaradti shtei takhanot me'ukhar midai."},{"fr":"On va prendre un taxi collectif.","tgt":"ניקח מונית שירות.","ro":"Nikakh monit sherut."},{"fr":"Le vendredi après-midi, il y a moins de bus.","tgt":"ביום שישי אחר הצהריים יש פחות אוטובוסים.","ro":"Be-yom shishi akhar ha-tsohorayim yesh pakhot otobusim."},{"fr":"Finalement, on est arrivés juste à l'heure.","tgt":"בסוף הגענו בדיוק בזמן.","ro":"Ba-sof higa'nu be-diyuk ba-zman."}]},{"title":"Un orage change nos plans","phrases":[{"fr":"On voulait aller à la plage, mais il pleut.","tgt":"רצינו ללכת לים, אבל יורד גשם.","ro":"Ratsinu lalekhet la-yam, aval yored geshem."},{"fr":"Bien qu'il pleuve, on sort quand même.","tgt":"למרות שיורד גשם, אנחנו יוצאים בכל זאת.","ro":"Lamrot she-yored geshem, anakhnu yots'im be-khol zot."},{"fr":"Le musée est petit, mais très intéressant.","tgt":"המוזיאון קטן, אבל מאוד מעניין.","ro":"Ha-muze'on katan, aval me'od me'anyen."},{"fr":"Bien qu'on soit fatigués, on a encore envie de marcher.","tgt":"למרות שאנחנו עייפים, עוד בא לנו ללכת.","ro":"Lamrot she-anakhnu ayefim, od ba lanu lalekhet."},{"fr":"Les routes sont inondées près de la côte.","tgt":"הכבישים מוצפים ליד החוף.","ro":"Ha-kvishim mutsafim leyad ha-khof."},{"fr":"J'ai pris un parapluie, mais j'ai oublié mon manteau.","tgt":"לקחתי מטרייה, אבל שכחתי את המעיל.","ro":"Lakakhti mitriya, aval shakhakhti et ha-me'il."},{"fr":"Bien que le ciel soit gris, la vue reste belle.","tgt":"למרות שהשמיים אפורים, הנוף עדיין יפה.","ro":"Lamrot she-ha-shamayim aforim, ha-nof adayin yafe."},{"fr":"On attend dans un café que l'orage passe.","tgt":"אנחנו מחכים בבית קפה עד שהסערה תעבור.","ro":"Anakhnu mekhakim be-veit kafe ad she-ha-se'ara ta'avor."},{"fr":"En été, il ne pleut presque jamais ici.","tgt":"בקיץ כמעט אף פעם לא יורד כאן גשם.","ro":"Ba-kayits kim'at af pa'am lo yored kan geshem."},{"fr":"Malgré la pluie, c'était une très belle journée.","tgt":"למרות הגשם, זה היה יום יפה מאוד.","ro":"Lamrot ha-geshem, ze haya yom yafe me'od."}],"tip":{"title":"« Aval » et « lamrot she- » : mais, bien que","example":"Bien qu'il pleuve, on sort quand même. — <b>למרות שיורד</b> גשם, אנחנו יוצאים בכל זאת.","body":"« Aval » veut dire mais et s'emploie exactement comme en français : « ha-muze'on katan, aval me'od me'anyen », le musée est petit, mais très intéressant. Pour dire bien que, on dit « lamrot she- », mot à mot malgré que. Bonne nouvelle, pas de subjonctif : le verbe reste au temps normal, comme dans « lamrot she-yored geshem », mot à mot malgré que descend pluie. Devant un simple nom, on enlève « she » : « lamrot ha-geshem », malgré la pluie. On finit souvent la phrase par « be-khol zot », quand même. Astuce : pensez à malgré, et ajoutez « she » dès qu'un verbe arrive.","exampleRo":"Lamrot she-yored geshem, anakhnu yots'im be-khol zot.","lit":"malgré · que-descend · pluie · nous · sortons · [en] tout · cela"}},{"title":"Un portefeuille perdu","phrases":[{"fr":"Je ne trouve pas mon portefeuille.","tgt":"אני לא מוצא את הארנק שלי.","ro":"Ani lo motse et ha-arnak sheli."},{"fr":"Je l'avais encore au restaurant.","tgt":"היה לי אותו עוד במסעדה.","ro":"Haya li oto od ba-mis'ada."},{"fr":"Tu as regardé sous le siège de la voiture ?","tgt":"הסתכלת מתחת למושב באוטו?","ro":"Histakalta mitakhat la-moshav ba-oto?"},{"fr":"Il y avait mes cartes et cent shekels dedans.","tgt":"היו בו הכרטיסים שלי ומאה שקל.","ro":"Hayu bo ha-kartisim sheli u-me'a shekel."},{"fr":"Il faut bloquer la carte tout de suite.","tgt":"צריך לחסום את הכרטיס מיד.","ro":"Tsarikh lakhsom et ha-kartis miyad."},{"fr":"Où est le commissariat le plus proche ?","tgt":"איפה תחנת המשטרה הכי קרובה?","ro":"Eifo takhanat ha-mishtara hakhi krova?"},{"fr":"Le policier m'a demandé de remplir un formulaire.","tgt":"השוטר ביקש ממני למלא טופס.","ro":"Ha-shoter bikesh mimeni lemale tofes."},{"fr":"Quelqu'un l'a rapporté à la réception de l'hôtel !","tgt":"מישהו החזיר אותו לקבלה של המלון!","ro":"Mishehu hekhezir oto la-kabala shel ha-malon!"},{"fr":"Rien ne manque, même pas l'argent.","tgt":"שום דבר לא חסר, אפילו לא הכסף.","ro":"Shum davar lo khaser, afilu lo ha-kesef."},{"fr":"Je respire enfin.","tgt":"סוף סוף אני נושם.","ro":"Sof sof ani noshem."}]},{"title":"À la pharmacie","phrases":[{"fr":"Les moustiques m'ont piqué toute la nuit.","tgt":"יתושים עקצו אותי כל הלילה.","ro":"Yetushim aktsu oti kol ha-laila."},{"fr":"Vous avez quelque chose contre les coups de soleil ?","tgt":"יש לך משהו נגד כוויות שמש?","ro":"Yesh lekha mashehu neged kviyot shemesh?"},{"fr":"J'ai mal à la gorge depuis hier.","tgt":"כואב לי הגרון מאתמול.","ro":"Ko'ev li ha-garon me-etmol."},{"fr":"Il faut prendre deux comprimés par jour.","tgt":"צריך לקחת שני כדורים ביום.","ro":"Tsarikh lakakhat shnei kadurim ba-yom."},{"fr":"Je me suis tordu la cheville pendant la randonnée.","tgt":"נקעתי את הקרסול בטיול.","ro":"Naka'ti et ha-karsol ba-tiyul."},{"fr":"Est-ce que j'ai besoin d'une ordonnance ?","tgt":"אני צריך מרשם?","ro":"Ani tsarikh mirsham?"},{"fr":"Mets de la glace et repose-toi.","tgt":"שים קרח ותנוח.","ro":"Sim kerakh ve-tanuakh."},{"fr":"Bois beaucoup, il fait très chaud dehors.","tgt":"תשתה הרבה, חם מאוד בחוץ.","ro":"Tishte harbe, kham me'od ba-khuts."},{"fr":"La pharmacienne m'a donné une pommade.","tgt":"הרוקחת נתנה לי משחה.","ro":"Ha-rokakhat natna li mishkha."},{"fr":"Je me sens déjà beaucoup mieux.","tgt":"אני כבר מרגיש הרבה יותר טוב.","ro":"Ani kvar margish harbe yoter tov."}]},{"title":"Derniers achats avant le retour","phrases":[{"fr":"Il me reste encore quelques shekels à dépenser.","tgt":"נשארו לי עוד כמה שקלים להוציא.","ro":"Nish'aru li od kama shkalim lehotsi."},{"fr":"J'ai acheté de l'huile d'olive de Galilée.","tgt":"קניתי שמן זית מהגליל.","ro":"Kaniti shemen zayit me-ha-Galil."},{"fr":"Ce bol en céramique est fait à la main.","tgt":"הקערה הזאת מקרמיקה עשויה ביד.","ro":"Ha-ke'ara ha-zot mi-keramika asuya be-yad."},{"fr":"Vous pouvez l'emballer pour l'avion ?","tgt":"אפשר לעטוף את זה לטיסה?","ro":"Efshar la'atof et ze la-tisa?"},{"fr":"Ma valise est beaucoup trop lourde.","tgt":"המזוודה שלי כבדה מדי.","ro":"Ha-mizvada sheli kveda midai."},{"fr":"On doit rendre la voiture demain à midi.","tgt":"אנחנו צריכים להחזיר את הרכב מחר בצהריים.","ro":"Anakhnu tsrikhim lehakhzir et ha-rekhev makhar ba-tsohorayim."},{"fr":"J'ai pris des dattes pour toute la famille.","tgt":"לקחתי תמרים לכל המשפחה.","ro":"Lakakhti tmarim le-khol ha-mishpakha."},{"fr":"Il faut être à l'aéroport trois heures avant le vol.","tgt":"צריך להיות בשדה התעופה שלוש שעות לפני הטיסה.","ro":"Tsarikh lihyot bi-sde ha-te'ufa shalosh sha'ot lifnei ha-tisa."},{"fr":"Ces savons à l'huile d'olive sentent très bon.","tgt":"הסבונים האלה משמן זית מריחים נהדר.","ro":"Ha-sabonim ha-ele mi-shemen zayit merikhim nehedar."},{"fr":"J'ai déjà envie de revenir dans le nord.","tgt":"כבר בא לי לחזור לצפון.","ro":"Kvar ba li lakhzor la-tsafon."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Maintenant, je sais louer une voiture en hébreu.","tgt":"עכשיו אני יודע לשכור רכב בעברית.","ro":"Akhshav ani yode'a liskor rekhev be-ivrit."},{"fr":"Je peux demander mon chemin sans hésiter.","tgt":"אני יכול לשאול על הדרך בלי להסס.","ro":"Ani yakhol lish'ol al ha-derekh bli lehases."},{"fr":"Je comprends mieux les annonces dans le bus.","tgt":"אני מבין יותר טוב את ההודעות באוטובוס.","ro":"Ani mevin yoter tov et ha-hoda'ot ba-otobus."},{"fr":"J'ai appris à parler au passé et au futur.","tgt":"למדתי לדבר בעבר ובעתיד.","ro":"Lamadti ledaber be-avar u-ve-atid."},{"fr":"Au marché, j'ai réussi à marchander en hébreu.","tgt":"בשוק הצלחתי להתמקח בעברית.","ro":"Ba-shuk hitslakhti lehitmake'akh be-ivrit."},{"fr":"Les gens sont contents quand je parle leur langue.","tgt":"אנשים שמחים כשאני מדבר בשפה שלהם.","ro":"Anashim smekhim kshe-ani medaber ba-safa shelahem."},{"fr":"Je fais encore des erreurs, mais on me comprend.","tgt":"אני עדיין עושה טעויות, אבל מבינים אותי.","ro":"Ani adayin ose ta'uyot, aval mevinim oti."},{"fr":"Le hébreu ne me paraît plus si difficile.","tgt":"העברית כבר לא נראית לי כל כך קשה.","ro":"Ha-ivrit kvar lo nir'et li kol kakh kasha."},{"fr":"Je veux continuer à pratiquer chaque jour.","tgt":"אני רוצה להמשיך לתרגל כל יום.","ro":"Ani rotse lehamshikh letargel kol yom."},{"fr":"Prochaine étape : parler avec de nouveaux amis.","tgt":"השלב הבא: לדבר עם חברים חדשים.","ro":"Ha-shalav ha-ba: ledaber im khaverim khadashim."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles à Netanya","phrases":[{"fr":"Ça fait une éternité qu'on ne s'est pas vus !","tgt":"הרבה זמן לא התראינו!","ro":"Harbe zman lo hitre'inu!"},{"fr":"Qu'est-ce que tu deviens depuis l'été dernier ?","tgt":"מה קורה איתך מאז הקיץ שעבר?","ro":"Ma kore itkha me'az hakayits she'avar?"},{"fr":"Je suis parti vivre à Netanya il y a trois mois.","tgt":"עברתי לגור בנתניה לפני שלושה חודשים.","ro":"Avarti lagur be-Netanya lifnei shlosha khodashim."},{"fr":"Tu habites près de la plage ?","tgt":"אתה גר ליד הים?","ro":"Ata gar leyad hayam?"},{"fr":"Oui, c'est à cinq minutes à pied.","tgt":"כן, חמש דקות הליכה.","ro":"Ken, khamesh dakot halikha."},{"fr":"Tu as l'air en pleine forme.","tgt":"אתה נראה מצוין.","ro":"Ata nir'e metsuyan."},{"fr":"Merci, je fais du sport tous les matins sur la promenade.","tgt":"תודה, אני עושה ספורט כל בוקר בטיילת.","ro":"Toda, ani ose sport kol boker batayelet."},{"fr":"Et toi, tu travailles toujours à Herzliya ?","tgt":"ואתה, אתה עדיין עובד בהרצליה?","ro":"Ve'ata, ata ada'in oved be-Hertsliya?"},{"fr":"Oui, mais je cherche quelque chose de nouveau.","tgt":"כן, אבל אני מחפש משהו חדש.","ro":"Ken, aval ani mekhapes mashehu khadash."},{"fr":"Il faudrait qu'on se voie plus souvent.","tgt":"צריך להיפגש יותר.","ro":"Tsarikh lehipagesh yoter."}]},{"title":"Parler comme un Israélien","phrases":[{"fr":"Salut frérot, quoi de neuf ?","tgt":"אהלן אחי, מה נשמע?","ro":"Ahlan akhi, ma nishma?"},{"fr":"Tout est cool, et toi ?","tgt":"הכל סבבה, ואתה?","ro":"Hakol sababa, ve'ata?"},{"fr":"On va à la plage ? Allez, on bouge !","tgt":"הולכים לים? יאללה, זזים!","ro":"Holkhim layam? Yalla, zazim!"},{"fr":"Ce film était vraiment top.","tgt":"הסרט היה ממש אחלה.","ro":"Haseret haya mamash akhla."},{"fr":"Sans blague ? Je ne te crois pas !","tgt":"וואלה? אני לא מאמין לך!","ro":"Wala? Ani lo ma'amin lekha!"},{"fr":"Je rigole, ne t'inquiète pas.","tgt":"סתם, אל תדאג.","ro":"Stam, al tid'ag."},{"fr":"Pas de pression, on a tout le temps.","tgt":"אין לחץ, יש זמן.","ro":"Ein lakhats, yesh zman."},{"fr":"Cette fête était complètement dingue !","tgt":"המסיבה הייתה חבל על הזמן!","ro":"Hamesiba hayta khaval al hazman!"},{"fr":"Allez, grouille-toi, on est en retard !","tgt":"יאללה, תזוז, אנחנו מאחרים!","ro":"Yalla, tazuz, anakhnu me'akharim!"},{"fr":"Trop bien, on se voit ce soir alors.","tgt":"אחלה, אז נתראה הערב.","ro":"Akhla, az nitra'e ha'erev."}],"tip":{"title":"Le registre familier et l'argot","example":"Tout est cool, et toi ? — הכל <b>סבבה</b>, ואתה?","body":"Entre amis, les Israéliens parlent de façon très détendue, avec quelques petits mots d'argot qui reviennent sans arrêt. « Sababa » veut dire cool ou ça marche, et « akhla » veut dire super : on dit « akhla seret », un super film. « Yalla » sert à tout pour lancer le mouvement, comme notre allez ou on y va. « Stam » veut dire je dis ça comme ça, ou je rigole, et « khaval al hazman », mot à mot dommage pour le temps, signifie au contraire que c'était génial. Décomposons « hakol sababa » : « hakol », le tout, puis « sababa », cool, sans aucun verbe être, exactement comme un tout cool. Astuce : glissez un « yalla » ou un « sababa » dans vos phrases, on vous trouvera tout de suite plus naturel.","exampleRo":"Hakol sababa, ve'ata?","lit":"le-tout · cool · et-toi ?"}},{"title":"Un anniversaire surprise","phrases":[{"fr":"Samedi, c'est l'anniversaire de Noa.","tgt":"בשבת יש לנועה יום הולדת.","ro":"Beshabat yesh le-No'a yom huledet."},{"fr":"On lui organise une fête surprise.","tgt":"אנחנו מארגנים לה מסיבת הפתעה.","ro":"Anakhnu me'argenim la mesibat hafta'a."},{"fr":"Elle fête ses trente ans.","tgt":"היא חוגגת שלושים.","ro":"Hi khogeget shloshim."},{"fr":"Qui se charge du gâteau ?","tgt":"מי אחראי על העוגה?","ro":"Mi akhra'i al ha'uga?"},{"fr":"Moi, je vais commander un gâteau au chocolat.","tgt":"אני אזמין עוגת שוקולד.","ro":"Ani azmin ugat shokolad."},{"fr":"Il ne faut surtout pas qu'elle se doute de quelque chose.","tgt":"אסור שהיא תדע כלום.","ro":"Asur shehi teda klum."},{"fr":"Son copain va d'abord l'emmener au restaurant.","tgt":"החבר שלה ייקח אותה קודם למסעדה.","ro":"Hakhaver shela yikakh ota kodem lemis'ada."},{"fr":"On se retrouve tous chez elle à huit heures.","tgt":"כולנו נפגשים אצלה בשמונה.","ro":"Kulanu nifgashim etsla bishmone."},{"fr":"Qu'est-ce qu'on lui achète comme cadeau ?","tgt":"מה נקנה לה במתנה?","ro":"Ma nikne la bematana?"},{"fr":"Chacun met cinquante shekels.","tgt":"כל אחד שם חמישים שקל.","ro":"Kol ekhad sam khamishim shekel."}]},{"title":"Matkot sur la plage","phrases":[{"fr":"Tu viens jouer aux raquettes de plage ?","tgt":"אתה בא לשחק מטקות?","ro":"Ata ba lesakhek matkot?"},{"fr":"J'ai apporté les raquettes et deux balles.","tgt":"הבאתי את המטקות ושני כדורים.","ro":"Heveti et hamatkot ushnei kadurim."},{"fr":"Mettons-nous près de l'eau, le sable y est plus dur.","tgt":"בוא נעמוד ליד המים, שם החול יותר קשה.","ro":"Bo na'amod leyad hamayim, sham hakhol yoter kashe."},{"fr":"Le bruit des matkot, c'est le son de l'été en Israël.","tgt":"הרעש של המטקות זה הצליל של הקיץ בישראל.","ro":"Hara'ash shel hamatkot ze hatslil shel hakayits be-Yisra'el."},{"fr":"Frappe plus fort, je suis prêt !","tgt":"תרביץ יותר חזק, אני מוכן!","ro":"Tarbits yoter khazak, ani mukhan!"},{"fr":"Oups, la balle est tombée dans l'eau.","tgt":"אופס, הכדור נפל למים.","ro":"Ups, hakadur nafal lamayim."},{"fr":"Le but, c'est que la balle ne tombe jamais.","tgt":"אסור שהכדור ייפול.","ro":"Asur shehakadur yipol."},{"fr":"Il fait trop chaud, on fait une pause ?","tgt":"חם מדי, עושים הפסקה?","ro":"Kham midai, osim hafsaka?"},{"fr":"Allons nager un peu avant de continuer.","tgt":"בוא נשחה קצת לפני שנמשיך.","ro":"Bo nis'khe ktsat lifnei shenamshikh."},{"fr":"Tu joues vraiment bien, tu t'entraînes où ?","tgt":"אתה משחק ממש טוב, איפה אתה מתאמן?","ro":"Ata mesakhek mamash tov, eifo ata mit'amen?"}]},{"title":"Rien n'est sûr","phrases":[{"fr":"Peut-être qu'on ira à la plage demain.","tgt":"אולי נלך לים מחר.","ro":"Ulay nelekh layam makhar."},{"fr":"Apparemment, il va faire très chaud ce week-end.","tgt":"כנראה שיהיה חם מאוד בסוף השבוע.","ro":"Kanir'e sheyihye kham me'od besof hashavua."},{"fr":"Dan ne répond pas, il dort apparemment.","tgt":"דן לא עונה, הוא כנראה ישן.","ro":"Dan lo one, hu kanir'e yashen."},{"fr":"Il est peut-être déjà en route.","tgt":"אולי הוא כבר בדרך.","ro":"Ulay hu kvar baderekh."},{"fr":"Tu viens ce soir ? Peut-être, je ne sais pas encore.","tgt":"אתה בא הערב? אולי, אני עוד לא יודע.","ro":"Ata ba ha'erev? Ulay, ani od lo yode'a."},{"fr":"Apparemment, il n'y a plus de billets pour le concert.","tgt":"כנראה שאין יותר כרטיסים להופעה.","ro":"Kanir'e she'ein yoter kartisim lahofa'a."},{"fr":"On peut peut-être en trouver sur internet.","tgt":"אולי אפשר למצוא באינטרנט.","ro":"Ulay efshar limtso ba'internet."},{"fr":"Elle est sûrement à Herzliya chez ses parents.","tgt":"היא כנראה בהרצליה אצל ההורים שלה.","ro":"Hi kanir'e be-Hertsliya etsel hahorim shela."},{"fr":"Peut-être plus tard, là je suis occupé.","tgt":"אולי אחר כך, עכשיו אני עסוק.","ro":"Ulay akhar kakh, akhshav ani asuk."},{"fr":"Il a apparemment oublié notre rendez-vous.","tgt":"כנראה שהוא שכח מהפגישה שלנו.","ro":"Kanir'e shehu shakhakh mehapgisha shelanu."}],"tip":{"title":"« Ulay » et « kanir'e » : peut-être, apparemment","example":"Dan ne répond pas, il dort apparemment. — דן לא עונה, הוא <b>כנראה</b> ישן.","body":"Pour exprimer le doute, deux petits mots suffisent. « Ulay » veut dire peut-être, et se place simplement en tête de phrase : « ulay nelekh layam », peut-être nous irons à la mer. « Kanir'e » veut dire apparemment ou sûrement, quand on devine quelque chose à partir d'un indice. Dans « hu kanir'e yashen », mot à mot lui apparemment dort, le mot se glisse juste avant le verbe. On peut aussi dire « kanir'e she » suivi d'une phrase entière, comme « kanir'e sheyihye kham », apparemment il fera chaud. Astuce : « ulay » pour ce qu'on ne sait pas du tout, « kanir'e » pour ce qu'on devine.","exampleRo":"Dan lo one, hu kanir'e yashen.","lit":"Dan · ne-pas · répond, · lui · apparemment · dort"}},{"title":"Un barbecue entre amis","phrases":[{"fr":"Vendredi, on fait un barbecue au parc.","tgt":"ביום שישי עושים מנגל בפארק.","ro":"Beyom shishi osim mangal bapark."},{"fr":"Qui apporte le charbon ?","tgt":"מי מביא את הפחמים?","ro":"Mi mevi et hapekhamim?"},{"fr":"J'ai acheté des brochettes et des saucisses.","tgt":"קניתי שיפודים ונקניקיות.","ro":"Kaniti shipudim venaknikiyot."},{"fr":"N'oublie pas les pitas et la salade !","tgt":"אל תשכח את הפיתות ואת הסלט!","ro":"Al tishkakh et hapitot ve'et hasalat!"},{"fr":"Mon frère est le roi du barbecue.","tgt":"אח שלי הוא מלך המנגל.","ro":"Akh sheli hu melekh hamangal."},{"fr":"La viande est presque prête, apportez des assiettes.","tgt":"הבשר כמעט מוכן, תביאו צלחות.","ro":"Habasar kim'at mukhan, tavi'u tsalakhot."},{"fr":"Il reste du houmous ?","tgt":"נשאר עוד חומוס?","ro":"Nishar od khumus?"},{"fr":"On a acheté beaucoup trop à manger, comme toujours.","tgt":"קנינו יותר מדי אוכל, כרגיל.","ro":"Kaninu yoter midai okhel, karagil."},{"fr":"Qui veut emporter les restes ?","tgt":"מי רוצה לקחת את השאריות?","ro":"Mi rotse lakakhat et hashe'eriyot?"},{"fr":"On range ensemble et on rentre.","tgt":"מנקים ביחד והולכים הביתה.","ro":"Menakim beyakhad veholkhim habayta."}]},{"title":"Un festival de musique","phrases":[{"fr":"Cet été, il y a un grand festival au bord de la mer.","tgt":"בקיץ הזה יש פסטיבל גדול ליד הים.","ro":"Bakayits haze yesh festival gadol leyad hayam."},{"fr":"Tu as déjà pris ton billet ?","tgt":"כבר קנית כרטיס?","ro":"Kvar kanita kartis?"},{"fr":"Oui, j'ai un billet pour les trois jours.","tgt":"כן, לקחתי כרטיס לשלושה ימים.","ro":"Ken, lakakhti kartis lishlosha yamim."},{"fr":"On dort sous la tente sur place.","tgt":"אנחנו ישנים באוהל במקום.","ro":"Anakhnu yeshenim ba'ohel bamakom."},{"fr":"Mon groupe préféré joue le deuxième soir.","tgt":"הלהקה האהובה עליי מופיעה בערב השני.","ro":"Halahaka ha'ahuva alai mofi'a ba'erev hasheni."},{"fr":"Il y aura un monde fou devant la scène.","tgt":"יהיו המון אנשים מול הבמה.","ro":"Yihyu hamon anashim mul habama."},{"fr":"Prends un chapeau et de la crème solaire.","tgt":"תיקח כובע וקרם הגנה.","ro":"Tikakh kova vekrem hagana."},{"fr":"L'année dernière, on a dansé jusqu'au matin.","tgt":"בשנה שעברה רקדנו עד הבוקר.","ro":"Bashana she'avra rakadnu ad haboker."},{"fr":"On a tellement chanté que j'ai perdu ma voix.","tgt":"שרנו כל כך הרבה שאיבדתי את הקול.","ro":"Sharnu kol kakh harbe she'ibadti et hakol."},{"fr":"On y retourne l'an prochain, c'est sûr.","tgt":"בשנה הבאה חוזרים, בטוח.","ro":"Bashana haba'a khozrim, batu'akh."}]},{"title":"Les séries du moment","phrases":[{"fr":"Tu regardes quelle série en ce moment ?","tgt":"מה אתה רואה עכשיו?","ro":"Ma ata ro'e akhshav?"},{"fr":"Je suis accro à une série israélienne.","tgt":"אני מכור לסדרה ישראלית.","ro":"Ani makhur lesidra yisre'elit."},{"fr":"Elle se passe dans un petit café de Netanya.","tgt":"היא מתרחשת בבית קפה קטן בנתניה.","ro":"Hi mitrakheshet beveit kafe katan be-Netanya."},{"fr":"Il y a combien de saisons ?","tgt":"כמה עונות יש?","ro":"Kama onot yesh?"},{"fr":"Il y en a trois, et la quatrième sort bientôt.","tgt":"יש שלוש, והרביעית יוצאת בקרוב.","ro":"Yesh shalosh, veharevi'it yotset bekarov."},{"fr":"Hier soir, j'ai regardé cinq épisodes d'affilée.","tgt":"אתמול בערב ראיתי חמישה פרקים ברצף.","ro":"Etmol ba'erev ra'iti khamisha prakim beretsef."},{"fr":"Ne me raconte surtout pas la fin !","tgt":"אל תספר לי את הסוף!","ro":"Al tesaper li et hasof!"},{"fr":"Le personnage principal est vraiment drôle.","tgt":"הדמות הראשית ממש מצחיקה.","ro":"Hadmut harashit mamash matskhika."},{"fr":"Je te conseille de commencer par la première saison.","tgt":"אני ממליץ לך להתחיל מהעונה הראשונה.","ro":"Ani mamlits lekha lehatkhil meha'ona harishona."},{"fr":"On la regarde ensemble ce week-end ?","tgt":"נראה אותה ביחד בסוף השבוע?","ro":"Nir'e ota beyakhad besof hashavua?"}]},{"title":"Donner son avis","phrases":[{"fr":"À mon avis, ce restaurant est trop cher.","tgt":"לדעתי, המסעדה הזאת יקרה מדי.","ro":"Leda'ati, hamis'ada hazot yekara midai."},{"fr":"Là, je ne suis pas d'accord avec toi.","tgt":"פה אני לא מסכים איתך.","ro":"Po ani lo maskim itkha."},{"fr":"La cuisine est excellente, ça vaut le prix.","tgt":"האוכל מעולה, זה שווה את המחיר.","ro":"Ha'okhel me'ule, ze shave et hamekhir."},{"fr":"Pour moi, l'ambiance compte plus que le menu.","tgt":"בשבילי, האווירה יותר חשובה מהתפריט.","ro":"Bishvili, ha'avira yoter khashuva mehatafrit."},{"fr":"Et toi, tu en penses quoi ?","tgt":"ומה אתה חושב?","ro":"Uma ata khoshev?"},{"fr":"Je pense que tu as un peu raison.","tgt":"אני חושב שאתה קצת צודק.","ro":"Ani khoshev she'ata ktsat tsodek."},{"fr":"Franchement, ça m'est égal.","tgt":"האמת, לא אכפת לי.","ro":"Ha'emet, lo ikhpat li."},{"fr":"Ça dépend du jour et de l'humeur.","tgt":"זה תלוי ביום ובמצב הרוח.","ro":"Ze taluy bayom uvematsav haru'akh."},{"fr":"Tu exagères un peu, non ?","tgt":"אתה קצת מגזים, לא?","ro":"Ata ktsat magzim, lo?"},{"fr":"Bon, on n'est pas obligés d'avoir le même avis.","tgt":"בסדר, לא חייבים להסכים.","ro":"Beseder, lo khayavim lehaskim."}]},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, on allait à la plage chaque samedi.","tgt":"כשהייתי קטן, הלכנו לים כל שבת.","ro":"Kshehayiti katan, halakhnu layam kol shabat."},{"fr":"C'est mon grand-père qui m'a appris à nager.","tgt":"סבא שלי לימד אותי לשחות.","ro":"Saba sheli limed oti liskhot."},{"fr":"On construisait des châteaux de sable pendant des heures.","tgt":"בנינו ארמונות חול במשך שעות.","ro":"Baninu armonot khol bemeshekh sha'ot."},{"fr":"Ma mère préparait des sandwichs pour tout le monde.","tgt":"אמא שלי הכינה כריכים לכולם.","ro":"Ima sheli hekhina krikhim lekulam."},{"fr":"Je me souviens bien de notre vieille maison.","tgt":"אני זוכר טוב את הבית הישן שלנו.","ro":"Ani zokher tov et habayit hayashan shelanu."},{"fr":"Il y avait un grand arbre dans la cour.","tgt":"היה עץ גדול בחצר.","ro":"Haya ets gadol bakhatser."},{"fr":"Mon frère et moi, on se disputait tout le temps.","tgt":"אח שלי ואני רבנו כל הזמן.","ro":"Akh sheli va'ani ravnu kol hazman."},{"fr":"Tu te rappelles notre première rencontre ?","tgt":"אתה זוכר את הפגישה הראשונה שלנו?","ro":"Ata zokher et hapgisha harishona shelanu?"},{"fr":"Bien sûr, c'était au collège, en cours de sport.","tgt":"בטח, זה היה בחטיבה, בשיעור ספורט.","ro":"Betakh, ze haya bakhativa, beshi'ur sport."},{"fr":"Ce sont vraiment de beaux souvenirs.","tgt":"אלה זיכרונות ממש יפים.","ro":"Ele zikhronot mamash yafim."}]},{"title":"Une soirée à la marina de Herzliya","phrases":[{"fr":"Ce soir, on sort à la marina de Herzliya.","tgt":"הערב יוצאים למרינה בהרצליה.","ro":"Ha'erev yotsim lamarina be-Hertsliya."},{"fr":"Il y a plein de bars et de restaurants au bord de l'eau.","tgt":"יש שם המון ברים ומסעדות על המים.","ro":"Yesh sham hamon barim umis'adot al hamayim."},{"fr":"Je passe te prendre à neuf heures.","tgt":"אני אאסוף אותך בתשע.","ro":"Ani e'esof otkha betesha."},{"fr":"Habille-toi léger, il fait encore chaud dehors.","tgt":"תתלבש קליל, עוד חם בחוץ.","ro":"Titlabesh kalil, od kham bakhuts."},{"fr":"On a réservé une table en terrasse.","tgt":"הזמנו שולחן בחוץ.","ro":"Hizmanu shulkhan bakhuts."},{"fr":"Le coucher de soleil sur la mer était magnifique.","tgt":"השקיעה על הים הייתה מדהימה.","ro":"Hashki'a al hayam hayta madhima."},{"fr":"Tu veux boire un petit quelque chose ?","tgt":"אתה רוצה לשתות משהו?","ro":"Ata rotse lishtot mashehu?"},{"fr":"Je prends juste un verre de vin blanc.","tgt":"אני לוקח רק כוס יין לבן.","ro":"Ani loke'akh rak kos yayin lavan."},{"fr":"Après le dîner, on s'est promenés sur le quai.","tgt":"אחרי ארוחת הערב טיילנו על הרציף.","ro":"Akharei arukhat ha'erev tiyalnu al haratsif."},{"fr":"On est rentrés tard, mais ça valait le coup.","tgt":"חזרנו מאוחר, אבל היה שווה.","ro":"Khazarnu me'ukhar, aval haya shave."}]},{"title":"Les dernières rumeurs","phrases":[{"fr":"J'ai entendu dire que Yoni se marie.","tgt":"שמעתי שיוני מתחתן.","ro":"Shamati she-Yoni mitkhaten."},{"fr":"Sérieusement ? Avec qui ?","tgt":"באמת? עם מי?","ro":"Be'emet? Im mi?"},{"fr":"J'ai entendu dire que c'est avec une fille de Netanya.","tgt":"שמעתי שזה עם בחורה מנתניה.","ro":"Shamati sheze im bakhura mi-Netanya."},{"fr":"Tu as entendu que le café de la plage a fermé ?","tgt":"שמעת שבית הקפה על החוף נסגר?","ro":"Shamata shebeit hakafe al hakhof nisgar?"},{"fr":"Oui, j'ai entendu qu'un nouveau restaurant ouvre à sa place.","tgt":"כן, שמעתי שנפתחת שם מסעדה חדשה.","ro":"Ken, shamati shenifta'khat sham mis'ada khadasha."},{"fr":"On m'a dit que la fête était géniale.","tgt":"אמרו לי שהמסיבה הייתה מעולה.","ro":"Amru li shehamesiba hayta me'ula."},{"fr":"J'ai entendu dire que tu as trouvé un nouveau travail.","tgt":"שמעתי שמצאת עבודה חדשה.","ro":"Shamati shematsata avoda khadasha."},{"fr":"Qui t'a raconté ça ?","tgt":"מי סיפר לך?","ro":"Mi siper lekha?"},{"fr":"J'ai entendu dire qu'il va pleuvoir samedi.","tgt":"שמעתי שירד גשם בשבת.","ro":"Shamati sheyered geshem beshabat."},{"fr":"Il ne faut pas croire tout ce qu'on entend.","tgt":"לא צריך להאמין לכל מה ששומעים.","ro":"Lo tsarikh leha'amin lekhol ma sheshom'im."}],"tip":{"title":"« Shamati she- » : j'ai entendu dire que","example":"J'ai entendu dire que Yoni se marie. — <b>שמעתי</b> שיוני מתחתן.","body":"Pour rapporter une nouvelle, l'hébreu utilise une formule très courte : « shamati she », j'ai entendu que. « Shamati » est le passé de entendre, et le petit « she », qui veut dire que, se colle directement au mot suivant. Décomposons « shamati she-Yoni mitkhaten » : j'ai entendu, que-Yoni, se marie, en trois blocs seulement, là où le français dit j'ai entendu dire que. Pour poser la question à un ami, on dit « shamata she », tu as entendu que, et pour un bruit qui court, « amru li she », on m'a dit que. Astuce : pensez à « she » comme un que soudé au mot qui suit, il ne se prononce jamais seul.","exampleRo":"Shamati she-Yoni mitkhaten.","lit":"j'ai-entendu · que-Yoni · se-marie"}},{"title":"Inviter et répondre","phrases":[{"fr":"Tu es libre jeudi soir ?","tgt":"אתה פנוי ביום חמישי בערב?","ro":"Ata panui beyom khamishi ba'erev?"},{"fr":"Je voulais t'inviter à dîner chez moi.","tgt":"רציתי להזמין אותך לארוחת ערב אצלי.","ro":"Ratsiti lehazmin otkha le'arukhat erev etsli."},{"fr":"Avec joie, qu'est-ce que j'apporte ?","tgt":"בשמחה, מה להביא?","ro":"Besimkha, ma lehavi?"},{"fr":"Juste toi et ta bonne humeur.","tgt":"רק את עצמך ומצב רוח טוב.","ro":"Rak et atsmekha umatsav ru'akh tov."},{"fr":"Désolé, ce soir je ne peux vraiment pas.","tgt":"מצטער, הערב אני לא יכול.","ro":"Mitsta'er, ha'erev ani lo yakhol."},{"fr":"On remet ça à la semaine prochaine ?","tgt":"נדחה את זה לשבוע הבא?","ro":"Nidkhe et ze lashavua haba?"},{"fr":"Ça me convient parfaitement.","tgt":"זה מתאים לי בדיוק.","ro":"Ze mat'im li bediyuk."},{"fr":"Je t'envoie l'adresse par message.","tgt":"אני אשלח לך את הכתובת בהודעה.","ro":"Ani eshlakh lekha et haktovet behoda'a."},{"fr":"Dis-moi si tu viens accompagné.","tgt":"תגיד לי אם אתה בא עם מישהו.","ro":"Tagid li im ata ba im mishehu."},{"fr":"Je viendrai peut-être avec ma copine.","tgt":"אולי אבוא עם החברה שלי.","ro":"Ulay avo im hakhavera sheli."}]},{"title":"Faire deux choses à la fois","phrases":[{"fr":"J'écoute des podcasts en courant sur la plage.","tgt":"אני שומע פודקאסטים תוך כדי ריצה על החוף.","ro":"Ani shome'a podkastim tokh kdei ritsa al hakhof."},{"fr":"Ne regarde pas ton téléphone en mangeant.","tgt":"אל תסתכל בטלפון תוך כדי אכילה.","ro":"Al tistakel batelefon tokh kdei akhila."},{"fr":"On a discuté en marchant sur la promenade.","tgt":"דיברנו תוך כדי הליכה בטיילת.","ro":"Dibarnu tokh kdei halikha batayelet."},{"fr":"Il chante en faisant la cuisine.","tgt":"הוא שר תוך כדי בישול.","ro":"Hu shar tokh kdei bishul."},{"fr":"Pendant le match, il a reçu un appel important.","tgt":"תוך כדי המשחק הוא קיבל שיחה חשובה.","ro":"Tokh kdei hamiskhak hu kibel sikha khashuva."},{"fr":"J'ai appris plein de mots en regardant des séries.","tgt":"למדתי הרבה מילים תוך כדי צפייה בסדרות.","ro":"Lamadti harbe milim tokh kdei tsfiya bisdarot."},{"fr":"Elle répondait à ses messages pendant qu'on parlait.","tgt":"היא ענתה להודעות תוך כדי שדיברנו.","ro":"Hi anta lahoda'ot tokh kdei shedibarnu."},{"fr":"C'est dangereux d'écrire des messages en conduisant.","tgt":"מסוכן לכתוב הודעות תוך כדי נהיגה.","ro":"Mesukan likhtov hoda'ot tokh kdei nehiga."},{"fr":"On apprend au fur et à mesure.","tgt":"לומדים תוך כדי תנועה.","ro":"Lomdim tokh kdei tnu'a."},{"fr":"Attends-moi, je finis ce plat et j'arrive.","tgt":"חכה לי, אני מסיים את המנה ובא.","ro":"Khake li, ani mesayem et hamana uva."}],"tip":{"title":"« Tokh kdei » : pendant que","example":"Il chante en faisant la cuisine. — הוא שר <b>תוך כדי</b> בישול.","body":"Pour dire qu'on fait deux choses en même temps, l'hébreu a une formule très pratique : « tokh kdei », pendant ou en faisant. Le plus souvent, on la fait suivre d'un nom d'action, et pas d'un verbe conjugué. Décomposons « hu shar tokh kdei bishul » : lui, chante, pendant, cuisine, là où le français dit il chante en faisant la cuisine. De la même façon, on dit « tokh kdei ritsa », en courant, « tokh kdei akhila », en mangeant, ou « tokh kdei nehiga », en conduisant. Si on veut une phrase complète, on ajoute « she » : « tokh kdei shedibarnu », pendant qu'on parlait. Astuce : retenez « tokh kdei » comme l'équivalent exact de notre gérondif en faisant.","exampleRo":"Hu shar tokh kdei bishul.","lit":"lui · chante · pendant · cuisine"}},{"title":"Raconter son week-end","phrases":[{"fr":"C'était comment, ton week-end ?","tgt":"איך היה סוף השבוע?","ro":"Eikh haya sof hashavua?"},{"fr":"Vendredi, je suis allé au marché de Netanya.","tgt":"ביום שישי הלכתי לשוק בנתניה.","ro":"Beyom shishi halakhti lashuk be-Netanya."},{"fr":"Ensuite, j'ai déjeuné en famille.","tgt":"אחר כך אכלתי צהריים עם המשפחה.","ro":"Akhar kakh akhalti tsohorayim im hamishpakha."},{"fr":"Samedi matin, j'ai fait du vélo le long de la mer.","tgt":"בשבת בבוקר רכבתי על אופניים לאורך הים.","ro":"Beshabat baboker rakhavti al ofanayim le'orekh hayam."},{"fr":"L'après-midi, je me suis reposé à la maison.","tgt":"אחר הצהריים נחתי בבית.","ro":"Akhar hatsohorayim nakhti babayit."},{"fr":"Le soir, on est allés voir un spectacle de stand-up.","tgt":"בערב הלכנו להופעת סטנדאפ.","ro":"Ba'erev halakhnu lehofa'at standap."},{"fr":"C'était tellement drôle que j'avais mal au ventre.","tgt":"היה כל כך מצחיק שכאבה לי הבטן.","ro":"Haya kol kakh matskhik sheka'ava li habeten."},{"fr":"Et toi, tu as fait quelque chose de spécial ?","tgt":"ואתה, עשית משהו מיוחד?","ro":"Ve'ata, asita mashehu meyukhad?"},{"fr":"Pas vraiment, j'ai surtout dormi.","tgt":"לא ממש, בעיקר ישנתי.","ro":"Lo mamash, be'ikar yashanti."},{"fr":"Parfois, c'est exactement ce qu'il faut.","tgt":"לפעמים זה בדיוק מה שצריך.","ro":"Lif'amim ze bediyuk ma shetsarikh."}]},{"title":"Des projets pour l'été","phrases":[{"fr":"Qu'est-ce que tu vas faire cet été ?","tgt":"מה תעשה בקיץ?","ro":"Ma ta'ase bakayits?"},{"fr":"Je vais travailler comme maître-nageur à Herzliya.","tgt":"אני אעבוד כמציל בהרצליה.","ro":"Ani e'evod kematsil be-Hertsliya."},{"fr":"Tu vas passer tout l'été à la plage !","tgt":"תהיה כל הקיץ בים!","ro":"Tihye kol hakayits bayam!"},{"fr":"Et toi, tu as des projets ?","tgt":"ואתה, יש לך תוכניות?","ro":"Ve'ata, yesh lekha tokhniyot?"},{"fr":"J'aimerais marcher sur le sentier d'Israël.","tgt":"הייתי רוצה ללכת את שביל ישראל.","ro":"Hayiti rotse lalekhet et shvil Yisra'el."},{"fr":"Ça prend combien de temps ?","tgt":"כמה זמן זה לוקח?","ro":"Kama zman ze loke'akh?"},{"fr":"Environ deux mois, si on le fait en entier.","tgt":"בערך חודשיים, אם עושים את כולו.","ro":"Be'erekh khodshayim, im osim et kulo."},{"fr":"Je partirai avec deux amis de la fac.","tgt":"אני אצא עם שני חברים מהאוניברסיטה.","ro":"Ani etse im shnei khaverim meha'universita."},{"fr":"Si on est fatigués, on n'en fera que la moitié.","tgt":"אם נהיה עייפים, נעשה רק חצי.","ro":"Im nihye ayefim, na'ase rak khetsi."},{"fr":"Envoie-moi des photos de la randonnée !","tgt":"תשלח לי תמונות מהטיול!","ro":"Tishlakh li tmunot mehatiyul!"}]},{"title":"Se faire de nouveaux amis","phrases":[{"fr":"Salut, moi c'est Eitan, je suis nouveau dans le quartier.","tgt":"היי, אני איתן, אני חדש בשכונה.","ro":"Hai, ani Eitan, ani khadash bashkhuna."},{"fr":"Bienvenue ! Tu viens d'où ?","tgt":"ברוך הבא! מאיפה אתה?","ro":"Barukh haba! Me'eifo ata?"},{"fr":"Je viens de France, mais j'habite ici depuis un an.","tgt":"אני מצרפת, אבל אני גר פה כבר שנה.","ro":"Ani mi-Tsarfat, aval ani gar po kvar shana."},{"fr":"Ton hébreu est déjà excellent !","tgt":"העברית שלך כבר מצוינת!","ro":"Ha'ivrit shelkha kvar metsuyenet!"},{"fr":"Merci, je prends des cours deux fois par semaine.","tgt":"תודה, אני לוקח שיעורים פעמיים בשבוע.","ro":"Toda, ani loke'akh shi'urim pa'amayim bashavua."},{"fr":"On joue au foot sur la plage tous les mardis, tu veux venir ?","tgt":"אנחנו משחקים כדורגל בחוף כל יום שלישי, רוצה לבוא?","ro":"Anakhnu mesakhakim kaduregel bakhof kol yom shlishi, rotse lavo?"},{"fr":"Avec plaisir, je ne connais encore presque personne.","tgt":"בכיף, אני עוד כמעט לא מכיר אף אחד.","ro":"Bekef, ani od kim'at lo makir af ekhad."},{"fr":"Donne-moi ton numéro, je t'ajoute au groupe.","tgt":"תן לי את המספר שלך, אני אוסיף אותך לקבוצה.","ro":"Ten li et hamispar shelkha, ani osif otkha lakvutsa."},{"fr":"Tu sais, ici, les gens sont très chaleureux.","tgt":"אתה יודע, פה האנשים מאוד חמים.","ro":"Ata yode'a, po ha'anashim me'od khamim."},{"fr":"Ravi d'avoir fait ta connaissance.","tgt":"שמחתי להכיר.","ro":"Samakhti lehakir."}]},{"title":"Les mots magiques","phrases":[{"fr":"Excusez-moi, je peux m'asseoir ici ?","tgt":"סליחה, אפשר לשבת פה?","ro":"Slikha, efshar lashevet po?"},{"fr":"Est-ce que je pourrais avoir un verre d'eau ?","tgt":"אפשר כוס מים?","ro":"Efshar kos mayim?"},{"fr":"Merci beaucoup pour l'invitation.","tgt":"תודה רבה על ההזמנה.","ro":"Toda raba al hahazmana."},{"fr":"Pardon, je ne voulais pas te déranger.","tgt":"סליחה, לא רציתי להפריע לך.","ro":"Slikha, lo ratsiti lehafri'a lekha."},{"fr":"Je peux prendre ton chargeur une minute ?","tgt":"אפשר לקחת רגע את המטען שלך?","ro":"Efshar lakakhat rega et hamet'an shelkha?"},{"fr":"Pardon, tu peux répéter plus lentement ?","tgt":"סליחה, אפשר לחזור על זה לאט יותר?","ro":"Slikha, efshar lakhzor al ze le'at yoter?"},{"fr":"Il n'y a pas de quoi, avec plaisir.","tgt":"אין בעד מה, בכיף.","ro":"Ein be'ad ma, bekef."},{"fr":"Désolé pour le retard, il y avait des bouchons.","tgt":"סליחה על האיחור, היו פקקים.","ro":"Slikha al ha'ikhur, hayu pkakim."},{"fr":"Merci mille fois, tu m'as sauvé la vie !","tgt":"תודה רבה, הצלת אותי!","ro":"Toda raba, hitsalta oti!"},{"fr":"On pourrait avoir l'addition, s'il vous plaît ?","tgt":"אפשר חשבון, בבקשה?","ro":"Efshar kheshbon, bevakasha?"}],"tip":{"title":"La politesse : efshar, slikha, toda raba","example":"Est-ce que je pourrais avoir un verre d'eau ? — <b>אפשר</b> כוס מים?","body":"La politesse israélienne est directe mais chaleureuse, et trois mots font presque tout le travail. « Efshar » veut dire c'est possible, et il suffit de le mettre devant ce qu'on veut : « efshar kos mayim », mot à mot possible verre eau, veut dire est-ce que je pourrais avoir un verre d'eau. « Slikha » sert à la fois pour excusez-moi, pour attirer l'attention, et pour pardon, quand on s'excuse vraiment. « Toda raba » veut dire merci beaucoup, et on répond « ein be'ad ma », il n'y a pas de quoi, ou simplement « bekef », avec plaisir. Astuce : « slikha, efshar », pardon, est-ce possible, ouvre presque toutes les portes.","exampleRo":"Efshar kos mayim?","lit":"possible · verre-de · eau ?"}},{"title":"Un petit froid entre amis","phrases":[{"fr":"Pourquoi tu ne m'as pas répondu hier ?","tgt":"למה לא ענית לי אתמול?","ro":"Lama lo anita li etmol?"},{"fr":"J'étais crevé, je me suis endormi tôt.","tgt":"הייתי גמור, נרדמתי מוקדם.","ro":"Hayiti gamur, nirdamti mukdam."},{"fr":"Tu aurais pu envoyer un petit message.","tgt":"יכולת לשלוח הודעה קטנה.","ro":"Yakholta lishlo'akh hoda'a ktana."},{"fr":"Tu as raison, je suis vraiment désolé.","tgt":"אתה צודק, אני מצטער.","ro":"Ata tsodek, ani mitsta'er."},{"fr":"Je t'ai attendu une heure au café.","tgt":"חיכיתי לך שעה בבית הקפה.","ro":"Khikiti lekha sha'a beveit hakafe."},{"fr":"Ça ne se reproduira plus, promis.","tgt":"זה לא יקרה שוב, מבטיח.","ro":"Ze lo yikre shuv, mavti'akh."},{"fr":"Bon, ce n'est pas grave, on oublie.","tgt":"טוב, לא נורא, שוכחים מזה.","ro":"Tov, lo nora, shokhekhim meze."},{"fr":"Je t'invite à prendre un café pour me faire pardonner.","tgt":"אני מזמין אותך לקפה כדי לפצות.","ro":"Ani mazmin otkha lekafe kdei lefatsot."},{"fr":"Marché conclu, mais c'est toi qui choisis l'endroit.","tgt":"סגרנו, אבל אתה בוחר את המקום.","ro":"Sagarnu, aval ata bokher et hamakom."},{"fr":"Les vrais amis savent se réconcilier vite.","tgt":"חברים אמיתיים יודעים להשלים מהר.","ro":"Khaverim amitiyim yod'im lehashlim maher."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à bavarder entre amis.","tgt":"המודול הזה לימד אותנו לפטפט עם חברים.","ro":"Hamodul haze limed otanu lefatpet im khaverim."},{"fr":"Maintenant, on sait raconter un souvenir ou une soirée.","tgt":"עכשיו אנחנו יודעים לספר על זיכרון או על ערב.","ro":"Akhshav anakhnu yod'im lesaper al zikaron o al erev."},{"fr":"On peut donner son avis sans vexer personne.","tgt":"אפשר להביע דעה בלי להעליב אף אחד.","ro":"Efshar lehabi'a de'a bli leha'aliv af ekhad."},{"fr":"L'argot rend l'hébreu bien plus vivant.","tgt":"הסלנג עושה את העברית יותר חיה.","ro":"Hasleng ose et ha'ivrit yoter khaya."},{"fr":"Des petits mots comme peut-être ou apparemment changent tout.","tgt":"מילים קטנות כמו אולי או כנראה משנות הכל.","ro":"Milim ktanot kmo ulay o kanir'e meshanot hakol."},{"fr":"Le deuxième niveau est maintenant terminé.","tgt":"הרמה השנייה הסתיימה.","ro":"Harama hashniya histayma."},{"fr":"Au niveau suivant, on abordera des sujets plus riches.","tgt":"ברמה הבאה נדבר על נושאים מורכבים יותר.","ro":"Barama haba'a nedaber al nos'im murkavim yoter."},{"fr":"Continue à parler hébreu avec tes amis israéliens.","tgt":"תמשיך לדבר עברית עם החברים הישראלים שלך.","ro":"Tamshikh ledaber ivrit im hakhaverim hayisre'elim shelkha."},{"fr":"Bravo pour tous tes efforts !","tgt":"כל הכבוד על כל המאמץ!","ro":"Kol hakavod al kol hama'amats!"},{"fr":"On se retrouve bientôt pour le dernier niveau.","tgt":"נתראה בקרוב ברמה האחרונה.","ro":"Nitra'e bekarov barama ha'akharona."}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Israël, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Premier jour dans une start-up","phrases":[{"fr":"Notre start-up a été fondée il y a trois ans.","tgt":"הסטארט-אפ שלנו נוסד לפני שלוש שנים.","ro":"Ha-start-ap shelanu nosad lifney shalosh shanim."},{"fr":"Un ordinateur portable m'a été remis dès le premier jour.","tgt":"מחשב נייד נמסר לי כבר ביום הראשון.","ro":"Makhshev nayad nimsar li kvar ba-yom ha-rishon."},{"fr":"Le bureau a été entièrement rénové l'été dernier.","tgt":"המשרד שופץ לגמרי בקיץ שעבר.","ro":"Ha-misrad shupats legamrey ba-kayits she-avar."},{"fr":"Les nouveaux employés sont présentés à l'équipe le dimanche.","tgt":"העובדים החדשים מוצגים לצוות ביום ראשון.","ro":"Ha-ovdim ha-khadashim mutsagim la-tsevet be-yom rishon."},{"fr":"Le code est vérifié par deux développeurs avant chaque mise en ligne.","tgt":"הקוד נבדק על ידי שני מפתחים לפני כל עלייה לאוויר.","ro":"Ha-kod nivdak al yedey shney mefatkhim lifney kol aliya la-avir."},{"fr":"Le produit a été lancé en mars.","tgt":"המוצר הושק במרץ.","ro":"Ha-mutsar hushak be-merts."},{"fr":"Mon contrat sera signé demain matin.","tgt":"החוזה שלי ייחתם מחר בבוקר.","ro":"Ha-khoze sheli yekhatem makhar ba-boker."},{"fr":"Les salaires sont versés le neuf de chaque mois.","tgt":"המשכורות משולמות בתשעה לכל חודש.","ro":"Ha-maskorot meshulamot ba-tish'a le-khol khodesh."},{"fr":"Le déjeuner est servi aux frais de la boîte tous les jeudis.","tgt":"ארוחת הצהריים מוגשת על חשבון החברה בכל יום חמישי.","ro":"Arukhat ha-tsohorayim mugeshet al kheshbon ha-khevra be-khol yom khamishi."},{"fr":"J'ai été vraiment bien accueilli ici.","tgt":"התקבלתי כאן ממש יפה.","ro":"Hitkabalti kan mamash yafe."}],"tip":{"title":"Le passif","example":"Le produit a été lancé en mars. — המוצר <b>הושק</b> במרץ.","body":"En hébreu, le passif ne se construit pas avec un auxiliaire comme « être lancé » : il a ses propres formes de verbe, qu'on reconnaît à l'oreille. La plus fréquente commence par « ni » ou « no » au passé : « nivdak », a été vérifié, « nimsar », a été remis, « nosad », a été fondé. Deux autres formes ont un son « ou » caractéristique : « shupats », a été rénové, et « hushak », a été lancé, qu'on retrouve au présent avec « mu » : « mutsag », présenté. Notre exemple, « ha-mutsar hushak be-merts », se décompose en « le produit · a été lancé · en mars », sans aucun verbe être. Pour dire « par », on ajoute « al yedey » : « nivdak al yedey shney mefatkhim ». Astuce : à l'oral, les Israéliens préfèrent souvent le « on » au pluriel, « shilmu li », on m'a payé, mais le passif fait très professionnel en réunion.","exampleRo":"Ha-mutsar hushak be-merts.","lit":"[le] produit · a-été-lancé · en-mars"}},{"title":"Une réunion d'équipe","phrases":[{"fr":"La réunion commence dans cinq minutes, tout le monde est là ?","tgt":"הפגישה מתחילה בעוד חמש דקות, כולם פה?","ro":"Ha-pgisha matkhila be-od khamesh dakot, kulam po?"},{"fr":"Qui rédige le compte rendu aujourd'hui ?","tgt":"מי רושם את הסיכום היום?","ro":"Mi roshem et ha-sikum ha-yom?"},{"fr":"On commence par un rapide point sur la semaine.","tgt":"נתחיל בעדכון קצר על השבוע.","ro":"Natkhil be-idkun katsar al ha-shavua."},{"fr":"Le client attend une réponse avant jeudi.","tgt":"הלקוח מחכה לתשובה עד יום חמישי.","ro":"Ha-lakoakh mekhake li-tshuva ad yom khamishi."},{"fr":"Je propose qu'on repousse la livraison d'une semaine.","tgt":"אני מציע שנדחה את המסירה בשבוע.","ro":"Ani matsi'a she-nidkhe et ha-mesira be-shavua."},{"fr":"Ce n'est pas réaliste avec l'équipe actuelle.","tgt":"זה לא ריאלי עם הצוות הנוכחי.","ro":"Ze lo re'ali im ha-tsevet ha-nokhekhi."},{"fr":"Qui se charge de parler au client ?","tgt":"מי לוקח על עצמו לדבר עם הלקוח?","ro":"Mi lokeakh al atsmo ledaber im ha-lakoakh?"},{"fr":"Je m'en occupe, je l'appelle cet après-midi.","tgt":"אני על זה, אני מתקשר אליו אחר הצהריים.","ro":"Ani al ze, ani mitkasher elav akhar ha-tsohorayim."},{"fr":"On fait une pause de dix minutes ?","tgt":"נעשה הפסקה של עשר דקות?","ro":"Na'ase hafsaka shel eser dakot?"},{"fr":"Bon, on récapitule et on termine.","tgt":"טוב, בואו נסכם ונסיים.","ro":"Tov, bo'u nesakem ve-nesayem."}]},{"title":"Le jour du déménagement","phrases":[{"fr":"Les déménageurs ont descendu le canapé par l'escalier.","tgt":"המובילים הורידו את הספה במדרגות.","ro":"Ha-movilim horidu et ha-sapa ba-madregot."},{"fr":"On a fait monter le frigo par la fenêtre.","tgt":"העלינו את המקרר דרך החלון.","ro":"He'elinu et ha-mekarer derekh ha-khalon."},{"fr":"Rentre les cartons avant qu'il commence à pleuvoir.","tgt":"תכניס את הארגזים לפני שיתחיל גשם.","ro":"Takhnis et ha-argazim lifney she-yatkhil geshem."},{"fr":"J'ai fait asseoir les enfants dans le salon vide.","tgt":"הושבתי את הילדים בסלון הריק.","ro":"Hoshavti et ha-yeladim ba-salon ha-reik."},{"fr":"Le propriétaire nous a fait attendre une heure pour les clés.","tgt":"בעל הבית גרם לנו לחכות שעה למפתחות.","ro":"Ba'al ha-bayit garam lanu lekhakot sha'a la-mafteakhot."},{"fr":"Sors les vieux meubles dans la rue, quelqu'un les prendra.","tgt":"תוציא את הרהיטים הישנים לרחוב, מישהו ייקח אותם.","ro":"Totsi et ha-rehitim ha-yeshanim la-rekhov, mishehu yikakh otam."},{"fr":"Ce déménagement m'a fait perdre trois jours de travail.","tgt":"המעבר הזה גרם לי להפסיד שלושה ימי עבודה.","ro":"Ha-ma'avar ha-ze garam li lehafsid shlosha yemey avoda."},{"fr":"J'ai fait installer internet dès notre arrivée.","tgt":"דאגתי שיתקינו אינטרנט מיד כשהגענו.","ro":"Da'agti she-yatkinu internet miyad kshe-higanu."},{"fr":"Rappelle-moi d'appeler le syndic de l'immeuble.","tgt":"תזכיר לי להתקשר לוועד הבית.","ro":"Tazkir li lehitkasher la-va'ad ha-bayit."},{"fr":"Le soir, on a fait manger les enfants sur les cartons.","tgt":"בערב האכלנו את הילדים על הארגזים.","ro":"Ba-erev he'ekhalnu et ha-yeladim al ha-argazim."}],"tip":{"title":"Faire faire : le causatif","example":"Les déménageurs ont descendu le canapé par l'escalier. — המובילים <b>הורידו</b> את הספה במדרגות.","body":"Le français dit « faire descendre », « faire entrer », « faire manger » ; l'hébreu, lui, transforme directement le verbe. « Yarad », descendre, devient « horid », faire descendre ; « nikhnas », entrer, devient « hikhnis », faire entrer ; « akhal », manger, devient « he'ekhil », faire manger. Notre exemple, « ha-movilim horidu et ha-sapa », se lit mot à mot : les déménageurs · ont fait descendre · le canapé. Quand quelque chose vous pousse à agir, on utilise « garam le », causer à : « garam lanu lekhakot », il nous a fait attendre. Et pour faire faire un travail par un professionnel, on dit « da'agti she-yatkinu », je me suis arrangé pour qu'on installe. Astuce : écoutez le « h » du début, « horid », « hikhnis », « hoshiv », c'est la signature sonore du causatif.","exampleRo":"Ha-movilim horidu et ha-sapa ba-madregot.","lit":"[le] déménageurs · ont-fait-descendre · [objet] [le] canapé · par-[les] escaliers"}},{"title":"Négocier un bail","phrases":[{"fr":"Le bail est d'un an, avec option de prolongation.","tgt":"החוזה לשנה, עם אופציה להארכה.","ro":"Ha-khoze le-shana, im optsya leha'arakha."},{"fr":"Le loyer comprend-il les charges de l'immeuble ?","tgt":"שכר הדירה כולל את ועד הבית?","ro":"Skhar ha-dira kolel et va'ad ha-bayit?"},{"fr":"Le propriétaire exige quatre chèques de garantie.","tgt":"בעל הבית מבקש ארבעה צ'קים לביטחון.","ro":"Ba'al ha-bayit mevakesh arba'a tchekim le-bitakhon."},{"fr":"Je voudrais qu'un avocat relise le contrat.","tgt":"אני רוצה שעורך דין יעבור על החוזה.","ro":"Ani rotse she-orekh din ya'avor al ha-khoze."},{"fr":"Est-ce qu'on peut négocier le montant du loyer ?","tgt":"אפשר להתמקח על גובה שכר הדירה?","ro":"Efshar lehitmake'akh al gova skhar ha-dira?"},{"fr":"Six mille shekels, c'est au-dessus de notre budget.","tgt":"שישת אלפים שקל זה מעל התקציב שלנו.","ro":"Sheshet alafim shekel ze me'al ha-taktsiv shelanu."},{"fr":"Qui paie les réparations si le chauffe-eau tombe en panne ?","tgt":"מי משלם על תיקונים אם הדוד מתקלקל?","ro":"Mi meshalem al tikunim im ha-dud mitkalkel?"},{"fr":"Les animaux sont-ils autorisés dans l'appartement ?","tgt":"מותר להחזיק חיות מחמד בדירה?","ro":"Mutar lehakhzik khayot makhmad ba-dira?"},{"fr":"Nous voulons une clause de sortie anticipée.","tgt":"אנחנו רוצים סעיף יציאה מוקדמת.","ro":"Anakhnu rotsim se'if yetsi'a mukdemet."},{"fr":"Parfait, on signe vendredi chez l'avocat.","tgt":"מצוין, חותמים ביום שישי אצל עורך הדין.","ro":"Metsuyan, khotmim be-yom shishi etsel orekh ha-din."}]},{"title":"Négocier son salaire","phrases":[{"fr":"Si vous m'augmentez, alors je reste dans l'équipe.","tgt":"אם תעלו לי את המשכורת, אז אני נשאר בצוות.","ro":"Im ta'alu li et ha-maskoret, az ani nish'ar ba-tsevet."},{"fr":"Si on termine le projet à temps, on aura une prime.","tgt":"אם נסיים את הפרויקט בזמן, אז נקבל בונוס.","ro":"Im nesayem et ha-proyekt ba-zman, az nekabel bonus."},{"fr":"Si j'avais su, j'aurais demandé plus.","tgt":"אילו ידעתי, הייתי מבקש יותר.","ro":"Ilu yadati, hayiti mevakesh yoter."},{"fr":"À ta place, je négocierais aussi les jours de congé.","tgt":"אילו הייתי במקומך, הייתי מתמקח גם על ימי החופשה.","ro":"Ilu hayiti bi-mkomkha, hayiti mitmake'akh gam al yemey ha-khufsha."},{"fr":"Si l'offre ne te convient pas, dis-le franchement.","tgt":"אם ההצעה לא מתאימה לך, תגיד את זה בכנות.","ro":"Im ha-hatsa'a lo mat'ima lekha, tagid et ze be-khenut."},{"fr":"Si la boîte lève des fonds, alors les salaires augmenteront.","tgt":"אם החברה תגייס כסף, אז המשכורות יעלו.","ro":"Im ha-khevra tegayes kesef, az ha-maskorot ya'alu."},{"fr":"Si on m'avait proposé des stock-options, j'aurais accepté tout de suite.","tgt":"אילו הציעו לי אופציות, הייתי מסכים מיד.","ro":"Ilu hitsi'u li optsyot, hayiti maskim miyad."},{"fr":"Si je n'avais pas négocié, je gagnerais beaucoup moins aujourd'hui.","tgt":"אילו לא התמקחתי, הייתי מרוויח היום הרבה פחות.","ro":"Ilu lo hitmakakhti, hayiti marvi'akh ha-yom harbe pakhot."},{"fr":"Mon chef a dit qu'il me répondrait d'ici la fin du mois.","tgt":"המנהל שלי אמר שהוא יענה לי עד סוף החודש.","ro":"Ha-menahel sheli amar she-hu ya'ane li ad sof ha-khodesh."},{"fr":"Et s'il refuse, je commencerai à chercher ailleurs.","tgt":"ואם הוא יסרב, אז אתחיל לחפש במקום אחר.","ro":"Ve-im hu yesarev, az atkhil lekhapes be-makom akher."}],"tip":{"title":"« Im... az... » et « ilu » : l'hypothèse","example":"Si j'avais su, j'aurais demandé plus. — <b>אילו</b> ידעתי, <b>הייתי</b> מבקש יותר.","body":"Pour une condition réaliste, on dit « im », si, suivi du futur, puis souvent « az », alors : « im nesayem ba-zman, az nekabel bonus », si on finit à temps, alors on aura une prime. Attention, contrairement au français, le verbe après « im » se met au futur et non au présent. Pour l'irréel, ce qu'on imagine ou ce qu'on regrette, on emploie « ilu », un peu plus soutenu, et l'autre moitié de la phrase se forme avec « hayiti » suivi du présent : « hayiti mevakesh », j'aurais demandé. Notre exemple, « ilu yadati, hayiti mevakesh yoter », se décompose ainsi : si · je savais · j'étais demandant · plus. Dans la conversation courante, beaucoup disent simplement « im hayiti yode'a », si j'avais su. Astuce : « hayiti » plus un présent, c'est votre conditionnel passe-partout.","exampleRo":"Ilu yadati, hayiti mevakesh yoter.","lit":"si-(irréel) · je-savais , · j'étais · demandant · plus"}},{"title":"Choisir une assurance","phrases":[{"fr":"Je dois choisir une assurance santé complémentaire.","tgt":"אני צריך לבחור ביטוח בריאות משלים.","ro":"Ani tsarikh livkhor bituakh bri'ut mashlim."},{"fr":"La complémentaire de la caisse de santé coûte environ cent shekels par mois.","tgt":"הביטוח המשלים של קופת החולים עולה בערך מאה שקל לחודש.","ro":"Ha-bituakh ha-mashlim shel kupat ha-kholim ole be-erekh me'a shekel le-khodesh."},{"fr":"Est-ce que les soins dentaires sont couverts ?","tgt":"טיפולי שיניים מכוסים?","ro":"Tipuley shinayim mekhusim?"},{"fr":"Il y a une franchise de trois cents shekels.","tgt":"יש השתתפות עצמית של שלוש מאות שקל.","ro":"Yesh hishtatfut atsmit shel shlosh me'ot shekel."},{"fr":"L'assurance auto a beaucoup augmenté cette année.","tgt":"ביטוח הרכב התייקר מאוד השנה.","ro":"Bituakh ha-rekhev hityaker me'od ha-shana."},{"fr":"Je compare trois offres avant de me décider.","tgt":"אני משווה שלוש הצעות לפני שאני מחליט.","ro":"Ani mashve shalosh hatsa'ot lifney she-ani makhlit."},{"fr":"L'agent m'a promis de me rappeler avec un meilleur prix.","tgt":"הסוכן הבטיח לחזור אליי עם מחיר טוב יותר.","ro":"Ha-sokhen hivti'akh lakhzor elay im mekhir tov yoter."},{"fr":"Lis bien les petites lignes avant de signer.","tgt":"תקרא טוב את האותיות הקטנות לפני שאתה חותם.","ro":"Tikra tov et ha-otiyot ha-ktanot lifney she-ata khotem."},{"fr":"Cette police ne couvre pas les dégâts des eaux.","tgt":"הפוליסה הזאת לא מכסה נזקי מים.","ro":"Ha-polisa ha-zot lo mekhasa nizkey mayim."},{"fr":"Finalement, je reste chez mon assureur actuel.","tgt":"בסוף, אני נשאר בחברת הביטוח הנוכחית שלי.","ro":"Ba-sof, ani nish'ar be-khevrat ha-bituakh ha-nokhekhit sheli."}]},{"title":"Bloqué sur l'Ayalon","phrases":[{"fr":"Il y a un énorme bouchon sur l'Ayalon ce matin.","tgt":"יש פקק ענק באיילון הבוקר.","ro":"Yesh pkak anak ba-Ayalon ha-boker."},{"fr":"Je suis coincé depuis quarante minutes au même endroit.","tgt":"אני תקוע כבר ארבעים דקות באותו מקום.","ro":"Ani taku'a kvar arba'im dakot be-oto makom."},{"fr":"Un accident bloque deux voies à la sortie vers Ramat Gan.","tgt":"תאונה חוסמת שני נתיבים ביציאה לרמת גן.","ro":"Te'una khosemet shney netivim ba-yetsi'a le-Ramat Gan."},{"fr":"Préviens l'équipe que je vais être en retard.","tgt":"תודיע לצוות שאני אאחר.","ro":"Todi'a la-tsevet she-ani a'akher."},{"fr":"La prochaine fois, je prends le train.","tgt":"בפעם הבאה אני לוקח רכבת.","ro":"Ba-pa'am ha-ba'a ani lokeakh rakevet."},{"fr":"Le tramway était censé régler ce problème.","tgt":"הרכבת הקלה הייתה אמורה לפתור את הבעיה הזאת.","ro":"Ha-rakevet ha-kala hayta amura liftor et ha-ba'aya ha-zot."},{"fr":"L'application propose un itinéraire par les petites rues.","tgt":"האפליקציה מציעה מסלול דרך הרחובות הקטנים.","ro":"Ha-aplikatsya matsi'a maslul derekh ha-rekhovot ha-ktanim."},{"fr":"Trouver une place de parking à Tel Aviv, c'est un cauchemar.","tgt":"למצוא חניה בתל אביב זה סיוט.","ro":"Limtso khanaya be-Tel Aviv ze siyut."},{"fr":"Je pense sérieusement passer au vélo électrique.","tgt":"אני חושב ברצינות לעבור לאופניים חשמליים.","ro":"Ani khoshev bi-rtsinut la'avor le-ofanayim khashmaliyim."},{"fr":"Je profite des bouchons pour écouter des podcasts.","tgt":"אני מנצל את הפקקים כדי להקשיב לפודקאסטים.","ro":"Ani menatsel et ha-pkakim kedey lehakshiv le-podkastim."}]},{"title":"Le télétravail","phrases":[{"fr":"Je télétravaille trois jours par semaine.","tgt":"אני עובד מהבית שלושה ימים בשבוע.","ro":"Ani oved me-ha-bayit shlosha yamim be-shavua."},{"fr":"Parfois, je ne m'habille même pas pour les réunions.","tgt":"לפעמים אני אפילו לא מתלבש לפגישות.","ro":"Lifamim ani afilu lo mitlabesh la-pgishot."},{"fr":"Même mon chef travaille de chez lui le jeudi.","tgt":"אפילו המנהל שלי עובד מהבית בימי חמישי.","ro":"Afilu ha-menahel sheli oved me-ha-bayit bi-ymey khamishi."},{"fr":"Je n'ai même pas eu le temps de déjeuner aujourd'hui.","tgt":"אפילו לא היה לי זמן לאכול צהריים היום.","ro":"Afilu lo haya li zman le'ekhol tsohorayim ha-yom."},{"fr":"Même avec une bonne connexion, la vidéo se fige sans arrêt.","tgt":"אפילו עם חיבור טוב, הווידאו נתקע כל הזמן.","ro":"Afilu im khibur tov, ha-vide'o nitka kol ha-zman."},{"fr":"Les enfants font du bruit, même quand la porte est fermée.","tgt":"הילדים עושים רעש, אפילו כשהדלת סגורה.","ro":"Ha-yeladim osim ra'ash, afilu kshe-ha-delet sgura."},{"fr":"Il ne m'a même pas dit bonjour avant la réunion.","tgt":"הוא אפילו לא אמר לי שלום לפני הפגישה.","ro":"Hu afilu lo amar li shalom lifney ha-pgisha."},{"fr":"Je me suis aménagé un vrai coin bureau sur le balcon fermé.","tgt":"סידרתי לי פינת עבודה אמיתית במרפסת הסגורה.","ro":"Sidarti li pinat avoda amitit ba-mirpeset ha-sgura."},{"fr":"Le plus dur, c'est d'arrêter de travailler le soir.","tgt":"הכי קשה זה להפסיק לעבוד בערב.","ro":"Hakhi kashe ze lehafsik la'avod ba-erev."},{"fr":"Même le petit café du bureau me manque.","tgt":"אפילו הקפה הקטן במשרד חסר לי.","ro":"Afilu ha-kafe ha-katan ba-misrad khaser li."}],"tip":{"title":"« Afilu » : même","example":"Parfois, je ne m'habille même pas pour les réunions. — לפעמים אני <b>אפילו</b> לא מתלבש לפגישות.","body":"Le mot « afilu » correspond exactement au français « même », et il se place juste devant le mot qu'il met en relief : « afilu ha-menahel sheli », même mon chef ; « afilu im khibur tov », même avec une bonne connexion. Pour dire « même pas », on pose simplement « afilu » devant la négation « lo » : « hu afilu lo amar li shalom », il ne m'a même pas dit bonjour. Notre exemple, « lifamim ani afilu lo mitlabesh », donne mot à mot : parfois · moi · même · pas · m'habillant. Avec « kshe », quand, on obtient « afilu kshe », même quand, et avec « im », « afilu im », même avec. Astuce : appuyez un peu sur « a-fi-lou », les Israéliens l'accentuent volontiers pour marquer la surprise ou l'agacement.","exampleRo":"Lifamim ani afilu lo mitlabesh la-pgishot.","lit":"parfois · moi · même · ne-pas · m'habillant · pour-[les] réunions"}},{"title":"L'arnona à la mairie","phrases":[{"fr":"Je dois déclarer mon nouvel appartement à la mairie.","tgt":"אני צריך לרשום את הדירה החדשה בעירייה.","ro":"Ani tsarikh lirshom et ha-dira ha-khadasha ba-iriya."},{"fr":"L'arnona est calculée selon la surface de l'appartement.","tgt":"הארנונה מחושבת לפי השטח של הדירה.","ro":"Ha-arnona mekhushevet lefi ha-shetakh shel ha-dira."},{"fr":"Il faut apporter une copie du bail et sa carte d'identité.","tgt":"צריך להביא העתק של החוזה ותעודת זהות.","ro":"Tsarikh lehavi he'etek shel ha-khoze ve-te'udat zehut."},{"fr":"Le guichet ferme à une heure, dépêchons-nous.","tgt":"האשנב נסגר באחת, בוא נמהר.","ro":"Ha-eshnav nisgar be-akhat, bo nemaher."},{"fr":"Aujourd'hui, on peut presque tout faire sur internet.","tgt":"היום אפשר לעשות כמעט הכול באינטרנט.","ro":"Ha-yom efshar la'asot kim'at ha-kol ba-internet."},{"fr":"Le site m'a renvoyé trois fois vers la même page.","tgt":"האתר החזיר אותי שלוש פעמים לאותו עמוד.","ro":"Ha-atar hekhzir oti shalosh pe'amim le-oto amud."},{"fr":"Ai-je droit à une réduction en tant que nouvel immigrant ?","tgt":"מגיעה לי הנחה כעולה חדש?","ro":"Magi'a li hanakha ke-ole khadash?"},{"fr":"La réduction ne vaut que pour la première année.","tgt":"ההנחה תקפה רק בשנה הראשונה.","ro":"Ha-hanakha tkefa rak ba-shana ha-rishona."},{"fr":"Je paierai par prélèvement automatique tous les deux mois.","tgt":"אשלם בהוראת קבע כל חודשיים.","ro":"Ashalem be-hora'at keva kol khodshayim."},{"fr":"Au bout du compte, la démarche a pris moins d'une heure.","tgt":"בסופו של דבר, כל הסידור לקח פחות משעה.","ro":"Be-sofo shel davar, kol ha-sidur lakakh pakhot mi-sha'a."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"J'ai pris rendez-vous à la banque pour ouvrir un compte.","tgt":"קבעתי תור בבנק כדי לפתוח חשבון.","ro":"Kavati tor ba-bank kedey liftoakh kheshbon."},{"fr":"Le conseiller m'a demandé une fiche de paie.","tgt":"הבנקאי ביקש ממני תלוש משכורת.","ro":"Ha-bankai bikesh mimeni tlush maskoret."},{"fr":"Les frais de tenue de compte sont assez élevés.","tgt":"דמי ניהול החשבון די גבוהים.","ro":"Dmey nihul ha-kheshbon dey gvohim."},{"fr":"J'aimerais être exonéré de frais pendant un an.","tgt":"הייתי רוצה פטור מעמלות לשנה.","ro":"Hayiti rotse ptor me-amlot le-shana."},{"fr":"Ma carte de crédit arrivera par la poste d'ici dix jours.","tgt":"כרטיס האשראי יגיע בדואר תוך עשרה ימים.","ro":"Kartis ha-ashrai yagi'a ba-do'ar tokh asara yamim."},{"fr":"Je vais faire un virement au propriétaire.","tgt":"אני אעשה העברה בנקאית לבעל הבית.","ro":"Ani e'ese ha'avara bankait le-va'al ha-bayit."},{"fr":"Je suis à découvert depuis le déménagement.","tgt":"אני במינוס מאז המעבר.","ro":"Ani ba-minus me'az ha-ma'avar."},{"fr":"Il faut absolument que je me fasse un budget.","tgt":"אני חייב לבנות לעצמי תקציב.","ro":"Ani khayav livnot le-atsmi taktsiv."},{"fr":"L'application de la banque est très pratique.","tgt":"האפליקציה של הבנק מאוד נוחה.","ro":"Ha-aplikatsya shel ha-bank me'od nokha."},{"fr":"On peut déposer un chèque en le prenant simplement en photo.","tgt":"אפשר להפקיד צ'ק פשוט בצילום מהטלפון.","ro":"Efshar lehafkid tchek pashut be-tsilum me-ha-telefon."}]},{"title":"Une colocation à Florentin","phrases":[{"fr":"Je cherche une chambre en colocation à Florentin.","tgt":"אני מחפש חדר בדירת שותפים בפלורנטין.","ro":"Ani mekhapes kheder bi-dirat shutafim be-Florentin."},{"fr":"L'annonce dit que l'appartement est lumineux et rénové.","tgt":"במודעה כתוב שהדירה מוארת ומשופצת.","ro":"Ba-moda'a katuv she-ha-dira mu'eret ve-meshupetset."},{"fr":"Combien de colocataires vivent ici ?","tgt":"כמה שותפים גרים פה?","ro":"Kama shutafim garim po?"},{"fr":"La chambre est petite, mais il y a un balcon sur rue.","tgt":"החדר קטן, אבל יש מרפסת לרחוב.","ro":"Ha-kheder katan, aval yesh mirpeset la-rekhov."},{"fr":"Comment est-ce que vous partagez les factures ?","tgt":"איך אתם מתחלקים בחשבונות?","ro":"Eykh atem mitkhalkim ba-kheshbonot?"},{"fr":"L'immeuble a un ascenseur, ou il faut tout monter à pied ?","tgt":"יש מעלית בבניין, או שצריך לעלות הכול ברגל?","ro":"Yesh ma'alit ba-binyan, o she-tsarikh la'alot ha-kol ba-regel?"},{"fr":"Le quartier est très animé, surtout le soir.","tgt":"השכונה תוססת, בעיקר בערב.","ro":"Ha-shkhuna tosesset, be-ikar ba-erev."},{"fr":"Je travaille beaucoup, je ne suis presque jamais à la maison.","tgt":"אני עובד הרבה, אני כמעט לא בבית.","ro":"Ani oved harbe, ani kim'at lo ba-bayit."},{"fr":"Est-ce que je peux emménager dès le début du mois ?","tgt":"אפשר להיכנס כבר בתחילת החודש?","ro":"Efshar lehikanes kvar bi-tkhilat ha-khodesh?"},{"fr":"Je vous donne une réponse d'ici demain soir.","tgt":"אני אחזור אליכם עד מחר בערב.","ro":"Ani akhzor aleykhem ad makhar ba-erev."}]},{"title":"Des messages professionnels","phrases":[{"fr":"Suite à notre conversation, voici la proposition en pièce jointe.","tgt":"בהמשך לשיחתנו, מצורפת ההצעה.","ro":"Be-hemshekh le-sikhatenu, metsorefet ha-hatsa'a."},{"fr":"Je vous prie de confirmer la réception de ce message.","tgt":"אבקש לאשר את קבלת ההודעה.","ro":"Avakesh le'asher et kabalat ha-hoda'a."},{"fr":"Nous serons ravis de vous rencontrer la semaine prochaine.","tgt":"נשמח להיפגש איתך בשבוע הבא.","ro":"Nismakh lehipagesh itkha ba-shavua ha-ba."},{"fr":"Je reviens vers vous concernant ma précédente demande.","tgt":"אני חוזר אליך בנוגע לפנייתי הקודמת.","ro":"Ani khozer elekha be-noge'a li-fniyati ha-kodemet."},{"fr":"Vous trouverez ci-joint le contrat signé.","tgt":"מצורף בזאת החוזה החתום.","ro":"Metsoraf be-zot ha-khoze ha-khatum."},{"fr":"Pour toute question, je reste à votre disposition.","tgt":"לכל שאלה, אני עומד לרשותך.","ro":"Le-khol she'ela, ani omed li-rshutkha."},{"fr":"Nous vous remercions de votre patience.","tgt":"אנו מודים לך על סבלנותך.","ro":"Anu modim lekha al savlanutkha."},{"fr":"Selon les termes de l'accord, le paiement s'effectue sous trente jours.","tgt":"על פי תנאי ההסכם, התשלום יבוצע תוך שלושים יום.","ro":"Al pi tna'ey ha-heskem, ha-tashlum yevutsa tokh shloshim yom."},{"fr":"Merci de noter que le bureau sera fermé jeudi.","tgt":"נא לשים לב שהמשרד יהיה סגור ביום חמישי.","ro":"Na lasim lev she-ha-misrad yihye sagur be-yom khamishi."},{"fr":"Cordialement, Yoni Levi, responsable produit.","tgt":"בברכה, יוני לוי, מנהל מוצר.","ro":"Bi-vrakha, Yoni Levi, menahel mutsar."}],"tip":{"title":"L'hébreu formel du bureau","example":"Nous vous remercions de votre patience. — <b>אנו</b> מודים לך על <b>סבלנותך</b>.","body":"Au bureau, surtout avec des clients ou des partenaires, l'hébreu monte d'un cran sans jamais passer au vouvoiement : on dit toujours « lekha » ou « itkha », même à un directeur. Le registre formel se marque autrement : « anu » remplace « anakhnu » pour dire nous, et le possessif se colle à la fin du mot, « sikhatenu », notre conversation, au lieu de « ha-sikha shelanu ». Notre exemple, « anu modim lekha al savlanutkha », se décompose en : nous · remercions · à toi · pour · ta patience. On adoucit aussi les demandes avec le futur, « avakesh », je demanderai, ou avec « na » suivi de l'infinitif, « na lasim lev », merci de noter. Pour conclure, « bi-vrakha » équivaut à cordialement. Astuce : répétez ces formules d'une traite, elles reviennent dans presque chaque échange professionnel.","exampleRo":"Anu modim lekha al savlanutkha.","lit":"nous · remerciant · à-toi · pour · patience-de-toi"}},{"title":"Lever des fonds","phrases":[{"fr":"On présente la start-up à des investisseurs la semaine prochaine.","tgt":"אנחנו מציגים את הסטארט-אפ למשקיעים בשבוע הבא.","ro":"Anakhnu matsigim et ha-start-ap la-mashki'im ba-shavua ha-ba."},{"fr":"La présentation doit durer dix minutes maximum.","tgt":"המצגת צריכה להיות עשר דקות לכל היותר.","ro":"Ha-matseget tsrikha lihyot eser dakot le-khol ha-yoter."},{"fr":"Ils veulent surtout voir des chiffres de croissance.","tgt":"הם רוצים לראות בעיקר נתוני צמיחה.","ro":"Hem rotsim lir'ot be-ikar netuney tsmikha."},{"fr":"Nous essayons de lever deux millions de shekels.","tgt":"אנחנו מנסים לגייס שני מיליון שקל.","ro":"Anakhnu menasim legayes shney milyon shekel."},{"fr":"Le fondateur a répété son pitch toute la nuit.","tgt":"המייסד התאמן על הפיץ' כל הלילה.","ro":"Ha-meyased hit'amen al ha-pitch kol ha-layla."},{"fr":"Un des fonds nous a déjà fait une offre.","tgt":"אחת הקרנות כבר הגישה לנו הצעה.","ro":"Akhat ha-keranot kvar higisha lanu hatsa'a."},{"fr":"Les conditions ne sont pas encore tout à fait claires.","tgt":"התנאים עוד לא לגמרי ברורים.","ro":"Ha-tna'im od lo legamrey brurim."},{"fr":"Ne crie pas victoire trop tôt, comme on dit ici.","tgt":"אל תגיד הופ עד שלא קפצת.","ro":"Al tagid hop ad she-lo kafatsta."},{"fr":"Si le tour se boucle, on recrutera dix personnes.","tgt":"אם הסבב ייסגר, נגייס עשרה אנשים.","ro":"Im ha-sevev yisager, negayes asara anashim."},{"fr":"Toute l'équipe croise les doigts.","tgt":"כל הצוות מחזיק אצבעות.","ro":"Kol ha-tsevet makhzik etsba'ot."}]},{"title":"Un entretien d'embauche","phrases":[{"fr":"Parle-moi un peu de toi.","tgt":"ספר לי קצת על עצמך.","ro":"Saper li ktsat al atsmekha."},{"fr":"J'ai cinq ans d'expérience en gestion de produit.","tgt":"יש לי חמש שנות ניסיון בניהול מוצר.","ro":"Yesh li khamesh shnot nisayon be-nihul mutsar."},{"fr":"Pourquoi as-tu quitté ton dernier emploi ?","tgt":"למה עזבת את העבודה הקודמת?","ro":"Lama azavta et ha-avoda ha-kodemet?"},{"fr":"Je cherchais un nouveau défi.","tgt":"חיפשתי אתגר חדש.","ro":"Khipasti etgar khadash."},{"fr":"Quel est ton plus gros point faible ?","tgt":"מה החולשה הכי גדולה שלך?","ro":"Ma ha-khulsha hakhi gdola shelkha?"},{"fr":"Je suis parfois trop perfectionniste.","tgt":"אני לפעמים פרפקציוניסט מדי.","ro":"Ani lifamim perfektsyonist miday."},{"fr":"Quelles sont tes prétentions salariales ?","tgt":"מה ציפיות השכר שלך?","ro":"Ma tsipiyot ha-sakhar shelkha?"},{"fr":"Le poste est hybride, avec deux jours au bureau.","tgt":"המשרה היברידית, יומיים במשרד.","ro":"Ha-misra hibridit, yomayim ba-misrad."},{"fr":"On revient vers toi d'ici une semaine.","tgt":"נחזור אליך תוך שבוע.","ro":"Nakhzor elekha tokh shavua."},{"fr":"Le deuxième entretien sera avec le responsable du développement.","tgt":"הראיון השני יהיה עם מנהל הפיתוח.","ro":"Ha-ra'ayon ha-sheni yihye im menahel ha-pituakh."}]},{"title":"Une fuite dans la salle de bain","phrases":[{"fr":"Il y a une fuite sous le lavabo de la salle de bain.","tgt":"יש נזילה מתחת לכיור בחדר האמבטיה.","ro":"Yesh nezila mitakhat la-kiyor be-khadar ha-ambatya."},{"fr":"J'ai appelé le propriétaire, il ne répond pas.","tgt":"התקשרתי לבעל הבית, הוא לא עונה.","ro":"Hitkasharti le-va'al ha-bayit, hu lo one."},{"fr":"Le voisin du dessous se plaint d'une tache au plafond.","tgt":"השכן מלמטה מתלונן על כתם בתקרה.","ro":"Ha-shakhen mi-lemata mitlonen al ketem ba-tikra."},{"fr":"Le plombier peut passer demain entre huit et dix.","tgt":"האינסטלטור יכול לבוא מחר בין שמונה לעשר.","ro":"Ha-instalator yakhol lavo makhar beyn shmone le-eser."},{"fr":"Combien ça va me coûter, à peu près ?","tgt":"כמה זה יעלה לי, בערך?","ro":"Kama ze ya'ale li, be-erekh?"},{"fr":"Selon la loi, c'est au propriétaire de payer ça.","tgt":"לפי החוק, בעל הבית אמור לשלם על זה.","ro":"Lefi ha-khok, ba'al ha-bayit amur leshalem al ze."},{"fr":"Garde le reçu, je te rembourserai.","tgt":"תשמור את הקבלה, אני אחזיר לך.","ro":"Tishmor et ha-kabala, ani akhzir lekha."},{"fr":"En attendant, ferme le robinet principal.","tgt":"בינתיים תסגור את הברז הראשי.","ro":"Beyntayim tisgor et ha-berez ha-rashi."},{"fr":"Le problème venait d'un vieux tuyau rouillé.","tgt":"הבעיה הייתה בצינור ישן וחלוד.","ro":"Ha-ba'aya hayta be-tsinor yashan ve-khalud."},{"fr":"Tout a été réparé, et le voisin est content.","tgt":"הכול תוקן, והשכן מרוצה.","ro":"Ha-kol tukan, ve-ha-shakhen merutse."}]},{"title":"Un rendez-vous à la caisse de santé","phrases":[{"fr":"J'ai pris rendez-vous chez le médecin par l'application.","tgt":"קבעתי תור לרופא דרך האפליקציה.","ro":"Kavati tor la-rofe derekh ha-aplikatsya."},{"fr":"Le premier créneau libre est dans trois semaines.","tgt":"התור הפנוי הראשון הוא בעוד שלושה שבועות.","ro":"Ha-tor ha-panuy ha-rishon hu be-od shlosha shavu'ot."},{"fr":"Je préfère une consultation en vidéo.","tgt":"אני מעדיף ייעוץ בווידאו.","ro":"Ani ma'adif yi'uts be-vide'o."},{"fr":"J'ai mal au dos depuis que je travaille assis toute la journée.","tgt":"כואב לי הגב מאז שאני עובד בישיבה כל היום.","ro":"Ko'ev li ha-gav me'az she-ani oved bi-yshiva kol ha-yom."},{"fr":"Le médecin m'a prescrit des séances de kiné.","tgt":"הרופא נתן לי הפניה לפיזיותרפיה.","ro":"Ha-rofe natan li hafnaya le-fizyoterapya."},{"fr":"Il faut un accord de la caisse avant le traitement.","tgt":"צריך התחייבות מהקופה לפני הטיפול.","ro":"Tsarikh hitkhayvut me-ha-kupa lifney ha-tipul."},{"fr":"La pharmacie est ouverte jusqu'à minuit.","tgt":"בית המרקחת פתוח עד חצות.","ro":"Beyt ha-merkakhat patuakh ad khatsot."},{"fr":"Est-ce que ce médicament est dans le panier de soins ?","tgt":"התרופה הזאת בסל?","ro":"Ha-trufa ha-zot ba-sal?"},{"fr":"J'ai besoin d'un arrêt maladie de deux jours.","tgt":"אני צריך אישור מחלה ליומיים.","ro":"Ani tsarikh ishur makhala le-yomayim."},{"fr":"Prends soin de toi et repose-toi bien.","tgt":"תשמור על עצמך ותנוח.","ro":"Tishmor al atsmekha ve-tanuakh."}]},{"title":"Le vendredi au marché Carmel","phrases":[{"fr":"Le vendredi matin, je fais mes courses au marché Carmel.","tgt":"בשישי בבוקר אני עושה קניות בשוק הכרמל.","ro":"Be-shishi ba-boker ani ose kniyot be-shuk ha-Karmel."},{"fr":"Les prix baissent juste avant la fermeture.","tgt":"המחירים יורדים ממש לפני הסגירה.","ro":"Ha-mekhirim yordim mamash lifney ha-sgira."},{"fr":"Combien coûte le kilo de tomates ?","tgt":"כמה עולה קילו עגבניות?","ro":"Kama ole kilo agvaniyot?"},{"fr":"Tu me fais un prix si j'en prends trois ?","tgt":"תעשה לי מחיר אם אני לוקח שלושה?","ro":"Ta'ase li mekhir im ani lokeakh shlosha?"},{"fr":"Ces fraises sont incroyablement sucrées.","tgt":"התותים האלה מתוקים בטירוף.","ro":"Ha-tutim ha-ele metukim be-teruf."},{"fr":"Je m'arrête toujours pour un jus pressé.","tgt":"אני תמיד עוצר למיץ סחוט.","ro":"Ani tamid otser le-mits sakhut."},{"fr":"Il y a trop de monde, on ne peut plus bouger.","tgt":"יש פה יותר מדי אנשים, אי אפשר לזוז.","ro":"Yesh po yoter miday anashim, i efshar lazuz."},{"fr":"Le marchand m'a reconnu et m'a ajouté un bouquet d'herbes.","tgt":"המוכר זיהה אותי והוסיף לי צרור עשבי תיבול.","ro":"Ha-mokher zihe oti ve-hosif li tsror isbey tibul."},{"fr":"Mes sacs pèsent une tonne.","tgt":"השקיות שלי שוקלות טונה.","ro":"Ha-sakiyot sheli shoklot tona."},{"fr":"C'est mon moment préféré de la semaine.","tgt":"זה הרגע האהוב עליי בשבוע.","ro":"Ze ha-rega ha-ahuv alay ba-shavua."}]},{"title":"Changer de travail","phrases":[{"fr":"J'ai décidé de quitter mon poste après trois ans.","tgt":"החלטתי לעזוב את התפקיד אחרי שלוש שנים.","ro":"Hekhlateti la'azov et ha-tafkid akharey shalosh shanim."},{"fr":"Je dois donner un préavis d'un mois.","tgt":"אני צריך לתת הודעה מוקדמת של חודש.","ro":"Ani tsarikh latet hoda'a mukdemet shel khodesh."},{"fr":"Mon chef a été surpris, mais il s'est montré compréhensif.","tgt":"המנהל שלי הופתע, אבל גילה הבנה.","ro":"Ha-menahel sheli hufta, aval gila havana."},{"fr":"Ils m'ont fait une contre-proposition.","tgt":"הציעו לי הצעה נגדית.","ro":"Hitsi'u li hatsa'a negdit."},{"fr":"J'ai refusé poliment.","tgt":"סירבתי בנימוס.","ro":"Seravti be-nimus."},{"fr":"Je vais passer le relais à mon remplaçant pendant deux semaines.","tgt":"אני אחפוף את המחליף שלי במשך שבועיים.","ro":"Ani akhpof et ha-makhlif sheli be-meshekh shvu'ayim."},{"fr":"Le nouveau poste est plus près de chez moi.","tgt":"התפקיד החדש קרוב יותר לבית.","ro":"Ha-tafkid ha-khadash karov yoter la-bayit."},{"fr":"Mes collègues m'organisent une fête de départ.","tgt":"הקולגות מארגנים לי מסיבת פרידה.","ro":"Ha-kolegot me'argenim li mesibat preda."},{"fr":"Je n'oublierai jamais cette équipe.","tgt":"אני אף פעם לא אשכח את הצוות הזה.","ro":"Ani af pa'am lo eshkakh et ha-tsevet ha-ze."},{"fr":"Il ne faut jamais couper les ponts.","tgt":"אסור אף פעם לשרוף גשרים.","ro":"Asur af pa'am lisrof gsharim."}]},{"title":"Un afterwork boulevard Rothschild","phrases":[{"fr":"Ce soir, toute la boîte sort boire un verre.","tgt":"הערב כל החברה יוצאת לשתות משהו.","ro":"Ha-erev kol ha-khevra yotset lishtot mashehu."},{"fr":"On se retrouve au bar en bas du bureau à sept heures.","tgt":"נפגשים בבר מתחת למשרד בשבע.","ro":"Nifgashim ba-bar mitakhat la-misrad be-sheva."},{"fr":"Je prends une bière pression, et toi ?","tgt":"אני מזמין בירה מהחבית, ומה איתך?","ro":"Ani mazmin bira me-ha-khavit, ve-ma itkha?"},{"fr":"Interdit de parler boulot ce soir, ça marche ?","tgt":"בלי לדבר על עבודה הערב, סגור?","ro":"Bli ledaber al avoda ha-erev, sagur?"},{"fr":"Avec le temps, mes collègues sont devenus des amis.","tgt":"עם הזמן הקולגות שלי הפכו לחברים.","ro":"Im ha-zman ha-kolegot sheli hafkhu le-khaverim."},{"fr":"La nouvelle développeuse est super drôle.","tgt":"המפתחת החדשה מצחיקה ברמות.","ro":"Ha-mefatakhat ha-khadasha matskhika be-ramot."},{"fr":"On marche jusqu'à la plage après ?","tgt":"נלך אחר כך ברגל עד הים?","ro":"Nelekh akhar kakh ba-regel ad ha-yam?"},{"fr":"La brise du soir fait vraiment du bien.","tgt":"הבריזה של הערב ממש עושה טוב.","ro":"Ha-briza shel ha-erev mamash osa tov."},{"fr":"Je rentre en trottinette, c'est plus rapide.","tgt":"אני חוזר בקורקינט, זה יותר מהיר.","ro":"Ani khozer be-korkinet, ze yoter mahir."},{"fr":"Demain, réunion à neuf heures, ne l'oublie pas !","tgt":"מחר פגישה בתשע, אל תשכח!","ro":"Makhar pgisha be-tesha, al tishkakh!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait entrer dans le quotidien de Tel Aviv.","tgt":"המודול הזה הכניס אותנו לחיי היומיום בתל אביב.","ro":"Ha-modul ha-ze hikhnis otanu le-khayey ha-yomyom be-Tel Aviv."},{"fr":"On a parlé de contrats, d'assurances et de démarches.","tgt":"דיברנו על חוזים, ביטוחים וסידורים.","ro":"Dibarnu al khozim, bituakhim ve-sidurim."},{"fr":"Le passif en hébreu ne me fait plus peur.","tgt":"הסביל בעברית כבר לא מפחיד אותי.","ro":"Ha-savil be-ivrit kvar lo mafkhid oti."},{"fr":"Même les messages formels deviennent plus faciles.","tgt":"אפילו מיילים רשמיים נהיים קלים יותר.","ro":"Afilu meylim rishmiyim nihyim kalim yoter."},{"fr":"Si je continue comme ça, je parlerai couramment.","tgt":"אם אמשיך ככה, אדבר עברית שוטפת.","ro":"Im amshikh kakha, adaber ivrit shotefet."},{"fr":"Je me sens de plus en plus à l'aise au bureau.","tgt":"אני מרגיש יותר ויותר בנוח במשרד.","ro":"Ani margish yoter ve-yoter be-no'akh ba-misrad."},{"fr":"Le prochain module nous emmène en voyage à travers le pays.","tgt":"המודול הבא לוקח אותנו לטיול ברחבי הארץ.","ro":"Ha-modul ha-ba lokeakh otanu le-tiyul be-rakhvey ha-arets."},{"fr":"Bravo pour tout ce travail, c'était un module exigeant.","tgt":"כל הכבוד על כל העבודה, זה היה מודול תובעני.","ro":"Kol ha-kavod al kol ha-avoda, ze haya modul tov'ani."},{"fr":"Une petite pause, et on repart.","tgt":"הפסקה קטנה, וממשיכים.","ro":"Hafsaka ktana, ve-mamshikhim."},{"fr":"À très vite, et bonne route !","tgt":"נתראה בקרוב, ודרך צלחה!","ro":"Nitra'e be-karov, ve-derekh tslekha!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Cap sur le Néguev","phrases":[{"fr":"On est partis de Tel Aviv tôt le matin, avant la chaleur.","tgt":"יצאנו מתל אביב מוקדם בבוקר, לפני החום.","ro":"Yatsanu mi-Tel Aviv mukdam ba-boker, lifnei ha-khom."},{"fr":"Plus on descend vers le sud, plus le paysage devient sec.","tgt":"ככל שיורדים דרומה, הנוף נעשה יבש יותר.","ro":"Kekhol she-yordim daroma, ha-nof na'ase yavesh yoter."},{"fr":"Le Néguev couvre plus de la moitié de la superficie du pays.","tgt":"הנגב מכסה יותר ממחצית משטח המדינה.","ro":"Ha-Negev mekhase yoter mi-makhatsit mi-shetakh ha-medina."},{"fr":"Pendant des heures, on n'a vu presque aucune voiture.","tgt":"במשך שעות לא ראינו כמעט אף מכונית.","ro":"Be-meshekh sha'ot lo ra'inu kim'at af mekhonit."},{"fr":"Le silence du désert nous a tout de suite frappés.","tgt":"השקט של המדבר הפתיע אותנו מיד.","ro":"Ha-sheket shel ha-midbar hifti'a otanu miyad."},{"fr":"On s'est arrêtés dans une station-service au milieu de nulle part.","tgt":"עצרנו בתחנת דלק באמצע שום מקום.","ro":"Atsarnu be-takhanat delek be-emtsa shum makom."},{"fr":"Il faut toujours garder beaucoup d'eau dans la voiture.","tgt":"תמיד צריך לקחת הרבה מים באוטו.","ro":"Tamid tsarikh lakakhat harbe mayim ba-oto."},{"fr":"Les panneaux préviennent parfois de la présence de chameaux sur la route.","tgt":"השלטים מזהירים מדי פעם מגמלים על הכביש.","ro":"Ha-shlatim mazhirim midei pa'am mi-gmalim al ha-kvish."},{"fr":"La lumière change complètement en fin d'après-midi.","tgt":"האור משתנה לגמרי לקראת סוף אחר הצהריים.","ro":"Ha-or mishtane legamrei likrat sof akhar ha-tsohorayim."},{"fr":"Ce voyage dans le sud, j'en rêvais depuis longtemps.","tgt":"על הטיול הזה לדרום חלמתי כבר הרבה זמן.","ro":"Al ha-tiyul ha-ze la-darom khalamti kvar harbe zman."}]},{"title":"Au bord du cratère de Mitzpe Ramon","phrases":[{"fr":"Le cratère que tu vois ici s'est formé pendant des millions d'années.","tgt":"המכתש שאתה רואה כאן נוצר במשך מיליוני שנים.","ro":"Ha-makhtesh she-ata ro'e kan notsar be-meshekh milyonei shanim."},{"fr":"Le guide qui nous accompagne a grandi à Mitzpe Ramon.","tgt":"המדריך שמלווה אותנו גדל במצפה רמון.","ro":"Ha-madrikh she-melave otanu gadal be-Mitspe Ramon."},{"fr":"C'est l'endroit dont tout le monde m'a parlé.","tgt":"זה המקום שכולם סיפרו לי עליו.","ro":"Ze ha-makom she-kulam sipru li alav."},{"fr":"On a trouvé un belvédère d'où l'on voit tout le cratère.","tgt":"מצאנו נקודת תצפית שממנה רואים את כל המכתש.","ro":"Matsanu nekudat tatspit she-mimena ro'im et kol ha-makhtesh."},{"fr":"Les bouquetins qu'on a vus ce matin n'avaient pas peur de nous.","tgt":"היעלים שראינו הבוקר לא פחדו מאיתנו.","ro":"Ha-ye'elim she-ra'inu ha-boker lo pakhadu me-itanu."},{"fr":"Le sentier qu'on a choisi descend jusqu'au fond du cratère.","tgt":"השביל שבחרנו יורד עד לתחתית המכתש.","ro":"Ha-shvil she-bakharnu yored ad la-takhtit ha-makhtesh."},{"fr":"Tout ce que je vois ici me paraît irréel.","tgt":"כל מה שאני רואה כאן נראה לי לא אמיתי.","ro":"Kol ma she-ani ro'e kan nir'a li lo amiti."},{"fr":"La ville est construite juste au bord du cratère.","tgt":"העיר בנויה ממש על שפת המכתש.","ro":"Ha-ir bnuya mamash al sfat ha-makhtesh."},{"fr":"Les couleurs des roches changent selon l'heure de la journée.","tgt":"הצבעים של הסלעים משתנים לפי שעות היום.","ro":"Ha-tsva'im shel ha-sla'im mishtanim lefi sha'ot ha-yom."},{"fr":"C'est le plus beau paysage que j'aie jamais vu.","tgt":"זה הנוף הכי יפה שראיתי אי פעם.","ro":"Ze ha-nof hakhi yafe she-ra'iti ei pa'am."}],"tip":{"title":"Les relatives avec « she- »","example":"Le guide qui nous accompagne a grandi à Mitzpe Ramon. — המדריך <b>שמלווה</b> אותנו גדל במצפה רמון.","body":"Pour dire « qui », « que » ou « dont », l'hébreu utilise un seul petit son, « she- », que l'on colle directement au mot suivant. Dans « ha-madrikh she-melave otanu », mot à mot « le guide qui-accompagne nous », il remplace notre « qui ». Dans « ha-nof she-ra'iti », « le paysage que j'ai vu », il remplace « que ». Pour « dont » ou « d'où », on garde « she- » et on ajoute à la fin un petit rappel, comme dans « ha-makom she-kulam sipru li alav », littéralement « l'endroit que tout le monde m'a raconté sur lui ». Astuce : dès que vous voulez dire « qui » ou « que » au milieu d'une phrase, pensez simplement « she » et enchaînez sans pause.","exampleRo":"Ha-madrikh she-melave otanu gadal be-Mitspe Ramon.","lit":"[le]-guide · qui-accompagne · [objet]-nous · a-grandi · à-Mitzpe Ramon"}},{"title":"Une nuit sous la tente","phrases":[{"fr":"Ce soir, on dort sous une tente bédouine.","tgt":"הערב אנחנו ישנים באוהל בדואי.","ro":"Ha-erev anakhnu yeshenim be-ohel bedui."},{"fr":"Nos hôtes nous ont accueillis avec du café et des dattes.","tgt":"המארחים קיבלו את פנינו בקפה ובתמרים.","ro":"Ha-me'arkhim kiblu et paneinu be-kafe u-vi-tmarim."},{"fr":"On est restés assis autour du feu jusqu'à minuit.","tgt":"ישבנו סביב המדורה עד חצות.","ro":"Yashavnu saviv ha-medura ad khatsot."},{"fr":"La nuit, la température chute de façon spectaculaire.","tgt":"בלילה הטמפרטורה יורדת בצורה דרמטית.","ro":"Ba-layla ha-temperatura yoredet be-tsura dramatit."},{"fr":"Heureusement, on avait apporté des sacs de couchage bien chauds.","tgt":"למזלנו, הבאנו שקי שינה חמים.","ro":"Le-mazalenu, heveinu sakei shena khamim."},{"fr":"Le thé à la sauge est servi très sucré.","tgt":"התה עם המרווה מוגש מתוק מאוד.","ro":"Ha-te im ha-marva mugash matok me'od."},{"fr":"On a dormi sur des matelas posés sur des tapis.","tgt":"ישנו על מזרנים שהונחו על שטיחים.","ro":"Yashanu al mizranim she-hunkhu al shtikhim."},{"fr":"Le matin, c'est le cri d'un chameau qui m'a réveillé.","tgt":"בבוקר העיר אותי הקול של גמל.","ro":"Ba-boker he'ir oti ha-kol shel gamal."},{"fr":"Je n'avais jamais dormi dans un silence aussi total.","tgt":"אף פעם לא ישנתי בשקט מוחלט כזה.","ro":"Af pa'am lo yashanti be-sheket mukhlat kaze."},{"fr":"Cette nuit sous la tente restera un moment à part dans le voyage.","tgt":"הלילה הזה באוהל יישאר רגע מיוחד בטיול.","ro":"Ha-layla ha-ze ba-ohel yisha'er rega meyukhad ba-tiyul."}]},{"title":"Plonger dans la mer Rouge à Eilat","phrases":[{"fr":"On est venus à Eilat pour plonger dans la mer Rouge.","tgt":"באנו לאילת כדי לצלול בים סוף.","ro":"Banu le-Eilat kdei litslol be-Yam Suf."},{"fr":"Il faut suivre une courte formation pour plonger avec une bouteille.","tgt":"צריך לעבור הדרכה קצרה כדי לצלול עם מיכל חמצן.","ro":"Tsarikh la'avor hadrakha ktsara kdei litslol im meikhal khamtsan."},{"fr":"Le moniteur vérifie l'équipement afin d'éviter tout problème.","tgt":"המדריך בודק את הציוד כדי למנוע כל בעיה.","ro":"Ha-madrikh bodek et ha-tsiyud kdei limno'a kol be'aya."},{"fr":"On met un masque pour voir les poissons sous l'eau.","tgt":"שמים מסכה כדי לראות את הדגים מתחת למים.","ro":"Samim masekha kdei lir'ot et ha-dagim mi-takhat la-mayim."},{"fr":"Les coraux sont protégés, alors il est interdit de les toucher.","tgt":"האלמוגים מוגנים, ולכן אסור לגעת בהם.","ro":"Ha-almogim muganim, ve-lakhen asur laga'at bahem."},{"fr":"Je suis descendu à dix mètres de profondeur.","tgt":"ירדתי לעומק של עשרה מטרים.","ro":"Yaradti le-omek shel asara metrim."},{"fr":"J'ai pris un appareil étanche afin de photographier les coraux.","tgt":"לקחתי מצלמה עמידה למים כדי לצלם את האלמוגים.","ro":"Lakakhti matslema amida la-mayim kdei letsalem et ha-almogim."},{"fr":"Des poissons de toutes les couleurs nagent juste à côté de nous.","tgt":"דגים בכל הצבעים שוחים ממש לידנו.","ro":"Dagim be-khol ha-tsva'im sokhim mamash le-yadenu."},{"fr":"Pour bien profiter de la plongée, il faut respirer lentement.","tgt":"כדי ליהנות באמת מהצלילה, צריך לנשום לאט.","ro":"Kdei lehanot be-emet me-ha-tslila, tsarikh linshom le-at."},{"fr":"Après la plongée, on s'est allongés sur la plage pour se réchauffer.","tgt":"אחרי הצלילה נחנו על החוף כדי להתחמם.","ro":"Akharei ha-tslila nakhnu al ha-khof kdei lehitkhamem."}],"tip":{"title":"« Kdei » : pour, afin de","example":"On est venus à Eilat pour plonger dans la mer Rouge. — באנו לאילת <b>כדי</b> לצלול בים סוף.","body":"Pour exprimer un but, l'hébreu utilise « kdei », qui correspond exactement à notre « pour » ou « afin de ». Il est toujours suivi d'un verbe à l'infinitif, qui commence presque toujours par le son « le » ou « li », comme « lir'ot », voir, ou « litslol », plonger. Dans « banu le-Eilat kdei litslol », mot à mot « sommes venus à Eilat afin de plonger », la construction suit l'ordre du français. Vous pouvez aussi commencer la phrase par lui : « kdei lehanot, tsarikh linshom le-at », pour en profiter, il faut respirer lentement. Astuce : chaque fois que vous diriez « pour » suivi d'un verbe, dites « kdei » et enchaînez avec l'infinitif.","exampleRo":"Banu le-Eilat kdei litslol be-Yam Suf.","lit":"sommes-venus · à-Eilat · afin-de · plonger · dans-mer · Souf"}},{"title":"Les couleurs du parc de Timna","phrases":[{"fr":"Le parc de Timna se trouve à une demi-heure au nord d'Eilat.","tgt":"פארק תמנע נמצא חצי שעה צפונית לאילת.","ro":"Park Timna nimtsa khatsi sha'a tsfonit le-Eilat."},{"fr":"Ici, on extrayait du cuivre il y a des milliers d'années.","tgt":"כאן כרו נחושת לפני אלפי שנים.","ro":"Kan karu nekhoshet lifnei alfei shanim."},{"fr":"Le rocher en forme de champignon est l'emblème du parc.","tgt":"הסלע בצורת פטרייה הוא הסמל של הפארק.","ro":"Ha-sela be-tsurat pitriya hu ha-semel shel ha-park."},{"fr":"Le vent et l'eau ont sculpté ces formes étonnantes.","tgt":"הרוח והמים פיסלו את הצורות המדהימות האלה.","ro":"Ha-ru'akh ve-ha-mayim pislu et ha-tsurot ha-madhimot ha-ele."},{"fr":"On a marché dans un petit canyon aux parois rouges.","tgt":"הלכנו בקניון קטן עם קירות אדומים.","ro":"Halakhnu be-kanyon katan im kirot adumim."},{"fr":"Au centre d'accueil, on peut remplir une bouteille de sable coloré.","tgt":"במרכז המבקרים אפשר למלא בקבוק בחול צבעוני.","ro":"Be-merkaz ha-mevakrim efshar lemale bakbuk be-khol tsiv'oni."},{"fr":"Le site a été adapté aux familles avec enfants.","tgt":"האתר הותאם למשפחות עם ילדים.","ro":"Ha-atar hut'am le-mishpakhot im yeladim."},{"fr":"À midi, il fait trop chaud pour marcher au soleil.","tgt":"בצהריים חם מדי ללכת בשמש.","ro":"Ba-tsohorayim kham midai lalekhet ba-shemesh."},{"fr":"On a pique-niqué au bord du petit lac artificiel.","tgt":"עשינו פיקניק ליד האגם המלאכותי הקטן.","ro":"Asinu piknik leyad ha-agam ha-melakhuti ha-katan."},{"fr":"Je ne m'attendais pas à des couleurs aussi vives dans le désert.","tgt":"לא ציפיתי לצבעים חזקים כל כך במדבר.","ro":"Lo tsipiti li-tsva'im khazakim kol kakh ba-midbar."}]},{"title":"Une journée à Beer-Sheva","phrases":[{"fr":"Beer-Sheva est la plus grande ville du Néguev.","tgt":"באר שבע היא העיר הגדולה ביותר בנגב.","ro":"Be'er Sheva hi ha-ir ha-gdola beyoter ba-Negev."},{"fr":"On l'appelle souvent la capitale du sud.","tgt":"קוראים לה לעיתים קרובות בירת הדרום.","ro":"Kor'im la le-itim krovot birat ha-darom."},{"fr":"Le marché bédouin du jeudi attire beaucoup de monde.","tgt":"השוק הבדואי של יום חמישי מושך הרבה אנשים.","ro":"Ha-shuk ha-bedui shel yom khamishi moshekh harbe anashim."},{"fr":"On peut y trouver des tapis tissés à la main.","tgt":"אפשר למצוא שם שטיחים ארוגים ביד.","ro":"Efshar limtso sham shtikhim arugim ba-yad."},{"fr":"La vieille ville a été rénovée ces dernières années.","tgt":"העיר העתיקה שופצה בשנים האחרונות.","ro":"Ha-ir ha-atika shuptsa ba-shanim ha-akharonot."},{"fr":"L'université attire des étudiants de tout le pays.","tgt":"האוניברסיטה מושכת סטודנטים מכל הארץ.","ro":"Ha-universita moshekhet studentim mi-kol ha-arets."},{"fr":"On a déjeuné dans un petit restaurant près de la gare.","tgt":"אכלנו צהריים במסעדה קטנה ליד התחנה.","ro":"Akhalnu tsohorayim be-mis'ada ktana leyad ha-takhana."},{"fr":"Le train relie Beer-Sheva à Tel Aviv en moins d'une heure et demie.","tgt":"הרכבת מחברת את באר שבע לתל אביב בפחות משעה וחצי.","ro":"Ha-rakevet mekhaberet et Be'er Sheva le-Tel Aviv be-pakhot mi-sha'a va-khetsi."},{"fr":"La ville est bien plus animée que je ne l'imaginais.","tgt":"העיר הרבה יותר תוססת ממה שדמיינתי.","ro":"Ha-ir harbe yoter toseset mi-ma she-dimyanti."},{"fr":"Ce soir, on reprend la route vers le sud.","tgt":"הערב אנחנו חוזרים לכביש לכיוון דרום.","ro":"Ha-erev anakhnu khozrim la-kvish le-kivun darom."}]},{"title":"Randonnée avec un guide","phrases":[{"fr":"Le guide nous a donné rendez-vous devant le centre d'accueil.","tgt":"המדריך קבע איתנו פגישה מול מרכז המבקרים.","ro":"Ha-madrikh kava itanu pgisha mul merkaz ha-mevakrim."},{"fr":"Il faut emporter une gourde et un chapeau.","tgt":"צריך לקחת בקבוק מים וכובע.","ro":"Tsarikh lakakhat bakbuk mayim ve-kova."},{"fr":"Les chaussures de marche sont indispensables sur ce terrain.","tgt":"נעלי הליכה הן חובה בשטח הזה.","ro":"Na'alei halikha hen khova ba-shetakh ha-ze."},{"fr":"On a marché le long du lit de la rivière asséchée.","tgt":"הלכנו לאורך אפיק הנחל היבש.","ro":"Halakhnu le-orekh afik ha-nakhal ha-yavesh."},{"fr":"Le guide nous a montré des traces d'animaux dans le sable.","tgt":"המדריך הראה לנו עקבות חיות בחול.","ro":"Ha-madrikh her'a lanu ikvot khayot ba-khol."},{"fr":"Le chef du groupe marche toujours en dernier.","tgt":"ראש הקבוצה הולך תמיד אחרון.","ro":"Rosh ha-kvutsa holekh tamid akharon."},{"fr":"On a fait une pause à l'ombre de l'acacia.","tgt":"עשינו הפסקה בצל עץ השיטה.","ro":"Asinu hafsaka be-tsel ets ha-shita."},{"fr":"Le lever du soleil sur le désert est inoubliable.","tgt":"זריחת השמש מעל המדבר בלתי נשכחת.","ro":"Zrikhat ha-shemesh me'al ha-midbar bilti nishkakhat."},{"fr":"Le prix de la randonnée comprend le déjeuner.","tgt":"מחיר הטיול כולל ארוחת צהריים.","ro":"Mekhir ha-tiyul kolel arukhat tsohorayim."},{"fr":"À la fin de la journée, on avait les jambes en compote.","tgt":"בסוף היום הרגליים שלנו היו גמורות.","ro":"Be-sof ha-yom ha-raglayim shelanu hayu gmurot."}],"tip":{"title":"Les noms accrochés : beit sefer, la maison du livre","example":"Le prix de la randonnée comprend le déjeuner. — <b>מחיר הטיול</b> כולל ארוחת צהריים.","body":"Pour dire « le prix de la randonnée », l'hébreu colle simplement deux noms l'un à l'autre, sans le petit mot « de » : « mekhir ha-tiyul », mot à mot « prix la-randonnée ». C'est ainsi qu'est né « beit sefer », l'école, littéralement « maison de livre ». Attention, le premier nom change souvent de son : « bayit », la maison, devient « beit », et « arukha », le repas, devient « arukhat », comme dans « arukhat tsohorayim », le déjeuner. Autre point clé : l'article « ha- » ne se met que sur le second nom, donc on dit « rosh ha-kvutsa », le chef du groupe, et jamais « ha-rosh ». Astuce : prononcez les deux noms d'un seul souffle, comme un mot composé.","exampleRo":"Mekhir ha-tiyul kolel arukhat tsohorayim.","lit":"prix · [le]-randonnée · comprend · repas · midi"}},{"title":"Sous les étoiles du désert","phrases":[{"fr":"Mitzpe Ramon est l'un des meilleurs endroits du pays pour observer les étoiles.","tgt":"מצפה רמון הוא אחד המקומות הטובים בארץ לצפייה בכוכבים.","ro":"Mitspe Ramon hu ekhad ha-mekomot ha-tovim ba-arets li-tsfiya ba-kokhavim."},{"fr":"Ici, l'éclairage des rues est volontairement faible.","tgt":"התאורה ברחובות כאן חלשה במכוון.","ro":"Ha-te'ura ba-rekhovot kan khalasha be-mekhuvan."},{"fr":"Loin des villes, on distingue nettement la Voie lactée.","tgt":"רחוק מהערים רואים בבירור את שביל החלב.","ro":"Rakhok me-he-arim ro'im be-verur et shvil ha-khalav."},{"fr":"Un astronome nous a prêté son télescope.","tgt":"אסטרונום השאיל לנו את הטלסקופ שלו.","ro":"Astronom hish'il lanu et ha-teleskop shelo."},{"fr":"On a vu les cratères de la lune de très près.","tgt":"ראינו את המכתשים של הירח מקרוב מאוד.","ro":"Ra'inu et ha-makhteshim shel ha-yare'akh mi-karov me'od."},{"fr":"Il faut une vingtaine de minutes pour que les yeux s'habituent au noir.","tgt":"לוקח בערך עשרים דקות עד שהעיניים מתרגלות לחושך.","ro":"Lokeakh be-erekh esrim dakot ad she-ha-einayim mitargelot la-khoshekh."},{"fr":"J'ai vu trois étoiles filantes en une heure.","tgt":"ראיתי שלושה כוכבים נופלים בשעה אחת.","ro":"Ra'iti shlosha kokhavim noflim be-sha'a akhat."},{"fr":"On s'est allongés sur le sable et on a perdu la notion du temps.","tgt":"שכבנו על החול ושכחנו מהזמן.","ro":"Shakhavnu al ha-khol ve-shakhakhnu me-ha-zman."},{"fr":"Il faisait froid, alors on s'est enroulés dans des couvertures.","tgt":"היה קר, אז התעטפנו בשמיכות.","ro":"Haya kar, az hit'atafnu bi-smikhot."},{"fr":"Je n'oublierai jamais ce ciel rempli d'étoiles.","tgt":"לעולם לא אשכח את השמיים המלאים בכוכבים.","ro":"Le-olam lo eshkakh et ha-shamayim ha-mele'im be-khokhavim."}]},{"title":"Le monde sous-marin d'Eilat","phrases":[{"fr":"Ceux qui ne plongent pas peuvent monter sur un bateau à fond transparent.","tgt":"מי שלא צולל יכול לעלות על סירה עם תחתית שקופה.","ro":"Mi she-lo tsolel yakhol la'alot al sira im takhtit shkufa."},{"fr":"L'observatoire sous-marin se trouve à plusieurs mètres sous la surface.","tgt":"המצפה התת ימי נמצא כמה מטרים מתחת לפני המים.","ro":"Ha-mitspe ha-tat-yami nimtsa kama metrim mi-takhat li-fnei ha-mayim."},{"fr":"Derrière la vitre, des requins passent tranquillement.","tgt":"מאחורי הזכוכית עוברים כרישים בשקט.","ro":"Me-akhorei ha-zkhukhit ovrim krishim be-sheket."},{"fr":"Les enfants collaient leur nez contre la vitre.","tgt":"הילדים הצמידו את האף לזכוכית.","ro":"Ha-yeladim hitsmidu et ha-af la-zkhukhit."},{"fr":"L'eau de la mer Rouge reste tiède même en hiver.","tgt":"המים בים סוף נשארים חמימים גם בחורף.","ro":"Ha-mayim be-Yam Suf nish'arim khamimim gam ba-khoref."},{"fr":"On a loué des palmes et un tuba pour la journée.","tgt":"שכרנו סנפירים ושנורקל ליום אחד.","ro":"Sakharnu snapirim ve-shnorkel le-yom ekhad."},{"fr":"Une tortue de mer a nagé juste sous notre bateau.","tgt":"צב ים שחה ממש מתחת לסירה שלנו.","ro":"Tsav yam sakha mamash mi-takhat la-sira shelanu."},{"fr":"La plage des coraux est une réserve naturelle protégée.","tgt":"חוף האלמוגים הוא שמורת טבע מוגנת.","ro":"Khof ha-almogim hu shmurat teva mugenet."},{"fr":"Il est interdit de donner à manger aux poissons.","tgt":"אסור להאכיל את הדגים.","ro":"Asur leha'akhil et ha-dagim."},{"fr":"Le soir, la promenade au bord de la mer se remplit de monde.","tgt":"בערב הטיילת מתמלאת באנשים.","ro":"Ba-erev ha-tayelet mitmale'et be-anashim."}]},{"title":"Au volant dans le désert","phrases":[{"fr":"On a loué une voiture pour être plus libres.","tgt":"שכרנו רכב כדי להיות חופשיים יותר.","ro":"Sakharnu rekhev kdei lihyot khofshiyim yoter."},{"fr":"L'agence de location nous a conseillé un véhicule tout-terrain.","tgt":"חברת ההשכרה המליצה לנו על רכב שטח.","ro":"Khevrat ha-haskara himlitsa lanu al rekhev shetakh."},{"fr":"Sur certaines pistes, une voiture ordinaire ne peut pas passer.","tgt":"בחלק מדרכי העפר רכב רגיל לא יכול לעבור.","ro":"Be-khelek mi-darkhei ha-afar rekhev ragil lo yakhol la'avor."},{"fr":"Les stations-service sont rares, alors on fait le plein à chaque occasion.","tgt":"תחנות הדלק נדירות, אז ממלאים דלק בכל הזדמנות.","ro":"Takhanot ha-delek nedirot, az memal'im delek be-khol hizdamnut."},{"fr":"L'application de navigation nous a envoyés sur une route fermée.","tgt":"אפליקציית הניווט שלחה אותנו לכביש סגור.","ro":"Aplikatsiyat ha-nivut shalkha otanu li-kvish sagur."},{"fr":"On a dû rebrousser chemin au bout de vingt kilomètres.","tgt":"נאלצנו לחזור על עקבותינו אחרי עשרים קילומטר.","ro":"Ne'eltsanu lakhzor al ikvoteinu akharei esrim kilometer."},{"fr":"La nuit, mieux vaut éviter de conduire dans le désert.","tgt":"בלילה עדיף לא לנהוג במדבר.","ro":"Ba-layla adif lo linhog ba-midbar."},{"fr":"Un pneu a éclaté en plein milieu de la piste.","tgt":"התפוצץ לנו גלגל באמצע הדרך.","ro":"Hitpotsets lanu galgal be-emtsa ha-derekh."},{"fr":"Par chance, un conducteur s'est arrêté pour nous aider.","tgt":"למזלנו, נהג אחד עצר כדי לעזור לנו.","ro":"Le-mazalenu, nahag ekhad atsar kdei la'azor lanu."},{"fr":"Conduire sur ces routes désertes donne un vrai sentiment de liberté.","tgt":"לנהוג בכבישים הריקים האלה נותן תחושה אמיתית של חופש.","ro":"Linhog ba-kvishim ha-reikim ha-ele noten tkhusha amitit shel khofesh."}]},{"title":"Une auberge au bord du cratère","phrases":[{"fr":"On a réservé deux nuits dans une auberge au bord du cratère.","tgt":"הזמנו שני לילות באכסניה על שפת המכתש.","ro":"Hizmanu shnei leilot be-akhsaniya al sfat ha-makhtesh."},{"fr":"La chambre donne directement sur le désert.","tgt":"החדר משקיף ישר על המדבר.","ro":"Ha-kheder mashkif yashar al ha-midbar."},{"fr":"Le petit-déjeuner est servi sur la terrasse jusqu'à dix heures.","tgt":"ארוחת הבוקר מוגשת במרפסת עד השעה עשר.","ro":"Arukhat ha-boker mugeshet ba-mirpeset ad ha-sha'a eser."},{"fr":"La plupart des clients sont des randonneurs.","tgt":"רוב האורחים הם מטיילים.","ro":"Rov ha-orkhim hem metaylim."},{"fr":"Dans la salle commune, chacun raconte son itinéraire.","tgt":"בחדר המשותף כל אחד מספר על המסלול שלו.","ro":"Ba-kheder ha-meshutaf kol ekhad mesaper al ha-maslul shelo."},{"fr":"Une voyageuse m'a donné de bons conseils pour la suite.","tgt":"מטיילת אחת נתנה לי עצות טובות להמשך.","ro":"Metayelet akhat natna li etsot tovot la-hemshekh."},{"fr":"Le quartier des artistes est tout près d'ici.","tgt":"רובע האמנים נמצא ממש קרוב לכאן.","ro":"Rova ha-omanim nimtsa mamash karov le-khan."},{"fr":"Le soir, un musicien du coin joue de la guitare.","tgt":"בערב מוזיקאי מקומי מנגן בגיטרה.","ro":"Ba-erev muzikai mekomi menagen ba-gitara."},{"fr":"La réception prête des lampes frontales aux clients.","tgt":"הקבלה משאילה פנסי ראש לאורחים.","ro":"Ha-kabala mash'ila panasei rosh la-orkhim."},{"fr":"J'aurais volontiers prolongé mon séjour d'une nuit.","tgt":"הייתי שמח להאריך את השהות שלי בעוד לילה.","ro":"Hayiti same'akh leha'arikh et ha-shehut sheli be-od layla."}]},{"title":"Une excursion organisée","phrases":[{"fr":"Le bus est censé partir à six heures précises.","tgt":"האוטובוס אמור לצאת בשש בדיוק.","ro":"Ha-otobus amur latset be-shesh be-diyuk."},{"fr":"Le guide était censé nous attendre à l'entrée de l'hôtel.","tgt":"המדריך היה אמור לחכות לנו בכניסה למלון.","ro":"Ha-madrikh haya amur lekhakot lanu ba-knisa la-malon."},{"fr":"On est censés être de retour avant le coucher du soleil.","tgt":"אנחנו אמורים לחזור לפני השקיעה.","ro":"Anakhnu amurim lakhzor lifnei ha-shki'a."},{"fr":"Le déjeuner est censé être compris dans le prix.","tgt":"ארוחת הצהריים אמורה להיות כלולה במחיר.","ro":"Arukhat ha-tsohorayim amura lihyot klula ba-mekhir."},{"fr":"Tu n'es pas censé quitter le groupe sans prévenir.","tgt":"אתה לא אמור לעזוב את הקבוצה בלי להודיע.","ro":"Ata lo amur la'azov et ha-kvutsa bli lehodi'a."},{"fr":"Finalement, le bus est arrivé avec quarante minutes de retard.","tgt":"בסוף האוטובוס הגיע באיחור של ארבעים דקות.","ro":"Ba-sof ha-otobus higi'a be-ikhur shel arba'im dakot."},{"fr":"Le programme a été modifié à cause de la chaleur.","tgt":"התוכנית שונתה בגלל החום.","ro":"Ha-tokhnit shunta biglal ha-khom."},{"fr":"La visite devait durer trois heures, elle en a duré cinq.","tgt":"הסיור היה אמור להימשך שלוש שעות, והוא נמשך חמש.","ro":"Ha-siyur haya amur lehimashekh shalosh sha'ot, ve-hu nimshakh khamesh."},{"fr":"Le guide parlait vite, mais j'ai presque tout compris.","tgt":"המדריך דיבר מהר, אבל הבנתי כמעט הכול.","ro":"Ha-madrikh diber maher, aval havanti kim'at ha-kol."},{"fr":"Malgré les imprévus, la journée a été très réussie.","tgt":"למרות ההפתעות, היום היה מוצלח מאוד.","ro":"Lamrot ha-hafta'ot, ha-yom haya mutslakh me'od."}],"tip":{"title":"« Amur le- » : être censé","example":"On est censés être de retour avant le coucher du soleil. — אנחנו <b>אמורים</b> לחזור לפני השקיעה.","body":"Pour dire « être censé », l'hébreu utilise « amur », littéralement « dit », suivi d'un verbe à l'infinitif en « le » ou « la ». Comme un adjectif, il s'accorde avec la personne : « amur » pour un homme, « amura » pour une femme ou un mot féminin, « amurim » pour un groupe. Au présent, pas de verbe être : « ha-otobus amur latset », mot à mot « le bus censé sortir ». Au passé, on ajoute simplement « haya » devant : « ha-madrikh haya amur lekhakot », le guide était censé attendre. Astuce : dès qu'un programme ne se passe pas comme prévu, « haya amur » vous servira toute la journée.","exampleRo":"Anakhnu amurim lakhzor lifnei ha-shki'a.","lit":"nous · censés · revenir · avant · [le]-coucher-du-soleil"}},{"title":"Un vignoble dans le désert","phrases":[{"fr":"On a visité un domaine viticole au milieu du Néguev.","tgt":"ביקרנו ביקב באמצע הנגב.","ro":"Bikarnu be-yekev be-emtsa ha-Negev."},{"fr":"Ici, les vignes sont arrosées au goutte-à-goutte.","tgt":"כאן משקים את הגפנים בטפטוף.","ro":"Kan mashkim et ha-gfanim be-tiftuf."},{"fr":"Cette technique d'irrigation a été mise au point en Israël.","tgt":"שיטת ההשקיה הזאת פותחה בישראל.","ro":"Shitat ha-hashka'a ha-zot putkha be-Yisra'el."},{"fr":"Le propriétaire nous a fait goûter plusieurs vins.","tgt":"בעל המקום נתן לנו לטעום כמה יינות.","ro":"Ba'al ha-makom natan lanu lit'om kama yeinot."},{"fr":"Les nuits fraîches donnent au raisin un goût particulier.","tgt":"הלילות הקרירים נותנים לענבים טעם מיוחד.","ro":"Ha-leilot ha-karirim notnim la-anavim ta'am meyukhad."},{"fr":"Le domaine produit aussi de l'huile d'olive.","tgt":"המשק מייצר גם שמן זית.","ro":"Ha-meshek meyatser gam shemen zayit."},{"fr":"On a acheté deux bouteilles pour nos amis à Paris.","tgt":"קנינו שני בקבוקים לחברים שלנו בפריז.","ro":"Kaninu shnei bakbukim la-khaverim shelanu be-Pariz."},{"fr":"Certaines fermes isolées proposent aussi des chambres d'hôtes.","tgt":"חלק מהחוות המבודדות מציעות גם חדרי אירוח.","ro":"Khelek me-ha-khavot ha-mevudadot metsi'ot gam khadrei eru'akh."},{"fr":"Faire pousser des fruits ici demande beaucoup de patience.","tgt":"לגדל פירות כאן דורש הרבה סבלנות.","ro":"Legadel perot kan doresh harbe savlanut."},{"fr":"Je n'aurais jamais cru qu'on pouvait cultiver la vigne dans le désert.","tgt":"לא האמנתי שאפשר לגדל גפנים במדבר.","ro":"Lo he'emanti she-efshar legadel gfanim ba-midbar."}]},{"title":"Les sources d'Ein Avdat","phrases":[{"fr":"Ein Avdat se cache au fond d'un canyon étroit.","tgt":"עין עבדת מסתתר בתוך קניון צר.","ro":"Ein Avdat mistater be-tokh kanyon tsar."},{"fr":"Tout au fond du canyon jaillit une source d'eau fraîche.","tgt":"בתחתית הקניון נובע מעיין של מים קרים.","ro":"Be-takhtit ha-kanyon nove'a ma'ayan shel mayim karim."},{"fr":"La baignade y est interdite pour protéger la nature.","tgt":"אסור לרחוץ שם כדי לשמור על הטבע.","ro":"Asur lirkhots sham kdei lishmor al ha-teva."},{"fr":"Des bouquetins boivent tranquillement près de la cascade.","tgt":"יעלים שותים בשקט ליד המפל.","ro":"Ye'elim shotim be-sheket leyad ha-mapal."},{"fr":"On a grimpé des échelles métalliques fixées dans la roche.","tgt":"טיפסנו בסולמות מתכת שקבועים בסלע.","ro":"Tipasnu be-sulamot matekhet she-kvu'im ba-sela."},{"fr":"Le sentier est à sens unique, on ne peut pas faire demi-tour.","tgt":"השביל הוא חד כיווני, אי אפשר לחזור אחורה.","ro":"Ha-shvil hu khad-kivuni, i efshar lakhzor akhora."},{"fr":"Mieux vaut partir tôt, avant que les groupes n'arrivent.","tgt":"עדיף להתחיל מוקדם, לפני שהקבוצות מגיעות.","ro":"Adif lehatkhil mukdam, lifnei she-ha-kvutsot magi'ot."},{"fr":"En haut, on découvre les vestiges d'une ancienne cité nabatéenne.","tgt":"למעלה מגלים את השרידים של עיר נבטית עתיקה.","ro":"Le-mala megalim et ha-sridim shel ir nabatit atika."},{"fr":"Les Nabatéens faisaient passer leurs caravanes d'épices par ici.","tgt":"הנבטים העבירו כאן את שיירות התבלינים שלהם.","ro":"Ha-nabatim he'eviru kan et shayarot ha-tavlinim shelahem."},{"fr":"Ce mélange de nature et d'histoire m'a beaucoup plu.","tgt":"השילוב הזה של טבע והיסטוריה מאוד מצא חן בעיניי.","ro":"Ha-shiluv ha-ze shel teva ve-historya me'od matsa khen be-einai."}]},{"title":"Voyager de façon responsable","phrases":[{"fr":"Dans le désert, chacun remporte ses propres déchets.","tgt":"במדבר כל אחד לוקח את האשפה שלו בחזרה.","ro":"Ba-midbar kol ekhad lokeakh et ha-ashpa shelo ba-khazara."},{"fr":"Il ne faut jamais quitter les sentiers balisés.","tgt":"אסור לצאת מהשבילים המסומנים.","ro":"Asur latset me-ha-shvilim ha-mesumanim."},{"fr":"Les plantes du désert mettent des années à repousser.","tgt":"לצמחי המדבר לוקח שנים לצמוח מחדש.","ro":"Le-tsimkhei ha-midbar lokeakh shanim litsmo'akh me-khadash."},{"fr":"On a choisi un hébergement qui fonctionne à l'énergie solaire.","tgt":"בחרנו מקום לינה שפועל על אנרגיה סולארית.","ro":"Bakharnu mekom lina she-po'el al energya solarit."},{"fr":"L'eau est précieuse ici, alors on prend des douches courtes.","tgt":"המים יקרים כאן, ולכן מתקלחים מהר.","ro":"Ha-mayim yekarim kan, ve-lakhen mitkalkhim maher."},{"fr":"Les guides locaux connaissent le terrain mieux que personne.","tgt":"המדריכים המקומיים מכירים את השטח יותר טוב מכולם.","ro":"Ha-madrikhim ha-mekomiyim makirim et ha-shetakh yoter tov mi-kulam."},{"fr":"En faisant appel à eux, on soutient l'économie de la région.","tgt":"כשמזמינים אותם, תומכים בכלכלה של האזור.","ro":"Kshe-mazminim otam, tomkhim ba-kalkala shel ha-ezor."},{"fr":"Mieux vaut acheter l'artisanat directement aux artisans.","tgt":"עדיף לקנות עבודות יד ישירות מהאומנים.","ro":"Adif liknot avodot yad yeshirot me-ha-umanim."},{"fr":"On ne nourrit pas les animaux sauvages, même les plus mignons.","tgt":"לא מאכילים חיות בר, אפילו את החמודות ביותר.","ro":"Lo ma'akhilim khayot bar, afilu et ha-khamudot beyoter."},{"fr":"Voyager autrement, c'est aussi respecter ceux qui vivent ici.","tgt":"לטייל אחרת זה גם לכבד את מי שגר כאן.","ro":"Letayel akheret ze gam lekhabed et mi she-gar kan."}]},{"title":"Une balade à dos de chameau","phrases":[{"fr":"On a fait une balade à dos de chameau au coucher du soleil.","tgt":"עשינו רכיבה על גמלים בשקיעה.","ro":"Asinu rkhiva al gmalim ba-shki'a."},{"fr":"Monter sur un chameau est plus difficile qu'on ne le pense.","tgt":"לעלות על גמל יותר קשה ממה שחושבים.","ro":"La'alot al gamal yoter kashe mi-ma she-khoshvim."},{"fr":"Quand il se relève, il faut bien se pencher en arrière.","tgt":"כשהוא קם, צריך להישען הרבה אחורה.","ro":"Kshe-hu kam, tsarikh lehisha'en harbe akhora."},{"fr":"Le chamelier marchait devant en tenant la corde.","tgt":"מוביל הגמלים הלך מקדימה והחזיק את החבל.","ro":"Movil ha-gmalim halakh mi-kadima ve-hekhzik et ha-khevel."},{"fr":"Mon chameau n'arrêtait pas de s'arrêter pour manger.","tgt":"הגמל שלי עצר כל הזמן כדי לאכול.","ro":"Ha-gamal sheli atsar kol ha-zman kdei le'ekhol."},{"fr":"Le rythme lent du chameau nous endormait un peu.","tgt":"הקצב האיטי של הגמל הרדים אותנו קצת.","ro":"Ha-ketsev ha-iti shel ha-gamal hirdim otanu ktsat."},{"fr":"Au bout d'une heure, j'avais mal partout.","tgt":"אחרי שעה כאב לי בכל הגוף.","ro":"Akharei sha'a ka'av li be-khol ha-guf."},{"fr":"Les enfants, eux, ne voulaient plus descendre.","tgt":"הילדים, לעומת זאת, לא רצו לרדת.","ro":"Ha-yeladim, le-umat zot, lo ratsu laredet."},{"fr":"On a terminé la balade par un thé près du feu.","tgt":"סיימנו את הרכיבה בכוס תה ליד המדורה.","ro":"Siyamnu et ha-rkhiva be-khos te leyad ha-medura."},{"fr":"C'était une expérience un peu folle, mais je la referais volontiers.","tgt":"זאת הייתה חוויה קצת משוגעת, אבל הייתי עושה אותה שוב בשמחה.","ro":"Zot hayta khavaya ktsat meshuga'at, aval hayiti ose ota shuv be-simkha."}]},{"title":"La chaleur et la santé","phrases":[{"fr":"En plein été, la température peut dépasser quarante-cinq degrés.","tgt":"באמצע הקיץ הטמפרטורה יכולה לעבור ארבעים וחמש מעלות.","ro":"Be-emtsa ha-kayits ha-temperatura yekhola la'avor arba'im ve-khamesh ma'alot."},{"fr":"Il faut boire avant même d'avoir soif.","tgt":"צריך לשתות עוד לפני שמרגישים צמא.","ro":"Tsarikh lishtot od lifnei she-margishim tsama."},{"fr":"Un litre d'eau par heure de marche, c'est la règle.","tgt":"ליטר מים לכל שעת הליכה, זה הכלל.","ro":"Liter mayim le-khol she'at halikha, ze ha-klal."},{"fr":"Mon ami a eu un coup de chaleur le deuxième jour.","tgt":"לחבר שלי הייתה מכת חום ביום השני.","ro":"La-khaver sheli hayta makat khom ba-yom ha-sheni."},{"fr":"Il avait mal à la tête et se sentait très faible.","tgt":"היה לו כאב ראש והוא הרגיש חלש מאוד.","ro":"Haya lo ke'ev rosh ve-hu hirgish khalash me'od."},{"fr":"On l'a installé à l'ombre et on l'a fait boire lentement.","tgt":"הושבנו אותו בצל ונתנו לו לשתות לאט.","ro":"Hoshavnu oto ba-tsel ve-natanu lo lishtot le-at."},{"fr":"La pharmacienne nous a recommandé des sels minéraux.","tgt":"הרוקחת המליצה לנו על מלחים מינרליים.","ro":"Ha-rokakhat himlitsa lanu al melakhim mineraliyim."},{"fr":"Le chapeau et la crème solaire sont une obligation, pas une suggestion.","tgt":"כובע וקרם הגנה הם חובה, לא המלצה.","ro":"Kova ve-krem hagana hem khova, lo hamlatsa."},{"fr":"Aux heures les plus chaudes, on reste à l'intérieur.","tgt":"בשעות החמות ביותר נשארים בפנים.","ro":"Ba-sha'ot ha-khamot beyoter nish'arim bifnim."},{"fr":"Le lendemain, par chance, il se sentait déjà beaucoup mieux.","tgt":"למחרת, למרבה המזל, הוא כבר הרגיש הרבה יותר טוב.","ro":"Le-mokhorat, le-marbe ha-mazal, hu kvar hirgish harbe yoter tov."}]},{"title":"Prise dans une tempête de sable","phrases":[{"fr":"En début d'après-midi, le vent s'est levé d'un coup.","tgt":"בתחילת אחר הצהריים פתאום התחילה לנשוב רוח חזקה.","ro":"Bi-tkhilat akhar ha-tsohorayim pit'om hitkhila linshov ru'akh khazaka."},{"fr":"Le ciel devenait de plus en plus jaune.","tgt":"השמיים נעשו צהובים יותר ויותר.","ro":"Ha-shamayim na'asu tsehubim yoter ve-yoter."},{"fr":"Le vent soufflait de plus en plus fort.","tgt":"הרוח נשבה חזק יותר ויותר.","ro":"Ha-ru'akh nashva khazak yoter ve-yoter."},{"fr":"On voyait la route de moins en moins bien.","tgt":"ראינו את הכביש פחות ופחות טוב.","ro":"Ra'inu et ha-kvish pakhot ve-pakhot tov."},{"fr":"Le guide nous a demandé de nous mettre tout de suite à l'abri.","tgt":"המדריך ביקש מאיתנו להיכנס מיד למחסה.","ro":"Ha-madrikh bikesh me-itanu lehikanes miyad le-makhase."},{"fr":"Le sable entrait partout, même dans nos sacs fermés.","tgt":"החול נכנס לכל מקום, אפילו לתיקים הסגורים.","ro":"Ha-khol nikhnas le-khol makom, afilu la-tikim ha-sgurim."},{"fr":"On s'est protégé le visage avec des foulards.","tgt":"כיסינו את הפנים בצעיפים.","ro":"Kisinu et ha-panim bi-tsa'ifim."},{"fr":"Les tempêtes de sable sont de plus en plus fréquentes dans la région.","tgt":"סופות חול נעשות נפוצות יותר ויותר באזור.","ro":"Sufot khol na'asot nefotsot yoter ve-yoter ba-ezor."},{"fr":"Au bout de deux heures, le vent s'est enfin calmé.","tgt":"אחרי שעתיים הרוח סוף סוף נרגעה.","ro":"Akharei sha'atayim ha-ru'akh sof sof nirge'a."},{"fr":"J'ai de plus en plus de respect pour ceux qui vivent dans le désert.","tgt":"יש לי יותר ויותר כבוד לאנשים שחיים במדבר.","ro":"Yesh li yoter ve-yoter kavod la-anashim she-khayim ba-midbar."}],"tip":{"title":"« Yoter ve-yoter » : de plus en plus","example":"Le vent soufflait de plus en plus fort. — הרוח נשבה חזק <b>יותר ויותר</b>.","body":"Pour dire « de plus en plus », l'hébreu répète simplement le mot « yoter », plus, en les reliant par « ve- », et : « yoter ve-yoter », mot à mot « plus et plus ». Contrairement au français, l'expression se place le plus souvent après l'adjectif : « khazak yoter ve-yoter », fort de plus en plus, ou « tsehubim yoter ve-yoter », jaunes de plus en plus. Devant un nom, en revanche, elle vient avant, comme en français : « yoter ve-yoter kavod », de plus en plus de respect. Et pour « de moins en moins », on fait pareil avec « pakhot », moins : « pakhot ve-pakhot ». Astuce : imaginez le vent qui forcit et répétez « yoter ve-yoter » en montant la voix.","exampleRo":"Ha-ru'akh nashva khazak yoter ve-yoter.","lit":"[le]-vent · soufflait · fort · plus · [et]-plus"}},{"title":"Retour à Eilat, dix ans après","phrases":[{"fr":"Je suis revenu à Eilat dix ans après mon premier séjour.","tgt":"חזרתי לאילת עשר שנים אחרי הביקור הראשון שלי.","ro":"Khazarti le-Eilat eser shanim akharei ha-bikur ha-rishon sheli."},{"fr":"La ville a beaucoup changé depuis.","tgt":"העיר השתנתה מאוד מאז.","ro":"Ha-ir hishtanta me'od me-az."},{"fr":"De nouveaux hôtels ont été construits le long de la plage.","tgt":"מלונות חדשים נבנו לאורך החוף.","ro":"Melonot khadashim nivnu le-orekh ha-khof."},{"fr":"Le petit café où l'on prenait le petit-déjeuner existe toujours.","tgt":"בית הקפה הקטן שבו אכלנו ארוחת בוקר עדיין קיים.","ro":"Beit ha-kafe ha-katan she-bo akhalnu arukhat boker adayin kayam."},{"fr":"Le patron m'a reconnu tout de suite.","tgt":"הבעלים זיהה אותי מיד.","ro":"Ha-be'alim zihe oti miyad."},{"fr":"On a longtemps parlé du bon vieux temps.","tgt":"דיברנו הרבה זמן על הימים הטובים ההם.","ro":"Dibarnu harbe zman al ha-yamim ha-tovim ha-hem."},{"fr":"Certains endroits m'ont paru plus petits que dans mon souvenir.","tgt":"כמה מקומות נראו לי קטנים יותר ממה שזכרתי.","ro":"Kama mekomot nir'u li ktanim yoter mi-ma she-zakharti."},{"fr":"La mer, elle, n'a pas changé du tout.","tgt":"הים, לעומת זאת, לא השתנה בכלל.","ro":"Ha-yam, le-umat zot, lo hishtana bikhlal."},{"fr":"J'ai refait la même plongée qu'à l'époque.","tgt":"עשיתי שוב את אותה צלילה כמו אז.","ro":"Asiti shuv et ota tslila kmo az."},{"fr":"Ce retour m'a rendu un peu nostalgique.","tgt":"החזרה הזאת עשתה אותי קצת נוסטלגי.","ro":"Ha-khazara ha-zot asta oti ktsat nostalgi."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce voyage dans le sud m'a beaucoup appris.","tgt":"הטיול בדרום לימד אותי הרבה.","ro":"Ha-tiyul ba-darom limed oti harbe."},{"fr":"Maintenant, je sais raconter un voyage en hébreu.","tgt":"עכשיו אני יודע לספר על טיול בעברית.","ro":"Akhshav ani yode'a lesaper al tiyul be-ivrit."},{"fr":"J'arrive à demander mon chemin sans hésiter.","tgt":"אני מצליח לשאול איך מגיעים בלי להסס.","ro":"Ani matsli'akh lish'ol eikh magi'im bli lehases."},{"fr":"Je comprends de mieux en mieux ce que disent les guides.","tgt":"אני מבין יותר ויותר טוב את מה שהמדריכים אומרים.","ro":"Ani mevin yoter ve-yoter tov et ma she-ha-madrikhim omrim."},{"fr":"Je fais encore des erreurs, mais ça ne me bloque plus.","tgt":"אני עדיין עושה טעויות, אבל זה כבר לא עוצר אותי.","ro":"Ani adayin ose ta'uyot, aval ze kvar lo otser oti."},{"fr":"Les gens d'ici apprécient vraiment qu'on fasse l'effort de parler hébreu.","tgt":"האנשים כאן מאוד מעריכים כשמשתדלים לדבר עברית.","ro":"Ha-anashim kan me'od ma'arikhim kshe-mishtadlim ledaber ivrit."},{"fr":"Le désert m'a appris à prendre mon temps.","tgt":"המדבר לימד אותי לא למהר.","ro":"Ha-midbar limed oti lo lemaher."},{"fr":"J'ai déjà envie de repartir explorer le nord du pays.","tgt":"כבר יש לי חשק לצאת שוב ולטייל בצפון הארץ.","ro":"Kvar yesh li kheshek latset shuv u-letayel bi-tsfon ha-arets."},{"fr":"La prochaine fois, je voyagerai seul, sans guide.","tgt":"בפעם הבאה אטייל לבד, בלי מדריך.","ro":"Ba-pa'am ha-ba'a atayel levad, bli madrikh."},{"fr":"Bravo, tu as terminé le deuxième module du niveau trois !","tgt":"כל הכבוד, סיימת את המודול השני של הרמה השלישית!","ro":"Kol ha-kavod, siyamta et ha-modul ha-sheni shel ha-rama ha-shlishit!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"L'hébreu, une langue qui a ressuscité","phrases":[{"fr":"Pendant des siècles, l'hébreu était surtout une langue écrite.","tgt":"במשך מאות שנים, העברית הייתה בעיקר שפה כתובה.","ro":"Be-meshekh me'ot shanim, ha-ivrit hayta be-ikar safa ktuva."},{"fr":"Personne ne la parlait à la maison avec ses enfants.","tgt":"אף אחד לא דיבר אותה בבית עם הילדים שלו.","ro":"Af ekhad lo diber ota ba-bayit im ha-yeladim shelo."},{"fr":"Il y a un peu plus de cent ans, elle est redevenue une langue parlée.","tgt":"לפני קצת יותר ממאה שנה, היא חזרה להיות שפה מדוברת.","ro":"Lifney ktsat yoter mi-me'a shana, hi khazra lihyot safa meduberet."},{"fr":"Il a fallu inventer des milliers de mots pour la vie moderne.","tgt":"היה צריך להמציא אלפי מילים בשביל החיים המודרניים.","ro":"Haya tsarikh lehamtsi alfey milim bishvil ha-khayim ha-moderniyim."},{"fr":"Le mot « ordinateur » a été créé à partir du mot « pensée ».","tgt":"המילה מחשב נוצרה מהמילה מחשבה.","ro":"Ha-mila makhshev notsra me-ha-mila makhshava."},{"fr":"Beaucoup de mots nouveaux sont construits sur des racines très anciennes.","tgt":"הרבה מילים חדשות בנויות על שורשים עתיקים מאוד.","ro":"Harbe milim khadashot bnuyot al shorashim atikim me'od."},{"fr":"Aujourd'hui, des millions de gens rêvent en hébreu.","tgt":"היום, מיליוני אנשים חולמים בעברית.","ro":"Ha-yom, milyoney anashim kholmim be-ivrit."},{"fr":"Les enfants corrigent parfois l'hébreu de leurs parents.","tgt":"הילדים מתקנים לפעמים את העברית של ההורים שלהם.","ro":"Ha-yeladim metaknim lifamim et ha-ivrit shel ha-horim shelahem."},{"fr":"Je trouve incroyable qu'une langue ancienne serve aujourd'hui dans la high-tech.","tgt":"אני חושב שזה מדהים ששפה עתיקה משמשת היום בחברות הייטק.","ro":"Ani khoshev she-ze madhim she-safa atika meshameshet ha-yom be-khevrot haytek."},{"fr":"Quand je parle hébreu, j'ai l'impression de toucher à l'histoire.","tgt":"כשאני מדבר עברית, יש לי הרגשה שאני נוגע בהיסטוריה.","ro":"Kshe-ani medaber ivrit, yesh li hargasha she-ani noge'a ba-historya."}],"tip":{"title":"L'hébreu : une langue ancienne redevenue parlée","example":"Le mot « ordinateur » a été créé à partir du mot « pensée ». — המילה <b>מחשב</b> נוצרה מהמילה <b>מחשבה</b>.","body":"Pendant très longtemps, l'hébreu servait surtout aux livres, et il a fallu le faire revivre à l'oral il y a un peu plus de cent ans. Pour inventer les mots modernes, on est reparti des vieilles racines de trois consonnes, qui portent chacune une idée générale. Prenez la racine « kh, sh, v », l'idée de penser : « lakhshov », penser, « makhshava », une pensée, « khashuv », important, et « makhshev », l'ordinateur, littéralement la machine qui pense. Notre exemple, « ha-mila makhshev notsra me-ha-mila makhshava », se décompose ainsi : le mot ordinateur a été créé du mot pensée. Quand vous entendez un mot inconnu, cherchez son squelette de trois consonnes : vous devinerez souvent son sens, et c'est la meilleure astuce pour enrichir votre vocabulaire en parlant.","exampleRo":"Ha-mila makhshev notsra me-ha-mila makhshava.","lit":"le-mot · ordinateur · a-été-créé · de-le-mot · pensée"}},{"title":"Travail et équilibre de vie","phrases":[{"fr":"En Israël, on travaille en général du dimanche au jeudi.","tgt":"בישראל עובדים בדרך כלל מיום ראשון עד יום חמישי.","ro":"Be-Yisra'el ovdim be-derekh klal mi-yom rishon ad yom khamishi."},{"fr":"Le vendredi est consacré à la famille et aux courses.","tgt":"יום שישי מוקדש למשפחה ולקניות.","ro":"Yom shishi mukdash la-mishpakha ve-la-kniyot."},{"fr":"Mon patron m'envoie des messages même tard le soir.","tgt":"הבוס שלי שולח לי הודעות גם מאוחר בלילה.","ro":"Ha-bos sheli shole'akh li hoda'ot gam me'ukhar ba-layla."},{"fr":"J'ai décidé de ne plus répondre après sept heures du soir.","tgt":"החלטתי לא לענות יותר אחרי שבע בערב.","ro":"Hekhlateti lo la'anot yoter akharey sheva ba-erev."},{"fr":"Depuis que je travaille de la maison, je vois davantage mes enfants.","tgt":"מאז שאני עובד מהבית, אני רואה יותר את הילדים שלי.","ro":"Me'az she-ani oved me-ha-bayit, ani ro'e yoter et ha-yeladim sheli."},{"fr":"Mais il est parfois difficile de séparer le bureau et le salon.","tgt":"אבל לפעמים קשה להפריד בין המשרד לסלון.","ro":"Aval lifamim kashe lehafrid beyn ha-misrad la-salon."},{"fr":"Mon amie Noa s'est épuisée à force d'heures supplémentaires.","tgt":"החברה שלי נועה נשחקה מרוב שעות נוספות.","ro":"Ha-khavera sheli No'a nishkheka me-rov sha'ot nosafot."},{"fr":"Elle a pris trois mois de congé pour se reposer.","tgt":"היא לקחה שלושה חודשים חופש כדי לנוח.","ro":"Hi lakkha shlosha khodashim khofesh kedey lanu'akh."},{"fr":"Selon moi, la santé passe avant la carrière.","tgt":"לדעתי, הבריאות קודמת לקריירה.","ro":"Le-da'ati, ha-bri'ut kodemet la-karyera."},{"fr":"Travailler moins ne veut pas dire travailler moins bien.","tgt":"לעבוד פחות לא אומר לעבוד פחות טוב.","ro":"La'avod pakhot lo omer la'avod pakhot tov."}]},{"title":"Un dîner entre amis","phrases":[{"fr":"Le dîner est prêt, bon appétit à tous !","tgt":"הארוחה מוכנה, בתיאבון לכולם!","ro":"Ha-arukha mukhana, be-te'avon le-khulam!"},{"fr":"Tu as acheté une nouvelle chemise ? Profites-en bien !","tgt":"קנית חולצה חדשה? תתחדש!","ro":"Kanita khultsa khadasha? Titkhadesh!"},{"fr":"Dana, ta nouvelle voiture est superbe, profite-en bien !","tgt":"דנה, האוטו החדש שלך מהמם, תתחדשי!","ro":"Dana, ha-oto he-khadash shelakh mehamem, titkhadshi!"},{"fr":"Tu as couru dix kilomètres ce matin ? Chapeau !","tgt":"רצת עשרה קילומטרים הבוקר? כל הכבוד!","ro":"Ratsta asara kilometrim ha-boker? Kol ha-kavod!"},{"fr":"Bravo, tu as enfin réussi ton permis de conduire !","tgt":"כל הכבוד שעברת סוף סוף את הטסט!","ro":"Kol ha-kavod she-avarta sof sof et ha-test!"},{"fr":"Levons nos verres, à la vie !","tgt":"בואו נרים כוסית, לחיים!","ro":"Bo'u narim kosit, lekhayim!"},{"fr":"Merci pour ce repas excellent, bravo au cuisinier !","tgt":"תודה על הארוחה המעולה, בריאות לידיים!","ro":"Toda al ha-arukha ha-me'ula, bri'ut la-yadayim!"},{"fr":"Bonne semaine à tous, on se revoit dimanche !","tgt":"שבוע טוב לכולם, נתראה ביום ראשון!","ro":"Shavu'a tov le-khulam, nitra'e be-yom rishon!"},{"fr":"Tu t'es fait couper les cheveux ? Ça te va super bien, profites-en !","tgt":"הסתפרת? זה יושב עליך מעולה, תתחדש!","ro":"Histaparta? Ze yoshev alekha me'ule, titkhadesh!"},{"fr":"Bon rétablissement, j'espère que tu iras vite mieux.","tgt":"רפואה שלמה, אני מקווה שתרגיש טוב מהר.","ro":"Refu'a shlema, ani mekave she-targish tov maher."}],"tip":{"title":"Les expressions du quotidien : be-te'avon, titkhadesh, kol ha-kavod","example":"Tu as acheté une nouvelle chemise ? Profites-en bien ! — קנית חולצה חדשה? <b>תתחדש</b>!","body":"En hébreu, beaucoup de situations appellent une formule toute faite, et les Israéliens les utilisent sans arrêt. Avant de manger, on dit « be-te'avon », littéralement « avec appétit », comme notre bon appétit. Quand quelqu'un montre un objet neuf, un vêtement ou une nouvelle coupe de cheveux, on lui lance « titkhadesh », mot à mot « sois renouvelé », et « titkhadshi » à une femme : le français n'a pas d'équivalent exact, c'est un peu « profite bien de ta nouveauté ». Pour féliciter, on dit « kol ha-kavod », littéralement « tout l'honneur », c'est-à-dire bravo, et après un bon repas on remercie le cuisinier avec « bri'ut la-yadayim », santé aux mains. Astuce : associez chaque formule à une image, la fourchette pour be-te'avon, le sac de courses pour titkhadesh, le pouce levé pour kol ha-kavod.","exampleRo":"Kanita khultsa khadasha? Titkhadesh!","lit":"tu-as-acheté · chemise · nouvelle ? · sois-renouvelé !"}},{"title":"La high-tech à l'israélienne","phrases":[{"fr":"Mon cousin travaille dans une start-up à Herzliya.","tgt":"בן הדוד שלי עובד בסטארטאפ בהרצליה.","ro":"Ben ha-dod sheli oved be-startap be-Hertsliya."},{"fr":"Son entreprise a été rachetée par une grande société l'an dernier.","tgt":"החברה שלו נקנתה על ידי חברה גדולה בשנה שעברה.","ro":"Ha-khevra shelo nikneta al yedey khevra gdola ba-shana she-avra."},{"fr":"Ici, tout le monde rêve de lancer sa propre application.","tgt":"כולם פה חולמים להקים אפליקציה משלהם.","ro":"Kulam po kholmim lehakim aplikatsya mishelahem."},{"fr":"On dit souvent qu'Israël est le pays des start-up.","tgt":"אומרים שישראל היא מדינה של סטארטאפים.","ro":"Omrim she-Yisra'el hi medina shel startapim."},{"fr":"Dans la high-tech, les salaires sont très élevés, mais la pression aussi.","tgt":"המשכורות בהייטק גבוהות מאוד, אבל גם הלחץ.","ro":"Ha-maskorot ba-haytek gvohot me'od, aval gam ha-lakhats."},{"fr":"Ma sœur s'est reconvertie et est devenue programmeuse à quarante ans.","tgt":"אחותי עשתה הסבה מקצועית והפכה למתכנתת בגיל ארבעים.","ro":"Akhoti asta hasava miktso'it ve-hafkha le-metakhnetet be-gil arba'im."},{"fr":"Elle dit que l'intelligence artificielle va changer notre façon de travailler.","tgt":"היא אומרת שהבינה המלאכותית תשנה את הדרך שבה אנחנו עובדים.","ro":"Hi omeret she-ha-bina ha-melakhutit teshane et ha-derekh she-ba anakhnu ovdim."},{"fr":"Moi, je crains que les machines nous remplacent un jour.","tgt":"אני חושש שהמכונות יחליפו אותנו יום אחד.","ro":"Ani khoshesh she-ha-mekhonot yakhlifu otanu yom ekhad."},{"fr":"Dans la high-tech, on parle un hébreu rempli de mots étrangers.","tgt":"בהייטק מדברים עברית מלאה במילים לועזיות.","ro":"Ba-haytek medabrim ivrit mele'a be-milim lo'aziyot."},{"fr":"Malgré tout, cette énergie créative me fascine.","tgt":"למרות הכול, האנרגיה היצירתית הזאת מרתקת אותי.","ro":"Lamrot ha-kol, ha-energya ha-yetsiratit ha-zot merateket oti."}]},{"title":"Parler comme les jeunes","phrases":[{"fr":"Il m'a regardé comme si j'étais fou.","tgt":"הוא הסתכל עליי כאילו אני משוגע.","ro":"Hu histakel alay ke'ilu ani meshuga."},{"fr":"Elle parle comme si elle connaissait tout le monde à Tel Aviv.","tgt":"היא מדברת כאילו היא מכירה את כולם בתל אביב.","ro":"Hi medaberet ke'ilu hi makira et kulam be-Tel Aviv."},{"fr":"J'étais, genre, complètement sous le choc.","tgt":"הייתי, כאילו, בהלם מוחלט.","ro":"Hayiti, ke'ilu, be-helem mukhlat."},{"fr":"C'est genre le meilleur café de la ville.","tgt":"זה כאילו בית הקפה הכי טוב בעיר.","ro":"Ze ke'ilu beyt ha-kafe ha-khi tov ba-ir."},{"fr":"On dirait qu'il va pleuvoir cet après-midi.","tgt":"נראה כאילו עומד לרדת גשם אחר הצהריים.","ro":"Nir'e ke'ilu omed laredet geshem akhar ha-tsohorayim."},{"fr":"Il fait comme si de rien n'était.","tgt":"הוא עושה כאילו לא קרה כלום.","ro":"Hu ose ke'ilu lo kara klum."},{"fr":"Tu fais semblant de ne pas m'entendre ?","tgt":"אתה עושה כאילו אתה לא שומע אותי?","ro":"Ata ose ke'ilu ata lo shome'a oti?"},{"fr":"Ce n'est pas comme si j'avais le choix.","tgt":"זה לא כאילו יש לי ברירה.","ro":"Ze lo ke'ilu yesh li brera."},{"fr":"Mes parents se plaignent que je dis « genre » à chaque phrase.","tgt":"ההורים שלי מתלוננים שאני אומר כאילו בכל משפט.","ro":"Ha-horim sheli mitlonenim she-ani omer ke'ilu be-khol mishpat."},{"fr":"Pendant ce concert, je me sentais comme dans un rêve.","tgt":"בהופעה הזאת הרגשתי כאילו אני בתוך חלום.","ro":"Ba-hofa'a ha-zot hirgashti ke'ilu ani be-tokh khalom."}],"tip":{"title":"« Ke'ilu » : on dirait que, genre","example":"Il m'a regardé comme si j'étais fou. — הוא הסתכל עליי <b>כאילו</b> אני משוגע.","body":"Le mot « ke'ilu » veut d'abord dire « comme si » : « hu histakel alay ke'ilu ani meshuga », il m'a regardé comme si j'étais fou, mot à mot « il, a regardé, sur moi, comme si, moi, fou ». Remarquez qu'après ke'ilu, l'hébreu garde simplement le présent, là où le français passe à l'imparfait. On le retrouve dans « nir'e ke'ilu », on dirait que, et dans « ose ke'ilu », faire semblant : « hu ose ke'ilu lo kara klum », il fait comme si de rien n'était. Mais chez les jeunes, ke'ilu sert surtout de mot de remplissage, exactement comme notre « genre » : « hayiti, ke'ilu, be-helem », j'étais, genre, sous le choc. Astuce : employez-le avec modération, sinon vous sonnerez comme un adolescent de Tel Aviv !","exampleRo":"Hu histakel alay ke'ilu ani meshuga.","lit":"il · a-regardé · sur-moi · comme-si · moi · fou"}},{"title":"Tradition et modernité","phrases":[{"fr":"Chez nous, le dîner du vendredi soir est une tradition que personne ne rate.","tgt":"אצלנו, ארוחת שישי היא מסורת שאף אחד לא מפספס.","ro":"Etslenu, arukhat shishi hi masoret she-af ekhad lo mefasfes."},{"fr":"Ma grand-mère prépare encore les recettes de son enfance.","tgt":"סבתא שלי עדיין מכינה את המתכונים מהילדות שלה.","ro":"Savta sheli adayin mekhina et ha-matkonim me-ha-yaldut shela."},{"fr":"Mais mes enfants préfèrent commander à manger sur leur téléphone.","tgt":"אבל הילדים שלי מעדיפים להזמין אוכל בטלפון.","ro":"Aval ha-yeladim sheli ma'adifim lehazmin okhel ba-telefon."},{"fr":"Il faut trouver un équilibre entre l'ancien et le nouveau.","tgt":"צריך למצוא איזון בין הישן לחדש.","ro":"Tsarikh limtso izun beyn ha-yashan la-khadash."},{"fr":"À Jaffa, les vieilles maisons en pierre côtoient des tours de verre.","tgt":"ביפו, בתי האבן הישנים עומדים ליד מגדלי זכוכית.","ro":"Be-Yafo, batey ha-even ha-yeshanim omdim leyad migdaley zkhukhit."},{"fr":"Certaines traditions se perdent avec le temps, et c'est dommage.","tgt":"חלק מהמסורות הולכות לאיבוד עם הזמן, וחבל.","ro":"Khelek me-ha-masorot holkhot le-ibud im ha-zman, ve-khaval."},{"fr":"D'autres se transforment pour s'adapter à la vie moderne.","tgt":"אחרות משתנות כדי להתאים לחיים המודרניים.","ro":"Akherot mishtanot kedey lehat'im la-khayim ha-moderniyim."},{"fr":"Mon grand-père m'a appris à jouer au backgammon.","tgt":"סבא שלי לימד אותי לשחק שש בש.","ro":"Saba sheli limed oti lesakhek shesh besh."},{"fr":"Aujourd'hui, on y joue aussi sur des applications.","tgt":"היום משחקים בזה גם באפליקציות.","ro":"Ha-yom mesakhakim be-ze gam be-aplikatsyot."},{"fr":"Garder ses racines n'empêche pas d'avancer.","tgt":"לשמור על השורשים לא מפריע להתקדם.","ro":"Lishmor al ha-shorashim lo mafri'a lehitkadem."}]},{"title":"La cuisine du monde à Tel Aviv","phrases":[{"fr":"À Tel Aviv, on peut manger une cuisine différente chaque soir.","tgt":"בתל אביב אפשר לאכול אוכל אחר בכל ערב.","ro":"Be-Tel Aviv efshar le'ekhol okhel akher be-khol erev."},{"fr":"Chaque vague d'immigration a apporté ses propres saveurs.","tgt":"כל גל עלייה הביא איתו טעמים משלו.","ro":"Kol gal aliya hevi ito te'amim mishelo."},{"fr":"La shakshouka est devenue un plat typiquement israélien.","tgt":"השקשוקה הפכה למנה ישראלית טיפוסית.","ro":"Ha-shakshuka hafkha le-mana yisra'elit tipusit."},{"fr":"Au marché du Carmel, les épices sentent incroyablement bon.","tgt":"בשוק הכרמל, התבלינים מריחים מדהים.","ro":"Be-shuk ha-Karmel, ha-tavlinim merikhim madhim."},{"fr":"Ce petit restaurant est toujours plein, il faut réserver à l'avance.","tgt":"המסעדה הקטנה הזאת תמיד מלאה, צריך להזמין מקום מראש.","ro":"Ha-mis'ada ha-ktana ha-zot tamid mele'a, tsarikh lehazmin makom me-rosh."},{"fr":"Le chef marie des recettes de grand-mère avec des techniques modernes.","tgt":"השף משלב מתכונים של סבתא עם טכניקות מודרניות.","ro":"Ha-shef meshalev matkonim shel savta im tekhnikot moderniyot."},{"fr":"Je n'avais jamais goûté un houmous aussi crémeux.","tgt":"אף פעם לא טעמתי חומוס כל כך קרמי.","ro":"Af pa'am lo ta'amti khumus kol kakh kremi."},{"fr":"Les Israéliens débattent sans fin pour savoir où trouver le meilleur falafel.","tgt":"הישראלים מתווכחים בלי סוף איפה הפלאפל הכי טוב.","ro":"Ha-yisra'elim mitvakhim bli sof eyfo ha-falafel ha-khi tov."},{"fr":"Pour moi, la nourriture est la meilleure porte d'entrée dans une culture.","tgt":"בשבילי, האוכל הוא הדרך הכי טובה להכיר תרבות.","ro":"Bishvili, ha-okhel hu ha-derekh ha-khi tova lehakir tarbut."},{"fr":"On partage tout au milieu de la table, c'est plus convivial.","tgt":"חולקים הכול באמצע השולחן, זה יותר חברותי.","ro":"Kholkim ha-kol be-emtsa ha-shulkhan, ze yoter khevruti."}]},{"title":"Faire les choses à contrecœur","phrases":[{"fr":"Je suis allé au mariage à contrecœur, mais finalement je me suis bien amusé.","tgt":"הלכתי לחתונה בעל כורחי, אבל בסוף נהניתי מאוד.","ro":"Halakhti la-khatuna be'al korkhi, aval ba-sof neheneti me'od."},{"fr":"Elle a accepté ce poste à contrecœur.","tgt":"היא קיבלה את התפקיד הזה בעל כורחה.","ro":"Hi kibla et ha-tafkid ha-ze be'al korkha."},{"fr":"Ils ont dû déménager malgré eux à cause des loyers.","tgt":"הם עברו דירה בעל כורחם בגלל שכר הדירה.","ro":"Hem avru dira be'al korkham biglal skhar ha-dira."},{"fr":"Je me suis retrouvé malgré moi au centre de la dispute.","tgt":"מצאתי את עצמי בעל כורחי במרכז הוויכוח.","ro":"Matsati et atsmi be'al korkhi be-merkaz ha-vikuakh."},{"fr":"Nous avons été obligés d'annuler le voyage.","tgt":"נאלצנו לבטל את הטיול.","ro":"Ne'eltsnu levatel et ha-tiyul."},{"fr":"J'ai été obligé de travailler pendant les vacances.","tgt":"נאלצתי לעבוד בחופש.","ro":"Ne'altsti la'avod ba-khofesh."},{"fr":"Mon fils range sa chambre à contrecœur, en soupirant sans arrêt.","tgt":"הבן שלי מסדר את החדר בעל כורחו ונאנח כל הזמן.","ro":"Ha-ben sheli mesader et ha-kheder be'al korkho ve-ne'enakh kol ha-zman."},{"fr":"Elle s'est retrouvée, malgré elle, à organiser toute la fête.","tgt":"היא מצאה את עצמה, בעל כורחה, מארגנת את כל המסיבה.","ro":"Hi matsa et atsma, be'al korkha, me'argenet et kol ha-mesiba."},{"fr":"Personne n'aime faire les choses par obligation.","tgt":"אף אחד לא אוהב לעשות דברים מתוך חובה.","ro":"Af ekhad lo ohev la'asot dvarim mi-tokh khova."},{"fr":"Parfois, ce qu'on fait à contrecœur nous surprend agréablement.","tgt":"לפעמים, מה שעושים בעל כורחנו מפתיע אותנו לטובה.","ro":"Lifamim, ma she-osim be'al korkhenu mafti'a otanu le-tova."}],"tip":{"title":"« Be'al korkhi » : à contrecœur, être obligé","example":"Je suis allé au mariage à contrecœur, mais finalement je me suis bien amusé. — הלכתי לחתונה <b>בעל</b> <b>כורחי</b>, אבל בסוף נהניתי מאוד.","body":"L'expression « be'al korkhi » signifie « malgré moi, à contrecœur ». Elle vient d'une langue assez soutenue mais s'emploie couramment à l'oral, et sa fin change selon la personne : « be'al korkhi » pour moi, « be'al korkho » pour lui, « be'al korkha » pour elle, « be'al korkhenu » pour nous, « be'al korkham » pour eux. Dans « halakhti la-khatuna be'al korkhi », on a mot à mot « je suis allé, au mariage, malgré moi ». Pour dire simplement « être obligé de », on utilise le verbe « ne'elats » : « ne'altsti la'avod », j'ai été obligé de travailler, « ne'eltsnu levatel », nous avons dû annuler. Astuce : les terminaisons de « korkh » suivent la même logique que « sheli, shelo, shela », à moi, à lui, à elle.","exampleRo":"Halakhti la-khatuna be'al korkhi, aval ba-sof neheneti me'od.","lit":"je-suis-allé · au-mariage · malgré-moi, · mais · à-la-fin · j'ai-apprécié · beaucoup"}},{"title":"Vivre en ville ou à la campagne","phrases":[{"fr":"Après vingt ans à Tel Aviv, j'ai déménagé dans un petit village de Galilée.","tgt":"אחרי עשרים שנה בתל אביב, עברתי לכפר קטן בגליל.","ro":"Akharey esrim shana be-Tel Aviv, avarti le-khfar katan ba-Galil."},{"fr":"Ici, on entend les oiseaux au lieu des klaxons.","tgt":"פה שומעים ציפורים במקום צפצופים.","ro":"Po shom'im tsiporim bimkom tsiftsufim."},{"fr":"Les loyers sont bien moins chers que dans le centre du pays.","tgt":"שכר הדירה הרבה יותר זול מאשר במרכז הארץ.","ro":"Skhar ha-dira harbe yoter zol me-asher be-merkaz ha-arets."},{"fr":"En revanche, il faut une voiture pour tout.","tgt":"מצד שני, צריך אוטו לכל דבר.","ro":"Mi-tsad sheni, tsarikh oto le-khol davar."},{"fr":"La vie nocturne de la ville me manque parfois.","tgt":"חיי הלילה של העיר חסרים לי לפעמים.","ro":"Khayey ha-layla shel ha-ir khaserim li lifamim."},{"fr":"Mais pour rien au monde je ne retournerais vivre en ville.","tgt":"אבל לא הייתי חוזר לגור בעיר בשום אופן.","ro":"Aval lo hayiti khozer lagur ba-ir be-shum ofen."},{"fr":"Mes voisins connaissent le prénom de chacun de mes enfants.","tgt":"השכנים שלי מכירים את השם של כל אחד מהילדים שלי.","ro":"Ha-shkhenim sheli makirim et ha-shem shel kol ekhad me-ha-yeladim sheli."},{"fr":"Les jeunes, eux, rêvent de partir vers la grande ville.","tgt":"הצעירים, לעומת זאת, חולמים לעבור לעיר הגדולה.","ro":"Ha-tse'irim, le-umat zot, kholmim la'avor la-ir ha-gdola."},{"fr":"Si j'étais plus jeune, je choisirais peut-être la ville moi aussi.","tgt":"אם הייתי צעיר יותר, אולי גם אני הייתי בוחר בעיר.","ro":"Im hayiti tsa'ir yoter, ulay gam ani hayiti bokher ba-ir."},{"fr":"Chaque mode de vie a ses avantages et ses inconvénients.","tgt":"לכל אורח חיים יש יתרונות וחסרונות.","ro":"Le-khol orakh khayim yesh yitronot ve-khesronot."}]},{"title":"Une amitié d'enfance","phrases":[{"fr":"Yoni et moi, nous nous connaissons depuis l'école primaire.","tgt":"יוני ואני מכירים מבית הספר היסודי.","ro":"Yoni ve-ani makirim mi-beyt ha-sefer ha-yesodi."},{"fr":"Même quand on ne se parle pas pendant des mois, rien ne change.","tgt":"גם כשאנחנו לא מדברים חודשים, שום דבר לא משתנה.","ro":"Gam kshe-anakhnu lo medabrim khodashim, shum davar lo mishtane."},{"fr":"Il a toujours été là pour moi dans les moments difficiles.","tgt":"הוא תמיד היה שם בשבילי ברגעים הקשים.","ro":"Hu tamid haya sham bishvili ba-rega'im ha-kashim."},{"fr":"Un vrai ami te dit la vérité, même quand elle fait mal.","tgt":"חבר אמיתי אומר לך את האמת, גם כשהיא כואבת.","ro":"Khaver amiti omer lekha et ha-emet, gam kshe-hi ko'evet."},{"fr":"On s'est disputés une fois, et on s'est réconciliés le lendemain.","tgt":"רבנו פעם אחת, והשלמנו למחרת.","ro":"Ravnu pa'am akhat, ve-hishlamnu la-mokhorat."},{"fr":"Avec lui, je n'ai jamais besoin de faire semblant.","tgt":"איתו אני אף פעם לא צריך להעמיד פנים.","ro":"Ito ani af pa'am lo tsarikh leha'amid panim."},{"fr":"Nos enfants aussi sont devenus amis.","tgt":"גם הילדים שלנו נהיו חברים.","ro":"Gam ha-yeladim shelanu nihyu khaverim."},{"fr":"Chaque été, nous partons camper ensemble au bord du lac de Tibériade.","tgt":"כל קיץ אנחנו יוצאים לקמפינג ביחד ליד הכנרת.","ro":"Kol kayits anakhnu yots'im le-kemping be-yakhad leyad ha-Kineret."},{"fr":"Une amitié comme la nôtre se construit avec le temps.","tgt":"חברות כמו שלנו נבנית עם הזמן.","ro":"Khaverut kmo shelanu nivnet im ha-zman."},{"fr":"Je lui fais confiance plus qu'à n'importe qui.","tgt":"אני סומך עליו יותר מכל אחד אחר.","ro":"Ani somekh alav yoter mi-kol ekhad akher."}]},{"title":"Les écrans et les réseaux sociaux","phrases":[{"fr":"Je perds beaucoup trop de temps sur mon téléphone.","tgt":"אני מבזבז יותר מדי זמן בטלפון.","ro":"Ani mevazbez yoter miday zman ba-telefon."},{"fr":"Les réseaux sociaux nous rapprochent et nous éloignent à la fois.","tgt":"הרשתות החברתיות מקרבות ומרחיקות אותנו בעת ובעונה אחת.","ro":"Ha-reshatot ha-khevratiyot mekarvot u-markhikot otanu be-et u-ve-ona akhat."},{"fr":"Tout le monde ne montre que les beaux moments de sa vie.","tgt":"כולם מראים רק את הרגעים היפים בחיים שלהם.","ro":"Kulam mar'im rak et ha-rega'im ha-yafim ba-khayim shelahem."},{"fr":"Ça crée une comparaison permanente qui nous fait du mal.","tgt":"זה יוצר השוואה מתמדת שפוגעת בנו.","ro":"Ze yotser hashva'a mitmedet she-poga'at banu."},{"fr":"Le groupe familial m'envoie cent messages par jour.","tgt":"הקבוצה המשפחתית שולחת לי מאה הודעות ביום.","ro":"Ha-kvutsa ha-mishpakhtit sholakhat li me'a hoda'ot ba-yom."},{"fr":"Le samedi, j'essaie d'éteindre mon téléphone toute la journée.","tgt":"בשבת אני מנסה לכבות את הטלפון כל היום.","ro":"Be-shabat ani menase lekhabot et ha-telefon kol ha-yom."},{"fr":"Au début c'était dur, maintenant c'est devenu un vrai plaisir.","tgt":"בהתחלה זה היה קשה, ועכשיו זה הפך לתענוג אמיתי.","ro":"Ba-hatkhala ze haya kashe, ve-akhshav ze hafakh le-ta'anug amiti."},{"fr":"On peut aussi y apprendre beaucoup de choses utiles.","tgt":"אפשר גם ללמוד שם הרבה דברים שימושיים.","ro":"Efshar gam lilmod sham harbe dvarim shimushiyim."},{"fr":"Les adolescents sont plus exposés que nous à ces dangers.","tgt":"בני הנוער חשופים לסכנות האלה יותר מאיתנו.","ro":"Bney ha-no'ar khasufim la-sakanot ha-ele yoter me-itanu."},{"fr":"Tout dépend de la manière dont on s'en sert.","tgt":"הכול תלוי באיך שמשתמשים בהם.","ro":"Ha-kol taluy be-eykh she-mishtamshim bahem."}]},{"title":"Proverbes et images","phrases":[{"fr":"Comme on dit, il n'y a pas de fumée sans feu.","tgt":"כמו שאומרים, אין עשן בלי אש.","ro":"Kmo she-omrim, eyn ashan bli esh."},{"fr":"Des goûts et des couleurs, on ne discute pas.","tgt":"על טעם וריח אין להתווכח.","ro":"Al ta'am va-re'akh eyn lehitvake'akh."},{"fr":"Arrête de faire d'une mouche un éléphant !","tgt":"תפסיק לעשות מזבוב פיל!","ro":"Tafsik la'asot mi-zvuv pil!"},{"fr":"Le concert était absolument génial !","tgt":"ההופעה הייתה חבל על הזמן!","ro":"Ha-hofa'a hayta khaval al ha-zman!"},{"fr":"Ces embouteillages, j'en ai par-dessus la tête.","tgt":"הפקקים האלה יוצאים לי מהאף.","ro":"Ha-pkakim ha-ele yots'im li me-ha-af."},{"fr":"Il rêve complètement s'il croit réussir sans travailler.","tgt":"הוא חי בסרט אם הוא חושב שיצליח בלי לעבוד.","ro":"Hu khay be-seret im hu khoshev she-yatsli'akh bli la'avod."},{"fr":"Tous les débuts sont difficiles, il faut de la patience.","tgt":"כל ההתחלות קשות, צריך סבלנות.","ro":"Kol ha-hatkhalot kashot, tsarikh savlanut."},{"fr":"Je me suis cassé la tête sur ce problème toute la nuit.","tgt":"שברתי את הראש על הבעיה הזאת כל הלילה.","ro":"Shavarti et ha-rosh al ha-be'aya ha-zot kol ha-layla."},{"fr":"Ce qui ne nous tue pas nous endurcit.","tgt":"מה שלא הורג מחשל.","ro":"Ma she-lo horeg mekhashel."},{"fr":"Le film était nul, une vraie perte de temps.","tgt":"הסרט היה על הפנים, ממש בזבוז זמן.","ro":"Ha-seret haya al ha-panim, mamash bizbuz zman."}],"tip":{"title":"Les proverbes et expressions imagées","example":"Arrête de faire d'une mouche un éléphant ! — תפסיק לעשות <b>מזבוב</b> <b>פיל</b>!","body":"Les Israéliens adorent les expressions imagées, et en placer une au bon moment fait toujours sourire. Certaines ressemblent aux nôtres : « eyn ashan bli esh », il n'y a pas de fumée sans feu, ou « la'asot mi-zvuv pil », faire d'une mouche un éléphant, exactement comme en français ; décomposons « tafsik la'asot mi-zvuv pil » : arrête, de faire, d'une mouche, éléphant. D'autres sont typiquement israéliennes : « khaval al ha-zman », littéralement « dommage pour le temps », veut dire génial, « al ha-panim », « sur le visage », veut dire nul, et « yatsa li me-ha-af », « ça m'est sorti par le nez », veut dire j'en ai assez. Astuce : apprenez-en une par semaine et glissez-la dans une vraie conversation, vos amis israéliens seront ravis.","exampleRo":"Tafsik la'asot mi-zvuv pil!","lit":"arrête · de-faire · d'une-mouche · éléphant !"}},{"title":"Un grand débat entre amis","phrases":[{"fr":"Hier soir, on a débattu jusqu'à deux heures du matin.","tgt":"אתמול בלילה התווכחנו עד שתיים לפנות בוקר.","ro":"Etmol ba-layla hitvakakhnu ad shtayim lifnot boker."},{"fr":"La question était de savoir si l'argent achète le bonheur.","tgt":"השאלה הייתה אם כסף קונה אושר.","ro":"Ha-she'ela hayta im kesef kone osher."},{"fr":"Ron soutenait que sans argent, on ne peut pas vivre tranquille.","tgt":"רון טען שבלי כסף אי אפשר לחיות בשקט.","ro":"Ron ta'an she-bli kesef i efshar likhyot be-sheket."},{"fr":"Maya, elle, pensait exactement le contraire.","tgt":"מאיה, לעומת זאת, חשבה בדיוק להפך.","ro":"Maya, le-umat zot, khashva be-diyuk la-hefekh."},{"fr":"Chacun a défendu son point de vue avec passion.","tgt":"כל אחד הגן על נקודת המבט שלו בלהט.","ro":"Kol ekhad hegen al nekudat ha-mabat shelo be-lahat."},{"fr":"Les Israéliens adorent discuter, même avec des inconnus.","tgt":"ישראלים אוהבים להתווכח, אפילו עם זרים.","ro":"Yisra'elim ohavim lehitvake'akh, afilu im zarim."},{"fr":"Au début, ces débats animés me stressaient beaucoup.","tgt":"בהתחלה, הוויכוחים הסוערים האלה הלחיצו אותי מאוד.","ro":"Ba-hatkhala, ha-vikukhim ha-so'arim ha-ele hilkhitsu oti me'od."},{"fr":"Maintenant, j'ose donner mon avis à voix haute.","tgt":"עכשיו אני מעז להגיד את דעתי בקול רם.","ro":"Akhshav ani me'ez lehagid et da'ati be-kol ram."},{"fr":"Ici, on peut se disputer et rester les meilleurs amis du monde.","tgt":"פה אפשר להתווכח ולהישאר החברים הכי טובים בעולם.","ro":"Po efshar lehitvake'akh ve-lehisha'er ha-khaverim ha-khi tovim ba-olam."},{"fr":"Finalement, personne n'a convaincu personne, mais on a beaucoup ri.","tgt":"בסוף אף אחד לא שכנע אף אחד, אבל צחקנו המון.","ro":"Ba-sof af ekhad lo shikhne'a af ekhad, aval tsakhaknu hamon."}]},{"title":"Changer de vie professionnelle","phrases":[{"fr":"À quarante-cinq ans, j'ai quitté mon poste à la banque.","tgt":"בגיל ארבעים וחמש עזבתי את העבודה שלי בבנק.","ro":"Be-gil arba'im ve-khamesh azavti et ha-avoda sheli ba-bank."},{"fr":"Je gagnais bien ma vie, mais je m'ennuyais terriblement.","tgt":"הרווחתי טוב, אבל השתעממתי נורא.","ro":"Hirvakhti tov, aval hishta'amamti nora."},{"fr":"J'ai toujours rêvé d'enseigner aux enfants.","tgt":"תמיד חלמתי ללמד ילדים.","ro":"Tamid khalamti lelamed yeladim."},{"fr":"Ma femme m'a encouragé à me jeter à l'eau.","tgt":"אשתי עודדה אותי לקפוץ למים.","ro":"Ishti odeda oti likfots la-mayim."},{"fr":"J'ai repris des études à l'université pendant deux ans.","tgt":"חזרתי ללמוד באוניברסיטה במשך שנתיים.","ro":"Khazarti lilmod ba-universita be-meshekh shnatayim."},{"fr":"Aujourd'hui, je gagne moins, mais je rentre heureux le soir.","tgt":"היום אני מרוויח פחות, אבל אני חוזר הביתה מאושר.","ro":"Ha-yom ani marvi'akh pakhot, aval ani khozer ha-bayta me'ushar."},{"fr":"Mes élèves m'apprennent autant que je leur apprends.","tgt":"התלמידים שלי מלמדים אותי לא פחות ממה שאני מלמד אותם.","ro":"Ha-talmidim sheli melamdim oti lo pakhot mi-ma she-ani melamed otam."},{"fr":"Si j'avais su, j'aurais changé de métier bien plus tôt.","tgt":"אילו ידעתי, הייתי מחליף מקצוע הרבה יותר מוקדם.","ro":"Ilu yada'ti, hayiti makhlif miktso'a harbe yoter mukdam."},{"fr":"Tout le monde n'a pas la chance de pouvoir choisir.","tgt":"לא לכל אחד יש את המזל לבחור.","ro":"Lo le-khol ekhad yesh et ha-mazal livkhor."},{"fr":"Un travail qui a du sens vaut plus qu'un gros salaire.","tgt":"עבודה עם משמעות שווה יותר ממשכורת גבוהה.","ro":"Avoda im mashma'ut shava yoter mi-maskoret gvoha."}]},{"title":"D'une génération à l'autre","phrases":[{"fr":"Mes grands-parents sont arrivés en Israël sans rien.","tgt":"סבא וסבתא שלי הגיעו לישראל בלי כלום.","ro":"Saba ve-savta sheli higi'u le-Yisra'el bli klum."},{"fr":"Ils ont construit leur vie à partir de zéro.","tgt":"הם בנו את החיים שלהם מאפס.","ro":"Hem banu et ha-khayim shelahem me-efes."},{"fr":"Ma grand-mère n'a appris l'hébreu qu'à trente ans.","tgt":"סבתא שלי למדה עברית רק בגיל שלושים.","ro":"Savta sheli lamda ivrit rak be-gil shloshim."},{"fr":"Elle parle encore avec un accent que j'adore.","tgt":"היא עדיין מדברת עם מבטא שאני מת עליו.","ro":"Hi adayin medaberet im mivta she-ani met alav."},{"fr":"Mes parents, eux, ont grandi dans un kibboutz.","tgt":"ההורים שלי, לעומתם, גדלו בקיבוץ.","ro":"Ha-horim sheli, le-umatam, gadlu be-kibuts."},{"fr":"Mes enfants sont incapables d'imaginer la vie sans internet.","tgt":"הילדים שלי לא מסוגלים לדמיין חיים בלי אינטרנט.","ro":"Ha-yeladim sheli lo mesugalim ledamyen khayim bli internet."},{"fr":"Chaque génération pense que la suivante a la vie trop facile.","tgt":"כל דור חושב שלדור הבא יש חיים קלים מדי.","ro":"Kol dor khoshev she-la-dor ha-ba yesh khayim kalim miday."},{"fr":"Pourtant, les jeunes aussi ont de vrais défis à relever.","tgt":"אבל גם לצעירים יש אתגרים אמיתיים.","ro":"Aval gam la-tse'irim yesh etgarim amitiyim."},{"fr":"Le vendredi, trois générations se retrouvent autour de la même table.","tgt":"בימי שישי, שלושה דורות נפגשים סביב אותו שולחן.","ro":"Bimey shishi, shlosha dorot nifgashim sviv oto shulkhan."},{"fr":"J'aimerais que mes enfants entendent les histoires de leur arrière-grand-mère.","tgt":"הייתי רוצה שהילדים שלי ישמעו את הסיפורים של סבתא רבתא שלהם.","ro":"Hayiti rotse she-ha-yeladim sheli yishme'u et ha-sipurim shel savta rabta shelahem."}]},{"title":"Art et musique à Tel Aviv","phrases":[{"fr":"Samedi, nous sommes allés au musée d'art de Tel Aviv.","tgt":"בשבת הלכנו למוזיאון תל אביב לאמנות.","ro":"Be-shabat halakhnu le-muze'on Tel Aviv le-omanut."},{"fr":"Certaines œuvres m'ont ému, d'autres m'ont laissé perplexe.","tgt":"חלק מהיצירות ריגשו אותי, ואחרות השאירו אותי מבולבל.","ro":"Khelek me-ha-yetsirot rigshu oti, ve-akherot hish'iru oti mevulbal."},{"fr":"L'art contemporain est parfois difficile à comprendre.","tgt":"אמנות עכשווית לפעמים קשה להבנה.","ro":"Omanut akhshavit lifamim kasha la-havana."},{"fr":"Dans les rues de Florentin, les murs sont couverts de graffitis.","tgt":"ברחובות פלורנטין, הקירות מכוסים בגרפיטי.","ro":"Birkhovot Florentin, ha-kirot mekhusim be-grafiti."},{"fr":"Ce quartier s'est transformé grâce aux artistes.","tgt":"השכונה הזאת עברה שינוי בזכות האמנים.","ro":"Ha-shkhuna ha-zot avra shinuy bizkhut ha-omanim."},{"fr":"La musique israélienne mélange des influences venues de partout.","tgt":"המוזיקה הישראלית משלבת השפעות מכל מקום.","ro":"Ha-muzika ha-yisra'elit meshalevet hashpa'ot mi-kol makom."},{"fr":"Toute la famille chante encore les vieilles chansons.","tgt":"כל המשפחה עדיין שרה את השירים הישנים.","ro":"Kol ha-mishpakha adayin shara et ha-shirim ha-yeshanim."},{"fr":"Écouter de la musique en hébreu m'a beaucoup aidé à progresser.","tgt":"להקשיב למוזיקה בעברית עזר לי מאוד להתקדם.","ro":"Lehakshiv le-muzika be-ivrit azar li me'od lehitkadem."},{"fr":"Je ne savais pas dessiner, alors je me suis inscrit à un cours de céramique.","tgt":"לא ידעתי לצייר, אז נרשמתי לחוג קרמיקה.","ro":"Lo yada'ti letsayer, az nirshamti le-khug keramika."},{"fr":"Créer quelque chose de ses mains apaise l'esprit.","tgt":"ליצור משהו בידיים מרגיע את הנפש.","ro":"Litsor mashehu ba-yadayim margi'a et ha-nefesh."}]},{"title":"Garder espoir","phrases":[{"fr":"Malgré les difficultés, je reste optimiste.","tgt":"למרות הקשיים, אני נשאר אופטימי.","ro":"Lamrot ha-kshayim, ani nish'ar optimi."},{"fr":"Les Israéliens répètent sans cesse que tout ira bien.","tgt":"ישראלים אומרים כל הזמן שיהיה בסדר.","ro":"Yisra'elim omrim kol ha-zman she-yihye be-seder."},{"fr":"Cette phrase m'agaçait au début, maintenant elle me rassure.","tgt":"המשפט הזה עצבן אותי בהתחלה, ועכשיו הוא מרגיע אותי.","ro":"Ha-mishpat ha-ze itsben oti ba-hatkhala, ve-akhshav hu margi'a oti."},{"fr":"Chaque crise finit par passer.","tgt":"כל משבר עובר בסוף.","ro":"Kol mashber over ba-sof."},{"fr":"L'essentiel, c'est de ne pas rester seul quand ça va mal.","tgt":"העיקר לא להישאר לבד כשקשה.","ro":"Ha-ikar lo lehisha'er levad kshe-kashe."},{"fr":"Je crois que l'avenir sera meilleur qu'on ne l'imagine.","tgt":"אני מאמין שהעתיד יהיה טוב יותר ממה שאנחנו מדמיינים.","ro":"Ani ma'amin she-ha-atid yihye tov yoter mi-ma she-anakhnu medamyenim."},{"fr":"Les jeunes que je rencontre me donnent beaucoup d'énergie.","tgt":"הצעירים שאני פוגש נותנים לי המון כוח.","ro":"Ha-tse'irim she-ani pogesh notnim li hamon ko'akh."},{"fr":"Chaque matin, je me dis que la journée apportera du bon.","tgt":"כל בוקר אני אומר לעצמי שהיום יביא משהו טוב.","ro":"Kol boker ani omer le-atsmi she-ha-yom yavi mashehu tov."},{"fr":"L'espoir, ce n'est pas de la naïveté, c'est un choix.","tgt":"תקווה זה לא תמימות, זאת בחירה.","ro":"Tikva ze lo tmimut, zot bkhira."},{"fr":"Il faut savoir profiter des petites choses.","tgt":"צריך לדעת ליהנות מהדברים הקטנים.","ro":"Tsarikh lada'at lehanot me-ha-dvarim ha-ktanim."}]},{"title":"Un au revoir difficile","phrases":[{"fr":"Demain, mon meilleur ami part s'installer en France.","tgt":"מחר החבר הכי טוב שלי עובר לגור בצרפת.","ro":"Makhar ha-khaver ha-khi tov sheli over lagur be-Tsarfat."},{"fr":"Nous avons passé toute la soirée sur la plage à parler du passé.","tgt":"בילינו את כל הערב בחוף ודיברנו על העבר.","ro":"Bilinu et kol ha-erev ba-khof ve-dibarnu al ha-avar."},{"fr":"Aucun de nous n'osait parler du départ.","tgt":"אף אחד מאיתנו לא העז לדבר על העזיבה.","ro":"Af ekhad me-itanu lo he'ez ledaber al ha-aziva."},{"fr":"On s'est promis de s'appeler chaque semaine.","tgt":"הבטחנו אחד לשני להתקשר כל שבוע.","ro":"Hivtakhnu ekhad la-sheni lehitkasher kol shavu'a."},{"fr":"Les Israéliens ne se disent jamais vraiment adieu, ils disent « à la revoyure ».","tgt":"ישראלים לא באמת נפרדים, הם אומרים להתראות.","ro":"Yisra'elim lo be-emet nifradim, hem omrim lehitra'ot."},{"fr":"Quand il m'a serré dans ses bras, j'ai eu les larmes aux yeux.","tgt":"כשהוא חיבק אותי, היו לי דמעות בעיניים.","ro":"Kshe-hu khibek oti, hayu li dma'ot ba-eynayim."},{"fr":"Il m'a demandé de prendre soin de moi.","tgt":"הוא ביקש ממני לשמור על עצמי.","ro":"Hu bikesh mi-meni lishmor al atsmi."},{"fr":"La distance ne pourra pas effacer vingt ans d'amitié.","tgt":"המרחק לא יוכל למחוק עשרים שנות חברות.","ro":"Ha-merkhak lo yukhal limkhok esrim shnot khaverut."},{"fr":"Je suis triste, mais heureux pour lui.","tgt":"אני עצוב, אבל אני שמח בשבילו.","ro":"Ani atsuv, aval ani same'akh bishvilo."},{"fr":"Bon voyage, et reviens-nous vite !","tgt":"דרך צלחה, ותחזור אלינו מהר!","ro":"Derekh tslekha, ve-takhzor eleynu maher!"}]},{"title":"Regard en arrière sur le parcours en hébreu","phrases":[{"fr":"Au début, je ne savais même pas dire bonjour en hébreu.","tgt":"בהתחלה לא ידעתי אפילו להגיד שלום בעברית.","ro":"Ba-hatkhala lo yada'ti afilu lehagid shalom be-ivrit."},{"fr":"Je pensais que je n'arriverais jamais à prononcer les sons de la gorge.","tgt":"חשבתי שלעולם לא אצליח לבטא את הצלילים מהגרון.","ro":"Khashavti she-le-olam lo atsli'akh levate et ha-tslilim me-ha-garon."},{"fr":"Petit à petit, les phrases ont commencé à sortir toutes seules.","tgt":"לאט לאט, המשפטים התחילו לצאת לבד.","ro":"Le'at le'at, ha-mishpatim hitkhilu latset levad."},{"fr":"J'ai appris à commander, à discuter, puis à débattre.","tgt":"למדתי להזמין, לשוחח, ואחר כך להתווכח.","ro":"Lamadti lehazmin, lesokhe'akh, ve-akhar kakh lehitvake'akh."},{"fr":"Les Israéliens m'ont toujours encouragé, même quand je me trompais.","tgt":"הישראלים תמיד עודדו אותי, גם כשטעיתי.","ro":"Ha-yisra'elim tamid odedu oti, gam kshe-ta'iti."},{"fr":"Aujourd'hui, je comprends même les blagues à la radio.","tgt":"היום אני מבין אפילו את הבדיחות ברדיו.","ro":"Ha-yom ani mevin afilu et ha-bdikhot ba-radyo."},{"fr":"L'hébreu m'a ouvert la porte d'une culture fascinante.","tgt":"העברית פתחה לי דלת לתרבות מרתקת.","ro":"Ha-ivrit patkha li delet le-tarbut merateket."},{"fr":"Je ne parle pas encore parfaitement, mais je n'ai plus peur.","tgt":"אני עדיין לא מדבר מושלם, אבל אני כבר לא מפחד.","ro":"Ani adayin lo medaber mushlam, aval ani kvar lo mefakhed."},{"fr":"Chaque conversation m'a appris quelque chose de nouveau.","tgt":"כל שיחה לימדה אותי משהו חדש.","ro":"Kol sikha limda oti mashehu khadash."},{"fr":"Je suis fier de tout le chemin parcouru depuis la toute première leçon.","tgt":"אני גאה בכל הדרך שעשיתי מאז השיעור הראשון.","ro":"Ani ge'e be-khol ha-derekh she-asiti me-az ha-shi'ur ha-rishon."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a fait parler de sujets profonds.","tgt":"המודול האחרון הזה גרם לנו לדבר על נושאים עמוקים.","ro":"Ha-modul ha-akharon ha-ze garam lanu ledaber al nos'im amukim."},{"fr":"Travail, tradition, amitié, nous avons tout abordé en hébreu.","tgt":"עבודה, מסורת, חברות, דיברנו על הכול בעברית.","ro":"Avoda, masoret, khaverut, dibarnu al ha-kol be-ivrit."},{"fr":"Maintenant, nous connaissons les expressions de la langue parlée.","tgt":"עכשיו אנחנו מכירים את הביטויים של השפה המדוברת.","ro":"Akhshav anakhnu makirim et ha-bituyim shel ha-safa ha-meduberet."},{"fr":"Nous savons aussi faire des hypothèses et donner notre avis avec nuance.","tgt":"אנחנו יודעים גם לשער ולהביע דעה בזהירות.","ro":"Anakhnu yod'im gam lesha'er ve-lehabi'a de'a bi-zhirut."},{"fr":"Trois niveaux, neuf modules et des centaines de phrases plus tard, nous voilà.","tgt":"שלוש רמות, תשעה מודולים ומאות משפטים אחר כך, הנה אנחנו כאן.","ro":"Shalosh ramot, tish'a modulim u-me'ot mishpatim akhar kakh, hine anakhnu kan."},{"fr":"Cette langue fait désormais partie de notre vie.","tgt":"השפה הזאת היא כבר חלק מהחיים שלנו.","ro":"Ha-safa ha-zot hi kvar khelek me-ha-khayim shelanu."},{"fr":"Le plus important maintenant, c'est de continuer à parler tous les jours.","tgt":"הדבר הכי חשוב עכשיו זה להמשיך לדבר כל יום.","ro":"Ha-davar ha-khi khashuv akhshav ze lehamshikh ledaber kol yom."},{"fr":"N'ayez pas peur de vous tromper, c'est comme ça qu'on apprend.","tgt":"אל תפחדו לטעות, ככה לומדים.","ro":"Al tifkhadu lit'ot, kakha lomdim."},{"fr":"Bravo pour ce magnifique parcours mené jusqu'au bout !","tgt":"כל הכבוד על הדרך המדהימה הזאת עד הסוף!","ro":"Kol ha-kavod al ha-derekh ha-madhima ha-zot ad ha-sof!"},{"fr":"Bonne chance pour la suite, et à bientôt en hébreu !","tgt":"בהצלחה בהמשך, ולהתראות בעברית!","ro":"Be-hatslakha ba-hemshekh, ve-lehitra'ot be-ivrit!"}]}]}]}];
